INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('395991d6-1761-44f9-b628-2d282ee3dabb', 'radical', '亅', 'barb', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Radikal ini berbentuk seperti duri. Seperti yang Anda lihat di kawat duri. Bayangkan salah satu benda ini menempel di lengan atau pakaian Anda. Pikirkan betapa sakitnya jika kait kecil di ujungnya menempel pada Anda. Katakan dengan lantang, "Oh sial, ada duri yang tertancap di tubuhku!"') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('395991d6-1761-44f9-b628-2d282ee3dabb', 'duri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('490e7ae9-ec02-4852-983a-64bc18803022', 'radical', '乚', 'umbrella', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Tahukah Anda bagaimana bentuk bagian bawah payung? Ini memiliki pengait yang melingkari pegangannya. Jadi ketika Anda melihat kata radikal ini, Anda harus memikirkan bagian bawah payung, yang akan membantu Anda mengingat apa artinya payung.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('490e7ae9-ec02-4852-983a-64bc18803022', 'Payung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('27c7f09e-40e0-4e21-9781-02438b1c535e', 'radical', '[triceratops]', 'triceratops', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketiga tanduk tersebut melambangkan triceratops, salah satu dinosaurus paling mengagumkan yang pernah ada.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('27c7f09e-40e0-4e21-9781-02438b1c535e', 'Triceratop', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('08123ffe-1504-458d-b1cb-e5221e44dd15', 'radical', '兀', 'pi', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Tentu saja, ini tampak seperti sesuatu yang bagus di versi 3.14, sesuatu yang seharusnya dipelajari oleh semua orang. Itu simbol matematika yang ada hubungannya dengan lingkaran... pi!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08123ffe-1504-458d-b1cb-e5221e44dd15', 'pi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1c67853d-d99a-4ff1-be6f-659ecdf4b6fc', 'radical', '彡', 'hair', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Tiga helai rambut yang mengalir ke samping ini adalah tiga helai rambut. Cukup mudah untuk dilihat dan diingat, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c67853d-d99a-4ff1-be6f-659ecdf4b6fc', 'Rambut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('48c07145-83c9-4528-be89-1d589bdeae96', 'radical', '廾', 'twenty', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda memiliki 十 plus 十... apa yang Anda dapatkan jika Anda menambahkan kedua kanji ini bersama-sama? Anda mendapat dua puluh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('48c07145-83c9-4528-be89-1d589bdeae96', 'Dua puluh', true) ON CONFLICT DO NOTHING;
