INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'vocabulary', '〜才', '〜才', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Meskipun kata ini terdiri dari satu kanji yang berdiri sendiri, namun maknanya tidak sama dengan kanji induknya. Namun maknanya serupa. Kata ini berarti tahun atau usia. Dengan bertambahnya tahun, semakin banyak kejeniusan, bukan? Itu sebabnya kata ini berarti "berusia bertahun-tahun" dan bukan "jenius", seperti kanji induknya. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'Berusia Tahun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'Age', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'さい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'わたしは五才です。', 'Saya berumur lima tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'らい月二日に、六十七才になります。', 'Saya akan berusia 67 tahun pada tanggal 2 bulan depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca9206b-47bf-420a-9aa6-be982035ebf4', 'ちちの五十五才のたんじょう日に、ホグワーツへしょうたいされた。', 'Pada ulang tahun ayahku yang kelima puluh lima, aku diundang ke Sekolah Sihir Hogwarts.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'vocabulary', '天才', '天才', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Seorang jenius dari surga tetaplah seorang jenius.', 'Seorang jenius dari surga tetaplah seorang jenius.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'Jenius', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'てんさい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'かれはしょうぎの天才です。', 'Dia seorang shogi yang jenius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'あのフランス人の女は天才だ。', 'Wanita Perancis itu jenius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e720b04d-4d12-4c2f-a022-257b47e21dc6', 'そのゴリラは、まぎれもなく天才だ。', 'Gorila itu benar-benar jenius.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', 'vocabulary', '王', '王', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', 'Raja', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', 'おう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', 'このくにの王はわたしだ。', 'Saya adalah raja negara ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', '王の刀をみせてください。', 'Tolong tunjukkan padaku pedang Raja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c7fa3ba-9893-4458-ae7a-b04ff7ad5e82', '王さまでもカレーをたべるのだ。', 'Bahkan raja pun makan kari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', 'vocabulary', '王子', '王子', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Seorang anak raja adalah pangeran. Suatu hari nanti dia akan menjadi 王, jika dia beruntung, tapi saat ini dia hanyalah anak raja.', 'Seorang anak raja adalah pangeran. Suatu hari nanti dia akan menjadi 王, jika dia beruntung, tapi saat ini dia hanyalah anak raja.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', 'Pangeran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', 'おうじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', '王子は、じょうばをはじめました。', 'Pangeran mulai menunggang kuda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', 'あの王子の左手は大きい。', 'Tangan kiri Pangeran besar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46687c59-a622-4752-af46-ca7a5e393d91', '王子がかえるにキスをすると、そのかえるは王子をたべてしまった。', 'Setelah sang pangeran mencium sang katak, sang katak pun memakan sang pangeran.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('604a92c6-9ef9-444b-8518-ab87c8ef5157', 'vocabulary', '女王', '女王', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Wanita yang menghadap raja bukanlah seorang putri. Ini adalah ratu.', 'Wanita yang menghadap raja bukanlah seorang putri. Ini adalah ratu.') ON CONFLICT (id) DO NOTHING;
