INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee6d6c7b-b48f-4585-8778-dcf93edf123c', '王子は、王女のうつくしさにうっとりしました。', 'Sang pangeran terpesona melihat kecantikan sang putri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee6d6c7b-b48f-4585-8778-dcf93edf123c', '王は王女に木のつくえをかってあげました。', 'Raja membelikan meja kayu untuk sang putri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee6d6c7b-b48f-4585-8778-dcf93edf123c', '王女さまはよろこびをバクてんでひょうげんしているようです。', 'Sang putri mengungkapkan kegembiraannya dengan melakukan jungkir balik ke belakang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b71cff08-9d5c-48f8-b88f-3f4d9f07b046', 'vocabulary', '石', '石', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
