INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b71cff08-9d5c-48f8-b88f-3f4d9f07b046', '人にむかって石をなげるんじゃない。', 'Anda tidak boleh melempari orang dengan batu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b71cff08-9d5c-48f8-b88f-3f4d9f07b046', '石が一つくつに入った。', 'Sebuah batu masuk ke dalam sepatuku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b71cff08-9d5c-48f8-b88f-3f4d9f07b046', '石と石がぶつかるおとにいらいらする。', 'Suara batu bertabrakan membuatku kesal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1ac65780-f1e6-4755-919c-fc2ccef371c0', 'vocabulary', '太い', '太い', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari lemak? Sama saja: gemuk.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari lemak? Sama saja: gemuk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1ac65780-f1e6-4755-919c-fc2ccef371c0', 'Gemuk', true) ON CONFLICT DO NOTHING;
