INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1ac65780-f1e6-4755-919c-fc2ccef371c0', '山田さんのまゆげはとても太いです。', 'Alis Yamada sangat tebal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1ac65780-f1e6-4755-919c-fc2ccef371c0', 'このおみせのめんはおもったより太かったです。', 'Mie di toko ini lebih kental dari yang saya kira.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1ac65780-f1e6-4755-919c-fc2ccef371c0', 'おれの母ちゃんは、ちょう太いんだぜ。', 'Ibuku sangat gemuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('74e2ebf1-785f-4f6f-9d16-b21290ee6687', 'vocabulary', '太る', '太る', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya gemuk jadi bentuk kata kerjanya adalah menjadi gemuk.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya gemuk jadi bentuk kata kerjanya adalah menjadi gemuk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('74e2ebf1-785f-4f6f-9d16-b21290ee6687', 'Menjadi Gemuk', true) ON CONFLICT DO NOTHING;
