INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5a39b0c-1abc-4853-87ab-1b323afc7862', '十引く四は六です。', 'Sepuluh dikurangi empat sama dengan enam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5a39b0c-1abc-4853-87ab-1b323afc7862', 'どうせ、女のきを引くためにいってるだけでしょう。', 'Dia mungkin mengatakan hal itu hanya untuk menarik perhatian para gadis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5a39b0c-1abc-4853-87ab-1b323afc7862', '引きがねを引いて、フライパンをうった。', 'Saya menarik pelatuknya dan menembak penggorengan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d5a4d758-c0db-4896-b6c7-0f3785a9a020', 'vocabulary', '市', '市', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
