INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5a4d758-c0db-4896-b6c7-0f3785a9a020', '大阪市で生まれました。', 'Saya lahir di Kota Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5a4d758-c0db-4896-b6c7-0f3785a9a020', '市のあたらしいマスコットキャラクターがけっていしました。', 'Maskot baru kota telah diputuskan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5a4d758-c0db-4896-b6c7-0f3785a9a020', 'きょうとの市バスの中で、はいてしまった。', 'Saya muntah di bus kota Kyoto.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7bede665-f955-4944-b197-dc8f67d1e362', 'vocabulary', '市立', '市立', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Stand kota bersifat kotamadya. Kotamadya berarti "dari atau berkaitan dengan kota atau badan pemerintahannya", dan kosakata ini memiliki arti yang sama. Atau hanya kota. Kota juga baik-baik saja.', 'Stand kota bersifat kotamadya. Kotamadya berarti "dari atau berkaitan dengan kota atau badan pemerintahannya", dan kosakata ini memiliki arti yang sama. Atau hanya kota. Kota juga baik-baik saja.') ON CONFLICT (id) DO NOTHING;
