INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bede665-f955-4944-b197-dc8f67d1e362', 'そぼは市立びょういんに入いんしています。', 'Nenek saya dirawat di rumah sakit di rumah sakit kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bede665-f955-4944-b197-dc8f67d1e362', '市立としょかんまでのみちをおしえてください。', 'Tolong beritahu saya arah ke perpustakaan kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bede665-f955-4944-b197-dc8f67d1e362', '大さか市立大がくのまえでさか立ちをした。', 'Saya berdiri tegak di depan Universitas Kota Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('106bc8c9-9ed4-4b02-a2ac-9fcf503697b7', 'vocabulary', 'シアトル市', 'シアトル市', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Nama kota (シアトル／しあとる) dengan tanda 市 berarti "kota ____". Anda dapat melakukan ini di kota mana pun (cobalah di kota asal Anda!). Jadi kata ini berarti Seattle, atau lebih spesifiknya Kota Seattle.', 'Nama kota (シアトル／しあとる) dengan tanda 市 berarti "kota ____". Anda dapat melakukan ini di kota mana pun (cobalah di kota asal Anda!). Jadi kata ini berarti Seattle, atau lebih spesifiknya Kota Seattle.') ON CONFLICT (id) DO NOTHING;
