INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('106bc8c9-9ed4-4b02-a2ac-9fcf503697b7', 'シアトルし', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('106bc8c9-9ed4-4b02-a2ac-9fcf503697b7', '今はシアトル市にすんでいます。', 'Saya tinggal di Seattle sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('106bc8c9-9ed4-4b02-a2ac-9fcf503697b7', 'わたしのお母さんは、シアトル市でそだちました。', 'Ibu saya dibesarkan di Seattle.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('106bc8c9-9ed4-4b02-a2ac-9fcf503697b7', 'あなたのへんがおしゃしんを、シアトル市におくります。', 'Aku akan mengirimkan foto lucumu itu ke Seattle.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d58502b-ed87-4433-85d8-af7a83bcd282', 'vocabulary', '太字', '太字', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Menurutmu apa itu surat gemuk? Jika saya bisa menebak, saya akan mengatakan huruf tebal.', 'Menurutmu apa itu surat gemuk? Jika saya bisa menebak, saya akan mengatakan huruf tebal.') ON CONFLICT (id) DO NOTHING;
