INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('926c2f65-6a64-42e8-b6f1-e258e0af411a', '年内には、かんせいするはずです。', 'Ini harus selesai dalam tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('926c2f65-6a64-42e8-b6f1-e258e0af411a', '年内にフォロワー10万人目ざします。', 'Saya menargetkan mencapai 100.000 pengikut pada akhir tahun ini.') ON CONFLICT DO NOTHING;
