INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('975cbd4d-6c7b-40a7-88e1-bfef9d96d114', 'このねこの耳はちゃいろです。', 'Telinga kucing ini berwarna coklat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('975cbd4d-6c7b-40a7-88e1-bfef9d96d114', 'パンの耳はわたしの大こうぶつです。', 'Saya suka kerak roti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('975cbd4d-6c7b-40a7-88e1-bfef9d96d114', 'わたしは、左耳をミミと名付けた。右耳はよく聞こえないので、ママと名付けた。', 'Aku menamai telinga kiriku Mimi. Telinga kananku tidak bisa mendengar dengan baik, jadi aku beri nama Mama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4177431c-f4a4-4959-b986-bdf434049da3', 'vocabulary', '耳打ち', '耳打ち', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Pukulan di telinga seseorang... Anda mungkin berpikir itu seperti berteriak di telinga mereka, tapi ternyata tidak. Anggap saja seperti Anda mendekatkan mulut Anda ke telinga mereka sehingga nyaman dan dekat sehingga Anda dapat berbisik di telinga.', 'Pukulan di telinga seseorang... Anda mungkin berpikir itu seperti berteriak di telinga mereka, tapi ternyata tidak. Anggap saja seperti Anda mendekatkan mulut Anda ke telinga mereka sehingga nyaman dan dekat sehingga Anda dapat berbisik di telinga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4177431c-f4a4-4959-b986-bdf434049da3', 'Bisikan Di Telinga', true) ON CONFLICT DO NOTHING;
