INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('231a50ad-a71f-4d6a-9a36-46aabbe8dcc3', 'ちょっと車内でまっていてください。', 'Harap tunggu di mobil sebentar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('231a50ad-a71f-4d6a-9a36-46aabbe8dcc3', 'シアトル市のバスの車内にスタバのコップをもったきょどうふしんな外人がいたとおもったら、ただのドバイのイケメン王子さまだった。', 'Ada seorang pria berpenampilan gelisah dengan cangkir Starbucks di dalam bus di Seattle, tapi sebenarnya dia adalah seorang pangeran tampan dari Dubai.') ON CONFLICT DO NOTHING;
