INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('93aa3bad-16df-460a-831e-db1a96240d2d', 'クラスの他のがく生はぜんぜん大したことのないように見えた。', 'Sepertinya siswa lain di kelas itu tidak hebat.') ON CONFLICT DO NOTHING;
