INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ad6b08f9-f5fd-41a3-928f-108d69a09828', 'vocabulary', '他人', '他人', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika Anda memiliki orang lain, Anda benar-benar memiliki orang lain.', 'Ketika Anda memiliki orang lain, Anda benar-benar memiliki orang lain.') ON CONFLICT (id) DO NOTHING;
