INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad6b08f9-f5fd-41a3-928f-108d69a09828', '他人のかねにたよるな。', 'Jangan mengandalkan uang orang lain.') ON CONFLICT DO NOTHING;
