INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02117b2b-920a-4e08-8436-3997aefebe7b', 'vocabulary', '平ら', '平ら', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis dengan sedikit hiragana yang menonjol. Karena hiragana tidak benar-benar menunjukkan apa yang dimaksud, boleh saja diasumsikan bahwa hiragana juga mempunyai arti yang sama.', 'Kanji dan kata-katanya sama persis dengan sedikit hiragana yang menonjol. Karena hiragana tidak benar-benar menunjukkan apa yang dimaksud, boleh saja diasumsikan bahwa hiragana juga mempunyai arti yang sama.') ON CONFLICT (id) DO NOTHING;
