INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02117b2b-920a-4e08-8436-3997aefebe7b', 'パソコンを、どこか平らなところにおいてください。', 'Tolong letakkan PC Anda di tempat yang datar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02117b2b-920a-4e08-8436-3997aefebe7b', 'その女の子は赤のビー玉を八つ平らなところにおいた。', 'Gadis itu meletakkan delapan kelereng merah pada suatu tempat datar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02117b2b-920a-4e08-8436-3997aefebe7b', '平らで細長いパスタの名前覚えてない？', 'Ingatkah Anda dengan nama pasta yang tipis, panjang dan pipih?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0f8c2f5-caa8-4bb0-9796-2ab68f56bb1d', 'vocabulary', '平日', '平日', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Hari-hari datar itu membosankan. Mereka sama. Hari demi hari. Itu jelas bukan akhir pekan Anda yang menyenangkan... itu hari kerja Anda yang membosankan dan datar.', 'Hari-hari datar itu membosankan. Mereka sama. Hari demi hari. Itu jelas bukan akhir pekan Anda yang menyenangkan... itu hari kerja Anda yang membosankan dan datar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a0f8c2f5-caa8-4bb0-9796-2ab68f56bb1d', 'Hari kerja', true) ON CONFLICT DO NOTHING;
