INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ee21adf-3cf3-4428-92d8-160d27f0a975', 'カブレラがホームランを打ちました。', 'Cabrera melakukan home run.') ON CONFLICT DO NOTHING;
