INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6e0ea2dd-7e80-45d2-9a63-683931c0308d', 'vocabulary', '一打', '一打', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda mendapat satu pukulan. Apa itu satu pukulan? Itu adalah satu pukulan, satu pukulan, atau hanya satu pukulan.', 'Anda mendapat satu pukulan. Apa itu satu pukulan? Itu adalah satu pukulan, satu pukulan, atau hanya satu pukulan.') ON CONFLICT (id) DO NOTHING;
