INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e0ea2dd-7e80-45d2-9a63-683931c0308d', 'ボールは、一打でグリーンにのりました。', 'Bola mendarat di lapangan dalam satu pukulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e0ea2dd-7e80-45d2-9a63-683931c0308d', 'テニスでは、さいしょの一打を「サービス」とよびます。', 'Dalam tenis, pukulan untuk memulai suatu poin disebut "servis".') ON CONFLICT DO NOTHING;
