INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('87c9264c-6e8f-4721-8afd-a665470a0057', 'vocabulary', '申す', '申す', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berkata dengan rendah hati, dan ini hanyalah bentuk kata kerjanya, mengatakan dengan rendah hati. Anda juga dapat menyebut ini untuk mengatakan, ingatlah bahwa ini rendah hati!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('87c9264c-6e8f-4721-8afd-a665470a0057', 'Mengatakan dengan Rendah Hati', true) ON CONFLICT DO NOTHING;
