INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('87c9264c-6e8f-4721-8afd-a665470a0057', 'トーフグのコウイチと申します。', 'Saya Koichi dari Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('87c9264c-6e8f-4721-8afd-a665470a0057', 'トーフグが日本のわかものにモノ申す！', 'Tofugu memberikan nasihat jujur ​​kepada generasi muda Jepang!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('87c9264c-6e8f-4721-8afd-a665470a0057', '申すまでもなく、私の上司は性転換手術をなされました。今の彼女は大変嬉しいそうだ。', 'Tentu saja bos saya menjalani operasi penegasan gender. Sekarang dia sangat bahagia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', 'vocabulary', '申し申し', '申し申し', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ini seperti Anda mengatakan katakan katakan. Inilah yang Anda ucapkan saat menjawab atau menyapa seseorang di telepon. Ada cerita aneh tentang ini. Salah satu alasan Anda mengucapkan 申し申し adalah karena rubah sulit mengatakannya. Jadi, Anda memastikan bahwa orang tersebut bukanlah rubah. Penjelasan lainnya adalah bahwa operator akan mengatakan hal ini, memberi tahu orang di saluran lain bahwa mereka sedang berbicara dengan mengatakan "katakanlah" tetapi dengan cara yang rendah hati. Apa pun yang terjadi, ini adalah sapaan telepon, jadi ucapkan halo lain kali saat Anda berbicara dengan orang Jepang di telepon... hanya untuk memastikan orang tersebut bukan rubah.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', 'Telepon Halo', true) ON CONFLICT DO NOTHING;
