INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', 'もしもし', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', '申し申し、花子ちゃん？', 'Halo? Hanako?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', 'あの、申し申し？きいていますか？？？', 'Hei, halo? Apakah kamu mendengarkan???') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('056c0bc2-a1c2-49ca-9569-24d4641a2d23', '「申し申し。鈴木と申しますが、佐藤さんはいらっしゃいますか？」', '"Halo? Ini Suzuki yang menelepon. Bisakah saya berbicara dengan Tuan Satou?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3e40a692-cf16-4025-9216-8b8174f4dffb', 'vocabulary', 'お礼', 'お礼', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Arti kata ini sama dengan kanji, hanya saja ada tanda お di depannya, yang membuat ucapan Anda lebih meninggikan orang lain. Pada dasarnya, ini lebih sopan dan mengagumkan.', 'Arti kata ini sama dengan kanji, hanya saja ada tanda お di depannya, yang membuat ucapan Anda lebih meninggikan orang lain. Pada dasarnya, ini lebih sopan dan mengagumkan.') ON CONFLICT (id) DO NOTHING;
