INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3f7bb21-4d09-4f85-8cc0-f1ac5690d849', 'トランプをよく交ぜてください。', 'Tolong campur kartunya dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3f7bb21-4d09-4f85-8cc0-f1ac5690d849', 'どうしてたくさんの男たちの中に女を一人交ぜたんだ？', 'Mengapa Anda menggabungkan seorang wanita ke dalam kelompok dengan sekelompok pria?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3f7bb21-4d09-4f85-8cc0-f1ac5690d849', '豆腐と河豚を交ぜるのは危険です。', 'Berbahaya mencampurkan tahu dan ikan buntal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d05a5e6-257f-49c9-bcf0-b4e5c90101a4', 'vocabulary', '光', '光', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
