INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d05a5e6-257f-49c9-bcf0-b4e5c90101a4', 'ひかり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d05a5e6-257f-49c9-bcf0-b4e5c90101a4', '太ようの光がまぶしいので、カーテンをしめてください。', 'Cahaya matahari menyilaukan, jadi harap tutup tirainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d05a5e6-257f-49c9-bcf0-b4e5c90101a4', '月の光にてらされて、かなえちゃんの歯がまるでパールのように見えるよ。', 'Di bawah sinar bulan, gigimu terlihat seperti mutiara, Kanae.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d05a5e6-257f-49c9-bcf0-b4e5c90101a4', '北朝鮮で行方不明になったあなたの子供には、まだ微かに希望の光が残っている。', 'Masih ada secercah harapan tersisa untuk anak Anda yang hilang di Korea Utara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', 'vocabulary', '光年', '光年', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Apa yang terjadi jika cahaya merambat dalam setahun? Anda memiliki satu tahun cahaya.', 'Apa yang terjadi jika cahaya merambat dalam setahun? Anda memiliki satu tahun cahaya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', 'Tahun cahaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', 'こうねん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', 'ちきゅうから月までは、一おく分の四光年です。', 'Jaraknya empat per seratus juta tahun cahaya dari bumi ke bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', 'ポートランドの中しんから北の方に四光年すすんだら、どこにつきますか。', 'Jika kita pergi ke utara dari pusat Portland sejauh empat tahun cahaya, di manakah kita akan berada?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1d6b89e-c717-4fc7-85cf-3d7210fab2b4', '光年とは、光の速度で1年間進み続け到達出来る距離だ。貴様が俺と対決しようなんて、一万光年早いわ。', 'Satu tahun cahaya adalah jarak yang dapat ditempuh cahaya dalam kurun waktu satu tahun. Anda 10.000 tahun cahaya terlalu dini untuk menghadapi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa42db67-9a80-4d8b-8df8-89c435aaa544', 'vocabulary', '月光', '月光', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Cahaya bulan (bukan sinar matahari!) terkadang bisa terang benderang. Ini adalah malam ketika Anda tersandung pulang dari nomikai sepulang kerja. Cahaya bulan ini disebut apa? Itu cahaya bulan. Kata ini juga bisa berarti sinar bulan.', 'Cahaya bulan (bukan sinar matahari!) terkadang bisa terang benderang. Ini adalah malam ketika Anda tersandung pulang dari nomikai sepulang kerja. Cahaya bulan ini disebut apa? Itu cahaya bulan. Kata ini juga bisa berarti sinar bulan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa42db67-9a80-4d8b-8df8-89c435aaa544', 'Cahaya bulan', true) ON CONFLICT DO NOTHING;
