INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa42db67-9a80-4d8b-8df8-89c435aaa544', 'そのよるは、月光がとてもきれいでした。', 'Cahaya bulan sangat indah malam itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa42db67-9a80-4d8b-8df8-89c435aaa544', '一りんの白い花に、月光がさえざえとふりそそいでいた。', 'Cahaya bulan yang terang menyinari bunga putih.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa42db67-9a80-4d8b-8df8-89c435aaa544', '月光に照らされた彼女は、とても美しかった。', 'Dia tampak sangat cantik di bawah sinar bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2821c993-be6a-4512-9845-561460645fa9', 'vocabulary', '日光', '日光', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda memiliki cahaya matahari. Cahaya macam apa ini? Jelas sinar matahari.', 'Anda memiliki cahaya matahari. Cahaya macam apa ini? Jelas sinar matahari.') ON CONFLICT (id) DO NOTHING;
