INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2821c993-be6a-4512-9845-561460645fa9', '日光をあびすぎるのは体によくない。', 'Mandi terlalu lama di bawah sinar matahari tidak baik untuk tubuh Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2821c993-be6a-4512-9845-561460645fa9', 'できるだけちょくしゃ日光にさらされないよう気をつけています。', 'Saya berhati-hati agar tidak terkena sinar matahari langsung.') ON CONFLICT DO NOTHING;
