INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25ab79b1-b014-4d72-a058-faeb78e17dba', '今日は、おきゃくさんと１８ホールを回りました。', 'Saya berkeliling 18 lubang dengan pelanggan hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25ab79b1-b014-4d72-a058-faeb78e17dba', '百円玉はまだつくえの上で回っています。', 'Koin 100 yen itu masih berputar di atas meja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25ab79b1-b014-4d72-a058-faeb78e17dba', '惑星が太陽の周りを回るように、その子猫たちが親猫の周りを回っている。', 'Anak-anak kucing itu berputar mengelilingi induknya seperti planet-planet berputar mengelilingi matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a33d204-607f-4ccc-ba96-12a7b527a0a7', 'vocabulary', '一回', '一回', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Satu kali adalah satu kali. Berapa kali? Hanya satu.', 'Satu kali adalah satu kali. Berapa kali? Hanya satu.') ON CONFLICT (id) DO NOTHING;
