INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a33d204-607f-4ccc-ba96-12a7b527a0a7', 'もう一回、言ってください。', 'Tolong ucapkan sekali lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a33d204-607f-4ccc-ba96-12a7b527a0a7', '平日は一日に一回シャワーをあびますが、休日はぜんぜんあびません。', 'Saya mandi sekali sehari selama seminggu, tapi tidak sama sekali selama akhir pekan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a33d204-607f-4ccc-ba96-12a7b527a0a7', 'もう一回欲しいのかい、ハニー？', 'Apakah kamu menginginkannya sekali lagi, sayang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f159f252-d331-47c5-83be-90473a2ffef4', 'vocabulary', '今回', '今回', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Saat ini adalah saat ini.', 'Saat ini adalah saat ini.') ON CONFLICT (id) DO NOTHING;
