INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f159f252-d331-47c5-83be-90473a2ffef4', '今回は、やめておきます。', 'Saya memutuskan untuk melewatkan kali ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f159f252-d331-47c5-83be-90473a2ffef4', '今回のマラソン大会では一いでした。', 'Saya adalah pemenang pertama di maraton ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f159f252-d331-47c5-83be-90473a2ffef4', '前回お前が運転した時は、岸にぶつかりそうになったじゃん。だから今回は俺が釣り船を運転するよ。', 'Saya akan mengemudikan perahu nelayan kali ini karena terakhir kali Anda mengendarainya, kita hampir menabrak pantai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('291f612b-ce97-40b6-9909-ea6699570202', 'vocabulary', '毎回', '毎回', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Setiap saat sungguh setiap saat. Apakah pembacaan kanji Anda benar 毎回?', 'Setiap saat sungguh setiap saat. Apakah pembacaan kanji Anda benar 毎回?') ON CONFLICT (id) DO NOTHING;
