INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f813abcf-e863-4ec2-bae5-1bda9110c3a2', 'たからくじで当たりが出るかくりつはとてもひくいです。', 'Peluang memenangkan lotre sangat rendah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f813abcf-e863-4ec2-bae5-1bda9110c3a2', 'あんなしょぼい当たりのゴロでヒットになるわけがない。', 'Grounder dengan pukulan lemah seperti itu tidak mungkin menjadi pukulan.') ON CONFLICT DO NOTHING;
