INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('828a7507-5d77-411e-aca8-a4a4b6860544', 'お金がないから草をたべて生きています。', 'Saya tidak punya uang, jadi saya hidup dengan makan rumput.') ON CONFLICT DO NOTHING;
