INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95305a0-1bcc-484b-9370-11701a0a7862', 'ちが、体内でどんなはたらきをしているのかしっていますか。', 'Tahukah Anda apa fungsi darah dalam tubuh?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95305a0-1bcc-484b-9370-11701a0a7862', 'カボチャに多くふくまれるβカロテンは体内でビタミンAにかわります。', 'Labu kabocha kaya akan beta-karoten dan diubah menjadi vitamin A di dalam tubuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95305a0-1bcc-484b-9370-11701a0a7862', '人間の体か吸血鬼の体かにかかわらず、血液は体内を循環する。', 'Darah beredar ke seluruh tubuh tak peduli apakah itu tubuh manusia atau tubuh vampir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b39f1f59-99f8-4264-bc6f-25443c1a0ac5', 'vocabulary', '声', '声', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
