INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47ffd59f-9e0c-4299-8e97-016eda72ebc4', 'そんな大声を出さないでください。', 'Tolong jangan gunakan suara sekeras itu.') ON CONFLICT DO NOTHING;
