INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ef1949e-55b8-4a21-b487-5331bc401833', 'つまとそうだんして、形より内ようをおもんじたけっか、この形にきめました。', 'Saya berbicara dengan istri saya dan kami memutuskan untuk memilih bentuk ini, karena kami lebih menghargai substansi daripada bentuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ef1949e-55b8-4a21-b487-5331bc401833', 'これでなんとか形がつきました。', 'Dengan ini, entah bagaimana aku bisa menjaga penampilan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ef1949e-55b8-4a21-b487-5331bc401833', 'ねえ、私の、お尻の形をしたお腹、撫でたい？', 'Hei, apakah kamu ingin menggosok perutku yang berbentuk pantat?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'vocabulary', 'ハート形', 'ハート形', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'ハート tentu saja berarti "hati" dan Anda tahu bahwa 形 berarti bentuk. Anda mungkin sudah mengetahui hal ini. Itu berbentuk hati. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'Berbentuk Hati', true) ON CONFLICT DO NOTHING;
