INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'ハートがた', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'ネイル用に、ハート形のストーンをさがしています。', 'Saya mencari batu berbentuk hati untuk digunakan pada kuku palsu saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'クリスティンは、くぎをくわえながら、ハート形のハンマーをふり回していた。', 'Kristen sedang mengayunkan palu berbentuk hati sambil memegang paku di mulutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9dab609-5d9f-46c8-8c05-ac3bb8ddabe7', 'フラミンゴがキスをする時、二羽の頭と首がハート形を描く。', 'Saat flamingo berciuman, kepala dan lehernya membentuk bentuk hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', 'vocabulary', '社内', '社内', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika Anda melakukan sesuatu di dalam perusahaan, Anda melakukannya di dalam perusahaan atau di dalam perusahaan. Misalnya, kami mengerjakan kanji kami sendiri. Ini memberinya rasa artisan.', 'Ketika Anda melakukan sesuatu di dalam perusahaan, Anda melakukannya di dalam perusahaan atau di dalam perusahaan. Misalnya, kami mengerjakan kanji kami sendiri. Ini memberinya rasa artisan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', 'Dalam Perusahaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', 'In House', false) ON CONFLICT DO NOTHING;
