INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', 'しゃない', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', 'つぎの日よう日に、社内のバスケットボール大会があります。', 'Minggu depan akan ada turnamen bola basket internal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', '花さんは、社内けっこんをしてたいしょくしました。', 'Hana keluar dari perusahaan tersebut setelah ia menikah dengan pria yang bekerja di perusahaan yang sama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ddb208db-81d7-4731-b43f-8328a2913082', '最近、社内で変なことが流行っている。従業員が、会社の冷蔵庫の中の食べ物に名前をつけるのだ。今日は、俺は、「鈴木」と名付けられたオニギリを食べた。', 'Baru-baru ini, ada tren baru yang aneh di perusahaan kami. Para pekerja memberi nama pada makanan di lemari es perusahaan. Hari ini, saya makan nasi kepal bernama "Suzuki".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', 'vocabulary', '文化', '文化', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Menulis telah mengubah seluruh budaya kita. Faktanya, ketika seseorang membaca sebuah tulisan yang bagus, hal itu akan mengubah dirinya dan mengubah budayanya juga. Tulisan apa yang begitu mengubah Anda hingga mengubah budaya dan cara Anda bertindak?', 'Menulis telah mengubah seluruh budaya kita. Faktanya, ketika seseorang membaca sebuah tulisan yang bagus, hal itu akan mengubah dirinya dan mengubah budayanya juga. Tulisan apa yang begitu mengubah Anda hingga mengubah budaya dan cara Anda bertindak?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', 'Budaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', 'ぶんか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', '日本の文化にきょうみがあります。', 'Saya tertarik dengan budaya Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', 'この国の文化にはなれましたか？', 'Apakah Anda sudah beradaptasi dengan budaya negara ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b6c98ba-1552-41e0-a52f-2c33ddc974ba', 'コスプレは日本の文化の一つですか？', 'Apakah cosplay merupakan bagian dari budaya Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac426df4-ad47-4915-9222-2361266c0dc5', 'vocabulary', '両手', '両手', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Jangan gunakan satu tangan jika Anda bisa menggunakan kedua tangan. Ini hanyalah gabungan kedua tangan. Bisa juga berarti kedua lengan.', 'Jangan gunakan satu tangan jika Anda bisa menggunakan kedua tangan. Ini hanyalah gabungan kedua tangan. Bisa juga berarti kedua lengan.') ON CONFLICT (id) DO NOTHING;
