INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f2c4c9ea-b1c4-40cc-b945-491541b6f0be', 'りょうじつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2c4c9ea-b1c4-40cc-b945-491541b6f0be', '両日とも、会ぎが入っています。', 'Saya akan menghadiri pertemuan kedua hari itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2c4c9ea-b1c4-40cc-b945-491541b6f0be', 'とうふまつりは、両日ともせい天にめぐまれた。', 'Festival tahu memiliki cuaca yang bagus untuk kedua hari tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2c4c9ea-b1c4-40cc-b945-491541b6f0be', 'iPadの使い方についての講義に両日とも参加したが、まだ使い方が分からない。', 'Saya menghadiri sesi kuliah iPad pada kedua hari tersebut, namun saya masih belum tahu cara menggunakannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3ff214df-a1be-4ba2-bc8d-d86322e889dd', 'vocabulary', '両方', '両方', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Di sini Anda memiliki kedua arah/cara. Setiap kali Anda harus memilih di antara sesuatu, rasanya seperti harus memilih di antara dua cara. Itu sebabnya kata ini berarti keduanya. 
