INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ff214df-a1be-4ba2-bc8d-d86322e889dd', '姉も妹も、両方とも大さかにすんでいます。', 'Kakak dan adik perempuan saya tinggal di Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ff214df-a1be-4ba2-bc8d-d86322e889dd', 'じかんはあるんだから、両方やってみたら？', 'Anda punya waktu, jadi mengapa Anda tidak mencoba keduanya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ff214df-a1be-4ba2-bc8d-d86322e889dd', 'ダメだよ！両方とも僕のだよ。', 'Tidak. Keduanya milikku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('601f00df-3d6d-4cf4-87e0-da6a45cf436c', 'vocabulary', '全て', '全て', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ini memiliki sedikit hiragana yang melekat padanya tetapi tidak ada yang menunjukkan bahwa itu adalah kata kerja atau kata sifat. Artinya, Anda dapat berasumsi bahwa kata ini memiliki arti yang sama dengan kanji induknya.', 'Ini memiliki sedikit hiragana yang melekat padanya tetapi tidak ada yang menunjukkan bahwa itu adalah kata kerja atau kata sifat. Artinya, Anda dapat berasumsi bahwa kata ini memiliki arti yang sama dengan kanji induknya.') ON CONFLICT (id) DO NOTHING;
