INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('601f00df-3d6d-4cf4-87e0-da6a45cf436c', '全てうまく行きました。', 'Semuanya berjalan lancar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('601f00df-3d6d-4cf4-87e0-da6a45cf436c', '申しわけございませんが、げんざい全てのおせきがうまっているじょうきょうでして...。', 'Maaf, tapi saat ini semua kursi sudah terisi penuh, jadi...') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('601f00df-3d6d-4cf4-87e0-da6a45cf436c', '僕が先だよ。ウィキペディアが僕の宿題を全て真似したんだ。', 'Saya orang pertama yang melakukannya. Wikipedia menyalin seluruh pekerjaan rumah saya setelahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26599277-da08-468b-81e3-6a9894f5ce8a', 'vocabulary', '全力', '全力', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika Anda mengerahkan seluruh kekuatan Anda pada sesuatu, Anda mengerahkan seluruh upaya Anda untuk mewujudkannya. Semoga itu juga yang Anda masukkan ke dalam pembelajaran kanji Anda!', 'Ketika Anda mengerahkan seluruh kekuatan Anda pada sesuatu, Anda mengerahkan seluruh upaya Anda untuk mewujudkannya. Semoga itu juga yang Anda masukkan ke dalam pembelajaran kanji Anda!') ON CONFLICT (id) DO NOTHING;
