INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26599277-da08-468b-81e3-6a9894f5ce8a', 'えきまで、全力で走りました。', 'Aku berlari sekuat tenaga menuju stasiun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26599277-da08-468b-81e3-6a9894f5ce8a', 'その中国人の女は、王子が自分とけっこんしてくれるよう全力でせっとくしたが、しっぱいにおわった。', 'Wanita Tionghoa itu berusaha sekuat tenaga membujuk pangeran untuk menikahinya, tetapi dia gagal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26599277-da08-468b-81e3-6a9894f5ce8a', 'そのゾンビは、死から蘇ろうと全力を尽くしていた。', 'Zombi itu menggunakan seluruh kekuatannya untuk mencoba bangkit dari kematian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e6136fbe-a3a4-454e-9a4d-ae40b01815da', 'vocabulary', '全日本', '全日本', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu 日本 berarti "Jepang". Jadi, sekarang Anda sudah menambahkan kanji untuk semua, sehingga menjadi kata All Japan (seperti dalam "All Japan Railways" atau semacamnya).', 'Anda tahu 日本 berarti "Jepang". Jadi, sekarang Anda sudah menambahkan kanji untuk semua, sehingga menjadi kata All Japan (seperti dalam "All Japan Railways" atau semacamnya).') ON CONFLICT (id) DO NOTHING;
