INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6136fbe-a3a4-454e-9a4d-ae40b01815da', 'これは、全日本バレーボール大会のしあいの写しんです。', 'Ini adalah gambar pertandingan turnamen Bola Voli Nasional Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6136fbe-a3a4-454e-9a4d-ae40b01815da', 'コウイチは、けん道の全日本せん手けんのしあいを見るために、日本に行っています。', 'Koichi berada di Jepang untuk menonton Kejuaraan Kendo Seluruh Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6136fbe-a3a4-454e-9a4d-ae40b01815da', '全日本が生クリームに包まれている。', 'Seluruh Jepang dilapisi krim kocok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c065d3ad-e112-4dcb-97ec-0df09fcb92e0', 'vocabulary', '安全', '安全', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika Anda semua santai, Anda akhirnya aman dan selamat.', 'Ketika Anda semua santai, Anda akhirnya aman dan selamat.') ON CONFLICT (id) DO NOTHING;
