INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dba75266-3426-44aa-b66b-db58c78e9252', '平安じだいはいつですか。', 'Kapankah zaman Heian?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dba75266-3426-44aa-b66b-db58c78e9252', '平安をみだす人がいないワニカニフォーラムは、わたしの心に平安をあたえてくれる。', 'Forum WaniKani tidak memiliki troll apa pun, jadi ini memberi saya ketenangan pikiran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dba75266-3426-44aa-b66b-db58c78e9252', 'ブリティッシュコロンビアの古の森を歩く時、心に平安を感じる。', 'Berjalan melalui hutan tua di British Columbia sungguh damai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8daaa99f-f47b-46db-ae32-4145dfcb956b', 'vocabulary', '曲', '曲', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ini hampir mempunyai arti yang sama dengan kanji. Pada hakikatnya adalah hal yang sama, meskipun jika berdiri sendiri, ia mengacu pada karya musik tertentu (alias sebuah lagu).', 'Ini hampir mempunyai arti yang sama dengan kanji. Pada hakikatnya adalah hal yang sama, meskipun jika berdiri sendiri, ia mengacu pada karya musik tertentu (alias sebuah lagu).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8daaa99f-f47b-46db-ae32-4145dfcb956b', 'Lagu', true) ON CONFLICT DO NOTHING;
