INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8daaa99f-f47b-46db-ae32-4145dfcb956b', 'その曲の名まえ、何だったっけ。', 'Apa nama lagu itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8daaa99f-f47b-46db-ae32-4145dfcb956b', '何かおすすめの曲はありますか？', 'Apakah ada lagu yang kamu rekomendasikan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8daaa99f-f47b-46db-ae32-4145dfcb956b', '彼がピアノで一曲弾いてくれたんですが、何故かそのピアノはギターの様な音がしたんです。', 'Dia memainkan sebuah lagu untuk kami di piano, tapi entah kenapa, pianonya terdengar seperti gitar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'vocabulary', '名曲', '名曲', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Musik terkenal adalah musik terkenal.', 'Musik terkenal adalah musik terkenal.') ON CONFLICT (id) DO NOTHING;
