INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'Masterpiece', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'めいきょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'クリスマスソングの名曲といえば、何だと思いますか。', 'Berbicara tentang lagu-lagu Natal yang terkenal, bagaimana menurut Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'この曲は名曲だと言われているけど、わたしには他の曲と大してかわりない。', 'Ini dikenal sebagai karya musik yang luar biasa, tetapi bagi saya itu sama seperti musik lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8b78a2f-6540-4875-9ab4-b094b1b88bac', 'ベートーベンの「スモークサーモン」は名曲だ。', '"Smoked Salmon" karya Beethoven adalah sebuah mahakarya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e462415-ce93-4a2e-859f-da99474731dc', 'vocabulary', '次', '次', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
