INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e462415-ce93-4a2e-859f-da99474731dc', '次のでん車にのりましょう。', 'Ayo naik kereta berikutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e462415-ce93-4a2e-859f-da99474731dc', '次のよていは、決まり次だいお知らせします。', 'Saya akan memberi tahu Anda setelah kami memutuskan rencana selanjutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e462415-ce93-4a2e-859f-da99474731dc', 'このバスツアーの次の目的地は、マイケル・ジャクソンの家です。', 'Destinasi selanjutnya dalam bus tour ini adalah rumah Michael Jackson.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9e514170-f210-4d94-87c7-d5fc4753cfde', 'vocabulary', '次回', '次回', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Lain kali Anda melihat kanji ini, Anda harus tahu artinya lain kali.', 'Lain kali Anda melihat kanji ini, Anda harus tahu artinya lain kali.') ON CONFLICT (id) DO NOTHING;
