INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e514170-f210-4d94-87c7-d5fc4753cfde', '次回の作ひんも、たのしみにしています。', 'Saya menantikan produksi berikutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e514170-f210-4d94-87c7-d5fc4753cfde', '次回なんてないんだよ。人生は一どきりなんだから。', 'Tidak ada waktu berikutnya. Kita hanya hidup sekali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e514170-f210-4d94-87c7-d5fc4753cfde', '兄貴、心配するなよ。次回は絶対あいつらを仕留めてやろうぜ。', 'Jangan khawatir, kawan. Kami akan mendapatkannya lain kali, yo.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ce85041c-32c4-4f23-be3c-8407cf706b19', 'vocabulary', '目次', '目次', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Mata Anda tertuju pada apa yang selanjutnya. Bagaimana mungkin untuk melihat apa yang akan terjadi? Itu karena Anda sedang melihat daftar isi.', 'Mata Anda tertuju pada apa yang selanjutnya. Bagaimana mungkin untuk melihat apa yang akan terjadi? Itu karena Anda sedang melihat daftar isi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ce85041c-32c4-4f23-be3c-8407cf706b19', 'Daftar Isi', true) ON CONFLICT DO NOTHING;
