INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce85041c-32c4-4f23-be3c-8407cf706b19', '目次のページがやぶれています。', 'Halaman daftar isi robek.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce85041c-32c4-4f23-be3c-8407cf706b19', '先ずはじめに、目次をごせつ明いたします。', 'Pertama, saya ingin menjelaskan daftar isi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce85041c-32c4-4f23-be3c-8407cf706b19', 'この本全部読まないとだめ？目次だけ読むってことは無理かな？', 'Apakah saya harus membaca keseluruhan buku ini? Tidak bisakah saya membaca daftar isi saja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('deb5f147-0cd7-4726-a522-43fd7c483a64', 'vocabulary', '年次', '年次', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Tahun berikutnya akan segera tiba. Apa yang akan Anda lakukan di tahun berikutnya seperti yang Anda lakukan tahun ini juga? Apa yang Anda lakukan yang bersifat tahunan?', 'Tahun berikutnya akan segera tiba. Apa yang akan Anda lakukan di tahun berikutnya seperti yang Anda lakukan tahun ini juga? Apa yang Anda lakukan yang bersifat tahunan?') ON CONFLICT (id) DO NOTHING;
