INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('deb5f147-0cd7-4726-a522-43fd7c483a64', '今年の年次けいかくを立てましょう。', 'Mari kita putuskan proyek tahunan tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('deb5f147-0cd7-4726-a522-43fd7c483a64', 'マリ子は年次有きゅう休か、何日もらえるの？', 'Berapa cuti tahunan yang kamu dapat, Mariko?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('deb5f147-0cd7-4726-a522-43fd7c483a64', '生徒たちの日本語がどれだけ上達したかに関する年次報告書を作成する。', 'Kami menulis laporan tahunan tentang seberapa besar kemajuan siswa bahasa Jepang kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1086ade8-ecd4-4aa6-ba8d-adc405a65006', 'vocabulary', '全国', '全国', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika sesuatu melibatkan seluruh negara, Anda tahu itu bersifat nasional atau nasional.', 'Ketika sesuatu melibatkan seluruh negara, Anda tahu itu bersifat nasional atau nasional.') ON CONFLICT (id) DO NOTHING;
