INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1086ade8-ecd4-4aa6-ba8d-adc405a65006', '全国でインフルエンザがはやっています。', 'Flu menyebar secara nasional.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1086ade8-ecd4-4aa6-ba8d-adc405a65006', 'リンゴのしゅうかくりょうが全国で一ばん多いけんはどこですか？', 'Prefektur manakah yang merupakan penghasil apel terbesar secara nasional?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1086ade8-ecd4-4aa6-ba8d-adc405a65006', '彼は全国規模のサイバーいじめのスキャンダルに関与していた。', 'Dia terlibat dalam skandal cyberbullying nasional.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b03cfc0b-b7c7-41ba-bcb0-8e559ba4f8d7', 'vocabulary', '米国', '米国', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Amerika adalah negara beras. Saya kira ini berasal dari semua dataran berbukit dan semacamnya yang kita miliki. Cara lain untuk mengatakan Amerika dalam bahasa Jepang adalah アメリカ, tapi ini adalah cara lain yang lebih formal (dan lebih tua). "Negeri Beras" alias Amerika Serikat, Amerika Serikat, Amerika, atau Amerika Serikat.', 'Amerika adalah negara beras. Saya kira ini berasal dari semua dataran berbukit dan semacamnya yang kita miliki. Cara lain untuk mengatakan Amerika dalam bahasa Jepang adalah アメリカ, tapi ini adalah cara lain yang lebih formal (dan lebih tua). "Negeri Beras" alias Amerika Serikat, Amerika Serikat, Amerika, atau Amerika Serikat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b03cfc0b-b7c7-41ba-bcb0-8e559ba4f8d7', 'Amerika Serikat', true) ON CONFLICT DO NOTHING;
