INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b03cfc0b-b7c7-41ba-bcb0-8e559ba4f8d7', '米国の大とうりょうの名まえを知っていますか。', 'Tahukah Anda nama presiden Amerika Serikat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b03cfc0b-b7c7-41ba-bcb0-8e559ba4f8d7', '米国には元々何もきたいなんてしてなかったよ。', 'Saya tidak pernah mengharapkan apa pun dari AS.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b03cfc0b-b7c7-41ba-bcb0-8e559ba4f8d7', '多くの人は、単にマクドナルドのスーパーサイズコンボのために米国に移住する。', 'Banyak orang berimigrasi ke Amerika Serikat hanya untuk menikmati kombo ukuran super di McDonald''s.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba0024a0-89c1-4c4a-a85c-eacdf42b4c28', 'vocabulary', '交通', '交通', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Meskipun jalur ini tercampur aduk, sistem lalu lintas dan transportasi modern sungguh menakjubkan. Kata ini mengacu pada lalu lintas dan angkutan pejalan kaki, sepeda, mobil, bus, kereta api, pesawat... apapun yang membawa kita dari A ke B.', 'Meskipun jalur ini tercampur aduk, sistem lalu lintas dan transportasi modern sungguh menakjubkan. Kata ini mengacu pada lalu lintas dan angkutan pejalan kaki, sepeda, mobil, bus, kereta api, pesawat... apapun yang membawa kita dari A ke B.') ON CONFLICT (id) DO NOTHING;
