INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba0024a0-89c1-4c4a-a85c-eacdf42b4c28', 'ここでは、交通じこがよくおきるんです。', 'Kecelakaan lalu lintas banyak terjadi di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba0024a0-89c1-4c4a-a85c-eacdf42b4c28', '交通安全のためにシートベルトをしてください。', 'Harap kenakan sabuk pengaman Anda untuk keselamatan lalu lintas.') ON CONFLICT DO NOTHING;
