INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af865f88-6d39-4a0c-97a9-8f7698943232', 'vocabulary', '全身', '全身', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Keseluruhan seseorang adalah keseluruhan tubuh seseorang.', 'Keseluruhan seseorang adalah keseluruhan tubuh seseorang.') ON CONFLICT (id) DO NOTHING;
