INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af865f88-6d39-4a0c-97a9-8f7698943232', 'わたし、全身毛むくじゃらのワイルドな男せいがすきなんです。', 'Saya suka pria yang seluruh tubuhnya ditutupi rambut tebal dan liar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af865f88-6d39-4a0c-97a9-8f7698943232', 'コウイチは全身にタトゥーを入れようと思っているみたいなんだけど、どう思う？', 'Rupanya Koichi ingin menato seluruh tubuhnya. Bagaimana menurut kalian?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af865f88-6d39-4a0c-97a9-8f7698943232', '昨日七ヶ月ぶりにランニングしたから、今日は全身筋肉痛だよ。', 'Saya berlari untuk pertama kalinya dalam tujuh bulan kemarin dan sekarang seluruh tubuh saya sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6cb75f8c-6b1b-401f-9093-4f2391f45118', 'vocabulary', '両者', '両者', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ketika Anda memiliki kedua orang, Anda memiliki kedua orang tersebut. Seiring berjalannya waktu, Anda akan menyadari bahwa 者 sering kali digunakan untuk menunjukkan seseorang atau tipe seseorang, jadi ingatlah hal itu juga untuk kata-kata berikutnya!', 'Ketika Anda memiliki kedua orang, Anda memiliki kedua orang tersebut. Seiring berjalannya waktu, Anda akan menyadari bahwa 者 sering kali digunakan untuk menunjukkan seseorang atau tipe seseorang, jadi ingatlah hal itu juga untuk kata-kata berikutnya!') ON CONFLICT (id) DO NOTHING;
