INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6cb75f8c-6b1b-401f-9093-4f2391f45118', 'りょうしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cb75f8c-6b1b-401f-9093-4f2391f45118', 'それは、両者にひがあると思うよ。', 'Saya pikir mereka berdua bersalah dalam hal ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cb75f8c-6b1b-401f-9093-4f2391f45118', 'コウイチせん手とマイケルせん手、今のところ両者のじつ力はほぼご角のようです。', 'Pemain Koichi dan Pemain Michael keduanya nampaknya cukup seimbang sejauh ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cb75f8c-6b1b-401f-9093-4f2391f45118', '車両事故に関与している両者は、共に衝突時に携帯電話で話をしていた。', 'Kedua orang yang terlibat dalam kecelakaan mobil sedang berbicara di ponsel mereka pada saat kecelakaan terjadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a2785a4-168e-4a5a-831a-898a4a838efe', 'vocabulary', '回転', '回転', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda berputar X beberapa kali. Sebenarnya, waktu tidaklah begitu penting, namun perputaranlah yang penting. Itu sebabnya kata ini berputar atau memutar.', 'Anda berputar X beberapa kali. Sebenarnya, waktu tidaklah begitu penting, namun perputaranlah yang penting. Itu sebabnya kata ini berputar atau memutar.') ON CONFLICT (id) DO NOTHING;
