INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6a2785a4-168e-4a5a-831a-898a4a838efe', 'かいてん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a2785a4-168e-4a5a-831a-898a4a838efe', 'ペットのハムスターがものすごいいきおいで回し車を回転させています。', 'Hamster peliharaan saya sedang memutar roda hamsternya dengan penuh semangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a2785a4-168e-4a5a-831a-898a4a838efe', 'あそこの回転ずし、もう行った？なんか、そこのすししょく人は皿がきらいらしく、すしが回転してあつくなってるコンベアベルトの上に直でおかれているらしいよ。', 'Apakah Anda pernah ke restoran sushi ban berjalan di sana? Rupanya koki sushi mereka tidak menyukai piring di sana, jadi sushi langsung disajikan di ban berjalan yang berputar dan panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a2785a4-168e-4a5a-831a-898a4a838efe', '月は地球の周り回転していて、地球は太陽の周りを回転している。', 'Bulan berputar mengelilingi bumi dan bumi berputar mengelilingi matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', 'vocabulary', '太平洋', '太平洋', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Samudera perdamaian yang besar adalah Samudera Pasifik. Orang Jepang menganggap lautan ini damai, sama seperti bahasa Inggris (kata 太平 sebenarnya berarti "perdamaian").
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', 'Samudera Pasifik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', 'たいへいよう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', 'トーフグチームは、ごうか客せんで太平洋をわたる社いんりょ行をけいかくしています。', 'Tim Tofugu merencanakan retret perusahaan untuk melakukan perjalanan melintasi Samudra Pasifik dengan kapal pesiar mewah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', '冷ぞうこの中の太平洋クロマグロは、カナエちゃんのお土産です。', 'Tuna sirip biru Pasifik di lemari es itu adalah oleh-oleh Kanae.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dadcafc6-5e80-4337-964e-34283df7f3ff', '現在、ほとんどの河豚は繁殖期である春に収穫され、太平洋に浮かぶ籠の中で養殖されます。', 'Saat ini, sebagian besar ikan buntal dipanen pada musim semi saat musim pemijahan, kemudian dibudidayakan di keramba apung di Samudera Pasifik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f512f686-daf4-4eb5-9bba-171ca5934f72', 'vocabulary', '全員', '全員', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Semua anggota berarti semua anggota. Ini juga merupakan cara yang bagus untuk mengatakan kepada semua orang.', 'Semua anggota berarti semua anggota. Ini juga merupakan cara yang bagus untuk mengatakan kepada semua orang.') ON CONFLICT (id) DO NOTHING;
