INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f512f686-daf4-4eb5-9bba-171ca5934f72', 'トーフグの社員は、全員がベーコンソムリエのしけんを受けることになりました。', 'Mereka memutuskan bahwa setiap karyawan Tofugu akan mengikuti ujian bacon sommelier.') ON CONFLICT DO NOTHING;
