INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('95a0d560-abe3-4730-8df7-c24d5a16bd82', 'vocabulary', '引き分け', '引き分け', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Saat Anda menarik sesuatu dan memisahkannya, Anda membuat semuanya menjadi rata. Dalam sebuah pertandingan, ini akan menjadi seri atau seri.', 'Saat Anda menarik sesuatu dan memisahkannya, Anda membuat semuanya menjadi rata. Dalam sebuah pertandingan, ini akan menjadi seri atau seri.') ON CONFLICT (id) DO NOTHING;
