INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9543f6a8-2f99-414a-af02-81f5ae94d1af', 'しんじられないような出来ごとが次々とおこったんです。', 'Peristiwa yang tampaknya sulit dipercaya terjadi satu demi satu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9543f6a8-2f99-414a-af02-81f5ae94d1af', 'コウイチかんとくは、さく夜、Youtubeで次々とヒット作を生み出すゆめを見ました。', 'Tadi malam, Sutradara Koichi bermimpi bahwa dia membuat YouTube menjadi hit demi hit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9543f6a8-2f99-414a-af02-81f5ae94d1af', 'ヨーロッパの街は、次々と疫病に侵されていった。', 'Satu demi satu, kota-kota di Eropa dilanda wabah penyakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2ce6bdae-1bb0-41ee-9ed2-95df66f25f02', 'vocabulary', '向こう', '向こう', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu bahwa 向 berarti di sana. Jadi, pikirkan "yang di sana こういち". Yang Anda tahu hanyalah dia ada di sisi lain / berlawanan dari tempat Anda berada. Pada dasarnya, dia cukup jauh, dimanapun dia berada.', 'Anda tahu bahwa 向 berarti di sana. Jadi, pikirkan "yang di sana こういち". Yang Anda tahu hanyalah dia ada di sisi lain / berlawanan dari tempat Anda berada. Pada dasarnya, dia cukup jauh, dimanapun dia berada.') ON CONFLICT (id) DO NOTHING;
