INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcffbd54-58db-45cc-b038-5558e3e904fd', '三つ目のしんごうを、右に曲がってください。', 'Silakan belok kanan pada lampu ketiga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcffbd54-58db-45cc-b038-5558e3e904fd', 'そのカレー色のネクタイ、ちょっと曲がってるよ。', 'Dasi berwarna kari Anda agak bengkok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcffbd54-58db-45cc-b038-5558e3e904fd', '野球のボールが当たってから、僕の小指はちょっとだけ左に曲がっています。', 'Sejak dipukul dengan bola baseball, jari kelingkingku sedikit menekuk ke kiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', 'vocabulary', '南米', '南米', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Ingat bagaimana 米国 juga bisa berarti Amerika? Hal ini sebenarnya berlaku untuk Amerika Utara dan Selatan, bukan hanya Amerika Serikat. Jadi, Amerika Selatan adalah Amerika Selatan.', 'Ingat bagaimana 米国 juga bisa berarti Amerika? Hal ini sebenarnya berlaku untuk Amerika Utara dan Selatan, bukan hanya Amerika Serikat. Jadi, Amerika Selatan adalah Amerika Selatan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', 'Amerika Selatan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', 'なんべい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', '学生時代に、バックパッカーとして南米をりょ行しました。', 'Di masa sekolah saya, saya melakukan perjalanan backpacking ke Amerika Selatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', 'このホテルの水道水は、南米で今までのんだ水の中で一番おいしい。', 'Air keran hotel ini adalah air terbaik yang pernah saya miliki di Amerika Selatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e3b3fa-e004-45fa-a63e-2e5bb1cd667b', 'ごめんなさい。南米はアメリカの一部だと思っていました。', 'Saya minta maaf. Saya pikir Amerika Selatan adalah bagian dari Amerika Serikat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb3b85bd-5413-49a2-9b6a-575de82d426a', 'vocabulary', '全米', '全米', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Apakah Anda ingat bagaimana 米国 bisa berarti "Amerika?" Itu 米 kadang-kadang berarti Amerika. Jadi, ketika Anda melihat semua beras (maksud saya, Amerika), Anda dapat menganggap kata ini berarti Seluruh Amerika (seperti 全日本 yang berarti "Seluruh Jepang".).', 'Apakah Anda ingat bagaimana 米国 bisa berarti "Amerika?" Itu 米 kadang-kadang berarti Amerika. Jadi, ketika Anda melihat semua beras (maksud saya, Amerika), Anda dapat menganggap kata ini berarti Seluruh Amerika (seperti 全日本 yang berarti "Seluruh Jepang".).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eb3b85bd-5413-49a2-9b6a-575de82d426a', 'Seluruh Amerika', true) ON CONFLICT DO NOTHING;
