INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b7811a8-d97b-4d45-940b-763d4049d08e', 'vocabulary', '先回り', '先回り', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Jika Anda tiba di sana sebelum sesuatu berputar (回り), Anda tiba lebih dulu, atau berjalan lebih dulu dalam antisipasi.', 'Jika Anda tiba di sana sebelum sesuatu berputar (回り), Anda tiba lebih dulu, atau berjalan lebih dulu dalam antisipasi.') ON CONFLICT (id) DO NOTHING;
