INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ce299fa0-8ca6-4373-99dc-ea0fa99eff72', 'あてる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce299fa0-8ca6-4373-99dc-ea0fa99eff72', 'この貝がら、耳に当てるとなみの音がするの。', 'Letakkan cangkang ini di telinga Anda dan Anda akan mendengar suara ombak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce299fa0-8ca6-4373-99dc-ea0fa99eff72', 'ひる休みに、だれがうそをついているのかを当てるゲームをしました。', 'Kami memainkan permainan mencoba menebak siapa yang berbohong saat istirahat makan siang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce299fa0-8ca6-4373-99dc-ea0fa99eff72', 'ボールをバットに上手く当てたと言いたかったんだけど、間違えてお尻に当てたと言ってしまった。', 'Saya ingin mengatakan, "Saya memukul bola dengan sangat baik dengan tongkat saya," tetapi saya tidak sengaja mengatakan pantat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'vocabulary', '交わる', '交わる', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu bahwa kanji berarti campuran dan kata 交ぜる berarti "mencampur", jadi mungkin ada hubungannya dengan itu. Kata ini artinya berpotongan, artinya seperti bercampur. Ketika dua hal saling bersinggungan, keduanya menjadi tercampur, sehingga dari situlah kata ini mendapatkan maknanya. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'Untuk Berpotongan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'To Cross', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'To Mingle', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'まじわる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'オレンジとあい色が交わる、夕ぐれの空が大すきなの。', 'Saya suka langit malam ketika warna oranye bertemu dengan warna biru nila.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', 'このオフィスでは、時々、日本とアメリカの文化が交わります。', 'Di kantor ini, budaya Jepang dan Amerika terkadang bersinggungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4431c82-ea05-4a5a-9912-a7e436ee36b9', '婆ちゃんの乳はとても長いので、たまに相互に交わることすらできる。', 'Payudara nenek saya sangat panjang sehingga terkadang saling bersilangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42e43948-7369-420c-984b-d18382964743', 'vocabulary', '化ける', '化ける', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti perubahan jadi Anda mungkin mengira versi kata kerjanya adalah "berubah" tapi ini sedikit berbeda. Kata ini berarti mentransformasikan diri sendiri atau bertransformasi, yang mirip dengan "berubah" namun lebih seperti ketika seseorang mengubah dirinya menjadi sesuatu yang lain, seperti dinosaurus.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti perubahan jadi Anda mungkin mengira versi kata kerjanya adalah "berubah" tapi ini sedikit berbeda. Kata ini berarti mentransformasikan diri sendiri atau bertransformasi, yang mirip dengan "berubah" namun lebih seperti ketika seseorang mengubah dirinya menjadi sesuatu yang lain, seperti dinosaurus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('42e43948-7369-420c-984b-d18382964743', 'Untuk Mengubah Diri Sendiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('42e43948-7369-420c-984b-d18382964743', 'To Be Transformed', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('42e43948-7369-420c-984b-d18382964743', 'ばける', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e43948-7369-420c-984b-d18382964743', 'かの女は、化しょうをすれば、び人に化けることで有名です。', 'Dia terkenal karena mengubah dirinya menjadi wanita cantik dengan riasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e43948-7369-420c-984b-d18382964743', 'あのようかいは、人間に化けることができる。', 'Yokai itu bisa mengubah dirinya menjadi seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e43948-7369-420c-984b-d18382964743', '私の家はリフォームの後で全く違う家に化けてしまったので、息子は学校が終わった後にどの家に帰るのか分からなくなってしまいました。', 'Rumah saya berubah total setelah renovasi sehingga anak saya tidak tahu rumah mana yang harus dia tinggali sepulang sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', 'vocabulary', '回す', '回す', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda mungkin pernah melihat kata 回る, yang artinya "berputar". Kata ini mirip, hanya saja Anda sedang melakukan tindakan memutar/memutar pada sesuatu yang lain. Anda cukup mengatakan untuk memutar sesuatu atau memutar sesuatu ketika menjawab pertanyaan ini, namun pastikan untuk membayangkan diri Anda benar-benar memutar/memutar sesuatu. Ingat ini dengan menggunakan す di akhir. Anda telah mengambil teman Anda Sue dan menjebaknya. Anda memutarnya di atas api karena Anda seorang kanibal yang sakit.', 'Anda mungkin pernah melihat kata 回る, yang artinya "berputar". Kata ini mirip, hanya saja Anda sedang melakukan tindakan memutar/memutar pada sesuatu yang lain. Anda cukup mengatakan untuk memutar sesuatu atau memutar sesuatu ketika menjawab pertanyaan ini, namun pastikan untuk membayangkan diri Anda benar-benar memutar/memutar sesuatu. Ingat ini dengan menggunakan す di akhir. Anda telah mengambil teman Anda Sue dan menjebaknya. Anda memutarnya di atas api karena Anda seorang kanibal yang sakit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', 'Untuk Mengubah Sesuatu', true) ON CONFLICT DO NOTHING;
