INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', 'まわす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', 'きのうは一日中、人さしゆびでピザを回すれんしゅうをしていました。', 'Saya berlatih memutar pizza dengan jari telunjuk saya sepanjang hari kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', 'ドアノブを回す音で、赤ちゃんの目がさめてしまいました。', 'Suara kenop pintu yang diputar membuat bayi itu terbangun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('336f7eac-7206-4412-afc3-1e739efec9be', '私がこの一ドル硬貨を十分速く回したら、もしかすると百ドル札になるかもしれない。', 'Jika saya memutar koin satu dolar dengan cukup cepat, mungkin koin itu akan berubah menjadi uang seratus dolar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'vocabulary', '〜向け', '〜向け', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Mudah-mudahan Anda sudah melihat 向く dan 向ける sekarang. Artinya "menghadapi" dan "berbalik ke arah". Ini memiliki gagasan serupa. Saat Anda menambahkan 向け ke sesuatu, bayangkan Anda memutarnya, mengarahkannya ke seseorang. Itu ditujukan untuk mereka, artinya itu dibuat untuk mereka. Arahkan sebuah buku kepada seseorang, sekarang ditujukan kepada mereka, dibuat untuk mereka. Lihat hubungannya?', 'Mudah-mudahan Anda sudah melihat 向く dan 向ける sekarang. Artinya "menghadapi" dan "berbalik ke arah". Ini memiliki gagasan serupa. Saat Anda menambahkan 向け ke sesuatu, bayangkan Anda memutarnya, mengarahkannya ke seseorang. Itu ditujukan untuk mereka, artinya itu dibuat untuk mereka. Arahkan sebuah buku kepada seseorang, sekarang ditujukan kepada mereka, dibuat untuk mereka. Lihat hubungannya?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'Dibuat Untuk', true) ON CONFLICT DO NOTHING;
