INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'むけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'これは子ども向けの作ひんではないですよね。', 'Karya ini tidak ditujukan untuk anak-anak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'このカレーは、日本人向けのあじですね。', 'Kari ini dibuat untuk selera orang Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9da67e4-d969-4653-bcc5-542032f02a1b', 'コウイチが履いてるパンツは、子供向けなんじゃないのか？ツンツルテンだよ。', 'Bukankah celana dalam yang dipakai Koichi untuk anak-anak? Pakaiannya sudah kebesaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', 'vocabulary', '化かす', '化かす', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda pernah melihat kata 化ける (mengubah) sebelumnya. Sekarang kita memiliki kata yang serupa. Kata ini artinya menyihir karena ketika kamu mengumpat (かす) kamu mengucapkan kata ajaib dan menyihir orang di depanmu. Bayangkan diri Anda meneriakkan kata-kata makian, dan setiap kali pesona baru menimpa korban Anda.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', 'Untuk Menyihir', true) ON CONFLICT DO NOTHING;
