INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', 'ばかす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', 'たぬきやきつねは、人間を化かすのがとくいだ。', 'Tanuki dan rubah pandai menyihir manusia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', 'わたしの友人はいつも化しょうで男の人を化かしています。', 'Teman saya selalu memikat pria dengan riasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f77d74be-64f6-4e95-8e0e-8ff48a4858e5', '「遅くなってすみません。いやあ、きつねに化かされちまってねえ。」「心配しないでください。それはどうしようもないことですからね。」', '“Maaf aku terlambat. Aku disihir oleh seekor rubah.” "Jangan khawatir. Hal seperti itu mau bagaimana lagi."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6cde7f13-05f2-45c6-8e5d-5736707263e7', 'vocabulary', '向く', '向く', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu bahwa kanjinya berarti di sana, yang artinya "di sana". Ini adalah versi kata kerja dari "di sana". Meskipun demikian, "ke sana" sebenarnya bukanlah sesuatu yang penting, jadi Anda harus memikirkan apa yang terjadi jika Anda "melihat ke sana". Kata ini berarti menghadap atau berpaling ke arah. Anda melihat ke sana, tetapi Anda harus menoleh ke sana untuk melihat ke sana.', 'Anda tahu bahwa kanjinya berarti di sana, yang artinya "di sana". Ini adalah versi kata kerja dari "di sana". Meskipun demikian, "ke sana" sebenarnya bukanlah sesuatu yang penting, jadi Anda harus memikirkan apa yang terjadi jika Anda "melihat ke sana". Kata ini berarti menghadap atau berpaling ke arah. Anda melihat ke sana, tetapi Anda harus menoleh ke sana untuk melihat ke sana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6cde7f13-05f2-45c6-8e5d-5736707263e7', 'Untuk Menghadapi', true) ON CONFLICT DO NOTHING;
