INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cde7f13-05f2-45c6-8e5d-5736707263e7', 'こっちを向いてください。', 'Tolong belok ke sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cde7f13-05f2-45c6-8e5d-5736707263e7', 'このへやは、南を向いているので日当たりがいい。', 'Ruangan ini menghadap ke Selatan, jadi cuacanya sangat cerah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cde7f13-05f2-45c6-8e5d-5736707263e7', '今度は、お父さんの方を向いて、どうして赤ちゃんの格好をしているのか聞いてみましょう。', 'Sekarang, mari kita menghadap ayahmu dan bertanya mengapa dia mengenakan kostum bayi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'vocabulary', '回転ずし', '回転ずし', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu bahwa 回転 adalah "rotasi" dan Anda mungkin tahu apa itu すし (dalam kata ini rendaku menjadi ずし). Jadi, apa itu "sushi rotasi?" Ini adalah sushi berputar, juga dikenal sebagai sushi ban berjalan. Carilah jika Anda tidak tahu apa itu.', 'Anda tahu bahwa 回転 adalah "rotasi" dan Anda mungkin tahu apa itu すし (dalam kata ini rendaku menjadi ずし). Jadi, apa itu "sushi rotasi?" Ini adalah sushi berputar, juga dikenal sebagai sushi ban berjalan. Carilah jika Anda tidak tahu apa itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'Memutar Sushi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'Conveyor Belt Sushi', false) ON CONFLICT DO NOTHING;
