INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'かいてんずし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', '新しく回転ずしのお店がオープンした。', 'Toko sushi conveyor belt baru dibuka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'その回転ずしは、毎秒三十二回転していました。', 'Sushi-go-round berputar dengan kecepatan 32 putaran per detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab7af3d6-b92d-4406-b182-fcd6e7a6836b', 'ねぇ、まだ準備出来てないの？お腹ペコペコなんだけど。三分以内に準備出来なかったら、先に回転寿司に行っちゃうからね！', 'Hei, masih belum siap? Saya terlalu lapar. Kami akan memutar sushi tanpa Anda, jika Anda masih belum siap dalam tiga menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'vocabulary', '回転する', '回転する', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda tahu bahwa 回転 berarti "rotasi" atau "revolusi". Jadi, apa yang terjadi jika Anda mengubahnya menjadi kata kerja? Ia menjadi berputar dan berputar.', 'Anda tahu bahwa 回転 berarti "rotasi" atau "revolusi". Jadi, apa yang terjadi jika Anda mengubahnya menjadi kata kerja? Ia menjadi berputar dan berputar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'Untuk Memutar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'To Revolve', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'かいてんする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'このコウイチ人形は、このビエト人形の周りを、時けい仕かけで高速で回転します。', 'Boneka Koichi ini berputar mengelilingi boneka Viet ini dengan kecepatan tinggi sesuai jarum jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'マイケルは、ふれずにそのボールを回転させることができます。', 'Michael bisa membuat bola berputar tanpa menyentuhnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5201badc-5cce-4705-977f-aca7c44a3396', 'この回転椅子はこんな風に回転するんだ。', 'Kursi putar berputar seperti ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', 'vocabulary', '前回', '前回', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Waktu sebelumnya adalah waktu terakhir atau waktu sebelumnya', 'Waktu sebelumnya adalah waktu terakhir atau waktu sebelumnya') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', 'Terakhir Kali', true) ON CONFLICT DO NOTHING;
