INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', 'ぜんかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', '前回のじゅぎょうでは、カエルのかいぼうをしました。', 'Kelas terakhir kita membedah seekor katak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', 'それでは、前回のつづきからはじめたいと思います。', 'Oke jadi... kita akan melanjutkan dari apa yang kita akhiri terakhir kali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dce9478-f53e-4914-b41d-173d55c89497', '前回のレッスンの復習は家でちゃんとやってきましたか？', 'Apakah kalian meninjau pelajaran terakhir di rumah dengan benar?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'vocabulary', '本当', '本当', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Apa yang nyata adalah benar. Ini adalah kenyataannya. Itu juga merupakan kebenaran. Jangan percaya apapun yang tidak nyata dan benar.', 'Apa yang nyata adalah benar. Ini adalah kenyataannya. Itu juga merupakan kebenaran. Jangan percaya apapun yang tidak nyata dan benar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'Kenyataan', true) ON CONFLICT DO NOTHING;
