INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'True', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'ほんとう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'それは本当ですか？', 'Apakah itu benar?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', 'さいきんの大学生はスマホでレポートをかくってきいたけど、本当かなあ。', 'Saya mendengar bahwa saat ini mahasiswa menulis esai di ponsel pintar mereka, tetapi saya bertanya-tanya apakah itu benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91ed8dc6-a8ff-4622-a0c7-0e1591886ae6', '本当に下手なのです。', 'Aku sangat buruk dalam hal itu.') ON CONFLICT DO NOTHING;
