INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27e541a1-4cc0-42c1-aa58-08dbfd5eb0f7', 'vocabulary', '車両', '車両', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Gerbong yang memiliki lebih banyak gerbong di kedua sisinya adalah gerbong yang menghubungkan ke gerbong lain... khususnya gerbong lain. Mereka memiliki pengait di kedua sisinya, dapat dihubungkan ke mobil lain, dan memenuhi semua persyaratan kanji kata vocab ini.', 'Gerbong yang memiliki lebih banyak gerbong di kedua sisinya adalah gerbong yang menghubungkan ke gerbong lain... khususnya gerbong lain. Mereka memiliki pengait di kedua sisinya, dapat dihubungkan ke mobil lain, dan memenuhi semua persyaratan kanji kata vocab ini.') ON CONFLICT (id) DO NOTHING;
