INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8cceff30-7273-4046-bb4f-32a89f5e943f', 'vocabulary', '草地', '草地', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Rumput yang menutupi bumi adalah padang rumput. Atau kalau kurang kreatif, itu padang rumput.', 'Rumput yang menutupi bumi adalah padang rumput. Atau kalau kurang kreatif, itu padang rumput.') ON CONFLICT (id) DO NOTHING;
