INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0ea4bc1-be70-4458-9c03-7105c799c6d7', 'あの国王は、とてもよくばりです。', 'Raja itu sangat rakus.') ON CONFLICT DO NOTHING;
