INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6da247d0-3fe2-4f9f-833d-0b3062161439', 'vocabulary', '当たり前', '当たり前', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda telah melihat bagaimana 当たり berarti kesuksesan. Jika Anda pernah mengalami kesuksesan sebelumnya, segalanya setelahnya tampak cukup jelas.', 'Anda telah melihat bagaimana 当たり berarti kesuksesan. Jika Anda pernah mengalami kesuksesan sebelumnya, segalanya setelahnya tampak cukup jelas.') ON CONFLICT (id) DO NOTHING;
