INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6da247d0-3fe2-4f9f-833d-0b3062161439', 'こんな当たり前のこと、どうして分からないの？', 'Ini adalah hal yang normal, mengapa Anda tidak bisa mendapatkannya?') ON CONFLICT DO NOTHING;
