INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d8d7156a-9148-4706-9d4f-97dc8c4b6f6b', 'vocabulary', '仕草', '仕草', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Hal-hal yang akhirnya Anda lakukan di rumput dan bukan di dalam mungkin memerlukan banyak tindakan dan tindakan besar. Anda harus melakukannya di luar ruangan, di atas rumput karena jika Anda melakukannya di tempat lain, Anda mungkin akan merusak sesuatu.', 'Hal-hal yang akhirnya Anda lakukan di rumput dan bukan di dalam mungkin memerlukan banyak tindakan dan tindakan besar. Anda harus melakukannya di luar ruangan, di atas rumput karena jika Anda melakukannya di tempat lain, Anda mungkin akan merusak sesuatu.') ON CONFLICT (id) DO NOTHING;
