INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8d7156a-9148-4706-9d4f-97dc8c4b6f6b', 'かの女が花をつむ仕草が大すきです。', 'Saya suka melihatnya memetik bunga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8d7156a-9148-4706-9d4f-97dc8c4b6f6b', 'うちのクラスの先生は、仕草がいつも大げさだ。', 'Guru kelas kami selalu melebih-lebihkan gerak-geriknya.') ON CONFLICT DO NOTHING;
