INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b5f6293-c534-4768-a481-505529a6eb2d', 'vocabulary', '〜形', '〜形', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kanji dan kata tersebut memiliki arti yang sama: bentuk. Bukan sekedar bentuk, tapi juga tegang. Seperti kata kerja tegang.', 'Kanji dan kata tersebut memiliki arti yang sama: bentuk. Bukan sekedar bentuk, tapi juga tegang. Seperti kata kerja tegang.') ON CONFLICT (id) DO NOTHING;
