INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b5f6293-c534-4768-a481-505529a6eb2d', 'どうして今、過去形で言ったの？', 'Mengapa kamu hanya mengatakan itu dalam bentuk lampau?') ON CONFLICT DO NOTHING;
