INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('98962c11-b5df-4b61-bd61-1eca7e9c63ba', 'おきゃくさまのおへやは、302号室になります。', 'Kamarmu 302.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('98962c11-b5df-4b61-bd61-1eca7e9c63ba', 'このマンションの444号室はゆうれいが出ることで有名です。', 'Kamar 444 apartemen ini terkenal berhantu.') ON CONFLICT DO NOTHING;
