INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55994eea-6435-4081-8a75-07f6926b2689', 'vocabulary', '見当たる', '見当たる', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Itu terdiri dari kanji untuk melihat dan benar, jadi apa yang terjadi jika Anda melihat hal yang benar? Anda berhasil menemukan apa yang Anda cari atau temukan, jika Andalah yang tersesat dan Anda melihat orang yang tepat sedang mencari Anda.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('55994eea-6435-4081-8a75-07f6926b2689', 'Dapat Ditemukan', true) ON CONFLICT DO NOTHING;
