INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55994eea-6435-4081-8a75-07f6926b2689', 'さいふが見当たりません。', 'Saya tidak dapat menemukan dompet saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55994eea-6435-4081-8a75-07f6926b2689', 'さがしたけど、どこにも見当たらなかったんです。', 'Saya mencarinya, tetapi tidak dapat menemukannya di mana pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55994eea-6435-4081-8a75-07f6926b2689', '俺の老眼鏡が見当たらないんだ。', 'Saya tidak dapat menemukan kacamata baca saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4afa6d01-73f5-40dd-ad1f-cbaf72d25566', 'vocabulary', '外交', '外交', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Anda ingin memadukan opini-opini dari luar negara Anda ke dalam cara Anda menangani berbagai hal. Itu disebut diplomasi. Jika Anda menggabungkan negara Anda dengan negara di luar negara Anda, Anda semua akan mendapat untung!', 'Anda ingin memadukan opini-opini dari luar negara Anda ke dalam cara Anda menangani berbagai hal. Itu disebut diplomasi. Jika Anda menggabungkan negara Anda dengan negara di luar negara Anda, Anda semua akan mendapat untung!') ON CONFLICT (id) DO NOTHING;
