INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4afa6d01-73f5-40dd-ad1f-cbaf72d25566', '今日は、日本の外交についてはなしあいをしました。', 'Kami membahas diplomasi Jepang hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4afa6d01-73f5-40dd-ad1f-cbaf72d25566', '外交かんが不足している。', 'Kita kekurangan diplomat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4afa6d01-73f5-40dd-ad1f-cbaf72d25566', '日本は外交があまり上手ではない。', 'Jepang tidak pandai dalam diplomasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00def63b-1ca2-44cd-83c9-a7f1fd78d847', 'vocabulary', '小声', '小声', 3, '3a2f8b5c-6d7e-4f9a-0b1c-2d3e4f5a6b7c', 'Suara kecil sangat kecil sehingga Anda hampir tidak dapat mendengarnya. Itu suara rendah atau bisikan.', 'Suara kecil sangat kecil sehingga Anda hampir tidak dapat mendengarnya. Itu suara rendah atau bisikan.') ON CONFLICT (id) DO NOTHING;
