INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90405204-9270-4f4f-bd47-8336dbf8cf2f', '星がきらきら光っている。', 'Bintang-bintang bersinar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90405204-9270-4f4f-bd47-8336dbf8cf2f', '右のくつに、光るとりょうが付いてるよ。', 'Ada cat berkilauan di sepatu kanan Anda.') ON CONFLICT DO NOTHING;
