INSERT INTO public.item_prerequisites (item_id, requires_item_id) VALUES ('003b57cf-7c7d-46e1-9fbe-47a776eefd06', 'a23e3a2b-9bf8-4d98-a50c-95e6f36ba994') ON CONFLICT DO NOTHING;
INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('003b57cf-7c7d-46e1-9fbe-47a776eefd06', 'a23e3a2b-9bf8-4d98-a50c-95e6f36ba994') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2d81d6a2-521f-46d0-9bc4-0ff6c8d37e00', 'radical', '灬', 'boil', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Radikal ini terlihat seperti api dari kompor atau uap yang keluar dari panci berisi air. Itu karena ini adalah bisul radikal. Anda perlu merebus banyak air di atas api. Radikal ini terlihat seperti semua bagian itu sekaligus!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2d81d6a2-521f-46d0-9bc4-0ff6c8d37e00', 'Rebus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('87fdc93e-1c83-436a-ae4c-5bce1102eb3d', 'radical', '亡', 'death', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ada penutup pada singa. Dan Anda terjebak di bawah penutup singa, yang berarti Anda pasti akan menemui ajal Anda. Atau jika Anda tidak ingin mati, pikirkanlah tentang singa yang malang. Jika Anda meninggalkan singa di bawah penutup terlalu lama, kematian juga akan menimpanya. Bagaimanapun, seseorang akan mati hari ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('87fdc93e-1c83-436a-ae4c-5bce1102eb3d', 'Kematian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e56e7f59-bfcd-48cd-9f94-12685e069e4a', 'radical', '夫', 'husband', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kaum radikal yang mendasar dan besar membentuk radikal ini. Ada pria besar di tanah... siapa pria besar itu? Yang memalukan, itu suamimu. Rasakan rasa malu karena dia terjatuh ke tanah. Naik apa? Siapa? Bagaimana? (Tidak masalah.)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e56e7f59-bfcd-48cd-9f94-12685e069e4a', 'Suami', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('dbc9b4ba-3459-4883-9cb9-d8b87edd6374', 'radical', '且', 'top-hat', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Radikal ini tampak seperti topi tinggi. Itu sebabnya ini top hat!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dbc9b4ba-3459-4883-9cb9-d8b87edd6374', 'Topi Atas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b726bdb1-7cc8-4f52-a103-9d41cf662cf5', 'radical', '舟', 'boat', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ini terlihat seperti perahu yang datang ke arah Anda di dalam air. Lihat layar yang mengepul dan pantulan air? Seperti itulah penampakan perahu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b726bdb1-7cc8-4f52-a103-9d41cf662cf5', 'Perahu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e8ac00cc-53bc-4f37-998b-9ea3db31b9c7', 'radical', '支', 'branch', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ada salib yang tumbuh dari bangku ini. Itu bercabang, jika Anda mau. Pohon tempat bangku ini dibuat hidup kembali dalam bentuk dahan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8ac00cc-53bc-4f37-998b-9ea3db31b9c7', 'Cabang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b868ac9b-07d4-4a1b-b725-24419a1a4c3f', 'radical', '[cape]', 'cape', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ini jubah, seperti yang dipakai pahlawan super. Lihat bagaimana benda itu tergantung ke samping? Bayangkan mengikatnya di leher Anda dan berlarian hingga terbang di belakang Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b868ac9b-07d4-4a1b-b725-24419a1a4c3f', 'Tanjung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f1dd1726-8e5c-4184-94d1-eeda0fc51978', 'radical', '殳', 'weapon', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Tempelkan meja di atas bangku dan Anda akan mendapatkan senjata yang sangat berbahaya. Bayangkan memukul seseorang dengan benda ini! Atau, lebih baik lagi, bayangkan menyuruh seseorang duduk di atasnya. Mereka akan hancur secara mental dan emosional dan yang lainnya. Itu senjata yang menakutkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1dd1726-8e5c-4184-94d1-eeda0fc51978', 'Senjata', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('53a02aaf-b2ee-41ac-bc71-81a3a33f2946', 'radical', 'ユ', 'hook', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ada garis datar di tempat tangan terpotong. Di dalamnya ada kail seperti yang dimiliki bajak laut. Yarrrr.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('53a02aaf-b2ee-41ac-bc71-81a3a33f2946', 'Kait', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1884b79c-cb3a-48ed-8a9b-b530910317da', 'radical', '釆', 'sickle', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Sebagian besar dari radikal ini hanyalah radikal beras, tetapi bagian atasnya adalah sesuatu yang datang untuk memotong beras dari tangkainya. Itu, temanku, adalah sabitnya. Lihat bagaimana nasinya masih ada di sana? Itu karena ia sedang bergerak. Sabit itu benar-benar sedang memotong SEKARANG! (Dan jangan bingung membedakan ini dengan butiran 禾 radikal!)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1884b79c-cb3a-48ed-8a9b-b530910317da', 'Sabit', true) ON CONFLICT DO NOTHING;
