INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d1626290-8a34-462b-8ee4-8a3faa7dc33a', 'vocabulary', '死亡', '死亡', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kematian dan almarhum. Itu banyak sekali kematian. Ini adalah kematian.', 'Kematian dan almarhum. Itu banyak sekali kematian. Ini adalah kematian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d1626290-8a34-462b-8ee4-8a3faa7dc33a', 'Kematian', true) ON CONFLICT DO NOTHING;
