INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a0d0e95-0b00-4b43-98e6-6f5bf818cad1', 'こしょうした車が直るのはいつですか。', 'Kapan saya bisa memperbaiki mobil saya yang rusak?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a0d0e95-0b00-4b43-98e6-6f5bf818cad1', 'それでアヤの気げんが直るなら、おれはぜんぜんかまわないよ。', 'Kalau itu membuatmu merasa lebih baik, maka aku tidak keberatan sama sekali, Aya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a0d0e95-0b00-4b43-98e6-6f5bf818cad1', '農夫の壊れたトラクターは直った。', 'Traktor milik petani yang rusak telah diperbaiki.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49795ab2-b7ac-479f-ad13-4c133d84b641', 'vocabulary', '正直', '正直', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda sudah benar dan memperbaikinya. Ketika Anda selalu memperbaiki segala sesuatunya agar menjadi benar (misalnya, kebohongan seseorang!), Anda adalah orang yang sangat jujur.', 'Anda sudah benar dan memperbaikinya. Ketika Anda selalu memperbaiki segala sesuatunya agar menjadi benar (misalnya, kebohongan seseorang!), Anda adalah orang yang sangat jujur.') ON CONFLICT (id) DO NOTHING;
