INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49795ab2-b7ac-479f-ad13-4c133d84b641', '川田さんは、とても正直な人です。', 'Kawata adalah orang yang sangat jujur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49795ab2-b7ac-479f-ad13-4c133d84b641', 'かれの正直なところがすきなんです。', 'Saya suka kejujurannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49795ab2-b7ac-479f-ad13-4c133d84b641', '僕は水中で息をしている火星からきた王子だし、他の人の模範となる必要があるので、いつも正直でいようと心がけています。', 'Saya berusaha jujur ​​sepanjang waktu karena saya adalah pangeran Mars yang bernapas di bawah air dan saya perlu memberi contoh kepada orang-orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('238af8a3-0d5e-44b0-ad77-dbd624a83ff3', 'vocabulary', '直行', '直行', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Jika Anda berpikir tentang perjalanan langsung (alias transportasi), bagaimana Anda membuatnya lebih baik? Anda akan membuat semuanya berjalan tanpa henti dan langsung. Bayangkan saja betapa menyenangkannya jika setiap pesawat yang Anda naiki bersifat langsung dan Anda tidak perlu berhenti. Sangat bagus!', 'Jika Anda berpikir tentang perjalanan langsung (alias transportasi), bagaimana Anda membuatnya lebih baik? Anda akan membuat semuanya berjalan tanpa henti dan langsung. Bayangkan saja betapa menyenangkannya jika setiap pesawat yang Anda naiki bersifat langsung dan Anda tidak perlu berhenti. Sangat bagus!') ON CONFLICT (id) DO NOTHING;
