INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('238af8a3-0d5e-44b0-ad77-dbd624a83ff3', 'このひ行きは、東京に直行します。', 'Pesawat ini nonstop ke Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('238af8a3-0d5e-44b0-ad77-dbd624a83ff3', '今日は、日本との会ぎの後、トーフグとのアポに直行します。', 'Hari ini setelah pertemuan dengan Jepang, saya akan langsung pergi ke janji temu dengan Tofugu.') ON CONFLICT DO NOTHING;
