INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d619b2af-43fa-44db-bd10-d6ab5a1a146a', 'vocabulary', '生活', '生活', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ketika Anda memiliki kehidupan dan bersemangat, itulah kehidupan sejati. Seperti apa 生活 Anda? Apakah kamu hidup?', 'Ketika Anda memiliki kehidupan dan bersemangat, itulah kehidupan sejati. Seperti apa 生活 Anda? Apakah kamu hidup?') ON CONFLICT (id) DO NOTHING;
