INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2c526a7-74a2-41b5-8daf-f6bd55a06357', 'このクローゼットにある二点五ばいのりょうのふくが他のへやにもちらばっています。', 'Dibandingkan dengan yang ada di lemari ini, pakaian saya 2,5 kali lebih banyak berserakan di ruangan lain.') ON CONFLICT DO NOTHING;
