INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e6f5ea8-af89-4793-bb89-de38dc5760a5', 'vocabulary', '科学', '科学', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ilmu yang mempelajari ilmu pengetahuan jelas disebut sains.', 'Ilmu yang mempelajari ilmu pengetahuan jelas disebut sains.') ON CONFLICT (id) DO NOTHING;
