INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64ac2eac-068b-4fc8-b4dc-494d7d423bd2', 'パソコンのしすぎで、首がいたいです。', 'Saya terlalu sering menggunakan komputer sehingga leher saya sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64ac2eac-068b-4fc8-b4dc-494d7d423bd2', '首をねちがえました。', 'Aku menekuk leherku dalam tidurku.') ON CONFLICT DO NOTHING;
