INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70d88d29-f3ff-47f9-8fdf-797844a3b759', 'vocabulary', '足首', '足首', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Apa leher kakimu? Pikirkan tentang hal ini. Itu pergelangan kakimu.', 'Apa leher kakimu? Pikirkan tentang hal ini. Itu pergelangan kakimu.') ON CONFLICT (id) DO NOTHING;
