INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70d88d29-f3ff-47f9-8fdf-797844a3b759', '足首をひねってしまいました。', 'Aku memutar pergelangan kakiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70d88d29-f3ff-47f9-8fdf-797844a3b759', '右の足首がすごくいたいんです！', 'Pergelangan kaki kanan saya sangat sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70d88d29-f3ff-47f9-8fdf-797844a3b759', '宙に舞う羽から逃げる途中で、足首を捻挫した。', 'Pergelangan kakiku terkilir saat melarikan diri dari bulu yang melayang di udara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'vocabulary', '首になる', '首になる', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Bagian になる berarti "menjadi", jadi secara harafiah artinya "menjadi leher". Kalau dipikir-pikir, ketika sesuatu menjadi leher, itu ada hubungannya dengan kepalamu yang dipenggal (di bagian leher). Namun, dalam masyarakat modern saat ini kita tidak terlalu sering melakukan hal tersebut. Sebaliknya, ini berarti Anda kehilangan pekerjaan alias dipecat.', 'Bagian になる berarti "menjadi", jadi secara harafiah artinya "menjadi leher". Kalau dipikir-pikir, ketika sesuatu menjadi leher, itu ada hubungannya dengan kepalamu yang dipenggal (di bagian leher). Namun, dalam masyarakat modern saat ini kita tidak terlalu sering melakukan hal tersebut. Sebaliknya, ini berarti Anda kehilangan pekerjaan alias dipecat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'Akan Dipecat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'To Get Sacked', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'くびになる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', '先月、会社を首になりました。', 'Saya dipecat dari perusahaan bulan lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'しゅう金したお金をつかいこんだら、首になるに決まってるじゃん！', 'Tentu saja kalian akan dipecat, jika uang yang terkumpul sudah habis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b25a9b69-8b73-4daa-aa59-03fe8c353b30', 'マーチングバンドを職場に引き連れてきたことが理由で、私は昨日首になりました。', 'Saya dipecat kemarin karena membawa marching band ke tempat kerja bersama saya.') ON CONFLICT DO NOTHING;
