INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('51c4ec1e-fa33-4bb5-84c8-7ef76e68af2a', 'だれだって、何かしらの欠点をもってるものさ。', 'Setiap orang mempunyai kelemahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('51c4ec1e-fa33-4bb5-84c8-7ef76e68af2a', 'そうだ、ちょっと思い出したんだけど、かの女って欠点がないんだよ。', 'Oh, aku baru ingat, dia tidak punya kesalahan apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('51c4ec1e-fa33-4bb5-84c8-7ef76e68af2a', '私は欠点がありすぎるので、絶対にプロのサッカー選手にはなれません。たとえば、私には足がありません。', 'Saya tidak akan pernah menjadi pemain sepak bola profesional karena saya mempunyai terlalu banyak kekurangan, misalnya saja saya tidak mempunyai kaki.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('33d5e712-39c9-4e05-9526-01068a2ebebf', 'vocabulary', '自由', '自由', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ketika Anda memiliki alasan diri, Anda dapat berpikir sendiri. Ketika Anda bisa berpikir sendiri, Anda memiliki kebebasan. Sangat filosofis, kosakata ini.', 'Ketika Anda memiliki alasan diri, Anda dapat berpikir sendiri. Ketika Anda bisa berpikir sendiri, Anda memiliki kebebasan. Sangat filosofis, kosakata ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('33d5e712-39c9-4e05-9526-01068a2ebebf', 'Kebebasan', true) ON CONFLICT DO NOTHING;
