INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad1dd77-ec4b-4d03-89d1-534391aada49', 'かれは必ずもどってくるので、大じょうぶです。', 'Dia pasti akan kembali, jadi aku baik-baik saja.') ON CONFLICT DO NOTHING;
