INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c8bdf265-8ad3-4739-8700-156ea4ed469c', '未だ二百才まで生きた人げんはいない。', 'Masih belum pernah ada orang yang hidup sampai usia dua ratus tahun.') ON CONFLICT DO NOTHING;
