INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c8bdf265-8ad3-4739-8700-156ea4ed469c', '仕事が決まったのかどうかは未だに分からないんだ。', 'Saya tidak yakin apakah saya sudah mendapatkan pekerjaan itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63732bc9-1eeb-4f75-9370-0dea67b21f85', 'vocabulary', '未来', '未来', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Apa yang belum datang? Masa depan.', 'Apa yang belum datang? Masa depan.') ON CONFLICT (id) DO NOTHING;
