INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7545b4f3-988c-4f4f-a2d9-bfff39031b34', 'こんなあそびがはやるとは、世も末だな。', 'Jika permainan seperti ini populer, maka itu adalah akhir dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7545b4f3-988c-4f4f-a2d9-bfff39031b34', 'おたくのむす子さんは末が本当にたのしみですね。', 'Anda pasti menantikan untuk melihat seperti apa putra Anda nantinya di masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7545b4f3-988c-4f4f-a2d9-bfff39031b34', '激しい口論の末、末息子は私の金をどこかに埋めるために出て行ってしまいました。', 'Setelah berdiskusi dengan sengit, putra bungsu saya pergi untuk mengubur emas saya di suatu tempat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2ff6bd1e-34c7-4c1d-98c4-acb77a1f489f', 'vocabulary', '年末', '年末', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Akhir tahun adalah akhir tahun alias akhir tahun.', 'Akhir tahun adalah akhir tahun alias akhir tahun.') ON CONFLICT (id) DO NOTHING;
