INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ff6bd1e-34c7-4c1d-98c4-acb77a1f489f', 'すみませんが、年末は、ちょっとバタバタしてじかんがとれなさそうです。', 'Maaf, tapi saya akan sangat sibuk sekitar akhir tahun ini dan mungkin saya tidak punya waktu untuk itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ff6bd1e-34c7-4c1d-98c4-acb77a1f489f', 'マイケルは、年末にトーフグのだい二えいぎょうぶにいどうになりました。', 'Michael dipindahkan ke Divisi Penjualan II Tofugu pada akhir tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ff6bd1e-34c7-4c1d-98c4-acb77a1f489f', '年末までには、氷中毒から立ち直れるといいんだけど。', 'Saya berharap bisa mengatasi kecanduan saya terhadap es batu sebelum akhir tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b9d8cc6-94a8-4758-a8c8-6b80d31eba10', 'vocabulary', '月末', '月末', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Tahukah kamu bahwa 月 juga bisa berarti bulan? Jika Anda menambahkan 末 di sana, Anda memiliki "akhir bulan" alias akhir bulan.', 'Tahukah kamu bahwa 月 juga bisa berarti bulan? Jika Anda menambahkan 末 di sana, Anda memiliki "akhir bulan" alias akhir bulan.') ON CONFLICT (id) DO NOTHING;
