INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b9d8cc6-94a8-4758-a8c8-6b80d31eba10', '月末までに五キロやせます。', 'Saya akan kehilangan lima kilogram pada akhir bulan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b9d8cc6-94a8-4758-a8c8-6b80d31eba10', 'ここ、ブラックきぎょうすぎるから、月末ににげ出すわ。', 'Perusahaan ini terlalu banyak mengeksploitasi karyawannya, jadi saya akan memberikan dana talangan pada akhir bulan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b9d8cc6-94a8-4758-a8c8-6b80d31eba10', '私の上司は、コアラで給料を払います。毎月末、わたしには二匹のコアラが支払われます。', 'Bos saya membayar saya dengan beruang koala. Saya mendapat dua di akhir setiap bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f5ca6f5-09e8-44cb-a62d-09e9dd50e3d7', 'vocabulary', '日記', '日記', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Saat Anda menuliskan hari Anda (dan melakukannya setiap hari) itulah buku harian Anda.', 'Saat Anda menuliskan hari Anda (dan melakukannya setiap hari) itulah buku harian Anda.') ON CONFLICT (id) DO NOTHING;
