INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f5ca6f5-09e8-44cb-a62d-09e9dd50e3d7', 'あなたの日記も、この本と一しょにここにおいておきます。 ', 'Saya akan meninggalkan buku harian Anda dengan buku ini di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f5ca6f5-09e8-44cb-a62d-09e9dd50e3d7', '北米には、こうかん日記みたいな文化はないんだよ。', 'Kami tidak memiliki budaya pertukaran buku harian di Amerika Utara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f5ca6f5-09e8-44cb-a62d-09e9dd50e3d7', '昨日の夜、フグの日記を読んだんだけどさ、実はとても悲しい日記だったんだよね。', 'Saya membaca jurnal Fugu tadi malam dan sejujurnya, itu sangat menyedihkan.') ON CONFLICT DO NOTHING;
