INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da728f34-9fb8-48ee-8ef4-55899377a5c5', 'これから、みなさんを二組に分けます。', 'Setelah ini, kami akan dibagi menjadi dua tim.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da728f34-9fb8-48ee-8ef4-55899377a5c5', 'オレたちの組はこの辺じゃ有名なんだぜ。', 'Grup kami terkenal di sekitar sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da728f34-9fb8-48ee-8ef4-55899377a5c5', '三年二組のコウイチくん、またこく白されたらしいよ。', 'Kudengar Koichi di kelas 3 kelas 2 diajak kencan lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27e57143-3c1b-4110-beff-9dcb0da48027', 'vocabulary', '船', '船', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
