INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27e57143-3c1b-4110-beff-9dcb0da48027', '次の船は、何時に出ぱつしますか。', 'Jam berapa kapal selanjutnya berangkat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27e57143-3c1b-4110-beff-9dcb0da48027', '船にのると必ず船よいしちゃうんだよね。', 'Saya selalu merasa mual ketika berada di atas kapal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27e57143-3c1b-4110-beff-9dcb0da48027', '俺様が船のすべてを取り仕切る船長だ。', 'Saya kaptennya dan saya menjalankan seluruh kapal ini sendirian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', 'vocabulary', '風船', '風船', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Perahu angin. Ini tentu saja merupakan hal yang aneh. Anda mungkin berasumsi ini seperti salah satu balon raksasa yang bisa Anda naiki, dan sebagian Anda benar. Sebenarnya, kata ini mencakup kata umum balon, meskipun secara khusus berkaitan dengan balon model mainan (atau balon yang lebih kecil). Ini adalah kapal angin bulat kecil!', 'Perahu angin. Ini tentu saja merupakan hal yang aneh. Anda mungkin berasumsi ini seperti salah satu balon raksasa yang bisa Anda naiki, dan sebagian Anda benar. Sebenarnya, kata ini mencakup kata umum balon, meskipun secara khusus berkaitan dengan balon model mainan (atau balon yang lebih kecil). Ini adalah kapal angin bulat kecil!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', 'Balon', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', 'ふうせん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', 'あのピエロが、風船で犬を作ってくれたんだ。', 'Badut itu membuatkan seekor anjing dari balon untukku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', 'ひ行きによったば合は、この風船をエチケットぶくろの代わりにごしようください。', 'Silakan gunakan balon ini sebagai tas mabuk perjalanan ketika Anda merasa mabuk udara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40e35181-c8a7-4900-a550-01c09030a4fa', '風船を使って実際に空飛ぶ家を作った人たちがいます。', 'Beberapa orang justru membuat rumah terapung dengan menggunakan balon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', 'vocabulary', '週末', '週末', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Akhir minggu adalah akhir pekan... kecuali Anda bekerja pada akhir pekan, namun kami tidak dapat melayani semua orang di sini.', 'Akhir minggu adalah akhir pekan... kecuali Anda bekerja pada akhir pekan, namun kami tidak dapat melayani semua orang di sini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', 'Akhir pekan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', 'しゅうまつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', '週末は、おきなわにりょ行に行っていました。', 'Saya berada di Okinawa selama akhir pekan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', 'せん週末、雪が十センチつもりました。', 'Kami mendapat salju setinggi 10 sentimeter akhir pekan lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec7c5a01-96f5-4d5c-b287-5ba5866b0894', '宝くじに当たったんだけど、週末ローマにピザでも食べに行かない？', 'Kami baru saja memenangkan lotre, jadi apakah Anda ingin pergi ke Roma akhir pekan ini untuk makan pizza?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('33ee10ec-7f08-4517-bc48-3f444ec497b8', 'vocabulary', '雪', '雪', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
