INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('33ee10ec-7f08-4517-bc48-3f444ec497b8', 'ゆき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33ee10ec-7f08-4517-bc48-3f444ec497b8', '日本でも、雪がふりますか？', 'Apakah di Jepang juga turun salju?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33ee10ec-7f08-4517-bc48-3f444ec497b8', 'そっちも雪、つもった？', 'Apakah kamu juga mendapat salju di sana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33ee10ec-7f08-4517-bc48-3f444ec497b8', '私が初めて雪を見たのは、四十六歳の時でした。', 'Pertama kali saya melihat salju adalah ketika saya berumur 46 tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('44917993-f51b-4fd5-bd39-036ecad14ec5', 'vocabulary', '馬', '馬', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
