INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44917993-f51b-4fd5-bd39-036ecad14ec5', 'あの馬に、ニンジンやリンゴをあげてもいいですか？', 'Bolehkah memberi wortel dan apel pada kuda itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44917993-f51b-4fd5-bd39-036ecad14ec5', 'わたしの馬は、また一つこんなんをのりこえました。', 'Kudaku telah mengatasi kesulitan lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44917993-f51b-4fd5-bd39-036ecad14ec5', 'お年寄りたちが次から次へと馬から落ちたの、めちゃくちゃ面白いと思うんだけど〜！', 'Saya merasa sangat lucu ketika orang-orang tua jatuh dari kuda satu demi satu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('634dedb6-20df-456e-b5fb-f832d2def351', 'vocabulary', '馬力', '馬力', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kata ini mungkin dibuat baru-baru ini. Kekuatan seekor kuda? Itu adalah tenaga kuda.', 'Kata ini mungkin dibuat baru-baru ini. Kekuatan seekor kuda? Itu adalah tenaga kuda.') ON CONFLICT (id) DO NOTHING;
