INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a2928718-6f35-4ec7-a310-cca83fe2bfda', 'してん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2928718-6f35-4ec7-a310-cca83fe2bfda', 'わたしのおっとは、大さか支店の支店長をつとめています。', 'Suami saya adalah manajer cabang di cabang Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2928718-6f35-4ec7-a310-cca83fe2bfda', 'この支店には、一人で行どうすることがすきな人もはたらいている。', 'Di toko cabang ini, ada juga pekerja yang suka melakukan sesuatu sendirian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2928718-6f35-4ec7-a310-cca83fe2bfda', '支店長の髭は少し長すぎる。', 'Kumis manajer cabang kami agak terlalu panjang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('186c275f-e98d-4872-965e-b5080becaf20', 'vocabulary', '住民', '住民', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Masyarakat yang bertempat tinggal di sini adalah penduduk.', 'Masyarakat yang bertempat tinggal di sini adalah penduduk.') ON CONFLICT (id) DO NOTHING;
