INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('48a89802-5a07-4d62-94c0-7273540a7b15', 'じょしゅ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48a89802-5a07-4d62-94c0-7273540a7b15', 'ワトソンはかせは、シャーロック・ホームズの助手ではなく、あくまで友人です。', 'Dr Watson bukan hanya asisten Sherlock Holmes, dia adalah temannya sampai akhir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48a89802-5a07-4d62-94c0-7273540a7b15', 'わたしの助手は、年末に肉ばなれになりました。', 'Ajudan saya mengalami cedera otot pada akhir tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48a89802-5a07-4d62-94c0-7273540a7b15', 'もし私が今首になった助手の助手だとしたら、それってつまり私も首になっちゃったってこと？', 'Jika saya asisten dari asisten yang baru saja dipecat, apakah itu berarti saya juga dipecat?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'vocabulary', '助言', '助言', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ketika Anda mengatakan hal-hal yang membantu, Anda sedang memberikan nasihat, meskipun tidak semua orang akan menganggapnya baik.', 'Ketika Anda mengatakan hal-hal yang membantu, Anda sedang memberikan nasihat, meskipun tidak semua orang akan menganggapnya baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'Saran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'じょげん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'あなたの助言、ぜんぜん役に立たなかったんだけど。', 'Tapi saran Anda tidak membantu sama sekali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'かの女の助言にしたがって、コウイチはついにタバコをやめたんだよ。', 'Sesuai dengan saran pacarnya, Koichi akhirnya berhenti merokok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('715bb585-a3f4-4276-8445-5f76355eca79', 'そのチョコレートをくれたら、助言をあげるわ。', 'Aku akan memberimu saran, jika kamu memberiku coklat itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e8d620a-b4bd-4fe6-a92a-d24794f7988a', 'vocabulary', '君主国', '君主国', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Saat Anda berteman dengan penguasa suatu negara, Anda akan mendapat imbalan yang sangat besar. Mengapa? Karena ini adalah monarki di mana berteman dengan tuannya adalah hal yang sangat menguntungkan!', 'Saat Anda berteman dengan penguasa suatu negara, Anda akan mendapat imbalan yang sangat besar. Mengapa? Karena ini adalah monarki di mana berteman dengan tuannya adalah hal yang sangat menguntungkan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e8d620a-b4bd-4fe6-a92a-d24794f7988a', 'Monarki', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7e8d620a-b4bd-4fe6-a92a-d24794f7988a', 'くんしゅこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e8d620a-b4bd-4fe6-a92a-d24794f7988a', '天のうのいる日本は君主国ですか、それとも民主国ですか？', 'Jepang punya kaisar, jadi monarki atau demokrasi?') ON CONFLICT DO NOTHING;
