INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a65dfd0-1024-4ccd-887d-06d9aacbd8ac', 'vocabulary', '対する', '対する', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Saat Anda melakukan (する) versus Anda menggabungkan dua hal untuk dibandingkan satu sama lain. Bayangkan menempatkan dua anjing dalam satu ring (tunjukkan anjing, bukan anjing aduan, ayolah). Kemudian seseorang mengumumkan permulaannya, dan para juri melihat mereka, mencoba membandingkan satu sama lain untuk memutuskan mana yang lebih baik.
