INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fe0bfc9c-607d-4d33-a0e7-a5aa868c15cf', 'やくにたつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fe0bfc9c-607d-4d33-a0e7-a5aa868c15cf', '日本ごのべん強の役に立つサイトを見つけました。', 'Saya menemukan situs web yang berguna untuk belajar bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fe0bfc9c-607d-4d33-a0e7-a5aa868c15cf', 'ハンガリーには、にげるははじだが役に立つ、ということわざがあります。', 'Di Hungaria ada pepatah yang artinya, “Melarikan diri itu memalukan, tapi berguna.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fe0bfc9c-607d-4d33-a0e7-a5aa868c15cf', 'ゾンビがいっぱいの町を歩くなら、銃よりも剣の方が役に立つだろうか？', 'Akankah pedang lebih berguna daripada senjata untuk berjalan melewati kota yang penuh dengan zombie?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c317f532-b150-47c4-b117-828ebcabab13', 'vocabulary', '大役', '大役', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Tugas besar adalah tugas besar. Ini juga bisa menjadi tugas penting. Pikirkan tentang tugas besar yang Anda miliki. Kemudian, pikirkan betapa pentingnya tugas itu juga. Banggalah dengan tugas penting Anda.', 'Tugas besar adalah tugas besar. Ini juga bisa menjadi tugas penting. Pikirkan tentang tugas besar yang Anda miliki. Kemudian, pikirkan betapa pentingnya tugas itu juga. Banggalah dengan tugas penting Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c317f532-b150-47c4-b117-828ebcabab13', 'Tugas Penting', true) ON CONFLICT DO NOTHING;
