INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c317f532-b150-47c4-b117-828ebcabab13', 'この大役をしっかりはたせるよう、一生けんめいがんばります！', 'Saya akan berusaha sekuat tenaga untuk berhasil menyelesaikan tugas penting ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c317f532-b150-47c4-b117-828ebcabab13', 'ずい分とまた大役を買って出たものだね。', 'Anda mengajukan diri untuk tugas yang begitu besar, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c317f532-b150-47c4-b117-828ebcabab13', 'ロード・オブ・ザ・リングでフロドは大役を任されたが、靴も履かずに見事にやってのけた。', 'Frodo, sang Lord of the Rings, diberi tugas paling penting dan dia melakukan semuanya tanpa mengenakan sepatu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3adcda3-9b03-423b-a281-859c1ef64502', 'vocabulary', '決', '決', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Versi kata benda dari memutuskan? Itu sebuah keputusan.', 'Versi kata benda dari memutuskan? Itu sebuah keputusan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3adcda3-9b03-423b-a281-859c1ef64502', 'Keputusan', true) ON CONFLICT DO NOTHING;
