INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e33bd9f8-07a5-4cdc-a555-1b17a7c420d0', 'けっしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e33bd9f8-07a5-4cdc-a555-1b17a7c420d0', 'あなたのおかげで、せい形手じゅつをする決心がつきました。', 'Berkatmu, aku memutuskan untuk menjalani operasi plastik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e33bd9f8-07a5-4cdc-a555-1b17a7c420d0', 'インスタセレブになるというトーフグの決心はトウフと同じぐらいかたい。', 'Resolusi Tofugu untuk menjadi selebriti Instagram sama kuatnya dengan Tofu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e33bd9f8-07a5-4cdc-a555-1b17a7c420d0', 'ついに、あなたに、どこから私の誕生日プレゼントの酒を買ってきてもらうか決心したよ。それは…日本だ。楽しんできてね！', 'Aku akhirnya memutuskan di mana kamu akan membelikanku minuman untuk ulang tahunku... Di Jepang. Menikmati!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d7c29b0d-d994-4c67-8460-b49946293cae', 'vocabulary', '未決', '未決', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Sesuatu yang belum diputuskan... sedang menunggu... belum terselesaikan.', 'Sesuatu yang belum diputuskan... sedang menunggu... belum terselesaikan.') ON CONFLICT (id) DO NOTHING;
