INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b96c77e4-5fa5-452b-91a4-5fd96a98f200', 'あのさむらいは自決した。', 'Samurai itu bunuh diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b96c77e4-5fa5-452b-91a4-5fd96a98f200', 'コウイチ社長は、トーフグは自決けんを強く心からしじするということを、何どもくりかえした。', 'Presiden Koichi menegaskan kembali dukungan Tofugu yang kuat dan sepenuh hati terhadap hak kita untuk menentukan nasib sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b96c77e4-5fa5-452b-91a4-5fd96a98f200', '彼は、獄中で絶望し、自決してしまったんです。', 'Dia mengalami depresi selama dipenjara dan bunuh diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3c552337-9f62-4bfc-99f0-59a71aede8ae', 'vocabulary', '投げる', '投げる', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melempar jadi versi verbanya artinya melempar.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melempar jadi versi verbanya artinya melempar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3c552337-9f62-4bfc-99f0-59a71aede8ae', 'Untuk Melempar', true) ON CONFLICT DO NOTHING;
