INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c552337-9f62-4bfc-99f0-59a71aede8ae', 'このあたらしいボールは、とても投げやすいです。', 'Bola baru ini sangat mudah untuk dilempar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c552337-9f62-4bfc-99f0-59a71aede8ae', 'どうしてあの人たちは、かんそうした大ずを投げているんですか？', 'Mengapa orang-orang itu membuang kacang kedelai kering?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3c552337-9f62-4bfc-99f0-59a71aede8ae', 'ピッチャーがボールを投げたんですけど、ちょうどバッターの前を飛んでいた鳩に当たったんですよね。', 'Pelempar melempar bola dan mengenai seekor merpati yang terbang di depan pemukul.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b12c111-0eff-4ea8-96dc-083838523de2', 'vocabulary', '番号', '番号', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Angka dalam satu deret ditambah angka. Anda tahu apa yang terjadi jika dua kanji dengan arti yang pada dasarnya sama digabungkan menjadi satu, bukan? Ternyata pada dasarnya memiliki arti yang sama. Kata ini berarti angka, dan digunakan dalam konteks seperti nomor telepon, nomor ujian, dan nomor seri.', 'Angka dalam satu deret ditambah angka. Anda tahu apa yang terjadi jika dua kanji dengan arti yang pada dasarnya sama digabungkan menjadi satu, bukan? Ternyata pada dasarnya memiliki arti yang sama. Kata ini berarti angka, dan digunakan dalam konteks seperti nomor telepon, nomor ujian, dan nomor seri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1b12c111-0eff-4ea8-96dc-083838523de2', 'Nomor', true) ON CONFLICT DO NOTHING;
