INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b12c111-0eff-4ea8-96dc-083838523de2', 'あなたのじゅけん番号は何番ですか？', 'Berapa nomor ujianmu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b12c111-0eff-4ea8-96dc-083838523de2', '三十分で、この番号をおぼえてください。', 'Anda memiliki waktu 30 menit untuk menghafal serangkaian angka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b12c111-0eff-4ea8-96dc-083838523de2', '今、めちゃくちゃ落ち込んでるんだよ。だって、彼女に偽の電話番号を渡されたんだよ。', 'Saya sangat kecewa saat ini karena dia memberi saya nomor telepon palsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b9f32d2e-4092-4aa5-a097-6c15360374d5', 'vocabulary', '一番', '一番', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Saat kamu menjadi nomor satu dalam sebuah seri, kamu adalah nomor satu sayang!', 'Saat kamu menjadi nomor satu dalam sebuah seri, kamu adalah nomor satu sayang!') ON CONFLICT (id) DO NOTHING;
