INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9f32d2e-4092-4aa5-a097-6c15360374d5', 'イチゴあじのあめが、この中で一番すきです。', 'Saya paling suka permen rasa stroberi dari semua ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9f32d2e-4092-4aa5-a097-6c15360374d5', 'わたしが人生で一番さいしょによんだ教かしょは、テキストフグです。', 'Buku teks pertama yang saya baca dalam hidup saya adalah TextFugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9f32d2e-4092-4aa5-a097-6c15360374d5', 'シドニー・クロスビーは、世界で一番うまいホッケー選手だ。', 'Sidney Crosby adalah pemain hoki nomor satu di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('95ff195f-1bf6-4990-a238-0eff4fbfa441', 'vocabulary', '二番', '二番', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Ketika Anda menjadi nomor dua dalam sebuah seri, Anda menjadi nomor dua. Tidak sebaik menjadi 一番, tapi ambillah apa yang bisa kamu dapatkan, lho?', 'Ketika Anda menjadi nomor dua dalam sebuah seri, Anda menjadi nomor dua. Tidak sebaik menjadi 一番, tapi ambillah apa yang bisa kamu dapatkan, lho?') ON CONFLICT (id) DO NOTHING;
