INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b95d532b-b306-4378-9a2f-9a0e37fe100f', 'しゅうてん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b95d532b-b306-4378-9a2f-9a0e37fe100f', '電車でばくすいしてしまって、終点でうん転手さんに起こされたことはよくありますね。', 'Saya sering tertidur di kereta dan harus dibangunkan oleh pengemudi di pemberhentian terakhir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b95d532b-b306-4378-9a2f-9a0e37fe100f', 'このシカゴ発のアムトラックの終点の駅は何て言う名前ですか。', 'Apa nama pemberhentian terakhir Amtrak yang berangkat dari Chicago?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b95d532b-b306-4378-9a2f-9a0e37fe100f', 'お願いがあるの。私がたとえ何と言っても、何をしようとも、終点に着くまで私が電車から降りないようにして。分かった？', 'Anda harus membantu saya. Apapun yang saya katakan, apapun yang saya lakukan, tolong jangan biarkan saya keluar dari kereta sampai kereta mencapai perhentian terakhir. Oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'vocabulary', '民族', '民族', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Suku bangsa (atau suku bangsa) adalah kelompok yang semuanya bersatu. Mereka adalah satu kelompok etnis tunggal. Apa kabarmu?', 'Suku bangsa (atau suku bangsa) adalah kelompok yang semuanya bersatu. Mereka adalah satu kelompok etnis tunggal. Apa kabarmu?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'Kelompok Etnis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'Ethnicity', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'Race', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'みんぞく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'わたしは民族のアイデンティティーを失いたくありません。', 'Saya tidak ingin kehilangan identitas ras saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'この民族は、とてもしん重なことでよく知られている。', 'Kelompok etnis ini dikenal sangat berhati-hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8b0aeac9-3050-41e0-ae43-efd9bcd3c905', 'インドには多様な民族がいますが、みんながみんなカレーを食べるのでしょうか。', 'India memiliki banyak keragaman etnis tapi saya bertanya-tanya apakah mereka semua masih makan kari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'vocabulary', '亡くなる', '亡くなる', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kata ini sebenarnya adalah dua kata yang disatukan. 亡く berarti "meninggal". なる berarti "menjadi". Jadi gabungkan semuanya dan Anda harus meninggal dunia atau meninggal. Ini pada dasarnya adalah cara sopan untuk mengatakan sesuatu telah mati (死ぬ).', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kata ini sebenarnya adalah dua kata yang disatukan. 亡く berarti "meninggal". なる berarti "menjadi". Jadi gabungkan semuanya dan Anda harus meninggal dunia atau meninggal. Ini pada dasarnya adalah cara sopan untuk mengatakan sesuatu telah mati (死ぬ).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'Akan Meninggal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'To Become Deceased', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'To Die', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'なくなる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'まつ本さんが、亡くなったそうです。', 'Saya mendengar bahwa Matsumoto meninggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'わたしの妹は、五才のときに、はいえんで亡くなりました。', 'Adik perempuan saya meninggal karena pneumonia ketika dia berusia lima tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c1e3c85-48d5-4075-befd-1b9edcc2c5f2', 'もし母さんが亡くなったら、僕の料理を作ってくれる人がいなくなってしまう。', 'Jika ibuku meninggal, orang yang membuatkan makanan untukku juga akan tiada.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'vocabulary', '見直す', '見直す', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda tahu kata 直す dari beberapa tingkat yang lalu. Artinya "memperbaiki". Jadi, ketika Anda memperbaiki apa yang Anda lihat, apa yang Anda lakukan? Anda sedang mengevaluasi kembali sesuatu. Itu sebabnya kata ini berarti mengevaluasi kembali.', 'Anda tahu kata 直す dari beberapa tingkat yang lalu. Artinya "memperbaiki". Jadi, ketika Anda memperbaiki apa yang Anda lihat, apa yang Anda lakukan? Anda sedang mengevaluasi kembali sesuatu. Itu sebabnya kata ini berarti mengevaluasi kembali.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'Untuk Mengevaluasi Kembali', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'To Look Again', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'To Reassess', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'みなおす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'もう一ど、けいかくを見直しましょう。', 'Mari kita lihat rencananya sekali lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', 'この間のはいひん回しゅうの日、主人が思ったよりたよりになって、ちょっと見直しちゃった。', 'Pada hari terakhir pembuangan sampah, suami saya jauh lebih bisa diandalkan daripada yang saya harapkan dan itu membuat saya memandangnya secara berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d20d94b1-5211-46c6-b933-3645caa3a2c4', '大学の授業の選択を見直す方がいいと思うよ。だって、愚鳩を捕まえるのが、いいキャリアになるとは思えないもん。', 'Saya pikir Anda harus mengevaluasi kembali pilihan Anda di kelas universitas. Menurut saya, menangkap burung dodo bukanlah jalur karier yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'vocabulary', '気を付けて', '気を付けて', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kata ini mengandung kata 気 (energi) dan 付ける (melampirkan). Jadi, ketika Anda melekatkan energi pada sesuatu, Anda memusatkan perhatian pada hal tersebut, bukan? Kata ini juga merupakan semacam "urutan", karena pada akhirnya terdapat bentuk te. Itu adalah ungkapan yang diucapkan orang kepada orang lain yang melakukan hal berbahaya. Ini seperti mengatakan, "Lampirkan energi pada apa yang Anda lakukan! Tetap fokus!" Cara yang lebih sederhana untuk menerjemahkannya adalah dengan mengatakan bahwa kata ini berarti hati-hati atau hati-hati. Pelajari kata ini agar kamu selalu dapat menunjukkan bahwa kamu peduli terhadap teman-temanmu!', 'Kata ini mengandung kata 気 (energi) dan 付ける (melampirkan). Jadi, ketika Anda melekatkan energi pada sesuatu, Anda memusatkan perhatian pada hal tersebut, bukan? Kata ini juga merupakan semacam "urutan", karena pada akhirnya terdapat bentuk te. Itu adalah ungkapan yang diucapkan orang kepada orang lain yang melakukan hal berbahaya. Ini seperti mengatakan, "Lampirkan energi pada apa yang Anda lakukan! Tetap fokus!" Cara yang lebih sederhana untuk menerjemahkannya adalah dengan mengatakan bahwa kata ini berarti hati-hati atau hati-hati. Pelajari kata ini agar kamu selalu dapat menunjukkan bahwa kamu peduli terhadap teman-temanmu!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'Hati-hati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'Take Care', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'きをつけて', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'あぶらを使ったちょうりをするさいは、火事にならないよう、気を付けてください。', 'Saat Anda memasak menggunakan minyak, berhati-hatilah agar tidak menyalakan api.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'このマグカップ、あついから、気を付けてね。', 'Mug ini panas. Hati-hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67f2dc28-37c6-4898-bae8-8ee65c693ceb', 'これから雪を食べる時はもっと気を付けてよ。色盲だから、色が黄色でも分かんないんだから。', 'Anda harus lebih berhati-hati saat makan salju mulai sekarang. Anda buta warna, jadi Anda tidak bisa membedakannya meskipun warnanya kuning.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', 'vocabulary', '付く', '付く', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda tahu bahwa kata 付ける berarti "melampirkan" dan Anda tahu bahwa kanji 付 berarti melampirkan. Jadi, kata ini mungkin ada hubungannya dengan melampirkan. Ini adalah versi intransitif, di mana ada sesuatu yang dilampirkan (dan Anda tidak melakukan lampiran). Anda dapat menggunakan く sebagai petunjuk. Anda melihat sesuatu menempel di dinding. Kamu bilang "Coo''"', 'Anda tahu bahwa kata 付ける berarti "melampirkan" dan Anda tahu bahwa kanji 付 berarti melampirkan. Jadi, kata ini mungkin ada hubungannya dengan melampirkan. Ini adalah versi intransitif, di mana ada sesuatu yang dilampirkan (dan Anda tidak melakukan lampiran). Anda dapat menggunakan く sebagai petunjuk. Anda melihat sesuatu menempel di dinding. Kamu bilang "Coo''"') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', 'Untuk Dilampirkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', 'つく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', '今このパソコンを買うと、オマケが付くので、おとくですよ。', 'Jika Anda membeli komputer ini sekarang, Anda akan mendapatkan sesuatu, jadi ini adalah kesepakatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', 'マイケルのTシャツにはドレッシングのしみがたくさん付いています。', 'Kaos Michael banyak noda saus saladnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd27da8b-3eac-473d-899a-ca9715907bb5', 'あなたの耳たぶに付いてるそれ、何？', 'Benda apa yang menempel di daun telingamu itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'vocabulary', '見付ける', '見付ける', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda tahu bahwa 付ける berarti "melampirkan" dan 見 berarti "melihat". Jadi, ketika Anda melekatkan penglihatan Anda pada sesuatu, itu seperti Anda sedang mencari-cari untuk mencari sesuatu. Ketika Anda menemukan apa yang Anda cari, bayangkan bola mata Anda terbang keluar dan menempel pada benda itu, lalu berteriak "AKU TEMUKANNYA!"
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'Untuk Menemukan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'To Find Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'みつける', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'むしさされって、見付けるととたんにかゆくなるよな。', 'Saat Anda menemukan gigitan serangga, itu membuat Anda gatal, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', 'このぼう子は、コウイチのかつらを見付けるための手がかりになるかもしれません。', 'Topi ini mungkin bisa membantu kita menemukan wig Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b07a8a9-dc9c-49a4-81c5-51c62580b0ce', '私は今朝、虹の端にあると言われている金の壺を見付けるために四時間以上も費やしました。', 'Saya menghabiskan lebih dari empat jam pagi ini untuk mencoba menemukan pot emas yang menurut mereka ada di ujung pelangi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', 'vocabulary', '欠ける', '欠ける', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', 'Menjadi Kurang', true) ON CONFLICT DO NOTHING;
