INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', 'かける', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', '自てん車でこけて、前ばが欠けてしまった。', 'Saya terjatuh dari sepeda dan gigi depan saya patah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', 'その予定は確実性に欠けています。', 'Rencana itu kurang dapat diandalkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6da76f6-fb03-4531-a087-81cb75b528b7', '私には、セーラームーンを見るのを止めるための強い意志が欠けている。', 'Saya tidak memiliki kemauan untuk berhenti menonton Sailor Moon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', 'vocabulary', '一番目', '一番目', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda pernah melihat 一番 (nomor satu), jadi apa sebenarnya mata pada akhirnya ini? Mata ini (目) menandakan keteraturan. Jadi, tambahkan ini ke "nomor satu" dan Anda mendapatkan yang pertama/yang pertama.', 'Anda pernah melihat 一番 (nomor satu), jadi apa sebenarnya mata pada akhirnya ini? Mata ini (目) menandakan keteraturan. Jadi, tambahkan ini ke "nomor satu" dan Anda mendapatkan yang pertama/yang pertama.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', 'Hal Pertama', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', 'The First', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', 'いちばんめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', 'このごうかな朝食を食べ終わって、一番目のかんそうは、やっぱりベーコンはおいしい、です。', 'Hal pertama yang terlintas dalam pikiran setelah menyelesaikan sarapan yang luar biasa ini adalah bahwa bacon itu enak, seperti yang kita semua tahu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', '一番目のらんには、すきな人の名前をかいてください。', 'Silakan tulis nama orang yang Anda sukai di kolom pertama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6727463c-fca4-4c40-8319-053f5ed0fc3a', '「僕は毎朝一番目に、5キロのランニングをするんだぜ。」「大したことないよ！僕は10キロ走るよ。」', '"Hal pertama yang saya lakukan setiap pagi adalah berlari sejauh lima kilometer." "Itu bukan masalah besar! Aku lari sepuluh!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'vocabulary', '助かる', '助かる', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda tahu bahwa 助ける berarti "membantu" dan ini ada kaitannya. Ini adalah saat seseorang dibantu, dan kita fokus pada orang yang dibantu, bukan pada orang yang membantu. Secara gramatika, verba ini bersifat intransitif, sehingga tidak ada objeknya. Akhiran かる merupakan sebuah petunjuk, karena kata kerja dengan かる sebagai okurigana (kana ditambahkan ke kanji) biasanya bersifat intransitif.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'Untuk Dibantu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'To Be Saved', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'To Be Rescued', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'たすかる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'まだ助かる見こみはあるんですか。', 'Apakah masih ada kemungkinan untuk diselamatkan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', 'コウイチ先生にもらったれんあいのアドバイスのおかげで、助かりました。', 'Saya terselamatkan oleh nasihat hubungan yang diberikan guru saya Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91abba64-6230-4bf1-a3e1-3d069848812a', '「で、私達付き合ってるのよね？どうなの？はっきりさせてよ。」「えーと…」＜その時、インターホンが鳴った。:ピンポーン＞「ふぅ、間一髪で助かった。」', '"Jadi, kita akan keluar atau bagaimana? Jelaskan!" "Um..." (Bel pintu depan berbunyi: dering-dering.) "Fiuh, terselamatkan oleh bel."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', 'vocabulary', '決まる', '決まる', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Semoga Anda pernah melihat kata 決める sebelumnya. Hal serupa terjadi, hanya saja alih-alih melakukan tindakan memutuskan, sesuatu baru saja diputuskan (oleh sesuatu atau orang lain). Anda bukan pengambil keputusan, di sini. Itu sebabnya kata ini harus diputuskan.', 'Semoga Anda pernah melihat kata 決める sebelumnya. Hal serupa terjadi, hanya saja alih-alih melakukan tindakan memutuskan, sesuatu baru saja diputuskan (oleh sesuatu atau orang lain). Anda bukan pengambil keputusan, di sini. Itu sebabnya kata ini harus diputuskan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', 'Untuk Diputuskan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', 'To Be Settled', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', 'きまる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', '仕事が決まってからは、きょうみがなくなりました。', 'Sejak saya mendapat pekerjaan itu, saya kehilangan minat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', 'コウイチは毎朝かみがたが決まらないせいで会社にちこくする。', 'Setiap pagi Koichi terlambat ke kantor karena dia belum memutuskan gaya rambutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b466d665-034f-4d88-9dda-be02d35fcf69', '「それは本当にいい考えだね。そうしよう。」「よし、じゃあ、それで話は決まりだ。」', '“Itu ide yang sangat bagus. Ayo kita lakukan.” "Oke, kalau begitu sudah diputuskan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'vocabulary', '投げ付ける', '投げ付ける', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda tahu bahwa Anda sedang melempar sesuatu yang menempel pada sesuatu yang lain. Bagaimana lagi kamu bisa mengatakan itu? Cara terbaik adalah dengan mengatakan melempar melawan atau melempar.', 'Anda tahu bahwa Anda sedang melempar sesuatu yang menempel pada sesuatu yang lain. Bagaimana lagi kamu bisa mengatakan itu? Cara terbaik adalah dengan mengatakan melempar melawan atau melempar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'Untuk Melawan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'To Throw At', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'なげつける', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'むすめから、頭に花びんを投げ付けられて、七はりをぬう大けがを負いました。', 'Putri saya melemparkan vas ke kepala saya dan menyebabkan saya mengalami luka serius sehingga memerlukan tujuh jahitan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', 'せつ分の日にコウイチにまめを投げ付けてじゃ気をはらいました。', 'Di Setsubun, kami melemparkan kacang kering ke arah Koichi dan mengusir roh jahat tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64384a7e-a27a-4195-b4fe-4d286e98defa', '「サーモン、僕は君に夢中なんだ。」「フグ、私はあんたに怒り心頭よ。どうして私に向かってニンニクなんて投げ付けるのよ！」「ご…ごめん。鮭はニンニクの臭いが好きって聞いたことがあったんだ。」', '"Salmon, aku tergila-gila padamu." "Fugu, sebenarnya aku marah padamu! Kenapa kamu melempar bawang putih ke arahku? M..maaf aku dengar salmon itu suka bau bawang putih."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2ddf8a7-bef7-4ad3-bbac-d673ff2f36b1', 'vocabulary', '気付く', '気付く', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Saat kamu melampirkan energimu (bayangkan seseorang tiba-tiba menatap sesuatu, menempelkan energinya padanya), kamu telah memperhatikan atau menyadari sesuatu. Karena itulah kata ini berarti menyadari atau memperhatikan. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a2ddf8a7-bef7-4ad3-bbac-d673ff2f36b1', 'Untuk Menyadari', true) ON CONFLICT DO NOTHING;
