INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c03f6c8e-f227-465d-ba19-ae3a17481bf3', 'この曲、ビートルズの中で三番目くらいにすき。', 'Ini mungkin lagu Beatles favorit ketiga saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c03f6c8e-f227-465d-ba19-ae3a17481bf3', 'コウイチなら左から三番目のトイレでハリーポッターを読んでるよ。', 'Jika Anda mencari Koichi, dia sedang membaca Harry Potter di toilet ketiga dari kiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c03f6c8e-f227-465d-ba19-ae3a17481bf3', '日本の有人島の多さは、インドネシア、フィリピンに次いで、世界で三番目だってこと、知ってた？', 'Tahukah Anda kalau Jepang merupakan negara dengan jumlah pulau berpenghuni terbanyak ketiga di dunia setelah Indonesia dan Filipina?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25c4daa5-67db-4c93-9b36-cb7df224c27e', 'vocabulary', '私生活', '私生活', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Anda pernah melihat 生活 sebelumnya, kan? Lalu bagaimana dengan “kehidupan” saya? Kehidupan siapa itu? Wah, itu kehidupan pribadi saya.', 'Anda pernah melihat 生活 sebelumnya, kan? Lalu bagaimana dengan “kehidupan” saya? Kehidupan siapa itu? Wah, itu kehidupan pribadi saya.') ON CONFLICT (id) DO NOTHING;
