INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ba5073b-15e5-447e-875c-3b036c2d4cec', 'このそうじきは、一年間のほしょうしょ付きですよ。', 'Penyedot debu ini dilengkapi dengan garansi satu tahun.') ON CONFLICT DO NOTHING;
