INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a659db64-36c6-4304-88d2-3bbdbe0d69cc', 'vocabulary', '教科書', '教科書', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Benda yang Anda gunakan untuk mengajar mata kuliah dengan tulisan adalah buku teks. Ini adalah buku tulisan yang Anda gunakan untuk mengajar mata kuliah Anda!', 'Benda yang Anda gunakan untuk mengajar mata kuliah dengan tulisan adalah buku teks. Ini adalah buku tulisan yang Anda gunakan untuk mengajar mata kuliah Anda!') ON CONFLICT (id) DO NOTHING;
