INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d0f4a2e-5b63-4404-883a-bbc762dbf67d', 'vocabulary', '役目', '役目', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Jika Anda tertarik pada pelayanan, Anda selalu berpikir membantu orang lain adalah tugas Anda! Jika Anda melihatnya, maka Anda menawarkan layanan Anda. Itu adalah hal yang benar untuk dilakukan!', 'Jika Anda tertarik pada pelayanan, Anda selalu berpikir membantu orang lain adalah tugas Anda! Jika Anda melihatnya, maka Anda menawarkan layanan Anda. Itu adalah hal yang benar untuk dilakukan!') ON CONFLICT (id) DO NOTHING;
