INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a50db843-6233-42dc-80b5-d83bd4cebb1a', 'vocabulary', '番組', '番組', 3, '4b3c9d6e-7f8a-5b0c-1d2e-3f4a5b6c7d8e', 'Gunakan nomor dalam rangkaian untuk mengelompokkan hal-hal yang Anda tonton dan dengarkan. Itu menjadikannya program Anda. Program TV dan radio Anda, khususnya. Jika Anda menonton TV, Anda akan sering mendengarnya!', 'Gunakan nomor dalam rangkaian untuk mengelompokkan hal-hal yang Anda tonton dan dengarkan. Itu menjadikannya program Anda. Program TV dan radio Anda, khususnya. Jika Anda menonton TV, Anda akan sering mendengarnya!') ON CONFLICT (id) DO NOTHING;
