INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a50db843-6233-42dc-80b5-d83bd4cebb1a', 'この番組はおも白くありませんでしたが、わたしのすきなはいゆうが出ていました。', 'Acara TV ini tidak menarik, tapi aktor favoritku ada di dalamnya.') ON CONFLICT DO NOTHING;
