INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('573a0b1f-321f-4728-945f-29488ca7f037', 'radical', '戸', 'door', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Kemana biasanya sebuah bendera dibawa? Itu melewati sebuah pintu. Saya tahu radikal 一 biasanya berarti tanah, tetapi dalam kasus ini kita akan mengatakan benderanya ada di ambang pintu (di mana 一 adalah bagian atas pintu).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('573a0b1f-321f-4728-945f-29488ca7f037', 'Pintu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('af17f0e0-c57b-4d1d-bf7f-240bb319a40a', 'radical', '厂', 'cliff', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Lihat tebingnya? Itu menghadap ke arah barat. Laut apa yang ada di sebelah baratmu? Ke sanalah arah hadap tebing ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('af17f0e0-c57b-4d1d-bf7f-240bb319a40a', 'Tebing', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('22d288f3-0072-4b60-83b6-aedeae9e723f', 'radical', '[cleat]', 'cleat', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ada bagian bawah sepatu dan paku yang keluar darinya. Hanya satu jenis sepatu yang seperti ini, yaitu cleat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('22d288f3-0072-4b60-83b6-aedeae9e723f', 'Bersih', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6101ffec-e1b4-4a73-9919-9650bd994dc6', 'radical', '永', 'eternity', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Setetes air akan bertahan selamanya. Apakah Anda ingat pelajaran tentang siklus air di sekolah? Setetes air dapat mendaur ulang dirinya sendiri dengan cara ini selamanya!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6101ffec-e1b4-4a73-9919-9650bd994dc6', 'Keabadian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('428e62fb-0808-4539-9f5e-09461ba6884f', 'radical', '[kick]', 'kick', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ini adalah kaki yang menekuk dengan lucu. Mereka membungkuk sehingga mereka bisa menendangmu! Bayangkan seseorang melakukan tendangan terbang ke arah Anda. Lihatlah kaki mereka dan, ah ya, terlihat seperti ini!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('428e62fb-0808-4539-9f5e-09461ba6884f', 'Tendangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('10f55747-5f72-4cbe-af28-f9cf7a66dd75', 'radical', '咅', 'clown', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Badut melakukan trik aneh. Salah satu trik yang mungkin mereka lakukan adalah berdiri di atas mulutnya (atau berdiri di atas mulut orang lain). Bayangkan seorang badut melakukan salah satu dari hal-hal ini untuk mengingat hal radikal ini: badut.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('10f55747-5f72-4cbe-af28-f9cf7a66dd75', 'Badut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fbb878bf-a782-4b00-9cb6-d738d79ca45e', 'radical', '覀', 'helicopter', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Orang radikal ini terlihat seperti helikopter yang mendatangi Anda, bukan? Anda tidak dapat melihat bagian ekornya karena berada di belakang kabin depan helikopter yang lebih besar. Tapi Anda bisa melihat jendela dan pisau besar yang berputar di atasnya dari sini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fbb878bf-a782-4b00-9cb6-d738d79ca45e', 'Helikopter', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('75152d72-b99f-491d-8e86-480cf3693029', 'radical', '[gladiator]', 'gladiator', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Seseorang menjelek-jelekkan suamimu dan berkata dia harus berjuang demi mereka sekarang. Mereka mengubahnya menjadi seorang gladiator! Sekarang suamimu harus berjuang demi hiburan mereka. Oh tidak!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('75152d72-b99f-491d-8e86-480cf3693029', 'Budak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('05c7bcc8-020b-4d22-ab90-fb492df8ba82', 'radical', '束', 'bundle', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ini adalah pohon dengan sesuatu yang melilit bagian tengahnya, memegangnya erat-erat. Jika Anda membuka bagian tengahnya, Anda akan menyadari bahwa sebenarnya itu adalah sekumpulan pohon yang diikat di sana. Itu seikat pohon!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('05c7bcc8-020b-4d22-ab90-fb492df8ba82', 'Paket', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('348364a9-5425-4b93-b67a-5491ae4fd364', 'radical', '酉', 'alcohol', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Lihat radikal barat di atas mulut radikal? Bayangkan mulut seseorang dari alam liar barat (seperti di film koboi). Apa yang selalu ada di mulut mereka? Itu alkohol.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('348364a9-5425-4b93-b67a-5491ae4fd364', 'Alkohol', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b3584f45-d228-4534-97b7-665b8b8fe521', 'radical', '各', 'kiss', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Saat Anda menggabungkan musim dingin dan mulut, Anda mendapatkan... mulut musim dingin! Atau setidaknya mulut yang terasa seperti musim dingin karena ingin dicium. Sebelum Anda mencium orang, Anda makan permen mint, bukan? Ini merupakan kesopanan umum agar Anda tidak membuat mulut mereka penuh dengan bau mulut. Jadi ketika Anda memikirkan mulut musim dingin, pikirkan ciuman yang manis dan mint!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b3584f45-d228-4534-97b7-665b8b8fe521', 'Ciuman', true) ON CONFLICT DO NOTHING;
