INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d16511b4-4b87-4ec0-be24-9efd6f3ffed7', 'vocabulary', '反対', '反対', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Anti versus... Anda mungkin berpikir ini akan menjadi negatif ganda, tapi ini seperti banyak kata lain di mana Anda memiliki dua kata yang mirip digabungkan... artinya sama dengan kedua kata itu. Dalam hal ini, kebalikan dari sesuatu adalah kebalikannya. Alternatifnya, bisa jadi pihak oposisi. Anda memilih.', 'Anti versus... Anda mungkin berpikir ini akan menjadi negatif ganda, tapi ini seperti banyak kata lain di mana Anda memiliki dua kata yang mirip digabungkan... artinya sama dengan kedua kata itu. Dalam hal ini, kebalikan dari sesuatu adalah kebalikannya. Alternatifnya, bisa jadi pihak oposisi. Anda memilih.') ON CONFLICT (id) DO NOTHING;
