INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d16511b4-4b87-4ec0-be24-9efd6f3ffed7', 'その考えには反対です。', 'Saya menentang gagasan itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d16511b4-4b87-4ec0-be24-9efd6f3ffed7', '不自由の男神は、アッパーわんをはさんで、自由の女神の反対がわに立っています。', 'Patung Pembatasan berdiri di seberang Patung Liberty di tengah Teluk Atas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d16511b4-4b87-4ec0-be24-9efd6f3ffed7', 'チェンジビルに引っ越してからというもの、あいつは昔のあいつとは正反対の人間になっちまったんだ。', 'Dia sangat bertolak belakang dengan keadaannya dulu sejak dia pindah ke Changeville.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02c4e8e4-10b7-44c8-9294-a00c59626d86', 'vocabulary', '場所', '場所', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tempat lokasi adalah suatu tempat atau suatu lokasi, sama seperti kanji yang menjadi dasar pembuatannya.', 'Tempat lokasi adalah suatu tempat atau suatu lokasi, sama seperti kanji yang menjadi dasar pembuatannya.') ON CONFLICT (id) DO NOTHING;
