INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02c4e8e4-10b7-44c8-9294-a00c59626d86', '自分がたたかうべき場所をきちんと知っておくべきだ。', 'Anda harus mengetahui medan perang Anda sendiri.') ON CONFLICT DO NOTHING;
