INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5113095d-fdc6-42d5-b546-4465b248217d', '分からない所があれば、手を上げてください。', 'Jika ada bagian yang tidak Anda mengerti, silakan angkat tangan.') ON CONFLICT DO NOTHING;
