INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0157bf2-13ae-4c4f-a265-5ee09d966270', 'vocabulary', '名所', '名所', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tempat yang terkenal adalah tempat yang terkenal. Saat bepergian keliling Jepang, Anda harus bertanya tentang 名所 jika bisa.', 'Tempat yang terkenal adalah tempat yang terkenal. Saat bepergian keliling Jepang, Anda harus bertanya tentang 名所 jika bisa.') ON CONFLICT (id) DO NOTHING;
