INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('047d1df5-07a4-4055-b43b-bce9e1499613', 'この絵は、クリックでかく大します。', 'Gambar menjadi lebih besar ketika Anda mengkliknya.') ON CONFLICT DO NOTHING;
