INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4db04da9-94b9-46d5-9d9e-99cb64813c11', 'カラオケに行く人数は全ぶで何人ですか。', 'Berapa jumlah orang yang pergi karaoke?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4db04da9-94b9-46d5-9d9e-99cb64813c11', 'トーフグのあたらしいライターのぼしゅう人数は何人ですか？', 'Berapa nomor rekrutmen penulis Tofugu baru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4db04da9-94b9-46d5-9d9e-99cb64813c11', '沢山の人数の人が、この国の人は同じズボンを履くべきだという私の提案に反対しました。', 'Ada banyak orang yang tidak setuju dengan usulan saya bahwa setiap orang di negara ini harus memakai celana yang sama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eaf7dd13-cad7-4f44-9a8d-f44ea5770873', 'vocabulary', '点数', '点数', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Jumlah poin adalah berapa banyak poin yang ada (alias skornya).', 'Jumlah poin adalah berapa banyak poin yang ada (alias skornya).') ON CONFLICT (id) DO NOTHING;
