INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eaf7dd13-cad7-4f44-9a8d-f44ea5770873', 'ワニカニに百点まん点で点数をつけるなら、何点になると思いますか？', 'Jika Anda memberi WaniKani skor 100, berapa poin yang akan Anda berikan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eaf7dd13-cad7-4f44-9a8d-f44ea5770873', 'この点数は、こないだくれたプレゼントのおかえしだよ。', 'Poin-poin ini adalah imbalan atas hadiah yang Anda berikan kepada saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eaf7dd13-cad7-4f44-9a8d-f44ea5770873', '「どうしてそのテストでこんなに低い点数をとったの？」「欠席のせい。つまり、僕の隣の席の子が休んでたんだよ。」', '“Mengapa kamu mendapat nilai rendah pada ujian itu?” “Karena ketidakhadiran. Maksudku, anak yang duduk di sebelahku tidak hadir.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f7cf7d00-ff33-4234-b5e4-ce170b6f46fb', 'vocabulary', '返事', '返事', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tindakan kembali. Itu adalah balasan atau tanggapan.', 'Tindakan kembali. Itu adalah balasan atau tanggapan.') ON CONFLICT (id) DO NOTHING;
