INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7cf7d00-ff33-4234-b5e4-ce170b6f46fb', 'まだ返事をおくっていません。', 'Saya belum menjawabnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7cf7d00-ff33-4234-b5e4-ce170b6f46fb', '出せきのお返事、ありがとうございます。', 'Terima kasih atas RSVP Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7cf7d00-ff33-4234-b5e4-ce170b6f46fb', '私は、お金が欲しいというメールを百通以上ビル・ゲーツに送りましたが、まだ返事をもらっていません。', 'Saya mengirimi Bill Gates lebih dari seratus pesan tentang memberi saya uang, namun dia masih belum membalas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6cb29e95-2ac2-4534-b0aa-2aea1564de7b', 'vocabulary', '道具', '道具', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Peralatan yang Anda gunakan dalam perjalanan hidup penting untuk dimiliki. Apa alat terpenting Anda?', 'Peralatan yang Anda gunakan dalam perjalanan hidup penting untuk dimiliki. Apa alat terpenting Anda?') ON CONFLICT (id) DO NOTHING;
