INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e637a4-2725-4017-9bdb-2ee1952f9081', '朝ごはんは、和食がいいですね。', 'Ya, saya suka sarapan ala Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e637a4-2725-4017-9bdb-2ee1952f9081', 'アメリカ人の中にもさい近、よう食よりも和食がすきな人がふえている。', 'Ada peningkatan orang Amerika yang lebih menyukai masakan Jepang daripada masakan Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e637a4-2725-4017-9bdb-2ee1952f9081', '和食イコール寿司ってわけじゃない。', 'Makanan ala Jepang tidak selalu berarti sushi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', 'vocabulary', '和室', '和室', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Kamar bergaya Jepang cenderung berukuran cukup kecil. Ini terutama mengacu pada jenis ruangan yang ditutupi tikar tatami. Jika Anda mencari tempat tinggal di Jepang, 和室 akan menjadi seperti itu. Anda akan mengeluarkan futon dari lemari dan tidur di lantai. Sangat nyaman, kamar bergaya Jepang ini!', 'Kamar bergaya Jepang cenderung berukuran cukup kecil. Ini terutama mengacu pada jenis ruangan yang ditutupi tikar tatami. Jika Anda mencari tempat tinggal di Jepang, 和室 akan menjadi seperti itu. Anda akan mengeluarkan futon dari lemari dan tidur di lantai. Sangat nyaman, kamar bergaya Jepang ini!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', 'Kamar Bergaya Jepang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', 'わしつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', '和室でねるのは、これがはじめてです。', 'Ini pertama kalinya aku tidur di kamar bergaya Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', 'この和室、ドッグフードとコウイチの足のにおいがまざったようなにおいがしない？', 'Bukankah ruangan bergaya Jepang ini berbau seperti campuran makanan anjing dan kakimu, Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5df55023-96d5-43c7-bc90-64b9f18b5b4c', '私のお兄ちゃんは、和室で大きな蜘蛛を飼っています。', 'Kakak laki-laki saya memiliki seekor laba-laba peliharaan berukuran besar di kamarnya yang bergaya Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ff2ec9bb-4982-4708-84ef-6d5102fe9638', 'vocabulary', '和服', '和服', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Pakaian gaya Jepang (Japanese Style Clothes). Kita berbicara tentang kimono dan yukata dan hal-hal seperti itu. Pada dasarnya inilah yang membedakan pakaian Jepang dengan pakaian Barat. 
