INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff2ec9bb-4982-4708-84ef-6d5102fe9638', '和服もに合ってるね。', 'Kamu juga terlihat bagus dengan pakaian gaya Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff2ec9bb-4982-4708-84ef-6d5102fe9638', '何ちゃく和服をもっていますか？', 'Berapa banyak pakaian gaya Jepang yang Anda miliki?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff2ec9bb-4982-4708-84ef-6d5102fe9638', '和服でマラソンをする日本人を見たことがありますか？', 'Pernahkah Anda melihat orang Jepang lari maraton dengan pakaian ala Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c3fb13ae-6c72-4270-ada3-e13d03c0a162', 'vocabulary', '予定', '予定', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Sesuatu telah ditentukan sebelumnya. Benda apa ini? Tindakan ini? Itu adalah sebuah rencana.', 'Sesuatu telah ditentukan sebelumnya. Benda apa ini? Tindakan ini? Itu adalah sebuah rencana.') ON CONFLICT (id) DO NOTHING;
