INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3fb13ae-6c72-4270-ada3-e13d03c0a162', 'ねえ、日よう日、予定を入れてもいい？', 'Hei, bolehkah aku membuat rencana di hari Minggu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3fb13ae-6c72-4270-ada3-e13d03c0a162', 'その小わく星は地きゅうに向かっていて、北大西ようのどこかにしょうとつする予定だ。', 'Asteroid tersebut berada dalam jalur langsung menuju Bumi dan diperkirakan menghantam suatu tempat di Samudera Atlantik Utara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3fb13ae-6c72-4270-ada3-e13d03c0a162', '私がせっかく予定を立てても、誰もその通りに動いてくれないことが嫌です。', 'Saya benci ketika saya menjadwalkan hari saya, tetapi tidak ada yang mengikuti naskahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3ec7dd43-0aa9-47b5-aee8-bc557166a75d', 'vocabulary', '決定', '決定', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Itu sudah diputuskan dan ditentukan. Keputusan telah dibuat.', 'Itu sudah diputuskan dan ditentukan. Keputusan telah dibuat.') ON CONFLICT (id) DO NOTHING;
