INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd6d41a-3e53-4867-ae99-9c29ad01b78e', '事実かもしれないけど、なっとくはできないな。', 'Itu mungkin benar, tapi saya masih belum yakin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd6d41a-3e53-4867-ae99-9c29ad01b78e', 'あのせいじ家の言っていることは、事実に反します。', 'Apa yang dikatakan politisi tersebut bertentangan dengan fakta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd6d41a-3e53-4867-ae99-9c29ad01b78e', '口髭を生やした男が気味悪く見えるのは、科学的な事実です。', 'Sudah menjadi fakta ilmiah bahwa pria berkumis terlihat menyeramkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9e9bddb5-0672-493a-b872-50ad970c48fa', 'vocabulary', '実力', '実力', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Kebenaran di balik kekuatan seseorang adalah kekuatannya yang sebenarnya. Itu juga merupakan kemampuan mereka yang sebenarnya.', 'Kebenaran di balik kekuatan seseorang adalah kekuatannya yang sebenarnya. Itu juga merupakan kemampuan mereka yang sebenarnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9e9bddb5-0672-493a-b872-50ad970c48fa', 'Kekuatan Sejati', true) ON CONFLICT DO NOTHING;
