INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2837ec97-e86b-466b-b024-2dca506987b7', 'すきなチームが負けたので、くやしいです。', 'Tim favoritku kalah, jadi aku frustasi dan patah hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2837ec97-e86b-466b-b024-2dca506987b7', '食パンマンは、アンパンマンに、チェスでこてんぱんに負けました。', 'Breadman dikalahkan telak dalam permainan catur oleh Anpanman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2837ec97-e86b-466b-b024-2dca506987b7', '「今夜は、どこで食事したい？」「あなたが決めてよ。私はじゃんけんに負けたんだから。」', '"Di mana kamu ingin makan malam ini?" "Itu keputusanmu. Aku kehilangan batu-gunting-kertas."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e6166e5-5c08-45c4-86a0-f7ce57547a0f', 'vocabulary', '勝負', '勝負', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Menang, kalah...keduanya akan terjadi pada pertandingan malam ini! Ini akan menjadi pertarungan yang luar biasa!', 'Menang, kalah...keduanya akan terjadi pada pertandingan malam ini! Ini akan menjadi pertarungan yang luar biasa!') ON CONFLICT (id) DO NOTHING;
