INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c550068-f9a8-48e8-8302-d7f838e438dc', 'サッカーのし合では、1対0で勝つことができました。', 'Pada pertandingan sepak bola, kami berhasil menang 1-0.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c550068-f9a8-48e8-8302-d7f838e438dc', '四才の時に、し合には勝ったが勝ぶに負けた。', 'Ketika saya berusia empat tahun, saya memenangkan pertandingan tetapi saya tetap merasa kalah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c550068-f9a8-48e8-8302-d7f838e438dc', '明日のドッグ・レースにペットのウサギの参加を申し込むつもりなんだけど、確実に勝てると思うんだよね。', 'Saya mengikutsertakan kelinci peliharaan saya dalam perlombaan anjing besok dan saya jamin kelinci itu akan menang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e856a630-92d9-416a-aa2e-8d887acae2fd', 'vocabulary', '勝者', '勝者', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Seseorang yang menang adalah pemenang/pemenang.', 'Seseorang yang menang adalah pemenang/pemenang.') ON CONFLICT (id) DO NOTHING;
