INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69e01f0c-d331-4c2d-9542-36695c80d728', '今回のテストは、楽勝だったね。', 'Tes ini sangat mudah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69e01f0c-d331-4c2d-9542-36695c80d728', '「JLPT5はどうだった？」「ワニカニのおかげで、楽勝だったよ。」', '“Bagaimana JLPT5nya?” ''Berkat WaniKani, semuanya mudah sekali.''') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69e01f0c-d331-4c2d-9542-36695c80d728', '戦争では、より高度な技術を持っている側が通常楽勝する。', 'Pihak yang memiliki teknologi lebih baik dalam berperang biasanya akan mendapatkan kemenangan mudah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2040952e-4594-42bc-99ec-9f52cdd38187', 'vocabulary', '重要', '重要', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ketika sesuatu mempunyai kebutuhan yang berat, Anda tahu bahwa hal itu penting. Ini penting.', 'Ketika sesuatu mempunyai kebutuhan yang berat, Anda tahu bahwa hal itu penting. Ini penting.') ON CONFLICT (id) DO NOTHING;
