INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3718b1e7-c237-492d-8ee3-9b5746f08d4a', 'バスをおりてから、少し歩く必要があります。', 'Saya harus berjalan sebentar setelah turun dari bus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3718b1e7-c237-492d-8ee3-9b5746f08d4a', 'JETのめんせつに合かくするために必要なことって何ですか。', 'Apa yang diperlukan untuk lulus wawancara JET?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3718b1e7-c237-492d-8ee3-9b5746f08d4a', '日本に行ったら必要になるものって何だろう？', 'Apa yang saya perlukan jika saya pergi ke Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b378ad76-d0d2-49db-ab61-5a876527b42e', 'vocabulary', '要点', '要点', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Poin yang dibutuhkan adalah poin utama. Itu adalah inti dari apa yang ingin Anda katakan.', 'Poin yang dibutuhkan adalah poin utama. Itu adalah inti dari apa yang ingin Anda katakan.') ON CONFLICT (id) DO NOTHING;
