INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b378ad76-d0d2-49db-ab61-5a876527b42e', 'もう少し要点をせいりしてからいけんをのべてください。', 'Silakan nyatakan pendapat Anda setelah mengatur ulang poin utama Anda sedikit lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b378ad76-d0d2-49db-ab61-5a876527b42e', 'ユウサクが要点をはあくしているとは思えないんだけど。', 'Menurutku Yusaku tidak mengerti maksudnya.') ON CONFLICT DO NOTHING;
