INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4421b57c-323b-4ba4-950b-d56552c0d2ba', 'vocabulary', '早速', '早速', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Melakukan sesuatu dengan cepat dan dini mungkin mengharuskan Anda melakukannya sekaligus atau segera. Apapun itu, pastikan untuk melakukannya tanpa penundaan.', 'Melakukan sesuatu dengan cepat dan dini mungkin mengharuskan Anda melakukannya sekaligus atau segera. Apapun itu, pastikan untuk melakukannya tanpa penundaan.') ON CONFLICT (id) DO NOTHING;
