INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4421b57c-323b-4ba4-950b-d56552c0d2ba', '早速のごへんしん、ありがとうございます。', 'Terima kasih atas tanggapan langsung Anda.') ON CONFLICT DO NOTHING;
