INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9eaea171-3dce-431a-8072-0d51dc862f6b', 'インターネットの速度がおそすぎてイライラしています。', 'Kecepatan internetnya terlalu lambat dan itu membuatku kesal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9eaea171-3dce-431a-8072-0d51dc862f6b', 'もう少し速度をおとして走行してください。', 'Harap mengemudi sedikit lebih lambat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9eaea171-3dce-431a-8072-0d51dc862f6b', 'ドアを開けたら、冬の突風が物凄い速度で吹きこんできた。', 'Ketika saya membuka pintu, hembusan angin musim dingin menyerbu masuk dengan kecepatan dan kekuatan yang luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'vocabulary', '配る', '配る', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mendistribusikan jadi versi vocab verbanya adalah mendistribusikan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mendistribusikan jadi versi vocab verbanya adalah mendistribusikan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'Untuk Mendistribusikan', true) ON CONFLICT DO NOTHING;
