INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'くばる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'バレンタインデーには、友だちに、手作りのおかしを配るんです。', 'Untuk Hari Valentine kami akan membagikan manisan buatan tangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'しんぶんを配るバイトって月にいくらくらいかせげるのかな。', 'Saya bertanya-tanya berapa banyak yang bisa saya peroleh per bulan dari pekerjaan mengantarkan surat kabar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ba24d7-8619-4da9-88c8-5b515311faa7', 'このパーティーマジでつまんない。道でティシュでも配ってる方がマシだよ。', 'Pesta ini meledak. Bahkan membagikan tisu saku di jalan akan lebih baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed0bd423-67d2-430c-a229-fa31abf7ad86', 'vocabulary', 'お酒', 'お酒', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ini hanya versi kata benda dari kanji 酒 - ada お yang membuatnya bagus. Kata ini bisa berarti alkohol (seperti kanji induknya) atau sake (jenis utama alkohol Jepang, setidaknya di masa kanji).', 'Ini hanya versi kata benda dari kanji 酒 - ada お yang membuatnya bagus. Kata ini bisa berarti alkohol (seperti kanji induknya) atau sake (jenis utama alkohol Jepang, setidaknya di masa kanji).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed0bd423-67d2-430c-a229-fa31abf7ad86', 'Demi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed0bd423-67d2-430c-a229-fa31abf7ad86', 'Alcohol', false) ON CONFLICT DO NOTHING;
