INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('354a79c3-3a6d-4781-9375-712dca3d9e8f', '仕事は進んでいますか？', 'Apakah Anda membuat kemajuan dalam pekerjaan Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('354a79c3-3a6d-4781-9375-712dca3d9e8f', 'トーフグは、いつも一歩先を進んでいるよね。', 'Tofugu selalu selangkah lebih maju, bukan?') ON CONFLICT DO NOTHING;
