INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2fc998a9-dd4e-4f7f-9d3d-3d4484d1a89a', 'vocabulary', '進化', '進化', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Pikirkan hal-hal yang maju dan berubah. Apakah ini terdengar familier? Apakah ini terdengar seperti evolusi?', 'Pikirkan hal-hal yang maju dan berubah. Apakah ini terdengar familier? Apakah ini terdengar seperti evolusi?') ON CONFLICT (id) DO NOTHING;
