INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2fc998a9-dd4e-4f7f-9d3d-3d4484d1a89a', 'しんか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fc998a9-dd4e-4f7f-9d3d-3d4484d1a89a', '日に日に進化してるのが実かんできて、うれしいです。', 'Saya senang bisa menyadari seberapa besar kemajuan saya setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fc998a9-dd4e-4f7f-9d3d-3d4484d1a89a', 'みなさんのおかげで、トーフグは大きな進化をとげることができました。', 'Terima kasih kepada kalian semua, Tofugu mencapai kemajuan luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fc998a9-dd4e-4f7f-9d3d-3d4484d1a89a', 'おい、お前って本当に阿呆だな。ダーウィンの進化論はディズニー映画のタイトルなんかじゃねえよ。', 'Astaga, kamu benar-benar bodoh. Teori evolusi Darwin bukanlah judul film Disney.') ON CONFLICT DO NOTHING;
