INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aec43302-4953-4a69-8b17-265c1e440c8f', 'おいしゃさんに、進行がんがあると言われました。', 'Dokter memberi tahu saya bahwa saya menderita kanker stadium lanjut.') ON CONFLICT DO NOTHING;
