INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95e2015c-0062-43bf-a16d-6fcea43074a2', 'くやしいから、なんか仕返ししたいな。', 'Itu memalukan, jadi aku ingin membalasnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95e2015c-0062-43bf-a16d-6fcea43074a2', 'キャットウーマン！あんたって本当に最低の女だね！いつか仕返ししてやるわ！', 'wanita kucing! Kamu sangat jahat! Aku akan segera menjemputmu kembali!') ON CONFLICT DO NOTHING;
