INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3127dd40-1c12-46b0-ab9a-ca64d39d4c67', 'vocabulary', '研究所', '研究所', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Anda telah melihat bahwa 研究 merupakan penelitian dari kosakata sebelumnya. Jadi, “tempat” yang merupakan tempat penelitian bisa bermacam-macam, meskipun yang utama adalah lembaga penelitian atau laboratorium penelitian.', 'Anda telah melihat bahwa 研究 merupakan penelitian dari kosakata sebelumnya. Jadi, “tempat” yang merupakan tempat penelitian bisa bermacam-macam, meskipun yang utama adalah lembaga penelitian atau laboratorium penelitian.') ON CONFLICT (id) DO NOTHING;
