INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3127dd40-1c12-46b0-ab9a-ca64d39d4c67', 'とあるアメリカの研究所が、日本語がペラペラになるくすりを開発したそうだ。', 'Saya mendengar bahwa laboratorium Amerika tertentu telah membuat pil yang akan membuat Anda fasih berbahasa Jepang.') ON CONFLICT DO NOTHING;
