INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf9ef63f-cb75-4c65-bfec-3b784463e236', 'われに返ると、かれはトーフグオフィスのソファーに横たわっていた。', 'Ketika dia sadar, dia sedang berbaring di sofa di kantor Tofugu.') ON CONFLICT DO NOTHING;
