INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f8b90dd-96cd-4333-a38a-88b05e046eb6', 'vocabulary', '乗り場', '乗り場', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Mudah-mudahan Anda sudah melihat kata 乗る dan mengetahui artinya "berkendara". Jadi kata ini ada hubungannya dengan "lokasi berkendara". Ke mana Anda pergi untuk mendapatkan tumpangan ke suatu tempat? Kemungkinan besar, itu adalah halte bus atau tempat taksi.', 'Mudah-mudahan Anda sudah melihat kata 乗る dan mengetahui artinya "berkendara". Jadi kata ini ada hubungannya dengan "lokasi berkendara". Ke mana Anda pergi untuk mendapatkan tumpangan ke suatu tempat? Kemungkinan besar, itu adalah halte bus atau tempat taksi.') ON CONFLICT (id) DO NOTHING;
