INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('438e9433-fd45-409b-aa7d-d5d02017b2bb', 'vocabulary', '負け犬', '負け犬', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Mudah-mudahan Anda sudah menemukan 負ける sekarang, yang artinya "kalah". Jadi, Anda dapat mengetahui bahwa kata ini berarti "anjing yang kalah". Memanggil seseorang sebagai anjing tidaklah baik, jadi Anda mungkin hanya menyebut mereka pecundang.', 'Mudah-mudahan Anda sudah menemukan 負ける sekarang, yang artinya "kalah". Jadi, Anda dapat mengetahui bahwa kata ini berarti "anjing yang kalah". Memanggil seseorang sebagai anjing tidaklah baik, jadi Anda mungkin hanya menyebut mereka pecundang.') ON CONFLICT (id) DO NOTHING;
