INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e04d53d1-578f-4bdf-b1fd-92931c9269a3', '早い者勝ちなんだだから、急ごうよ！あのフグのキーホルダーすごく欲しいんだよね！この機会を逃したくないんだ。', 'Ini yang pertama datang, yang pertama dilayani. Mari kita lanjutkan! Saya sangat menginginkan gantungan kunci Fugu. Saya tidak ingin melewatkan kesempatan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da4191a4-6def-46d5-9426-e061a3e51f0b', 'vocabulary', '決定する', '決定する', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Sebuah 決定 adalah sebuah "keputusan". Jadi, ketika kamu menambahkan する ke dalamnya, kamu menjadikannya kata kerja, artinya kata ini berarti memutuskan.', 'Sebuah 決定 adalah sebuah "keputusan". Jadi, ketika kamu menambahkan する ke dalamnya, kamu menjadikannya kata kerja, artinya kata ini berarti memutuskan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('da4191a4-6def-46d5-9426-e061a3e51f0b', 'Untuk Memutuskan', true) ON CONFLICT DO NOTHING;
