INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19280231-ce4f-4caa-970a-93c666cce824', 'トーフグの考え方は、理かいに苦しみます。', 'Saya kesulitan memahami cara berpikir Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19280231-ce4f-4caa-970a-93c666cce824', 'はんざいに手をそめるようそそのかしてくるコウイチからの強れつなプレッシャーに苦しんでいます。', 'Saya berjuang di bawah tekanan kuat dari Koichi, yang membantu dan bersekongkol dengan saya dalam suatu kejahatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19280231-ce4f-4caa-970a-93c666cce824', 'なぜ罪のない人が苦しんでいるのか。', 'Mengapa orang yang tidak bersalah menderita?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'vocabulary', '受付', '受付', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Bayangkan seseorang menerima sesuatu dan kemudian melampirkan sesuatu. Orang tersebut adalah resepsionis, karena mereka menerima panggilan, menuliskan informasinya, dan kemudian melampirkan informasi tersebut ke catatan tempel untuk Anda baca. Anda berkata, "Tidak, saya tidak bisa hadir."', 'Bayangkan seseorang menerima sesuatu dan kemudian melampirkan sesuatu. Orang tersebut adalah resepsionis, karena mereka menerima panggilan, menuliskan informasinya, dan kemudian melampirkan informasi tersebut ke catatan tempel untuk Anda baca. Anda berkata, "Tidak, saya tidak bisa hadir."') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'Resepsionis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'Reception', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'うけつけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'あの受付の女せい、左足に大きな魚の目があるらしいよ。', 'Saya dengar wanita resepsionis itu mempunyai jagung besar di kaki kirinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', '明日から、シュワちゃんがトーフグの受付をしてくれます。', 'Arnold Schwarzenegger akan menjadi resepsionis Tofugu mulai besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e531f2d8-8776-4a75-a903-d2ac793612d3', 'え？知らない。受付で聞いてない？', 'Hah? Aku tidak tahu. Bukankah seseorang di resepsi menjelaskannya padamu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b1d08fd9-2efc-4ad6-b626-e5509ca634cd', 'vocabulary', '苦手', '苦手', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Sebuah "tangan yang menderita" agak menyesatkan. Pikirkan lebih banyak tentang kata 苦い (pahit) dan 手 (orang... ingat bagaimana hal itu terkadang terjadi?). Sekarang pikirkan kata ini seperti Anda merasa sedih karena harus bekerja dengan seseorang. Mengapa? Karena mereka sangat sulit untuk dihadapi.', 'Sebuah "tangan yang menderita" agak menyesatkan. Pikirkan lebih banyak tentang kata 苦い (pahit) dan 手 (orang... ingat bagaimana hal itu terkadang terjadi?). Sekarang pikirkan kata ini seperti Anda merasa sedih karena harus bekerja dengan seseorang. Mengapa? Karena mereka sangat sulit untuk dihadapi.') ON CONFLICT (id) DO NOTHING;
