INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b0c3df2f-4d4a-4334-b398-f4b6eb6e34e3', 'さけのみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c3df2f-4d4a-4334-b398-f4b6eb6e34e3', '子どものくせにスルメがすきだなんて、こりゃぁこの子はしょう来酒飲みになるねぇ。', 'Dia suka sotong kering, padahal dia masih kecil ya? Dia bisa menjadi pemabuk di masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c3df2f-4d4a-4334-b398-f4b6eb6e34e3', 'コウイチはお酒は好きだけど、酒飲みってほどじゃあないですよ。', 'Koichi suka minum, tapi dia tidak seperti pecandu alkohol.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c3df2f-4d4a-4334-b398-f4b6eb6e34e3', '彼は大酒飲みだが、赤ワインが苦手だ。', 'Dia peminum berat tapi dia tidak suka anggur merah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('440a1ba8-c5a7-43eb-bcb3-e442c4d1a203', 'vocabulary', '心配事', '心配事', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tindakan dan hal yang harus Anda pikirkan adalah kekhawatiran dan kekhawatiran Anda.', 'Tindakan dan hal yang harus Anda pikirkan adalah kekhawatiran dan kekhawatiran Anda.') ON CONFLICT (id) DO NOTHING;
