INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('440a1ba8-c5a7-43eb-bcb3-e442c4d1a203', 'しんぱいごと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('440a1ba8-c5a7-43eb-bcb3-e442c4d1a203', '心配事をわらいとばしてくれてありがとう。', 'Terima kasih telah menertawakan kekhawatiranku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('440a1ba8-c5a7-43eb-bcb3-e442c4d1a203', 'なんだか心配事があるみたいだよ。', 'Rupanya dia punya kekhawatiran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('440a1ba8-c5a7-43eb-bcb3-e442c4d1a203', '私の一番の心配事は、町に降り落ちる火山灰です。', 'Kekhawatiran terbesar saya adalah abu vulkanik berjatuhan di kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', 'vocabulary', '返す', '返す', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya kembali, jadi versi verbanya artinya mengembalikan sesuatu. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', 'Untuk Mengembalikan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', 'To Return', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', 'かえす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', '今日、としょかんに本を返しに行かなくちゃいけないんです。', 'Hari ini saya harus pergi ke perpustakaan untuk mengambil kembali buku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', '返す言ばが見当たらないよ。', 'Saya tidak punya apa-apa untuk dikatakan kembali kepada Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a009d9cf-9fb3-49a5-9ecf-1763b62f010c', '「昨日あげたクッキー返してくれない？」「えっ、吐きだせってこと？」', '"Bisakah kamu mengembalikan kue yang kuberikan padamu kemarin?" "Hah? Maksudmu, aku harus membuangnya?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'vocabulary', '見返る', '見返る', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Penglihatan Anda kembali pada sesuatu. Kata kerja ini dapat bersifat transitif dan intransitif. Kalau transitif artinya melihat ke belakang, dalam artian melihat kembali seseorang yang ada di belakang Anda, atau melihat kembali masa lalu Anda. Jika bersifat intransitif, artinya melihat ke belakang, dalam arti melihat ke belakang.', 'Penglihatan Anda kembali pada sesuatu. Kata kerja ini dapat bersifat transitif dan intransitif. Kalau transitif artinya melihat ke belakang, dalam artian melihat kembali seseorang yang ada di belakang Anda, atau melihat kembali masa lalu Anda. Jika bersifat intransitif, artinya melihat ke belakang, dalam arti melihat ke belakang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'Untuk Melihat Kembali', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'To Look Back On', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'To Look Back', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'みかえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'か去を見返ってるひまはないんだよ。', 'Saya tidak punya waktu untuk melihat kembali masa lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', '赤さまの見返るおすがたがただただかわいすぎてモエまくっておりまする（*´▽｀*）', 'Sosok bayi yang melihat ke arahku terlalu lucu dan menggemaskan.（*´▽｀*）') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb8f6f-7d5c-45dd-b08f-14eb7c7a775d', 'ガシャーンと大きな音がして、私は思わず後ろを見返った。', 'Terjadi tabrakan besar dan tanpa sadar saya melihat ke belakang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'vocabulary', '落とす', '落とす', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Anda telah melihat bagaimana 落ちる berarti "jatuh". Sekarang Anda sedang melakukan aksi “menjatuhkan sesuatu” alias Anda menjatuhkannya. Kamu dapat mengingat ini karena kamu melemparkan (とす) sesuatu dan benda itu jatuh ke tanah, sehingga kata ini berarti menjatuhkan sesuatu.', 'Anda telah melihat bagaimana 落ちる berarti "jatuh". Sekarang Anda sedang melakukan aksi “menjatuhkan sesuatu” alias Anda menjatuhkannya. Kamu dapat mengingat ini karena kamu melemparkan (とす) sesuatu dan benda itu jatuh ke tanah, sehingga kata ini berarti menjatuhkan sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'Untuk Menjatuhkan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'To Let Something Fall', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'To Lose Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'おとす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', '今朝、コウイチのデスクの下に生たまごを落としてしまいました。', 'Pagi ini, saya tidak sengaja menjatuhkan telur mentah di bawah meja Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', 'そんな信用を落とすようなことは今すぐ止めた方がいいよ。', 'Anda harus segera berhenti melakukan hal-hal yang akan membuat orang lain kehilangan kepercayaan terhadap Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c63ad4aa-5970-4287-95b1-089a729e50cb', '今日、『男を落とす方法』っていう本を買ったんだけど、帰り道にどこかで落としちゃったみたいなんだよね。', 'Hari ini aku membeli sebuah buku berjudul ''Cara Membuat Pria Jatuh Cinta padamu'', tapi aku kehilangan buku itu di suatu tempat dalam perjalanan pulang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'vocabulary', '心配する', '心配する', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Anda tahu bahwa 心配 adalah "kekhawatiran". Bagaimana dengan versi kata kerjanya? Ini akan menjadi kekhawatiran.', 'Anda tahu bahwa 心配 adalah "kekhawatiran". Bagaimana dengan versi kata kerjanya? Ini akan menjadi kekhawatiran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'Khawatir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'To Be Concerned', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'To Be Anxious', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'しんぱいする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'あの会社は安全第一だから、心配しなくても大丈夫ですよ。', 'Keselamatan adalah prioritas pertama perusahaan, jadi Anda tidak perlu khawatir tentang hal itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', 'トーフグの業せきを心配してくれているのであれば、どうか手ぬぐいを買ってください。', 'Jika Anda cemas dengan performa Tofugu, silakan beli tenugui kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a27e180-9da3-4b37-9849-5f383e9d195c', '外では雪がしんしんと降っており、地面が凍りだしているので、彼氏の家に行くときに丘を車で登りきれるのかどうか心配しています。', 'Di luar sedang turun salju lebat dan jalanan menjadi sangat dingin, jadi aku khawatir tidak bisa berkendara ke atas bukit menuju rumah pacarku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2afe30a2-6157-47aa-8fca-e8dea6ad71bd', 'vocabulary', '心配', '心配', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ketika kamu mendistribusikan hatimu ke sekelilingmu, rasanya seperti hatimu ada di mana-mana sekaligus, tapi tidak di tubuhmu. Kamu merasa panik, kamu tidak tahu harus berbuat apa karena hatimu ada di luar sana. Ini mewakili perasaan yang Anda miliki ketika Anda memiliki kekhawatiran atau kekhawatiran. 心配しないでね！', 'Ketika kamu mendistribusikan hatimu ke sekelilingmu, rasanya seperti hatimu ada di mana-mana sekaligus, tapi tidak di tubuhmu. Kamu merasa panik, kamu tidak tahu harus berbuat apa karena hatimu ada di luar sana. Ini mewakili perasaan yang Anda miliki ketika Anda memiliki kekhawatiran atau kekhawatiran. 心配しないでね！') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2afe30a2-6157-47aa-8fca-e8dea6ad71bd', 'Kekhawatiran', true) ON CONFLICT DO NOTHING;
