INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2afe30a2-6157-47aa-8fca-e8dea6ad71bd', 'かれが元気がないのはめずらしいので心配です。', 'Saya khawatir karena tidak biasa dia begitu sedih.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2afe30a2-6157-47aa-8fca-e8dea6ad71bd', 'この船の進行方向が西なのか東なのか心配になった。', 'Saya khawatir apakah kapal itu menuju ke timur atau barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2afe30a2-6157-47aa-8fca-e8dea6ad71bd', '心配しないで。すべて上手くいくよ。私の言うことを信じて。', 'Jangan khawatir, semuanya akan baik-baik saja. Anda bisa percaya apa yang saya katakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91c7f8c9-e371-4254-8324-1d6bcc733ef4', 'vocabulary', '勝手', '勝手', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tangan (atau orang, seperti yang Anda tahu 手 sering merujuk pada seseorang) yang menang dapat melakukan apa yang diinginkannya tanpa mempedulikan orang lain.', 'Tangan (atau orang, seperti yang Anda tahu 手 sering merujuk pada seseorang) yang menang dapat melakukan apa yang diinginkannya tanpa mempedulikan orang lain.') ON CONFLICT (id) DO NOTHING;
