INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('91c7f8c9-e371-4254-8324-1d6bcc733ef4', 'かって', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91c7f8c9-e371-4254-8324-1d6bcc733ef4', 'ほんと、勝手だよね！', 'Kamu sangat egois!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91c7f8c9-e371-4254-8324-1d6bcc733ef4', '勝手なことばっかり言わないでよ！', 'Jangan katakan apapun yang kamu mau.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91c7f8c9-e371-4254-8324-1d6bcc733ef4', '「サーモン！フグは五回も浮気したんだよ。そんな男のこと、信じちゃダメだってば。」「分かってるんだけど、でも、彼、私がいないと生きていけないって言うの。」「じゃあ、もう、勝手にすれば！」', '"Salmon! Fugu selingkuh lima kali. Jangan pernah percaya pada pria seperti itu." “Aku tahu… tapi dia bilang dia tidak bisa hidup tanpaku.” "Yah, kalau begitu, sesuaikan dirimu!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', 'vocabulary', '英和', '英和', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Hal ini terlihat pada hal-hal seperti kamus. Ketika Anda memiliki kamus (gaya) bahasa Inggris dan Jepang, misalnya. Anda juga akan melihatnya sebaliknya, tetapi yang ini adalah bahasa Inggris dan Jepang.', 'Hal ini terlihat pada hal-hal seperti kamus. Ketika Anda memiliki kamus (gaya) bahasa Inggris dan Jepang, misalnya. Anda juga akan melihatnya sebaliknya, tetapi yang ini adalah bahasa Inggris dan Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', 'Bahasa Inggris Jepang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', 'えいわ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', '英和ほんやくの仕事をしています。', 'Saya bekerja sebagai penerjemah Inggris-Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', '新しい英和対やくの本が出ました。', 'Buku terjemahan paralel Inggris-Jepang baru telah diterbitkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7df8782-8aa7-4a59-a78e-78a1f2ecc06a', 'おっと、キャメロンが泣きそうだ！ちょっとあの英和辞典を探して来て、キャメロンに渡してあげてくれない？', 'Uh-oh, Cameron hampir menangis! Bisakah Anda mencari kamus bahasa Inggris-Jepang dan menyerahkannya padanya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', 'vocabulary', '落ち着く', '落ち着く', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Hai. Jatuhkan dirimu dan kembali padaku. Kamu jadi gila di sana. Turunkan ke bawah. Kembali. Tiba. Anda perlu melakukan hal-hal ini untuk menenangkan diri.', 'Hai. Jatuhkan dirimu dan kembali padaku. Kamu jadi gila di sana. Turunkan ke bawah. Kembali. Tiba. Anda perlu melakukan hal-hal ini untuk menenangkan diri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', 'Untuk Menenangkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', 'おちつく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', 'かの女はとらえどころのない女性ですが、一しょにいると落ち着くんです。', 'Aku tidak tahu apa yang dia pikirkan, tapi aku bisa santai saat bersamanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', 'ビエトは赤ちゃんにスコッチをあげて落ち着かせた。', 'Viet menenangkan bayi itu dengan memberinya scotch.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3354481-56cd-4773-af79-40c9bdbfb9e8', '「ちくしょう、上司のやつ！もう、頭にきた！こんな仕事、辞めてやる。」「おいおいおい、そう焦るなって。ちょっと落ち着けよ。 」', '"Sialan dia! Aku muak dengan bosku. Aku akan berhenti dari pekerjaanku." "Wah, wah, wah. Jangan terburu-buru. Tenanglah."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', 'vocabulary', '真実', '真実', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Hakikat kebenaran tidak lain hanyalah kebenaran dan kenyataan. Tidak ada yang lebih nyata dari ini.', 'Hakikat kebenaran tidak lain hanyalah kebenaran dan kenyataan. Tidak ada yang lebih nyata dari ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', 'Kebenaran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', 'Reality', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', 'しんじつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', 'トーフグが、あるワニカニユーザーから５万ドルのそんがいばいしょうを要求されているというのは真実ですか？', 'Benarkah Tofugu menuntut ganti rugi sebesar 50.000 dolar dari pengguna WaniKani?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', '真実のあいを見つけたいという私の希望は打ちくだかれてしまいました。', 'Harapanku untuk menemukan cinta sejati hancur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc4125f0-5507-41e8-8a38-e7d547552ff9', '真実から目を背けないで。結局マザコンだってこと、認めなさいよ。あんたのお母さんはあんたのことを愛しているし、あんたもお母さんのことを愛しているんでしょ。', 'Anda harus menghadapi faktanya! Akui saja bahwa Anda adalah anak ibu. Ibumu mencintaimu dan kamu juga mencintainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'vocabulary', '落書き', '落書き', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Saat tulisan kebetulan "jatuh" di dinding (wah, bukan saya yang melakukan itu, aneh sekali) tulisannya tidak seharusnya berada di tempatnya. Tulisan semacam ini adalah grafiti.', 'Saat tulisan kebetulan "jatuh" di dinding (wah, bukan saya yang melakukan itu, aneh sekali) tulisannya tidak seharusnya berada di tempatnya. Tulisan semacam ini adalah grafiti.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'Grafiti', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'Scribble', false) ON CONFLICT DO NOTHING;
