INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'らくがき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'コウイチの落書きは今やオークションで百万ドルで落札されるまでになった。', 'Nilai sketsa Koichi meningkat sebanyak satu juta dolar di lelang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', '新宿駅の地下道には、昔、たくさんの落書きがしてありましたが、今はほとんど見当たりません。', 'Dahulu kala terdapat banyak coretan di sepanjang lorong bawah tanah di Stasiun Shinjuku, namun sekarang kita sudah jarang melihatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f328972e-84a1-4da6-81c2-7b599c988abc', 'スプレーでの落書きアートは既に少し時代遅れです。新しい芸術家達は、壁の汚れをゴシゴシ擦って洗い落としながらアートを創りだします。', 'Grafiti lukisan semprot sudah agak kuno. Seniman-seniman baru menciptakan karya seni dengan membersihkan kotoran dari dinding.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1712c247-c3c3-4f55-adfc-100767312d61', 'vocabulary', '受験', '受験', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ketika Anda menerima ujian, Anda sedang mengikuti ujian atau mengikuti ujian. Semoga beruntung! SEBUAH++++!', 'Ketika Anda menerima ujian, Anda sedang mengikuti ujian atau mengikuti ujian. Semoga beruntung! SEBUAH++++!') ON CONFLICT (id) DO NOTHING;
