INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24e11a9c-09bc-4b38-8a2e-812b237c91e4', '実験のために、車を一台借りました。', 'Saya meminjam mobil untuk percobaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24e11a9c-09bc-4b38-8a2e-812b237c91e4', 'どんなことを言ったらビエトがおこるのか、実験してみた。', 'Kami bereksperimen untuk mencari tahu hal-hal apa yang bisa kami katakan untuk membuat Viet marah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24e11a9c-09bc-4b38-8a2e-812b237c91e4', '私達の新製品「フグ風味の豆腐」の実験台になりたい人はいますか？', 'Siapa yang ingin menjadi kelinci percobaan dalam eksperimen proyek tahu rasa fugu baru kami?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('465f1a8e-69e0-4531-9d13-f7040d8103ba', 'vocabulary', '発表', '発表', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Saya akan mengungkapkan kepergian saya. Itu satu-satunya pengumuman saya.', 'Saya akan mengungkapkan kepergian saya. Itu satu-satunya pengumuman saya.') ON CONFLICT (id) DO NOTHING;
