INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cba566f3-5231-44ad-8f8e-35132275919e', '玉ねぎとトマトと大こんが要ります。', 'Kamu membutuhkan bawang bombay, tomat, dan lobak.') ON CONFLICT DO NOTHING;
