INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('686cebc3-dd31-46d3-b906-93df4e77891e', 'vocabulary', '対談', '対談', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Versus berdiskusi adalah ketika Anda duduk dan melihat orang lain. Anda sedang mendiskusikan sesuatu versus mereka, jadi Anda berbicara bolak-balik satu sama lain. Dengan cara ini, Anda sedang melakukan percakapan.', 'Versus berdiskusi adalah ketika Anda duduk dan melihat orang lain. Anda sedang mendiskusikan sesuatu versus mereka, jadi Anda berbicara bolak-balik satu sama lain. Dengan cara ini, Anda sedang melakukan percakapan.') ON CONFLICT (id) DO NOTHING;
