INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686cebc3-dd31-46d3-b906-93df4e77891e', 'コウイチとスティーヴ・ブシェミのゆめの対談が実げんしました！', 'Impian berbicara Koichi dan Steve Buscemi menjadi kenyataan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686cebc3-dd31-46d3-b906-93df4e77891e', 'ざんねんながら、そろそろこの対談をおわらせる時間になってしまいました。', 'Sayangnya, inilah waktunya untuk mengakhiri pembicaraan ini.') ON CONFLICT DO NOTHING;
