INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adc55edd-ec63-4b83-a145-011f98f9bee4', 'のうの前の部分の名前って何だっけ？', 'Apa lagi otak bagian depan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adc55edd-ec63-4b83-a145-011f98f9bee4', 'この映画、共感出来る部分だらけでめちゃくちゃ泣けた。', 'Film itu penuh dengan bagian-bagian yang membuatku bersimpati dan aku menangis sekujur tubuhku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', 'vocabulary', '見返す', '見返す', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ketika Anda melihat seseorang meragukan Anda dan malah mengembalikan sesuatu yang sukses, itu adalah untuk menunjukkan kepada seseorang apa yang dapat dilakukannya atau lebih sederhananya untuk menunjukkan kepada seseorang. Dengan kata lain, Anda menunjukkan kepada seseorang yang meragukan Anda atau memperlakukan Anda dengan tidak adil mengenai kemampuan Anda sebenarnya.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', 'Untuk Menunjukkan Kepada Seseorang Apa yang Dapat Dilakukan', true) ON CONFLICT DO NOTHING;
