INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', 'みかえす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', 'トーフグの社長になって、コウイチを見返してやるぞ！', 'Saya akan menjadi presiden Tofugu dan menunjukkan kepada Koichi, yang meremehkan saya, apa yang bisa saya lakukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', '子猫にイワシをあげたら、「本当にいいの？」って感じの顔でマジマジと見返してきたのがマジかわいかった。', 'Saat aku memberi anak kucing itu sarden, dia kembali menatapku dengan wajah yang berkata, "Apakah ini benar-benar untukku?!" dan itu sangat lucu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1ff6d7e-8aa8-4bc0-93d3-b7ff898ef22c', '答案は提出する前に見返したほうがいい。', 'Anda harus melihat kembali tes Anda sebelum mengirimkannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('01987fa3-b7d1-44dc-8a71-1d4f50859084', 'vocabulary', '表', '表', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ini adalah versi kata benda dari kanji ekspres. Jika Anda ingin memahami apa yang ingin diungkapkan oleh sesuatu, Anda biasanya melihat bagian depan atau bagian luarnya. Kata ini biasanya digunakan untuk bagian luar bangunan.', 'Ini adalah versi kata benda dari kanji ekspres. Jika Anda ingin memahami apa yang ingin diungkapkan oleh sesuatu, Anda biasanya melihat bagian depan atau bagian luarnya. Kata ini biasanya digunakan untuk bagian luar bangunan.') ON CONFLICT (id) DO NOTHING;
