INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b621842-7b47-4c44-a1f9-9055501baa79', '落ちをじゃまされてムカついた。', 'Saya disela sebelum saya mengucapkan kalimat lucunya dan saya merasa kesal.') ON CONFLICT DO NOTHING;
