INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c0978-b3c3-4fb8-af1b-19edd4588bdd', 'マイケルは魚よりも泳ぎが上手です。', 'Renang Michael lebih baik dari pada ikan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c0978-b3c3-4fb8-af1b-19edd4588bdd', 'カエルの泳ぎにあこがれて必死に平泳ぎをれんしゅうしていたら、手と足がほそ長くなりました。', 'Saya mengagumi renang katak, jadi saya dengan panik berlatih gaya dada hingga lengan dan kaki saya bertambah panjang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c0978-b3c3-4fb8-af1b-19edd4588bdd', '泳ぎはあまり得意ではありません。', 'Saya tidak pandai berenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4b04bf3-9300-4ba5-869c-a3b0c5bb41e2', 'vocabulary', '台所', '台所', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tempat manakah di rumah Anda yang memiliki sebagian besar mesin di dalamnya? Dapur Anda! Pikirkan saja. Kulkas, freezer, mesin pencuci piring, kompor, microwave, WOW! Itu sangat banyak. Dapur pasti memiliki mesin paling banyak.', 'Tempat manakah di rumah Anda yang memiliki sebagian besar mesin di dalamnya? Dapur Anda! Pikirkan saja. Kulkas, freezer, mesin pencuci piring, kompor, microwave, WOW! Itu sangat banyak. Dapur pasti memiliki mesin paling banyak.') ON CONFLICT (id) DO NOTHING;
