INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b04bf3-9300-4ba5-869c-a3b0c5bb41e2', '母は、台所でりょうりをしています。', 'Ibuku sedang memasak di dapur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b04bf3-9300-4ba5-869c-a3b0c5bb41e2', 'マイケルの家の台所にはなっとうの空きばこが三百万八千九百十七こおいてあるんだって。', 'Kudengar di dapur Michael, ada 3.008.917 kotak natto kosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b04bf3-9300-4ba5-869c-a3b0c5bb41e2', '台所から焦げ臭い臭いがするよ。', 'Aku mencium sesuatu yang terbakar di dapur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b3232553-1dc0-4b96-b64c-ac4c7b148281', 'vocabulary', '部室', '部室', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ruang klub adalah ruang klub!', 'Ruang klub adalah ruang klub!') ON CONFLICT (id) DO NOTHING;
