INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3232553-1dc0-4b96-b64c-ac4c7b148281', 'そのまんがなら、部室に全かんそろってるよ。', 'Sedangkan untuk manga itu, kami memiliki seluruh serinya di ruang klub.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3232553-1dc0-4b96-b64c-ac4c7b148281', '何ぜか部室に魚を口にくわえたネコがいるんです。', 'Entah kenapa, ada seekor kucing dengan ikan di mulutnya di ruang klub.') ON CONFLICT DO NOTHING;
