INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', 'vocabulary', '数年', '数年', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Ketika beberapa tahun telah berlalu, Anda mengatakan bahwa beberapa tahun telah berlalu! Anda tidak ingin mengatakan berapa tahun, jadi katakan saja beberapa tahun.', 'Ketika beberapa tahun telah berlalu, Anda mengatakan bahwa beberapa tahun telah berlalu! Anda tidak ingin mengatakan berapa tahun, jadi katakan saja beberapa tahun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', 'Beberapa Tahun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', 'すうねん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', '数年がすぎさった。', 'Beberapa tahun berlalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', '数年前まで、日本に住んでいました。', 'Saya tinggal di Jepang sampai beberapa tahun yang lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f03a00cd-fc5a-4a20-bfb9-ce8fd9144b3c', 'この絵が完成するには、あと数年かかります。', 'Diperlukan waktu beberapa tahun untuk menyelesaikan lukisan itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('17b50bff-5885-42a5-975d-a2cc93def3e2', 'vocabulary', '絵文字', '絵文字', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Saat Anda menggunakan gambar untuk menggantikan huruf saat mengetik, Anda menggunakan emoji! Itu adalah wajah yang Anda kirim saat Anda mengirim pesan teks atau email.', 'Saat Anda menggunakan gambar untuk menggantikan huruf saat mengetik, Anda menggunakan emoji! Itu adalah wajah yang Anda kirim saat Anda mengirim pesan teks atau email.') ON CONFLICT (id) DO NOTHING;
