INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('17b50bff-5885-42a5-975d-a2cc93def3e2', 'えもじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17b50bff-5885-42a5-975d-a2cc93def3e2', 'みなさんは絵文字はつかいますか？', 'Apakah Anda semua menggunakan emoji?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17b50bff-5885-42a5-975d-a2cc93def3e2', 'しいて言えば、この絵文字がすきです。', 'Jika saya harus memilih, saya suka emoji ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17b50bff-5885-42a5-975d-a2cc93def3e2', '一番よく使う絵文字を教えてください。', 'Bisakah Anda memberi tahu saya emoji mana yang paling sering Anda gunakan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f17b00a-1dde-4ceb-8021-530622849526', 'vocabulary', '部首', '部首', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Bayangkan bagian tubuh Anda yang membentuk leher Anda. Apakah Anda membayangkannya? Itu adalah bahan penyusun yang membentuk tubuh Anda. Yang sangat penting. Jika Anda tidak memiliki leher itu, Anda tidak akan terlihat seperti manusia sama sekali. Kedengarannya familier? Itu harus! Karena bagian lehermu itu radikal! Sama seperti bagian leher Anda yang merupakan bahan penyusun tubuh Anda, radikal adalah bahan penyusun kanji. Mengerti? Saya harap demikian!', 'Bayangkan bagian tubuh Anda yang membentuk leher Anda. Apakah Anda membayangkannya? Itu adalah bahan penyusun yang membentuk tubuh Anda. Yang sangat penting. Jika Anda tidak memiliki leher itu, Anda tidak akan terlihat seperti manusia sama sekali. Kedengarannya familier? Itu harus! Karena bagian lehermu itu radikal! Sama seperti bagian leher Anda yang merupakan bahan penyusun tubuh Anda, radikal adalah bahan penyusun kanji. Mengerti? Saya harap demikian!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7f17b00a-1dde-4ceb-8021-530622849526', 'Radikal', true) ON CONFLICT DO NOTHING;
