INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17b00a-1dde-4ceb-8021-530622849526', 'このかん字の部首は何ですか？', 'Apa radikal kanji ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17b00a-1dde-4ceb-8021-530622849526', '部首をわらうものは部首になく。', 'Seseorang yang menertawakan kaum radikal pada akhirnya akan menangisi kaum radikal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17b00a-1dde-4ceb-8021-530622849526', '私は全部の部首を覚えています。', 'Saya ingat semua radikal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e45a053c-2328-40bc-bc7d-a3bc8990b5d2', 'vocabulary', '近所', '近所', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Tempat tinggal Anda di dekat adalah lingkungan Anda!', 'Tempat tinggal Anda di dekat adalah lingkungan Anda!') ON CONFLICT (id) DO NOTHING;
