INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e45a053c-2328-40bc-bc7d-a3bc8990b5d2', 'トーフグのオフィスの近所には、おしゃれなお店が多く集まっています。', 'Banyak toko mewah berkumpul di sekitar kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e45a053c-2328-40bc-bc7d-a3bc8990b5d2', '近所にコインランドリーがあるわよ。', 'Ada binatu di lingkungan ini.') ON CONFLICT DO NOTHING;
