INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9731f2c8-da9f-4294-a216-92f7ccb2e3a3', 'これ以上、私を苦しめないで！', 'Jangan sakiti aku lagi!') ON CONFLICT DO NOTHING;
