INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dc859b7-19c2-47d3-a68d-992927bf5118', 'やった！シアトル市の大学に受かったよ！', 'Hore! Saya diterima di universitas di Seattle!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dc859b7-19c2-47d3-a68d-992927bf5118', '次回受からなければ、医者になれるチャンスは少なくなるよ。', 'Jika Anda tidak lulus di lain waktu, peluang Anda untuk menjadi dokter akan lebih kecil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dc859b7-19c2-47d3-a68d-992927bf5118', '試験に受かるまで週末は出かけないって決心したんだ。', 'Saya membuat resolusi bahwa saya tidak akan keluar pada akhir pekan sampai saya lulus ujian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', 'vocabulary', '飲酒運転', '飲酒運転', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Anda tahu bahwa 飲酒 berarti "minum alkohol" dan 運転する berarti "mengemudi", jadi masuk akal jika kata ini berarti mengemudi dalam keadaan mabuk, atau minum dan mengemudi.', 'Anda tahu bahwa 飲酒 berarti "minum alkohol" dan 運転する berarti "mengemudi", jadi masuk akal jika kata ini berarti mengemudi dalam keadaan mabuk, atau minum dan mengemudi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', 'Mengemudi Dalam Keadaan Mabuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', 'Drinking And Driving', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', 'いんしゅうんてん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', '飲酒運転は犯罪です。', 'Mengemudi dalam keadaan mabuk adalah kejahatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', '飲酒運転はしたくないから、タクシーで帰るよ。', 'Saya tidak ingin minum dan mengemudi, jadi saya akan pulang dengan taksi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c8298bf-ffbd-4eee-a4f3-932ea1f071fa', '自転車でも飲酒運転とみなされるとは知りませんでしたが、なるほどと思いました。', 'Saya tidak tahu bahwa itu dianggap mengemudi dalam keadaan mabuk dengan sepeda, tapi itu masuk akal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', 'vocabulary', '飲酒', '飲酒', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Minum alkohol adalah minum alkohol, atau sekadar minum. Ini selalu mengacu pada alkohol.', 'Minum alkohol adalah minum alkohol, atau sekadar minum. Ini selalu mengacu pada alkohol.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', 'Minum Alkohol', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', 'Drinking', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', 'いんしゅ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', '飲酒をやめようと思った一番の理由は何ですか？', 'Apa alasan utama Anda memutuskan untuk berhenti minum alkohol?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', '喫煙や飲酒はお金がかかるし、体に悪いでしょう。', 'Merokok dan minum minuman keras itu mahal dan buruk bagi Anda, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e9df1ac-879d-4924-a7a2-6b73e3b2342e', '飲酒者のほとんどが自分の飲酒は大丈夫と思っている。', 'Kebanyakan peminum berpikir bahwa minuman mereka baik-baik saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('394f18c1-1e9b-421f-bc47-8b0c270a3fce', 'vocabulary', '乗客', '乗客', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Jika Anda menumpang sebagai tamu (atau pelanggan), itu menjadikan Anda penumpang.', 'Jika Anda menumpang sebagai tamu (atau pelanggan), itu menjadikan Anda penumpang.') ON CONFLICT (id) DO NOTHING;
