INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('394f18c1-1e9b-421f-bc47-8b0c270a3fce', '乗客にとって安全であることが何よりも重要です。', 'Yang penting aman bagi penumpang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('394f18c1-1e9b-421f-bc47-8b0c270a3fce', 'タクシードライバーとのおしゃべりを楽しみにしている乗客もいる。', 'Beberapa penumpang menantikan untuk mengobrol dengan pengemudi taksi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('394f18c1-1e9b-421f-bc47-8b0c270a3fce', 'ホームには女性の乗客が一人で待っていた。', 'Seorang penumpang wanita sedang menunggu sendirian di peron.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f96b13d-c310-495f-923b-89da3ac10a9a', 'vocabulary', '乗馬', '乗馬', 3, '5c4d0e7f-8a9b-6c1d-2e3f-4a5b6c7d8e9f', 'Jika Anda menunggang kuda, itu berarti menunggang kuda atau, di beberapa bagian dunia, sekadar menunggang kuda.', 'Jika Anda menunggang kuda, itu berarti menunggang kuda atau, di beberapa bagian dunia, sekadar menunggang kuda.') ON CONFLICT (id) DO NOTHING;
