INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f96b13d-c310-495f-923b-89da3ac10a9a', '今朝、乗馬をしました。', 'Pagi ini, saya pergi menunggang kuda.') ON CONFLICT DO NOTHING;
