INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('5f96b13d-c310-495f-923b-89da3ac10a9a', 'fff90e3a-ae25-4905-b680-9f34a37bc454') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3c58430d-9f2f-4f8b-b8e0-1d7e22f7b3d9', 'radical', '黄', 'yellow', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Bunga yang tumbuh dari tanah sawah setelah Anda mengubur siripnya di sana akan tumbuh berwarna kuning. Mengapa? Karena kuning adalah warna jiwa ikan, maka menanam bunga di atas siripnya akan mengubahnya menjadi kuning yang bagus dan cantik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3c58430d-9f2f-4f8b-b8e0-1d7e22f7b3d9', 'Kuning', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f71990b0-3492-4e26-8b9d-043823977f71', 'radical', '豆', 'beans', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Radikal ini mempunyai polong (persegi di tengah) antara tanah dan beberapa akar. Polong itu akan berubah menjadi tanaman suatu hari nanti. Tanaman apa itu? Kacang besar yang enak, seperti yang ada di Jack and the Beanstalk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f71990b0-3492-4e26-8b9d-043823977f71', 'Kacang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('94a87889-9dde-4d72-8a54-b00249edd5d4', 'radical', '[blackjack]', 'blackjack', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda memiliki dua puluh radikal dan satu kanji. Gabungkan semuanya dan Anda mendapatkan 21. Apa nama lain dari 21? Itu blackjack.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('94a87889-9dde-4d72-8a54-b00249edd5d4', 'Blackjack', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ceac7f97-f99f-40d5-9bc8-9d436fbccc6b', 'radical', '戈', 'drunkard', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ini adalah upacara radikal dengan slide radikal. Mengapa seseorang meluncur di lantai pada sebuah upacara? Jika mereka pemabuk, itu alasannya! Orang suka minum pada upacara. Dan selalu ada setidaknya satu pemabuk yang bertindak terlalu jauh dan tergelincir ke lantai sambil melakukan cacingan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceac7f97-f99f-40d5-9bc8-9d436fbccc6b', 'Pemabuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('dae51efe-9e56-41d5-96b0-31352a6122f0', 'radical', '令', 'orders', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Stempel "Topi-Tanah" ada di amplop ini. Itu hanya berarti satu hal: Perintah dari Kantor Pusat. Bayangkan stempel ini pada beberapa pesanan untuk Anda—bacalah pesanan tersebut dengan lantang untuk membantu Anda mengingat bahwa stempel bertopi ini berarti "pesanan" dan tidak ada yang lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dae51efe-9e56-41d5-96b0-31352a6122f0', 'Pesanan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ef144491-9650-4bc3-abf6-ba8cf5613332', 'radical', '[trash]', 'trash', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ada penutup di atas sesuatu yang Anda coba rahasiakan. Itu sampahmu. Anda tentu tidak ingin orang lain membuang sampah pribadi Anda, itulah sebabnya kami menutup tempat sampah kami. Melihat sampah seseorang juga merupakan tindakan ilegal, jadi pastikan Anda tidak pernah melakukannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ef144491-9650-4bc3-abf6-ba8cf5613332', 'Sampah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('abb22cf2-9dab-4d1c-a773-e0a3d9a33cdb', 'radical', '申', 'humble', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Radikal ini sama dengan kanji yang Anda pelajari sebelumnya, namun maknanya sedikit berbeda. Ini bukan hanya tentang mengatakan sesuatu dengan rendah hati, tapi juga tentang bersikap rendah hati secara umum. Ketika Anda melihat hal radikal ini, pikirkanlah untuk bersikap rendah hati.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('abb22cf2-9dab-4d1c-a773-e0a3d9a33cdb', 'Rendah hati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0c61e50a-50aa-47b3-878b-47afd6670972', 'radical', '単', 'simple', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ada sesuatu yang tumbuh di sawah ini dan ada salib yang menjaganya. Sawah ini dimiliki oleh keluarga sederhana yang hidup sederhana. Mereka menanam padi, berdoa kepada tuhan mereka, dan segala sesuatunya baik dan sederhana. Ahh, aku cemburu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c61e50a-50aa-47b3-878b-47afd6670972', 'Sederhana', true) ON CONFLICT DO NOTHING;
