INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18c0e915-383f-44ef-9a8e-c610c87d6dc1', '青葉が目にしみるきせつとなりました。', 'Saat itu adalah tahun dimana dedaunan membuat mataku terbakar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18c0e915-383f-44ef-9a8e-c610c87d6dc1', '家のにわの青葉に虫がいっぱい付いてる！', 'Ada banyak serangga pada daun muda di kebun kami!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18c0e915-383f-44ef-9a8e-c610c87d6dc1', 'お前の頭、ちょっと変なにおいがするぞ。 乾燥した青葉か何かみたいな。', 'Kepalamu berbau sedikit aneh. Itu seperti daun kering atau semacamnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3af765a9-eb88-4751-84f8-592aecaa9428', 'vocabulary', '道路', '道路', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jalan raya jelas merupakan jenis jalan terbaik. Ini jalan ganda. Jadi, apa jalan terakhir ini? Itu adalah jalan beraspal.', 'Jalan raya jelas merupakan jenis jalan terbaik. Ini jalan ganda. Jadi, apa jalan terakhir ini? Itu adalah jalan beraspal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3af765a9-eb88-4751-84f8-592aecaa9428', 'Jalan Beraspal', true) ON CONFLICT DO NOTHING;
