INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('be1ac754-6522-4c98-8952-6faaceb2f8c4', 'なく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be1ac754-6522-4c98-8952-6faaceb2f8c4', '子犬がワンワン鳴いています。', 'Anak anjing itu menggonggong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be1ac754-6522-4c98-8952-6faaceb2f8c4', 'あそこでコケコッコーとおんどりが鳴くまねをしているのが、うちの社長です。', 'Orang yang menirukan ayam jago di sana adalah presiden kita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be1ac754-6522-4c98-8952-6faaceb2f8c4', '今夜、あの新しい洒落た日本食レストランに行こうよ。知ってた？あそこには、ホーホケキョと美しい声で鳴く鶯も何羽かいるんだぜ。', 'Ayo pergi ke restoran Jepang baru yang keren malam ini. Tahukah Anda bahwa ada beberapa burung pengicau semak Jepang yang lucu bernyanyi dengan suara indah mereka?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('be14750b-20c2-481c-bd24-6c7475722456', 'vocabulary', '横', '横', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Harap dicatat bahwa kata ini mengacu pada "sisi dari sesuatu". Bukan "sisi kanan", misalnya. Itu akan menjadi 右側.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Harap dicatat bahwa kata ini mengacu pada "sisi dari sesuatu". Bukan "sisi kanan", misalnya. Itu akan menjadi 右側.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('be14750b-20c2-481c-bd24-6c7475722456', 'Sisi', true) ON CONFLICT DO NOTHING;
