INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be14750b-20c2-481c-bd24-6c7475722456', 'きっ茶店の横に、食どうがあります。', 'Ada restoran di sebelah kafe.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be14750b-20c2-481c-bd24-6c7475722456', 'もし強とうがトーフグのオフィスにやって来たら、コウイチのデスクまで走ってその横にしゃがみこむんだ。そこが最も安全な場所だからね。', 'Jika perampok masuk ke kantor Tofugu, lari saja ke meja Koichi dan berjongkok di sebelahnya karena itu tempat paling aman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be14750b-20c2-481c-bd24-6c7475722456', '午後の仮眠の間に横向きに寝る。', 'Saat tidur siang, saya tidur miring.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('151166ee-6b40-4f9e-8e79-a7d47b831fb3', 'vocabulary', '調子', '調子', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Bayangkan diri Anda sedang menyelidiki seorang anak. Anda mendengar anak ini sedang mengalami masa sulit, sehingga Anda perlu datang memeriksa kondisi rumah dan kehidupannya. Anda mendapati kondisinya sangat buruk, dan Anda memberi tahu orang tuanya bahwa Anda harus membawa anak tersebut pergi karena kondisi ini (bayangkan kondisi mereka sangat buruk... mungkin mereka memelihara rakun di dapur mereka?).', 'Bayangkan diri Anda sedang menyelidiki seorang anak. Anda mendengar anak ini sedang mengalami masa sulit, sehingga Anda perlu datang memeriksa kondisi rumah dan kehidupannya. Anda mendapati kondisinya sangat buruk, dan Anda memberi tahu orang tuanya bahwa Anda harus membawa anak tersebut pergi karena kondisi ini (bayangkan kondisi mereka sangat buruk... mungkin mereka memelihara rakun di dapur mereka?).') ON CONFLICT (id) DO NOTHING;
