INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('151166ee-6b40-4f9e-8e79-a7d47b831fb3', '最近、トーフグの調子はどう？', 'Bagaimana kabar Tofugu akhir-akhir ini?') ON CONFLICT DO NOTHING;
