INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad7d8f81-a587-40e0-846d-56ce26ae4dd8', '今日の午後は、としょかんでせんそうについて調べました。', 'Sore ini, aku mencari informasi tentang perang di perpustakaan.') ON CONFLICT DO NOTHING;
