INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6edfb8ef-6fd5-441d-9c0b-446ec95c26a8', 'きのう会ったりょ行会社の人の顔をもうわすれました。', 'Saya sudah lupa wajah agen perjalanan yang saya temui kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6edfb8ef-6fd5-441d-9c0b-446ec95c26a8', 'コウイチって、顔がこいよね？', 'Koichi memiliki fitur wajah yang sangat jelas, bukan begitu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6edfb8ef-6fd5-441d-9c0b-446ec95c26a8', '「おい、お前。何か文句でもあんのか？ジロジロ見てんじゃねぇぞコラ。」「えっと、あなたの顔、かなり青く見えるんですが、大丈夫ですか？」', '"Hei, sobat. Apakah kamu ingin bertengkar denganku? Kenapa kamu menatapku seperti itu?" "Wah, wajahmu terlihat sangat pucat. Apa kamu baik-baik saja?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('89008922-657e-4751-b7c5-158f430ad1c7', 'vocabulary', '顔付き', '顔付き', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Benda yang menempel di wajahmu bukanlah booger besar atau semacamnya. Itu adalah sesuatu yang selalu ada. Itu ekspresimu.', 'Benda yang menempel di wajahmu bukanlah booger besar atau semacamnya. Itu adalah sesuatu yang selalu ada. Itu ekspresimu.') ON CONFLICT (id) DO NOTHING;
