INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('981de028-4302-4389-8fc8-9dd32d184751', 'お前に金をやるのは、これが最後だ。', 'Ini terakhir kalinya aku memberimu uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('981de028-4302-4389-8fc8-9dd32d184751', 'うちのつま、いつも最後に一言多いんですよね。', 'Istri saya selalu berakhir dengan satu kata yang terlalu banyak.') ON CONFLICT DO NOTHING;
