INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8680f61-aa81-4517-9aed-d4be8690bb52', 'コウイチとは共通点が全くないから、何を話せばいいか分からないよ。', 'Aku tidak tahu harus bicara apa karena Koichi dan aku tidak punya kesamaan.') ON CONFLICT DO NOTHING;
