INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8680f61-aa81-4517-9aed-d4be8690bb52', '「コウイチが熟女好きっていう噂を聞いたんだけど。」「マジかよ！もしそれが本当なら、俺とコウイチに共通点ができるってことになるぜ。」', '"Aku mendengar rumor kalau Koichi menyukai wanita yang lebih tua." "Serius? Kalau itu benar berarti dia dan aku punya kesamaan."') ON CONFLICT DO NOTHING;
