INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eec1cf9c-5594-4a70-b488-005e5f14dec7', '「あのヨットは素敵ですね。田中さんのですか？」 「兄貴と共有なんですよ。」', '"Itu kapal pesiar yang sangat bagus. Apakah itu milik Anda, Tuan Tanaka?" “Saya adalah salah satu pemilik bersama saudara laki-laki saya.”') ON CONFLICT DO NOTHING;
