INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64583906-4702-4449-a3fd-f287c8c51555', 'トーフグのことが好きです。でも、ワニカニはもっと好きです。', 'Aku suka Tofugu, tapi aku suka WaniKani.') ON CONFLICT DO NOTHING;
