INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70aee122-3504-4b86-b675-06c3cc68e71f', 'vocabulary', '友好', '友好', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jika Anda memiliki teman yang Anda sukai, itulah persahabatan sejati!', 'Jika Anda memiliki teman yang Anda sukai, itulah persahabatan sejati!') ON CONFLICT (id) DO NOTHING;
