INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23bb26fc-24d1-47fd-a06a-2429f2011ec0', '取りこし苦労だよ。成るように成るさ。', 'Anda tidak mengkhawatirkan apa pun. Apa yang akan terjadi, akan terjadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23bb26fc-24d1-47fd-a06a-2429f2011ec0', '日食を直に見てしまったため、目が不自由に成りました。', 'Saya tunanetra karena melihat langsung gerhana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23bb26fc-24d1-47fd-a06a-2429f2011ec0', 'うわーー！！コウイチがとうとうアメリカ大統領に成ったよ。「為せば成る。為さねばならぬ何事も、成らぬは人の為さぬなりけり」だね！', 'Astaga! Koichi akhirnya menjadi Presiden Amerika Serikat! Dimana ada kemauan, disitu ada jalan!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1945df8-c476-4334-8061-ee3009d4bc43', 'vocabulary', '老人', '老人', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Orang lanjut usia adalah orang tua (atau orang lanjut usia). Namun, jangan menyebut seseorang sebagai 古い人. 古い digunakan untuk benda, bukan orang. Bersikaplah baik, mereka adalah orang yang lebih tua darimu.', 'Orang lanjut usia adalah orang tua (atau orang lanjut usia). Namun, jangan menyebut seseorang sebagai 古い人. 古い digunakan untuk benda, bukan orang. Bersikaplah baik, mereka adalah orang yang lebih tua darimu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1945df8-c476-4334-8061-ee3009d4bc43', 'Orang Tua', true) ON CONFLICT DO NOTHING;
