INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1945df8-c476-4334-8061-ee3009d4bc43', '日本では、老人の一人ぐらしや二人ぐらしがふえています。', 'Di Jepang, semakin banyak lansia yang tinggal sendirian atau berpasangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1945df8-c476-4334-8061-ee3009d4bc43', 'あの老人とは仲直りした？', 'Apakah Anda memperbaiki keadaan dengan orang tua itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1945df8-c476-4334-8061-ee3009d4bc43', 'うわ！あの老人めちゃくちゃイケメンでマッチョなんだけど。', 'Wow! Orang tua itu benar-benar keren.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b0a99d8-fd02-4053-8dba-2f3f67e6db88', 'vocabulary', '〜位', '〜位', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
