INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b0a99d8-fd02-4053-8dba-2f3f67e6db88', '今年は何位だろう？', 'Saya ingin tahu di mana peringkat saya tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b0a99d8-fd02-4053-8dba-2f3f67e6db88', 'コウイチは黒ニンニクのしょうひりょうにかんしては、ポートランドで一位かもしれない。', 'Dalam hal konsumsi bawang putih hitam, Koichi mungkin menjadi nomor satu di Portland.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b0a99d8-fd02-4053-8dba-2f3f67e6db88', 'マラソン大会で一位になったので、両親がマウンテンバイクを買ってくれた。', 'Saya menjadi juara pertama pada reli maraton, jadi orang tua saya membelikan saya sepeda gunung.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c7a86d22-19e4-4ad5-a1f5-56fd42e58031', 'vocabulary', '一位', '一位', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Peringkat satu adalah tempat pertama.', 'Peringkat satu adalah tempat pertama.') ON CONFLICT (id) DO NOTHING;
