INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7a86d22-19e4-4ad5-a1f5-56fd42e58031', '一位になったら、一週間毎日からあげを作ってあげる。', 'Jika kamu mendapat tempat pertama, aku akan membuatkanmu karaage setiap hari selama seminggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7a86d22-19e4-4ad5-a1f5-56fd42e58031', '子供がピアノコンクールで一位をとりました。', 'Anak saya memenangkan juara pertama dalam kompetisi piano.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7a86d22-19e4-4ad5-a1f5-56fd42e58031', 'お母さん！僕、あのテストで滅茶苦茶良い点をとったんだよ！なんとクラスで一位だったんだ！', 'Mama! Saya benar-benar berhasil dalam ujian itu! Aku mendapat peringkat teratas di kelasku!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('070fd378-991c-4a4d-afff-089f4ee747e8', 'vocabulary', '首位', '首位', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jika Anda berada di peringkat leher, Anda berada di posisi pertama. Pernahkah Anda mendengar ungkapan, “neck and neck” ketika dua orang dalam suatu perlombaan sama-sama sangat dekat dengan posisi pertama? Ingatlah itu dan Anda tidak akan pernah melupakan kata ini.', 'Jika Anda berada di peringkat leher, Anda berada di posisi pertama. Pernahkah Anda mendengar ungkapan, “neck and neck” ketika dua orang dalam suatu perlombaan sama-sama sangat dekat dengan posisi pertama? Ingatlah itu dan Anda tidak akan pernah melupakan kata ini.') ON CONFLICT (id) DO NOTHING;
