INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5aad9426-18a5-4ed1-b3b8-1506bd4c3212', '最初はとりあえず生で！', 'Saya akan mulai dengan bir draft!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5aad9426-18a5-4ed1-b3b8-1506bd4c3212', 'コウイチの最初のかの女の名前はコウイチ子でした。', 'Nama pacar pertama Koichi adalah Koichiko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5aad9426-18a5-4ed1-b3b8-1506bd4c3212', 'お前本当に下手くそだな！初心者でもこんなに下手くそじゃねぇだろ。俺が最初にこのゲームをプレイした時は、お前よりずっと上手かったわ。', 'Kamu buruk dalam hal ini! Bahkan seorang pemula pun tidak seburuk itu! Saat aku memainkan game ini untuk pertama kalinya, aku jauh lebih baik darimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ac77b5e-879e-44c2-9751-e4658bcf5149', 'vocabulary', '利く', '利く', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda tahu kanji artinya untung. Namun, jika Anda mengubahnya menjadi kata kerja, itu berarti bekerja dengan baik. Jika dipikir-pikir, ketika sesuatu berjalan dengan baik, itu memberi Anda keuntungan.', 'Anda tahu kanji artinya untung. Namun, jika Anda mengubahnya menjadi kata kerja, itu berarti bekerja dengan baik. Jika dipikir-pikir, ketika sesuatu berjalan dengan baik, itu memberi Anda keuntungan.') ON CONFLICT (id) DO NOTHING;
