INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ac77b5e-879e-44c2-9751-e4658bcf5149', '自転車のブレーキが利かない。', 'Rem sepeda saya tidak berfungsi dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ac77b5e-879e-44c2-9751-e4658bcf5149', '今日は、うでの利くりょうり人にりょうりを作ってもらいました。', 'Saya memiliki seorang juru masak yang terampil membuatkan makanan untuk saya hari ini.') ON CONFLICT DO NOTHING;
