INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c1260e7-d4bd-4507-8c02-2f8defad50fa', 'vocabulary', '努力', '努力', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda bekerja keras dan menggunakan kekuatan Anda. Ugh! Betapa sulitnya. Anda benar-benar berusaha keras.', 'Anda bekerja keras dan menggunakan kekuatan Anda. Ugh! Betapa sulitnya. Anda benar-benar berusaha keras.') ON CONFLICT (id) DO NOTHING;
