INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22c0f8d9-19db-4519-ba42-3ee8cf04c114', 'ワニカニに出会うまでは、おれの人生は苦労ばかりだった。', 'Hidupku penuh kesulitan sampai aku bertemu WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22c0f8d9-19db-4519-ba42-3ee8cf04c114', '「このコウイチのサイン、苦労してやっと手に入れたんだよ。」「それはご苦労なことですね。」', '"Aku menghabiskan banyak waktu dan tenaga untuk mendapatkan tanda tangan Koichi." "Kerja bagus untuk itu!"') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22c0f8d9-19db-4519-ba42-3ee8cf04c114', 'うちのお風呂って、シャワーの位置が固定されちゃってるから、浴槽を洗って流すときにかなり苦労するんだよね。', 'Karena posisi kepala pancuran di dalam bak mandi saya sudah terpasang, sangat merepotkan untuk membilas bak mandi saat saya mencucinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'vocabulary', '命', '命', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kosakata yang dibuat dari satu kanji saja biasanya mengandung setidaknya satu arti dari induk kanjinya. Dalam hal ini, itulah hidup.', 'Kosakata yang dibuat dari satu kanji saja biasanya mengandung setidaknya satu arti dari induk kanjinya. Dalam hal ini, itulah hidup.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'Kehidupan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'いのち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'コウイチはわたしたちみんなの命のおん人です。', 'Kita semua berhutang nyawa pada Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'おねがいですから、ワニカニでかん字をべん強することよりもご自分の命を大切にしてください。', 'Tolong, hargai hidup Anda lebih dari sekedar belajar kanji di WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09d42e4c-6137-4465-8d8a-c096ed9b8093', 'セーラームーンの命が危ない！', 'Kehidupan Sailor Moon dalam bahaya!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', 'vocabulary', '運命', '運命', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Setiap orang harus memikul nasibnya. Jadi barang apa yang kamu bawa? Itu takdirmu.', 'Setiap orang harus memikul nasibnya. Jadi barang apa yang kamu bawa? Itu takdirmu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', 'Nasib', true) ON CONFLICT DO NOTHING;
