INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', 'うんめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', '運命をしんじますか。', 'Apakah Anda percaya pada takdir?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', '二人は運命の赤い糸でむすばれているって思ってたけど、だんだん心がはなれていってるみたい。', 'Kupikir mereka berdua terikat oleh benang merah takdir, tapi nampaknya hati mereka semakin menjauh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c05e68-3511-4b1a-abbe-9891dbb8867e', 'iPhoneさん天国行き。用を足した後のトイレに落としちゃいました。まぁ、これがiPhoneさんの運命だったのかもしれないけどさ。でも、猛烈に悲しいぜよ...。', 'Beristirahatlah dengan tenang iPhone. Saya baru saja menjatuhkannya ke toilet yang berisi lebih dari sekedar air. Mungkin ini hanya takdir tapi aku sangat sedih saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8fb0bd20-a98b-48ad-bae1-edd8e9e43675', 'vocabulary', '放す', '放す', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melepaskan jadi versi vocab verbanya adalah melepaskan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melepaskan jadi versi vocab verbanya adalah melepaskan.') ON CONFLICT (id) DO NOTHING;
