INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fb0bd20-a98b-48ad-bae1-edd8e9e43675', '放せよ！', 'Lepaskan aku!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fb0bd20-a98b-48ad-bae1-edd8e9e43675', '三十分後、コウイチはついにビエトの手を放した。', 'Koichi akhirnya melepaskan tangan Viet setelah tiga puluh menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fb0bd20-a98b-48ad-bae1-edd8e9e43675', 'フグを海に放すといつも、泳いで逃げちゃって、私が呼んでも知らんぷりするの。どうすれば逃げないように教えることができるのかしら。', 'Setiap kali saya melepaskan Fugu di laut, dia berenang menjauh dan ketika saya memanggilnya, dia tidak mendengarkan. Apa yang harus saya lakukan untuk mengajarinya agar tidak melarikan diri?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2ed4f91-2d02-4a50-af20-a0cf5b97966d', 'vocabulary', '開放する', '開放する', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ketika Anda membuka lalu melepaskan, katakanlah, sebuah pintu, Anda membukanya agar semua orang bisa masuk. Itu sebabnya artinya membuka sesuatu atau membuka sesuatu.', 'Ketika Anda membuka lalu melepaskan, katakanlah, sebuah pintu, Anda membukanya agar semua orang bisa masuk. Itu sebabnya artinya membuka sesuatu atau membuka sesuatu.') ON CONFLICT (id) DO NOTHING;
