INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a2ed4f91-2d02-4a50-af20-a0cf5b97966d', 'かいほうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2ed4f91-2d02-4a50-af20-a0cf5b97966d', 'このそうこをひなん所として開放することになりました。', 'Mereka memutuskan untuk membuka gudang ini sebagai tempat perlindungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2ed4f91-2d02-4a50-af20-a0cf5b97966d', 'このプールは、夏の間、一ぱんに開放されます。', 'Kolam ini terbuka untuk umum pada musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2ed4f91-2d02-4a50-af20-a0cf5b97966d', 'あるゲームにアクセスするために、ポートを開放する方法が知りたいんだ。', 'Saya ingin tahu cara membuka port untuk memberikan akses pada game yang satu ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a10d817-98ef-413b-86ca-9ccbecca1f35', 'vocabulary', '昔', '昔', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Omong-omong, ini cara yang bagus untuk memulai cerita: 昔々に… (Dahulu kala).', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Omong-omong, ini cara yang bagus untuk memulai cerita: 昔々に… (Dahulu kala).') ON CONFLICT (id) DO NOTHING;
