INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df595460-a4a2-4d01-97e4-be47d5edfa0b', 'わたしは東京で生まれ育ちました。', 'Saya lahir dan besar di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df595460-a4a2-4d01-97e4-be47d5edfa0b', 'わたしはとてもきびしい家ていで、ベーコンを食べて育ちました。', 'Saya dibesarkan dengan daging bacon di rumah tangga yang sangat ketat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df595460-a4a2-4d01-97e4-be47d5edfa0b', '私は明治神宮がとっても好きなの。森が、自然の森として育つように計算して造られているので、とても美しいし、自然的な空間なの。', 'Saya sangat menyukai Kuil Meiji karena hutannya dirancang dengan cermat untuk meniru hutan alam dan karena itu indah serta memiliki suasana yang sangat alami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', 'vocabulary', '教育', '教育', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ajarkan dan peliharalah. Itulah yang seharusnya dilakukan oleh pendidikan Anda.', 'Ajarkan dan peliharalah. Itulah yang seharusnya dilakukan oleh pendidikan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', 'Pendidikan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', 'きょういく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', '今日行くのは教育センターです。', 'Tempat yang kita tuju hari ini adalah pusat pendidikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', '日本では、小学校教育と中学校教育がぎむ教育です。', 'Di Jepang, pendidikan diwajibkan sampai sekolah dasar dan sekolah menengah pertama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6b4279c-f8f2-4966-a3c2-8b07dca0e1d1', '「教育があって常識がないよりも、教育がなくて常識がある方がはるかによい。」って誰の言葉だっけ？', 'Ingatkah Anda siapa yang berkata, "Adalah seribu kali lebih baik memiliki akal sehat tanpa pendidikan daripada pendidikan tanpa akal sehat?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('090a3916-d860-4b45-9f86-d6147f3523ec', 'vocabulary', '指す', '指す', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kanji artinya jari. Jadi, jika Anda "menjari" sesuatu, apa yang Anda lakukan? Anda menunjuk. Itu sebabnya kata ini berarti menunjuk.', 'Kanji artinya jari. Jadi, jika Anda "menjari" sesuatu, apa yang Anda lakukan? Anda menunjuk. Itu sebabnya kata ini berarti menunjuk.') ON CONFLICT (id) DO NOTHING;
