INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('438d4a45-2e19-4363-ae88-8c00d6700b8b', '指がきれいですね。', 'Kamu mempunyai jari-jari yang indah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('438d4a45-2e19-4363-ae88-8c00d6700b8b', 'ええっ、この間指のえがき方のレッスンを受けてから、もう一ヶ月もたったの！？', 'Wow. Sudah sebulan terakhir aku mengikuti pelajaran menggambar jari ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('438d4a45-2e19-4363-ae88-8c00d6700b8b', '突然中指が痛くなったんだけど。', 'Tiba-tiba saya merasakan sakit di jari tengah saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a06fcb31-4e90-42fb-a904-5010492f603b', 'vocabulary', '小指', '小指', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jari kelingking adalah jari kelingking atau jari kelingking Anda. Masuk akal, tapi ini juga digunakan untuk jari kelingking kaki Anda. Kau tahu, jari kelingkingmu.', 'Jari kelingking adalah jari kelingking atau jari kelingking Anda. Masuk akal, tapi ini juga digunakan untuk jari kelingking kaki Anda. Kau tahu, jari kelingkingmu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a06fcb31-4e90-42fb-a904-5010492f603b', 'Jari Kelingking', true) ON CONFLICT DO NOTHING;
