INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a06fcb31-4e90-42fb-a904-5010492f603b', 'なんでグラスで飲み物を飲む時に小指を立てるの？', 'Mengapa jari kelingkingmu memanjang saat kamu minum dari gelas?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a06fcb31-4e90-42fb-a904-5010492f603b', 'いってぇー、そこのタンスの角に右足の小指ぶつけた。', 'Aduh! Aku baru saja membenturkan jari kelingking kananku ke sudut meja rias.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a06fcb31-4e90-42fb-a904-5010492f603b', 'またシュートミスっちまったぜ。突き指してる小指のせいで今日はまじでダメだわ。', 'Itu bola udara lainnya. Keadaanku buruk hari ini karena jari kelingkingku yang macet ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55e79306-9cc9-4b87-aadb-989aaa80d3ec', 'vocabulary', '指定する', '指定する', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Saat Anda menentukan dan menggunakan jari Anda untuk menunjuk seseorang atau sesuatu, Anda akan menunjuk mereka. Bayangkan saja diri Anda menentukan siapa yang terbaik untuk pekerjaan itu lalu menunjuk dengan jari Anda. Itulah orang yang akan Anda tunjuk. Huruf する di akhir membuatnya menjadi kata kerja, jadi 指定 adalah "penunjukan" atau "penunjukan" atau semacamnya. Keren cara kerjanya.', 'Saat Anda menentukan dan menggunakan jari Anda untuk menunjuk seseorang atau sesuatu, Anda akan menunjuk mereka. Bayangkan saja diri Anda menentukan siapa yang terbaik untuk pekerjaan itu lalu menunjuk dengan jari Anda. Itulah orang yang akan Anda tunjuk. Huruf する di akhir membuatnya menjadi kata kerja, jadi 指定 adalah "penunjukan" atau "penunjukan" atau semacamnya. Keren cara kerjanya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('55e79306-9cc9-4b87-aadb-989aaa80d3ec', 'Untuk Menunjuk', true) ON CONFLICT DO NOTHING;
