INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('aa26ea35-21b3-41a8-89ee-d7a9abca59fa', 'せんしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa26ea35-21b3-41a8-89ee-d7a9abca59fa', 'うちの市では、ゴミしゅう集車の代わりに戦車が使われることになりました。', 'Kota kami memutuskan untuk menggunakan tangki daripada truk sampah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa26ea35-21b3-41a8-89ee-d7a9abca59fa', 'この戦車、そろそろせん車しないとなぁ。', 'Kita harus segera mencuci tangki ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa26ea35-21b3-41a8-89ee-d7a9abca59fa', '「俺の戦車のタイヤ、どう？」「もう少し空気を入れるか、戦車用の履帯に換えた方がいいと思いますよ。」', '“Bagaimana kondisi ban tangki saya?” "Saya pikir Anda harus memompanya lebih banyak atau beralih ke tapak tangki."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'vocabulary', '戦場', '戦場', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Lokasi perang adalah medan perang. Di situlah peperangan terjadi.', 'Lokasi perang adalah medan perang. Di situlah peperangan terjadi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'Medan Perang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'Battleground', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'せんじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', '戦場にいたって、そりゃあだれだって命はおしいさ。', 'Tak seorang pun ingin terbunuh, bahkan di medan pertempuran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'ビエトのせいで、トーフグのオフィスはヤクザの戦場と化した。', 'Kantor Tofugu berubah menjadi medan perang Yakuza karena Vietnam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08c3c238-7b83-4243-af66-cc3a7ba2dd2b', 'コウイチは頼れるやつだ。たとえ戦場にいたとしても、俺達を決して見捨てやしないよ。', 'Koichi adalah pria yang bisa diandalkan. Dia tidak akan pernah mengecewakan kita meskipun kita berada di medan perang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', 'vocabulary', '最悪', '最悪', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Yang paling buruk adalah yang terburuk. Setidaknya semuanya sudah ada sekarang, bukan?', 'Yang paling buruk adalah yang terburuk. Setidaknya semuanya sudah ada sekarang, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', 'Yang Terburuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', 'Worst', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', 'さいあく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', '今日は最悪な一日だったよ。', 'Hari ini adalah hari terburuk yang pernah ada.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', '最悪、すいみん時間をけずって仕事をしなければならないですが、まぁなんとかなるでしょう。', 'Skenario terburuknya adalah saya harus kurang tidur dan bekerja, tapi semuanya akan baik-baik saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb298ba-12cc-43df-aba4-081c0af3433d', '「昨夜、自動車を盗まれちゃったんだよ。」「げっ、最悪じゃん。」', '"Mobilku dicuri tadi malam." "Oh, tidak! Itu yang terburuk!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9cd755f6-b37d-4580-ad70-d71418be836b', 'vocabulary', '酒好き', '酒好き', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jika Anda sangat menyukai alkohol, kemungkinan besar Anda adalah seorang peminum berat.', 'Jika Anda sangat menyukai alkohol, kemungkinan besar Anda adalah seorang peminum berat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9cd755f6-b37d-4580-ad70-d71418be836b', 'Peminum', true) ON CONFLICT DO NOTHING;
