INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2d91b08-2436-487f-a618-e296220c8863', 'きりんの鳴き声を聞いたことがありますか。', 'Pernahkah Anda mendengar seperti apa suara jerapah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2d91b08-2436-487f-a618-e296220c8863', '外からコウイチの声が聞こえると思ったら、小鳥の鳴き声だった。', 'Kupikir aku mendengar Koichi di luar, tapi yang terdengar hanyalah kicauan burung kecil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2d91b08-2436-487f-a618-e296220c8863', '自動販売機の下から子犬の鳴き声が聞こえるんです。', 'Saya mendengar anak anjing menggonggong di bawah mesin penjual otomatis.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', 'vocabulary', '落ち葉', '落ち葉', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Daun yang gugur adalah daun yang gugur.', 'Daun yang gugur adalah daun yang gugur.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', 'Daun Jatuh', true) ON CONFLICT DO NOTHING;
