INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', 'おちば', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', '目の前には、落ち葉のじゅうたんが広がっていました。', 'Ada hamparan daun-daun berguguran yang terbentang di sekeliling kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', '落ち葉をひろって天ぷらにしました。', 'Saya mengambil beberapa daun yang jatuh dan membuat tempura dengannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43ac5f55-6ff2-4342-abcb-94e0aeecd6ce', '「聞いてよ。最初は、お姉ちゃんの彼氏だから、フグと仲良くしようとしてただけだったの。でも、次々にいろんなことが重なって、知らない間に、お…落ち葉を一緒に熊手で集めてたの。」「ツ…ツナったら、なんてことなの。」「サーモン、待って。一度だけよ。それに、私は何とも思わなかったわ。」', '"Begini, saat semuanya dimulai, aku hanya berusaha bersikap baik pada Fugu karena dia adalah pacar kakak perempuanku. Lalu, satu hal mengarah ke hal lain dan sebelum aku menyadarinya, kami... menyapu daun-daun berguguran bersama-sama." "T-Tuna. Kenapa kamu melakukan itu?" "Salmon, tunggu. Kami hanya melakukannya sekali. Itu tidak berarti apa-apa bagiku."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('684639f9-74f0-458a-a5c9-477b7583175d', 'vocabulary', '鳴る', '鳴る', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ini sangat mirip dengan 鳴く, yang berarti "berkicau" (atau suara binatang lainnya). Hal ini ada hubungannya dengan suara-suara juga, tetapi tidak terlalu berkaitan dengan suara binatang dan lebih mirip dengan bel (termasuk telepon). Kata ini berarti berdering. Jika membantu, anggap る sebagai petunjuk, seperti bunyi pertama dari kata "dering" (る). Jadi, る = "dering" dan itu adalah kata kerja, jadi berdering.', 'Ini sangat mirip dengan 鳴く, yang berarti "berkicau" (atau suara binatang lainnya). Hal ini ada hubungannya dengan suara-suara juga, tetapi tidak terlalu berkaitan dengan suara binatang dan lebih mirip dengan bel (termasuk telepon). Kata ini berarti berdering. Jika membantu, anggap る sebagai petunjuk, seperti bunyi pertama dari kata "dering" (る). Jadi, る = "dering" dan itu adalah kata kerja, jadi berdering.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('684639f9-74f0-458a-a5c9-477b7583175d', 'Untuk menelepon', true) ON CONFLICT DO NOTHING;
