INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('684639f9-74f0-458a-a5c9-477b7583175d', 'お腹が鳴ってしまった。', 'Perutku keroncongan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('684639f9-74f0-458a-a5c9-477b7583175d', 'だれかの電話が鳴ってるね。', 'Ponsel seseorang berdering.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('684639f9-74f0-458a-a5c9-477b7583175d', '雷が鳴ったが、雨は降らなかった。', 'Guntur bergemuruh tetapi tidak turun hujan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61ab7070-1e4b-4b3b-a8f6-6e28e648118b', 'vocabulary', '初めに', '初めに', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ini adalah kata berdasarkan waktu (karena に). Apa titik waktu pertama ketika Anda memulai sesuatu? Itu adalah awalnya.', 'Ini adalah kata berdasarkan waktu (karena に). Apa titik waktu pertama ketika Anda memulai sesuatu? Itu adalah awalnya.') ON CONFLICT (id) DO NOTHING;
