INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('61ab7070-1e4b-4b3b-a8f6-6e28e648118b', 'はじめに', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ab7070-1e4b-4b3b-a8f6-6e28e648118b', 'まず初めに牛肉をスライスして、それからフライパンでいためてください。', 'Untuk memulainya, silakan iris dulu daging sapinya lalu goreng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ab7070-1e4b-4b3b-a8f6-6e28e648118b', '初めに言わせてもらいますが、アドリブえんそうはしないでください。', 'Pertama-tama, mohon jangan berimprovisasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ab7070-1e4b-4b3b-a8f6-6e28e648118b', 'トーフグよ安らかに眠ってくれ。今月初めに、僕の一番好きな日本語学習サイトが倒産しちゃったんだ。', 'MEROBEK. Tahu. Awal bulan ini situs belajar bahasa Jepang favorit saya bangkrut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', 'vocabulary', '初めて', '初めて', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda tahu bahwa 初 berarti "pertama" Kata ini berarti pertama kali. Bayangkan めて sebagai "bertemu". Kemudian pikirkan "saat kita pertama kali bertemu ____ terjadi."', 'Anda tahu bahwa 初 berarti "pertama" Kata ini berarti pertama kali. Bayangkan めて sebagai "bertemu". Kemudian pikirkan "saat kita pertama kali bertemu ____ terjadi."') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', 'Untuk Pertama Kalinya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', 'First Time', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', 'はじめて', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', '初めてオバマ大とうりょうと会ったしゅんかんから意気投合した。', 'Sejak pertama kali kami bertemu, Presiden Obama dan saya memiliki hubungan yang sangat baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', '初めての銀行業むに四苦八苦しています。', 'Ini adalah pertama kalinya saya berurusan dengan perbankan dan saya benar-benar kesulitan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8860c07-7a5d-471b-b4b8-2d9ccfc06f0d', '「もしかして、日本はこれが初めて？」「はい。そうなんです。」「そうなんだ。日本はどう？」「かなり気に入ってるわ。」', '"Mungkinkah ini pertama kalinya kamu ke Jepang?" "Ya, benar." “Oh benarkah? Bagaimana kamu menyukainya?” "Saya sangat menyukainya!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', 'vocabulary', '神風', '神風', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Angin para dewa. Ini adalah angin ilahi. Lebih populernya, kata ini dikenal sebagai kamikaze, yang dikenal karena pilot kamikaze selama Perang Dunia II. Ini digunakan sebelum Perang Dunia II, ketika seluruh armada Mongol dihancurkan oleh badai, sehingga mencegah invasi ke Jepang. Betapa beruntungnya.', 'Angin para dewa. Ini adalah angin ilahi. Lebih populernya, kata ini dikenal sebagai kamikaze, yang dikenal karena pilot kamikaze selama Perang Dunia II. Ini digunakan sebelum Perang Dunia II, ketika seluruh armada Mongol dihancurkan oleh badai, sehingga mencegah invasi ke Jepang. Betapa beruntungnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', 'Kamikaze', true) ON CONFLICT DO NOTHING;
