INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', 'しんぷう', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', 'この神社には神風がふいています。', 'Angin ilahi bertiup di kuil ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', '第二次世界大戦の末期には日本ぐんは神風とっこうたいを使ってアメリカぐんをこうげきしました。', 'Pada akhir Perang Dunia II, tentara Jepang menggunakan korps kamikaze untuk menyerang tentara Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a949c6cc-2676-40fb-9c1d-1ce4f2419aa0', '五年前、神風が吹き、コウイチはビエトの軍隊を海岸から後退させた。', 'Lima tahun yang lalu, Koichi mengusir pasukan Viet kembali dari pantainya dan mereka ditelan oleh angin dewa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'vocabulary', '手伝う', '手伝う', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ketika Anda menyerahkan tangan Anda kepada sesuatu atau seseorang, Anda mengulurkan tangan Anda untuk menolong atau membantu mereka.', 'Ketika Anda menyerahkan tangan Anda kepada sesuatu atau seseorang, Anda mengulurkan tangan Anda untuk menolong atau membantu mereka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'Untuk Membantu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'To Assist', false) ON CONFLICT DO NOTHING;
