INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'てつだう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'れいぞうこをかた付けるの、手伝ってくれない？', 'Bisakah Anda membantu saya membersihkan lemari es?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'ビエトに、コウイチに一億ドルのほけん金をかけたので、やつを暗殺するのを手伝ってほしいとたのまれたんだ。', 'Viet memintaku membantunya membunuh Koichi karena dia membelikan polis asuransi senilai 100 juta dolar untuknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad390cb-6559-4c4e-b017-2274729486e3', 'ごめんなさい。お手伝いしてあげたいんだけど、私にはどうにもできないんです。', 'Saya minta maaf. Saya ingin membantu tetapi tangan saya terikat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', 'vocabulary', '左利き', '左利き', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jika Anda mendapat untung dari sayap kiri, Anda mungkin melakukan segalanya di sayap kiri. Itu sisi baikmu. Anda mungkin kidal.', 'Jika Anda mendapat untung dari sayap kiri, Anda mungkin melakukan segalanya di sayap kiri. Itu sisi baikmu. Anda mungkin kidal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', 'Tangan Kiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', 'ひだりきき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', 'なぜかいつも左利きの女せいにひかれるんです。', 'Entah kenapa aku selalu tertarik pada wanita kidal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', '左利きの人向けの仕事に力を入れています。', 'Saya bekerja keras untuk orang kidal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26fa5f29-90e9-4f0f-91e9-a2dbd766d245', '「どういったご用件でしょうか？」「あなたが左利きかどうかだけ知りたいんですが。」「あいにくそれはお伝えできないことになっております。」', '"Bolehkah aku menanyakan tujuan panggilanmu?" "Aku hanya ingin tahu apakah kamu kidal." "Saya khawatir saya tidak mempunyai kebebasan untuk mengungkapkan informasi itu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'vocabulary', '体育', '体育', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ingat bagaimana 教育 berarti "pendidikan?" Ya, 育 di sini mengacu pada kata pendidikan, tapi kali ini adalah pendidikan tubuh. Apa yang disebut dengan pendidikan tubuh di sekolah? Pendidikan Jasmani atau PE.', 'Ingat bagaimana 教育 berarti "pendidikan?" Ya, 育 di sini mengacu pada kata pendidikan, tapi kali ini adalah pendidikan tubuh. Apa yang disebut dengan pendidikan tubuh di sekolah? Pendidikan Jasmani atau PE.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'Kelas PE', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'PE', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'Physical Education', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'Gym Class', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', 'たいいく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', '小学校の時、体育のマラソンが大きらいでした。', 'Saya benci saat di sekolah dasar ketika kami harus lari jarak jauh di gym.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', '次の体育のじゅ業の前に、つめを切ってください。', 'Sebelum kelas olahraga berikutnya, harap potong kuku jari Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e9440b1-74ab-465a-8523-2c64777225b5', '「体育の日に、一緒にバレーボールしない？」「ああ、確か祝日だったよね。十月十日とかだっけ？」「そうそう。祝日。でも、もう十月十日じゃないよ。ハッピー・マンデー制度ができてから、十月の第二月曜日になったんだよ。」', '“Apakah kamu ingin bermain bola voli bersama kami di Hari Pendidikan Jasmani?” “Oh, ini hari libur nasional kan? Bukankah ini tanggal 10 Oktober atau semacamnya?” “Iya, ini hari libur, tapi bukan tanggal 10 Oktober lagi. Sekarang Senin kedua bulan Oktober karena sistem Happy Monday.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', 'vocabulary', '右利き', '右利き', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Sisi kanan tubuh Anda adalah sisi yang paling Anda manfaatkan. Jadi, Anda lebih sering menggunakannya. Itu karena Anda tidak kidal.', 'Sisi kanan tubuh Anda adalah sisi yang paling Anda manfaatkan. Jadi, Anda lebih sering menggunakannya. Itu karena Anda tidak kidal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', 'Tangan Kanan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', 'みぎきき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', 'わたしの息子は右利きではありません。', 'Anak saya tidak kidal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', 'ぼくは左利きなのに、お母さんが間ちがえて右利きのグローブを買っちゃったんだ。', 'Meskipun saya kidal, ibu saya tidak sengaja membeli sarung tangan baseball untuk tangan kanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c487caee-53f1-417f-abad-0576a29c9ff8', '彼女のこと、すごく好きだったんだけど、右利きだって分かってから冷めちゃったんだよね。どうしてかは分からないけど。', 'Saya sangat menyukainya tetapi saya tidak tertarik ketika mengetahui bahwa dia tidak kidal. Saya tidak tahu kenapa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'vocabulary', '好む', '好む', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda tahu bahwa 好き adalah "seperti". Meskipun 好き sudah seperti kata kerja, ini sudah pasti merupakan kata kerja. Bisa jadi menyukai atau menyukai.', 'Anda tahu bahwa 好き adalah "seperti". Meskipun 好き sudah seperti kata kerja, ini sudah pasti merupakan kata kerja. Bisa jadi menyukai atau menyukai.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'Menjadi Suka', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'To Like', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'このむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'この日本酒は、大変酒好きだった私の父が生前に好んで飲んでいたものです。', 'Sake Jepang ini adalah apa yang disukai ayah saya yang merupakan peminum berat ketika dia masih hidup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'コウイチは、黒ニンニクを好んで食べます。', 'Koichi suka makan bawang putih hitam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e31edc2-cd63-4589-8fa2-6e90a3e20c3d', 'コウイチさん、申し訳ありませんが、好むと好まざるとに関わらず、あなたの秘密は暴露されてしまうかもしれません。', 'Maafkan saya, Tuan Koichi. Suka atau tidak suka, rahasia Anda mungkin akan terungkap.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'vocabulary', '育てる', '育てる', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ini mirip dengan 育つ, hanya saja sekarang Anda membesarkan seseorang. Kata ini berarti membesarkan atau membesarkan. Anda dapat mengingat ini karena てる. Versi Anda dalam membesarkan anak melibatkan merobek (てる) semua pakaian mereka untuk membuat mereka terlihat miskin sehingga mereka bisa mendapatkan makan siang yang lebih murah di sekolah. Anda kaya karena semua keringanan pajak yang Anda peroleh dari semua anak yang Anda besarkan, namun Anda selalu dapat menggunakan lebih banyak uang untuk memicu kecanduan StarCraft Anda (kita semua pernah mengalaminya).', 'Ini mirip dengan 育つ, hanya saja sekarang Anda membesarkan seseorang. Kata ini berarti membesarkan atau membesarkan. Anda dapat mengingat ini karena てる. Versi Anda dalam membesarkan anak melibatkan merobek (てる) semua pakaian mereka untuk membuat mereka terlihat miskin sehingga mereka bisa mendapatkan makan siang yang lebih murah di sekolah. Anda kaya karena semua keringanan pajak yang Anda peroleh dari semua anak yang Anda besarkan, namun Anda selalu dapat menggunakan lebih banyak uang untuk memicu kecanduan StarCraft Anda (kita semua pernah mengalaminya).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'Untuk Memunculkan', true) ON CONFLICT DO NOTHING;
