INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'To Cultivate', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'そだてる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'ビエトとコウイチは、オフィスで野さいを育てるのが大好きです。', 'Viet dan Koichi senang menanam sayuran di kantor mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', 'この子犬をわたしの代わりに育ててくれませんか。わたしが育てたいんですが、来月から海王星に転きんになってしまったんです。', 'Bisakah Anda membesarkan anak anjing ini? Saya ingin sekali melakukannya, tetapi saya harus pindah ke Neptunus bulan depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbfd1be-b04c-49ff-be88-49a97120d436', '小学校の時、クラスで何を育ててた？うちのクラスはおたまじゃくしとハムスターとなすを育ててたんだけど、ハムスターはみんな逃げてねこに食べられちゃった。', 'Apa yang Anda angkat di kelas ketika Anda masih di sekolah dasar? Kelas kami beternak berudu, hamster, dan terong, tapi semua hamsternya kabur dan dimakan kucing.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', 'vocabulary', '追い付く', '追い付く', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Mengikuti lalu melekatkan diri Anda pada siapa pun yang Anda ikuti berarti mengejar seseorang.', 'Mengikuti lalu melekatkan diri Anda pada siapa pun yang Anda ikuti berarti mengejar seseorang.') ON CONFLICT (id) DO NOTHING;
