INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', 'To Keep Up With', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', 'おいつく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', '前日にシアトルまでと歩で出発したコウイチに車で五分もかからず追い付きました。', 'Kami naik mobil dan kurang dari lima menit kemudian kami menyusul Koichi yang berangkat ke Seattle dengan berjalan kaki pada hari sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', '100メートル走でクリステンに追い付くことができたらオリンピックに出られるよ。', 'Jika Anda bisa mengejar Kristen dalam lari seratus meter, Anda bisa berkompetisi di Olimpiade.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('178d8195-f1ce-4df8-a329-d2570b79266e', 'トーフグの塗り絵は人気すぎて、生産が需要に追い付かなかった。', 'Buku mewarnai Tofugu sangat populer sehingga produksinya tidak dapat memenuhi permintaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', 'vocabulary', '戦う', '戦う', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ini adalah versi kata kerja dari kosakata 戦い, yang saya harap Anda pelajari sebelumnya. Versi verbanya tentu saja berarti berperang atau berperang.', 'Ini adalah versi kata kerja dari kosakata 戦い, yang saya harap Anda pelajari sebelumnya. Versi verbanya tentu saja berarti berperang atau berperang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', 'Untuk Bertarung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', 'To Battle', false) ON CONFLICT DO NOTHING;
