INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', 'たたかう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', '第二次世界大戦で日本とアメリカは戦いました。', 'Jepang dan Amerika bertempur dalam Perang Dunia II.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', 'わたしたちは日本語がうまくなるために、毎日このかん字というきょ大な化け物と戦っているんです。', 'Kami bertarung melawan monster raksasa bernama kanji ini setiap hari agar kami bisa menguasai bahasa Jepang dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9e96fa8-7461-467e-a153-8f5355d4bcf3', '剣道は通常、一対一で戦う武道だが、コウイチは五年前、二人の男を同時に相手にしなくてはいけなかった。', 'Kendo biasanya merupakan seni bela diri satu lawan satu, tetapi 5 tahun yang lalu Koichi harus bertarung melawan dua orang sekaligus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82acf162-01f4-4837-ae05-d0889fb1b86d', 'vocabulary', '追いかける', '追いかける', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda tahu bahwa 追う berarti "mengikuti". Jadi, Anda mengikuti sesuatu atau seseorang, atau sesuatu yang serupa. Bayangkan saja かける karena Anda terlalu "sombong" tentang hal itu. Anda tidak hanya mengikuti orang ini, Anda mengejarnya, dengan maksud untuk menangkapnya. Jadi, kata ini adalah mengejar dan mengejar. Menakutkan!', 'Anda tahu bahwa 追う berarti "mengikuti". Jadi, Anda mengikuti sesuatu atau seseorang, atau sesuatu yang serupa. Bayangkan saja かける karena Anda terlalu "sombong" tentang hal itu. Anda tidak hanya mengikuti orang ini, Anda mengejarnya, dengan maksud untuk menangkapnya. Jadi, kata ini adalah mengejar dan mengejar. Menakutkan!') ON CONFLICT (id) DO NOTHING;
