INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('75bdd426-a2dc-4cbc-822d-39f6d33e9534', 'だいすき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75bdd426-a2dc-4cbc-822d-39f6d33e9534', '大好きです。', 'Aku mencintaimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75bdd426-a2dc-4cbc-822d-39f6d33e9534', 'なんだかんだ言っても、フグはワニカニのことが大好きなんですよ。', 'Apapun yang dia katakan, Fugu tetap sangat menyukai WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75bdd426-a2dc-4cbc-822d-39f6d33e9534', '天然ボケで、一緒にいていつも楽しいなって思うんだ。お前のこと大好きだよ。', 'Kamu agak konyol dan itu membuatmu asyik bergaul. Aku sangat menyukaimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a9623ff5-0f70-4511-bb11-46f80fc7eb7d', 'vocabulary', '伝わる', '伝わる', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja.
