INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a52fee-00b9-46f3-bf8e-2af1e220472d', '馬が馬小屋から放れました。', 'Seekor kuda dilepaskan dari kandang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a52fee-00b9-46f3-bf8e-2af1e220472d', '苦労して働いて、ようやくしゃっ金から放れることができました。', 'Saya bekerja keras dan akhirnya terbebas dari hutang saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a52fee-00b9-46f3-bf8e-2af1e220472d', 'ようやく子どもから手が放れたと思ったんだが、五十三歳の妻がまた妊娠してしまってね。', 'Saya berpikir bahwa saya akhirnya bebas dari keharusan merawat anak-anak saya, namun kemudian istri saya yang berusia 53 tahun hamil lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', 'vocabulary', '〜放題', '〜放題', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Lepaskan saja topiknya...biarkan bebas! Biarkan ia melakukan apa pun yang diinginkannya. Terkadang topiknya adalah makanan... jika demikian, lepaskan saja diri Anda dan lakukan apa pun yang Anda inginkan dengan makanan tersebut (makan semuanya!). Jika itu minuman, minumlah semuanya! Kata ini ada hubungannya dengan melakukan apa pun yang Anda inginkan dan sebanyak yang Anda inginkan. Anda akan melihat ini dilampirkan pada kata "sepuasnya ____", jadi nantikan kata-kata tersebut di beberapa level berikutnya.', 'Lepaskan saja topiknya...biarkan bebas! Biarkan ia melakukan apa pun yang diinginkannya. Terkadang topiknya adalah makanan... jika demikian, lepaskan saja diri Anda dan lakukan apa pun yang Anda inginkan dengan makanan tersebut (makan semuanya!). Jika itu minuman, minumlah semuanya! Kata ini ada hubungannya dengan melakukan apa pun yang Anda inginkan dan sebanyak yang Anda inginkan. Anda akan melihat ini dilampirkan pada kata "sepuasnya ____", jadi nantikan kata-kata tersebut di beberapa level berikutnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', 'Sebanyak yang Anda Inginkan', true) ON CONFLICT DO NOTHING;
