INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', 'ほうだい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', '食べ放題に行くといつも食べすぎてしまいます。', 'Setiap kali saya pergi ke restoran makan sepuasnya, saya akhirnya makan terlalu banyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', 'カラオケに行くなら、朝まで歌い放題のプランにしようよ。', 'Kalau kita pergi karaoke, kenapa kita tidak memilih plan dimana kita bisa bernyanyi sepuasnya sampai pagi hari?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da19052e-6855-4db8-b3b9-e32542957834', 'もしテキストフグの永久購読権を購読されるのであれば、日本語の学習がし放題ですよ。', 'Jika Anda membeli langganan Textfugu seumur hidup, Anda dapat belajar bahasa Jepang sebanyak yang Anda mau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', 'vocabulary', '求める', '求める', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Apa bentuk kata kerja dari permintaan? Itu untuk meminta. Ini juga berlaku ketika Anda menginginkan sesuatu (menginginkan sesuatu), karena jika Anda akan meminta sesuatu, Anda mungkin menginginkannya.', 'Apa bentuk kata kerja dari permintaan? Itu untuk meminta. Ini juga berlaku ketika Anda menginginkan sesuatu (menginginkan sesuatu), karena jika Anda akan meminta sesuatu, Anda mungkin menginginkannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', 'Menginginkan Sesuatu', true) ON CONFLICT DO NOTHING;
