INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', 'もとめる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', 'トーフグは、ポーカーフェイスができる人を求めています。', 'Tofugu menginginkan seseorang yang memiliki wajah poker face.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', '時々、返金を求めるメールがとどきます。', 'Terkadang kami menerima email yang meminta pengembalian dana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58d30947-fbf6-47bd-aee3-db2445137362', 'トーフグの顧客は、ますます環境に優しい日本語学習製品を求めるようになってきている。', 'Semakin banyak klien Tofugu yang menuntut produk pembelajaran bahasa Jepang yang ramah lingkungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'vocabulary', '求人', '求人', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Saat Anda meminta orang, Anda sedang melakukan perekrutan. Kata ini dapat digunakan untuk segala hal mulai dari mencari pekerja, tawaran pekerjaan, hingga kolom "dibutuhkan bantuan" di surat kabar.', 'Saat Anda meminta orang, Anda sedang melakukan perekrutan. Kata ini dapat digunakan untuk segala hal mulai dari mencari pekerja, tawaran pekerjaan, hingga kolom "dibutuhkan bantuan" di surat kabar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'Rekrutmen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'Seeking Workers', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'Help Wanted', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'Job Offer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'きゅうじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', '求人については、後ほどあらためてせつ明をいたします。', 'Kami akan menjelaskan tawaran pekerjaan nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', '近年は、ほぼ全てのき業が求人にインターネットを使います。', 'Saat ini, hampir semua perusahaan menggunakan Internet untuk merekrut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1af44e0f-b919-404b-af50-6737fd3ab8ec', 'トーフグのブログで拝見した求人の件でお電話しました。プログラマー職に応募したいのですが、ビエトさんはまだ生きていらっしゃいますか？今朝方刺客を送り込んでおいたのですが。', 'Saya menelepon mengenai posisi yang diiklankan di blog Tofugu. Saya ingin melamar posisi programmer, tapi apakah Pak Viet masih hidup? Saya mengirim seorang pembunuh untuk mengejarnya pagi ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', 'vocabulary', '飲み放題', '飲み放題', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Minum sebanyak yang Anda mau memang menyenangkan, tapi jangan sampai sakit. Saat Anda melihat kata ini, Anda tahu bahwa Anda sedang berada di tempat minum sepuasnya. Tip: Biasanya ada batasan waktu, jadi minumlah sebanyak-banyaknya!', 'Minum sebanyak yang Anda mau memang menyenangkan, tapi jangan sampai sakit. Saat Anda melihat kata ini, Anda tahu bahwa Anda sedang berada di tempat minum sepuasnya. Tip: Biasanya ada batasan waktu, jadi minumlah sebanyak-banyaknya!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', 'Minum Sepuasnya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', 'のみほうだい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', '食べ放題と飲み放題だったらどっちの方がおとくかな？', 'Saya ingin tahu mana yang lebih baik, makan sepuasnya atau minum sepuasnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', '「カナエ、ちょっと飲み会をき画してくれない？」「おっけー！どんなテーマの飲み会？」「うーんと、ビエトが日本で買ってきたコスプレコレクションのおひろ目会なんだけど。」「分かった。めっちゃ安い飲み放題のい酒屋でもいい？」', '"Bisakah kamu merencanakan pesta minum, Kanae?" "Oke! Apa tema pestanya?" “Yah, itu untuk presentasi koleksi cosplay Viet yang dia beli di Jepang.” "Oke. Bisakah kita melakukannya di Izakaya minuman sepuasnya yang super murah?"') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d32fa89d-ae4b-4e60-bdbc-0e83745e6741', '「じゃあ、あなたは昨夜飲み放題に行っていた訳ですね。他には何かしましたか？」「いや、まあそんなところだよ。」', '"Jadi, kamu pergi ke tempat minum sepuasnya tadi malam. Ada lagi?" "Tidak, itu saja."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', 'vocabulary', '食べ放題', '食べ放題', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Saat Anda makan sebanyak yang Anda mau, Anda mendapatkan penawaran makan sepuasnya.', 'Saat Anda makan sebanyak yang Anda mau, Anda mendapatkan penawaran makan sepuasnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', 'Makan Sepuasnya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', 'たべほうだい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', '一しょに食べ放題に行ったのが、とおい昔のような気がするよ。', 'Aku merasa ingatanku tentang pergi ke restoran sepuasnya bersamamu semakin menjauh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', '日本で、ケーキ食べ放題のカフェに行ってみたんですが、思っていたよりもたくさん食べられました。', 'Saya pergi ke kafe kue makan sepuasnya di Jepang dan ternyata saya bisa makan lebih banyak dari yang saya perkirakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b375cda9-f75d-4652-9e6a-41c1254eead0', 'よし、今がチャンスだ。さあ、焼き肉食べ放題へ行こう。', 'Oke, pantainya bersih. Ayo makan yakiniku sepuasnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45dda523-ec5b-4223-bedc-42b43fd4022a', 'vocabulary', '要求', '要求', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda memerlukan permintaan ini agar terjadi, jadi Anda tidak sekadar memintanya, Anda menuntutnya.', 'Anda memerlukan permintaan ini agar terjadi, jadi Anda tidak sekadar memintanya, Anda menuntutnya.') ON CONFLICT (id) DO NOTHING;
