INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45dda523-ec5b-4223-bedc-42b43fd4022a', '労働者たちは、ちん上げを要求した。', 'Buruh menuntut upah yang lebih tinggi.') ON CONFLICT DO NOTHING;
