INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('24796413-c378-4d98-8cc7-ec2ac780d374', 'vocabulary', '要求する', '要求する', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Mudah-mudahan Anda tahu bahwa 要求 adalah sebuah permintaan. Ketika Anda menjadikannya kata kerja, itu menjadi menuntut sesuatu.', 'Mudah-mudahan Anda tahu bahwa 要求 adalah sebuah permintaan. Ketika Anda menjadikannya kata kerja, itu menjadi menuntut sesuatu.') ON CONFLICT (id) DO NOTHING;
