INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7d6de531-4b90-4cd7-a58e-1c0096ea9d45', 'エルフをやといたいのは山々なんですが、言葉のかべがあるのでむずかしいんですよ。', 'Saya ingin mempekerjakan elf jika saya bisa, tetapi sulit karena kendala bahasa.') ON CONFLICT DO NOTHING;
