INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9cfcd33-3d0c-4f07-8106-aa12bf3c27fa', 'ワニカニの使い方の初歩を教えるビデオを作りました。', 'Kami membuat video untuk mengajari Anda ABC cara menggunakan WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9cfcd33-3d0c-4f07-8106-aa12bf3c27fa', '父はわたしに、日本のしょうぎというゲームの初歩をおしえてくれました。', 'Ayah saya mengajari saya dasar-dasar permainan Jepang "Shogi".') ON CONFLICT DO NOTHING;
