INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36d0becd-cbb5-465d-a0ea-2e54eaed2c5d', 'vocabulary', '言葉つき', '言葉つき', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ingat bagaimana 言葉 berarti "bahasa?" Nah, ketika kamu menambahkan つき di akhir kalimat, kamu akan berbicara sepanjang bulan (つき) terbit dan lebih memperhatikan ucapan dan kata-katamu sendiri.', 'Ingat bagaimana 言葉 berarti "bahasa?" Nah, ketika kamu menambahkan つき di akhir kalimat, kamu akan berbicara sepanjang bulan (つき) terbit dan lebih memperhatikan ucapan dan kata-katamu sendiri.') ON CONFLICT (id) DO NOTHING;
