INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9efde9aa-d395-46b1-9cff-3472fab0176f', 'これは日本の昔話ですか。', 'Apakah ini cerita rakyat Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9efde9aa-d395-46b1-9cff-3472fab0176f', 'まるで昔話の中に出てくるおひめさまみたいね。', 'Itu seperti seorang putri dalam legenda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9efde9aa-d395-46b1-9cff-3472fab0176f', 'バス待合所でバスを待ちながら、昔話の絵本を子どもに読み聞かせた。', 'Sambil menunggu bus di halte bus, saya membacakan buku cerita rakyat bergambar untuk anak saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('09079cfd-b3bc-4586-b8fd-2565ea0385db', 'vocabulary', '顔文字', '顔文字', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Ingat bagaimana Anda mengetahui bahwa 文字 dapat berarti "karakter?" Nah, buatlah wajah dari karakter-karakter itu dan Anda telah membuat kaomoji! ʅ(◔౪◔ ) ʃ', 'Ingat bagaimana Anda mengetahui bahwa 文字 dapat berarti "karakter?" Nah, buatlah wajah dari karakter-karakter itu dan Anda telah membuat kaomoji! ʅ(◔౪◔ ) ʃ') ON CONFLICT (id) DO NOTHING;
