INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09079cfd-b3bc-4586-b8fd-2565ea0385db', '今の気持ちを顔文字で表してください。', 'Silakan ungkapkan perasaan Anda saat ini dengan kaomoji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09079cfd-b3bc-4586-b8fd-2565ea0385db', 'ビエトがコウイチにあてた手紙を内しょで読んだら、全てが顔文字でかかれていた。', 'Aku diam-diam membaca surat Viet kepada Koichi, tapi semuanya ditulis dalam kaomoji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09079cfd-b3bc-4586-b8fd-2565ea0385db', '上司へのメールに顔文字を使うんじゃない！', 'Jangan gunakan kaomoji saat Anda mengirim email ke atasan!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1905473-acdf-4bbe-a033-a66d0cb25242', 'vocabulary', '親指', '親指', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jari orang tuamu adalah ibu jarimu! Ini lebih besar dari jari Anda yang lain, jadi itu berarti ia juga memegang kendali! Ini juga berlaku untuk jari-jari kaki Anda, maksud saya, jari-jari kaki Anda. Jadi jari kaki orang tua adalah jempol kaki Anda.', 'Jari orang tuamu adalah ibu jarimu! Ini lebih besar dari jari Anda yang lain, jadi itu berarti ia juga memegang kendali! Ini juga berlaku untuk jari-jari kaki Anda, maksud saya, jari-jari kaki Anda. Jadi jari kaki orang tua adalah jempol kaki Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1905473-acdf-4bbe-a033-a66d0cb25242', 'jempol', true) ON CONFLICT DO NOTHING;
