INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1905473-acdf-4bbe-a033-a66d0cb25242', '親指を放してくれ！', 'Lepaskan jempolku!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1905473-acdf-4bbe-a033-a66d0cb25242', 'きんちょうすると、親指がふるえます。', 'Saat aku gugup, ibu jariku gemetar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1905473-acdf-4bbe-a033-a66d0cb25242', '親指にタコができました。', 'Saya punya kapalan di ibu jari saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'vocabulary', '指先', '指先', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Anda tahu bagian jari Anda sebelumnya? Bagian yang baru saja saya potong? Ya, itu ujung jarimu! Saya hanya punya waktu untuk mendapatkan tipnya. Dulunya ada di jarimu dan sekarang ada di sini, di tanganku. Maaf, menurutku. Oh, tapi jangan khawatir, saya akan meratakan semuanya dan mendapatkan ujung jari kaki Anda dengan cepat juga.', 'Anda tahu bagian jari Anda sebelumnya? Bagian yang baru saja saya potong? Ya, itu ujung jarimu! Saya hanya punya waktu untuk mendapatkan tipnya. Dulunya ada di jarimu dan sekarang ada di sini, di tanganku. Maaf, menurutku. Oh, tapi jangan khawatir, saya akan meratakan semuanya dan mendapatkan ujung jari kaki Anda dengan cepat juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'Ujung Jari', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'Tip Of The Toe', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'ゆびさき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'マリアって、左の小指の指先のホクロがセクシーだよね？', 'Tidakkah menurutmu Maria memiliki tahi lalat yang seksi di ujung kelingking kirinya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', 'コウイチは、考え事をしている時、サッカーボールを指先でクルクルと回すくせがあります。', 'Koichi memiliki kebiasaan memutar bola di ujung jarinya sambil berpikir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8330811-0784-4066-9226-4b7390e1f151', '指先がかじかんでいます。', 'Ujung jariku mati rasa karena kedinginan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'vocabulary', '伝記', '伝記', 3, '6d5e1f8a-9b0c-7d2e-3f4a-5b6c7d8e9f0a', 'Jika Anda ingin menyampaikan kisah hidup seseorang, Anda harus menuliskan semuanya dalam biografi.', 'Jika Anda ingin menyampaikan kisah hidup seseorang, Anda harus menuliskan semuanya dalam biografi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'Biografi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'Life Story', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'でんき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'この投手の伝記、おも白かったよ。', 'Kisah hidup pelempar itu menarik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'その作家の伝記に書かれていたことは、とても意外だった。', 'Hal-hal yang tertulis dalam biografi penulis sungguh mengejutkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc03b6d7-be58-49f4-9b8b-7b64411fa9bd', 'まあ、そう思うのは、最近読んだ伝記の影響かもしれません。', 'Saya rasa saya mungkin merasa seperti ini karena saya dipengaruhi oleh biografi yang saya baca baru-baru ini.') ON CONFLICT DO NOTHING;
