INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('64848487-9eb4-43f2-b706-0a467e99c9a1', 'radical', '者', 'someone', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Radikal ini sama dengan kanji. Itu berarti seseorang.') ON CONFLICT (id) DO NOTHING;
