INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2fe311a0-567e-4288-ba00-2573eb7a9ab9', 'radical', '求', 'request', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Radikal ini sama dengan kanji. Artinya permintaan.') ON CONFLICT (id) DO NOTHING;
