INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d01bf71e-eba9-4edb-9f04-b376679b1cb6', 'radical', '其', 'crab', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ini terlihat seperti kerang yang radikal tetapi lebih tajam dan gila. Makhluk bercangkang manakah yang mempunyai duri dan penjepit? Kepiting yang perkasa!') ON CONFLICT (id) DO NOTHING;
