INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('974e89bd-09e8-4b6b-a8a9-30b75b23a7e4', 'vocabulary', '場合', '場合', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Lokasi manakah yang paling sesuai dengan situasi? Itu selalu tergantung pada kasus atau keadaan. Anda tidak dapat mengetahui kesesuaian lokasi sampai Anda mengetahui semua fakta mengenai keadaannya.', 'Lokasi manakah yang paling sesuai dengan situasi? Itu selalu tergantung pada kasus atau keadaan. Anda tidak dapat mengetahui kesesuaian lokasi sampai Anda mengetahui semua fakta mengenai keadaannya.') ON CONFLICT (id) DO NOTHING;
