INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a763439-dd95-4365-8e77-4a5326827164', 'このアプリ、すごく便利だよね。', 'Aplikasi ini sangat berguna bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a763439-dd95-4365-8e77-4a5326827164', '何か子育てに便利なアイテムを知っていたらぜひ教えて下さい。', 'Jika Anda mengetahui beberapa item yang nyaman untuk mengasuh anak, beri tahu saya.') ON CONFLICT DO NOTHING;
