INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('95bcb5d8-cd1e-4e83-81c9-832f32a9bccd', 'vocabulary', '労働', '労働', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Pekerjaan buruh adalah saat Anda melakukan pekerjaan dengan tubuh Anda, bukan? Itu pekerjaan manual.', 'Pekerjaan buruh adalah saat Anda melakukan pekerjaan dengan tubuh Anda, bukan? Itu pekerjaan manual.') ON CONFLICT (id) DO NOTHING;
