INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('95bcb5d8-cd1e-4e83-81c9-832f32a9bccd', 'ろうどう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95bcb5d8-cd1e-4e83-81c9-832f32a9bccd', 'あなたの労働時間は週何時間ですか？', 'Berapa jam Anda bekerja per minggu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95bcb5d8-cd1e-4e83-81c9-832f32a9bccd', 'うちの主人は年なので、肉体労働はちょっとさすがにきびしいかも。', 'Suami saya sudah tua, jadi pekerjaan kasar akan terlalu sulit baginya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95bcb5d8-cd1e-4e83-81c9-832f32a9bccd', '俺には何が必要か知ってるかい？趣味の部屋と新しい車だよ。労働の対価をきちんと受け取る必要があるだろ？', 'Anda tahu apa yang saya butuhkan? Gua manusia dan mobil baru. Saya perlu memberi penghargaan yang pantas pada diri saya sendiri atas kerja keras saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85e0303c-80b6-41f9-a2fb-ec7898d7ec30', 'vocabulary', '労働者', '労働者', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Seseorang yang melakukan kerja untuk suatu pekerjaan adalah seorang buruh.', 'Seseorang yang melakukan kerja untuk suatu pekerjaan adalah seorang buruh.') ON CONFLICT (id) DO NOTHING;
