INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('85e0303c-80b6-41f9-a2fb-ec7898d7ec30', 'ろうどうしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e0303c-80b6-41f9-a2fb-ec7898d7ec30', 'コウイチ社長は、肉体労働者の不足についてどうお考えなんですか？', 'Apa pendapat Presiden Koichi mengenai kekurangan pekerja kerah biru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e0303c-80b6-41f9-a2fb-ec7898d7ec30', '一体、お前と労働者たちの間に、何があったんだよ。', 'Apa yang terjadi antara Anda dan semua buruh?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e0303c-80b6-41f9-a2fb-ec7898d7ec30', 'ちょっとコピー機使わせてもらってもいい？新しい労働者を雇うために、チラシを作ってるんだけど。', 'Bisakah saya menggunakan mesin fotokopi? Saya membuat brosur untuk mencoba mendapatkan pekerja baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81b72888-939b-46bc-adb4-d82162dcf00b', 'vocabulary', '良い', '良い', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat baik? Itu juga bagus.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat baik? Itu juga bagus.') ON CONFLICT (id) DO NOTHING;
