INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81b72888-939b-46bc-adb4-d82162dcf00b', 'お羊ざと天びんざは相しょうが良い。', 'Aries dan Libra kompatibel.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81b72888-939b-46bc-adb4-d82162dcf00b', 'けんかするほど仲が良いって言うだろ？', 'Bukankah mereka berkata, "Semakin dekat Anda, semakin sering Anda bertengkar?"') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81b72888-939b-46bc-adb4-d82162dcf00b', '良い考えだけど、実際はそれをするには資金が足りないんだよね。', 'Itu ide yang bagus, tapi faktanya kita tidak punya cukup uang untuk itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a2e6cc8-27ae-4bc0-afde-57adc8488852', 'vocabulary', '不便', '不便', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sesuatu yang tidak nyaman adalah tidak nyaman.', 'Sesuatu yang tidak nyaman adalah tidak nyaman.') ON CONFLICT (id) DO NOTHING;
