INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c335eb5-3f15-49a9-bf8d-5a7c3a464dcb', 'べんじょ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c335eb5-3f15-49a9-bf8d-5a7c3a464dcb', 'へをこく時は便所に行けよ。', 'Anda harus pergi ke kamar mandi saat kentut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c335eb5-3f15-49a9-bf8d-5a7c3a464dcb', 'サトシ、ようやく便所そうじのスイッチが入ったみたいだね。', 'Tampaknya Satoshi akhirnya serius membersihkan kamar mandi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c335eb5-3f15-49a9-bf8d-5a7c3a464dcb', 'よっしゃ！完璧なシュートが決まったぜ！俺、ここの便所のバスケットゴール付きのゴミ箱めっちゃ好きだわ。', 'Oh ya! Hanya bersih! Saya sangat suka tempat sampah toilet ini dilengkapi jaring basket.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', 'vocabulary', '働く', '働く', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti bekerja, dan versi verbanya berarti bekerja, bekerja, dan terkadang melakukan (kejahatan).', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti bekerja, dan versi verbanya berarti bekerja, bekerja, dan terkadang melakukan (kejahatan).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', 'Untuk Bekerja', true) ON CONFLICT DO NOTHING;
