INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', 'はたらく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', '頭はガンガンするし、おなかはペコペコだったが、一日中働かなければいけなかった。', 'Saya harus bekerja sepanjang hari dengan sakit kepala dan perut kosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', '日本で働くために日本語をべん強しています。', 'Saya sedang belajar bahasa Jepang untuk bekerja di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7d841bab-25ad-4fc5-ae94-e16249db05a6', '「金曜日、トーフグの記事を読みに来ませんか？」「行きたいんですが、金曜日の夜は遅くまで働かないといけないんです。」「それは残念ですね。それでは、また今度。」', '"Apakah kamu ingin datang membaca artikel Tofugu pada hari Jumat?" "Aku ingin, tapi aku harus bekerja hingga larut malam pada Jumat." "Sayang sekali. Mungkin lain kali."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c6a8633-5e00-48fe-9a1a-2b60ae13cdb4', 'vocabulary', '家庭', '家庭', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Hakikat rumah dan taman Anda adalah keluarga, rumah tangga, atau rumah Anda.', 'Hakikat rumah dan taman Anda adalah keluarga, rumah tangga, atau rumah Anda.') ON CONFLICT (id) DO NOTHING;
