INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6c6a8633-5e00-48fe-9a1a-2b60ae13cdb4', 'かてい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c6a8633-5e00-48fe-9a1a-2b60ae13cdb4', 'いつかはけっこんして、あたたかい家庭をきずきたいと思っています。', 'Saya ingin menikah dan membangun rumah yang penuh kasih suatu hari nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c6a8633-5e00-48fe-9a1a-2b60ae13cdb4', 'わたしのしゅ味は、かく家庭から出るゴミをす手でしゅう集することです。', 'Hobi saya adalah memungut sampah setiap anggota rumah tangga dengan tangan kosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c6a8633-5e00-48fe-9a1a-2b60ae13cdb4', '日本女性と比べると、外国の女性は家庭の時間と仕事の時間を分けることには、かなり厳格です。', 'Dibandingkan dengan perempuan Jepang, perempuan asing cenderung cukup ketat dalam memisahkan waktu keluarga dan waktu kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca410f0e-bd90-4c2f-b267-1f6d04057a1d', 'vocabulary', '庭', '庭', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Anda juga dapat menambahkan halaman makna ke bank memori Anda, jika Anda mau.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Anda juga dapat menambahkan halaman makna ke bank memori Anda, jika Anda mau.') ON CONFLICT (id) DO NOTHING;
