INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca410f0e-bd90-4c2f-b267-1f6d04057a1d', '今日は、庭の地ならしをします。', 'Aku akan meratakan tanah di halaman hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca410f0e-bd90-4c2f-b267-1f6d04057a1d', '庭で家庭さいえんをしています。', 'Saya menanam sayuran di kebun kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca410f0e-bd90-4c2f-b267-1f6d04057a1d', 'うちには美しい庭があるんだが、隣の人の鶏がいつも花を食べてしまうんだ。', 'Saya mempunyai taman yang indah tetapi ayam tetangga saya terus memakan bunga saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('37f926d2-32cb-4fb3-8296-f84e8d6b0f6d', 'vocabulary', '息', '息', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
