INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37f926d2-32cb-4fb3-8296-f84e8d6b0f6d', 'あんたの息、死ぬほどくさいよ。', 'Napasmu sangat bau sehingga aku bisa mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37f926d2-32cb-4fb3-8296-f84e8d6b0f6d', 'びっくりしすぎて、息が止まるかと思ったよ。', 'Kamu membuatku kehabisan nafas!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37f926d2-32cb-4fb3-8296-f84e8d6b0f6d', '水中で息はしないでください。', 'Tolong jangan bernapas di bawah air.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('015f8672-6aad-4029-9303-3e64be322fb7', 'vocabulary', '息子', '息子', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Anak nafas (yang memungkinkan Anda melepaskan nafas saat lahir) adalah seorang anak laki-laki. Saat ini, memiliki seorang anak perempuan adalah hal yang keren, tetapi dulu Anda menginginkan seorang anak laki-laki untuk meneruskan warisan menenun keranjang bawah air Anda. Itu sebabnya ini adalah seorang putra.', 'Anak nafas (yang memungkinkan Anda melepaskan nafas saat lahir) adalah seorang anak laki-laki. Saat ini, memiliki seorang anak perempuan adalah hal yang keren, tetapi dulu Anda menginginkan seorang anak laki-laki untuk meneruskan warisan menenun keranjang bawah air Anda. Itu sebabnya ini adalah seorang putra.') ON CONFLICT (id) DO NOTHING;
