INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cf5d888-22a5-4ed5-a0bd-71a24894f693', 'トイレの水、流すのわすれたでしょう？', 'Anda lupa menyiram toilet, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cf5d888-22a5-4ed5-a0bd-71a24894f693', 'どうしてあの人たちがぬま地にあぶらを流してるか知っている？', 'Tahukah Anda mengapa mereka menuangkan minyak ke rawa?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cf5d888-22a5-4ed5-a0bd-71a24894f693', 'トーフグの風習に、河豚の形に切りとった紙を、コウイチの誕生日に川に流すというものがあります。', 'Adat istiadat Tofugu melibatkan pemotongan kertas menjadi bentuk fugu dan menaruhnya di sungai pada hari ulang tahun Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9b4124a-2b2f-4a46-8459-1fa2c0fa2120', 'vocabulary', '流行', '流行', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ke mana arus mengalir adalah ke mana semua orang pergi. Itulah yang cenderung menjadi tren. Bayangkan sebuah tren yang sedang terjadi di masyarakat Anda saat ini. Bayangkan ia mengalir ke sungai dan semua orang mengikutinya. Kata ini juga digunakan untuk tren yang kurang diinginkan, seperti prevalensi penyakit menular.', 'Ke mana arus mengalir adalah ke mana semua orang pergi. Itulah yang cenderung menjadi tren. Bayangkan sebuah tren yang sedang terjadi di masyarakat Anda saat ini. Bayangkan ia mengalir ke sungai dan semua orang mengikutinya. Kata ini juga digunakan untuk tren yang kurang diinginkan, seperti prevalensi penyakit menular.') ON CONFLICT (id) DO NOTHING;
