INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('792bde6e-7b18-4b40-b728-06e32cadeff9', '消したい過去があるんです。', 'Aku punya masa lalu yang ingin aku hapus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('792bde6e-7b18-4b40-b728-06e32cadeff9', '間違えてデータを全部消しちゃったんだよ。', 'Saya tidak sengaja menghapus semua data.') ON CONFLICT DO NOTHING;
