INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('87c87046-ad13-4428-af15-0514a91118bc', 'vocabulary', '東京都', '東京都', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Metropolis Tokyo, tentu saja, adalah Metropolis Tokyo. Secara teknis, ini adalah salah satu prefektur di Jepang, namun justru disebut "Metropolis". Ini adalah ibu kota dan kota terbesar di seluruh Jepang!', 'Metropolis Tokyo, tentu saja, adalah Metropolis Tokyo. Secara teknis, ini adalah salah satu prefektur di Jepang, namun justru disebut "Metropolis". Ini adalah ibu kota dan kota terbesar di seluruh Jepang!') ON CONFLICT (id) DO NOTHING;
