INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9ba268-38b3-4be6-9584-be80f2998244', '水深が急に深くなりましたね。', 'Airnya tiba-tiba menjadi dalam, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9ba268-38b3-4be6-9584-be80f2998244', 'コウイチがデスクで深いため息をついてるのを見たんだけど、何かあったの？', 'Aku melihat Koichi menghela nafas panjang, apa terjadi sesuatu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9ba268-38b3-4be6-9584-be80f2998244', '魚たちが、親や兄弟、高校時代の友人たちとの深い繋がりを保っていることが多いって、本当ですか？', 'Benarkah ikan cenderung menjaga hubungan mendalam dengan orang tua, saudara kandung, dan teman sekolahnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec4da8ce-53e7-449c-879b-ebeca77c5ab2', 'vocabulary', '深夜', '深夜', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Malam yang dalam adalah tengah malam. Tidak ada yang lebih dalam dari itu sebelum Anda mulai keluar malam untuk memulai hari berikutnya.', 'Malam yang dalam adalah tengah malam. Tidak ada yang lebih dalam dari itu sebelum Anda mulai keluar malam untuk memulai hari berikutnya.') ON CONFLICT (id) DO NOTHING;
