INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a4a9857-1e15-4577-840e-c2fc44a797df', '水深100フィートまでもぐったことがあります。', 'Saya pernah menyelam hingga kedalaman seratus kaki sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a4a9857-1e15-4577-840e-c2fc44a797df', 'このプールの水深はあさいから、心配しなくていいよ。', 'Anda tidak perlu khawatir karena kolam ini sangat dangkal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a4a9857-1e15-4577-840e-c2fc44a797df', 'ダイビングをしている際に、水深十メートルのところで虹色の海藻を見つけました。', 'Saat menyelam di kedalaman sepuluh meter, saya menemukan rumput laut berwarna pelangi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('47d01db5-c1ad-48a4-b14a-5b7d6c9ecc22', 'vocabulary', '最深', '最深', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Yang terdalam adalah yang terdalam.', 'Yang terdalam adalah yang terdalam.') ON CONFLICT (id) DO NOTHING;
