INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('47d01db5-c1ad-48a4-b14a-5b7d6c9ecc22', 'さいしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47d01db5-c1ad-48a4-b14a-5b7d6c9ecc22', '日本で最深な地下鉄は、地下48ｍの場所がある大え戸線です。', 'Jalur kereta bawah tanah terdalam di Jepang adalah jalur Oedo, yang berada sedalam 48 meter di bawah tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47d01db5-c1ad-48a4-b14a-5b7d6c9ecc22', 'しっとは人間の最深のつみだ。', 'Kecemburuan adalah dosa terdalam dari dosa manusia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47d01db5-c1ad-48a4-b14a-5b7d6c9ecc22', 'サーモンと俺は、光が到達できる海の最深部に位置するロマンチックな秘密の洞穴で、結婚式をあげた。', 'Salmon dan saya melangsungkan upacara pernikahan kami di sebuah gua romantis tersembunyi yang terletak di bagian terdalam lautan yang masih bisa dijangkau cahaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', 'vocabulary', '球', '球', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Arti lain yang akan saya tambahkan adalah bola olahraga karena ini adalah kata yang digunakan untuk bola dalam berbagai cabang olahraga (sepak bola, baseball, dll).', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Arti lain yang akan saya tambahkan adalah bola olahraga karena ini adalah kata yang digunakan untuk bola dalam berbagai cabang olahraga (sepak bola, baseball, dll).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', 'Bola', true) ON CONFLICT DO NOTHING;
