INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', 'きゅう', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', 'ああっ！球がバンカーに入っちゃったよ。', 'Sial! Saya memukul bola ke dalam bunker.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', '球の体せきをもとめる公しきって何だっけ？', 'Apa rumus volume bola?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67e88a14-e017-4474-9151-1f832f6c6f9e', 'ねぇ、新しい野球の球を買ったんだけど、一緒にキャッチボールしない？', 'Hei, aku punya bola bisbol baru. Apakah kamu ingin bermain-main denganku?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d07c9e19-393e-4514-850b-409057fea815', 'vocabulary', '野球', '野球', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Bola Lapangan! Olah raga terhebat yang menghiasi muka bumi ini sejak olah raga yang sangat mirip (alias sama), baseball. Coba pikirkan, Anda bermain di lapangan dan menggunakan bola kecil. Luar biasa!', 'Bola Lapangan! Olah raga terhebat yang menghiasi muka bumi ini sejak olah raga yang sangat mirip (alias sama), baseball. Coba pikirkan, Anda bermain di lapangan dan menggunakan bola kecil. Luar biasa!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d07c9e19-393e-4514-850b-409057fea815', 'Bisbol', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d07c9e19-393e-4514-850b-409057fea815', 'やきゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d07c9e19-393e-4514-850b-409057fea815', 'これから、プロ野球のし合を見に行くところなんです。', 'Kami baru saja akan pergi ke pertandingan bisbol profesional.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d07c9e19-393e-4514-850b-409057fea815', '野球は好きだけど、野球部は体育会けいって聞いたから入りたくないんだよ。', 'Aku suka bisbol, tapi kudengar kamu harus bertindak seolah-olah kamu adalah tentara jika kamu tergabung dalam klub bisbol, jadi aku tidak ingin bergabung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d07c9e19-393e-4514-850b-409057fea815', '野球をしている時に膝を骨折しちゃったんだよね。', 'Lutut saya patah saat bermain bisbol.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b9d4c06-7cab-4df4-8a5a-4a5aa8b44064', 'vocabulary', '太陽', '太陽', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sinar matahari yang tebal di langit... apa namanya? Oh, benar. Itu matahari.', 'Sinar matahari yang tebal di langit... apa namanya? Oh, benar. Itu matahari.') ON CONFLICT (id) DO NOTHING;
