INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c1569bb-a990-4e69-bc0c-19e6ef562fe5', '寒すぎてふとんから出られない。', 'Terlalu dingin untuk bangun dari tempat tidur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c1569bb-a990-4e69-bc0c-19e6ef562fe5', 'この寒い中、一時間もバスを待たなきゃならなかったんだよ。', 'Saya harus menunggu satu jam dalam cuaca dingin ini untuk mendapatkan bus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c1569bb-a990-4e69-bc0c-19e6ef562fe5', '僕がハワイに行くのは、寒さから逃れるためだけではなく家族に会うためでもあります。', 'Saya pergi ke Hawaii bukan hanya untuk menghindari kedinginan, tetapi juga untuk bertemu keluarga saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b696b47-93a8-4530-9c8e-dbde9efedee3', 'vocabulary', '期待', '期待', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Untuk jangka waktu tertentu Anda harus menunggu. Selama masa tunggu ini, Anda mengharapkan atau mengantisipasi sesuatu akan terjadi. Menunggu, mengharapkan, menunggu, mengharapkan...', 'Untuk jangka waktu tertentu Anda harus menunggu. Selama masa tunggu ini, Anda mengharapkan atau mengantisipasi sesuatu akan terjadi. Menunggu, mengharapkan, menunggu, mengharapkan...') ON CONFLICT (id) DO NOTHING;
