INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('de958fa5-fed3-4d01-9283-3d8d68e1d7d8', '半年に一度は歯医者に行った方がいい。', 'Sebaiknya kunjungi dokter gigi minimal enam bulan sekali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('de958fa5-fed3-4d01-9283-3d8d68e1d7d8', '花田さんは、この歯医者にはもっ体ないよ。', 'Bu Handa terlalu baik untuk dokter gigi ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('de958fa5-fed3-4d01-9283-3d8d68e1d7d8', '彼はただ不良に憧れてるだけだと思うよ。絶対に本物の不良にはならないね。だって、歯医者さんに行くのですら怖がってるんだよ！', 'Menurutku, dia hanyalah seorang berandalan. Saya ragu dia akan menjadi nyata karena dia masih takut pergi ke dokter gigi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc0d3ffa-b3ae-4491-a1aa-ff3a455406db', 'vocabulary', '歯', '歯', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
