INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc0d3ffa-b3ae-4491-a1aa-ff3a455406db', '七本目の歯が生えてきました。', 'Gigi ketujuhnya tumbuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc0d3ffa-b3ae-4491-a1aa-ff3a455406db', 'タバコのすいすぎで歯が黄色くなってしまった。', 'Saya merokok sangat banyak sehingga gigi saya menjadi kuning sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc0d3ffa-b3ae-4491-a1aa-ff3a455406db', '電動歯ブラシを買うことを考えているんだが、どれも値段が高いんだよね。', 'Saya sedang berpikir untuk membeli salah satu sikat gigi elektrik itu, tapi harganya sangat mahal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a63168e0-d4a0-4c97-b098-7a57722c4acf', 'vocabulary', '空港', '空港', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Singkirkan sejenak fantasi balon steampunk Anda. Sky harbour adalah bandara, tidak lebih.', 'Singkirkan sejenak fantasi balon steampunk Anda. Sky harbour adalah bandara, tidak lebih.') ON CONFLICT (id) DO NOTHING;
