INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3adc9e56-1a8d-4b68-aa69-874e7b206c2a', 'のぼる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3adc9e56-1a8d-4b68-aa69-874e7b206c2a', 'この長くてきゅうなさかを登るのはかなりキツイっすね。', 'Mendaki lereng yang panjang dan curam ini sungguh berat, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3adc9e56-1a8d-4b68-aa69-874e7b206c2a', 'コウイチは、さるのようにスイスイと木に登り、いともかんたんにバナナを取っておりてきました。', 'Koichi memanjat pohon secepat monyet dan turun membawa pisang tanpa mengeluarkan keringat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3adc9e56-1a8d-4b68-aa69-874e7b206c2a', '一生の内、少なくとも一度は富士山に登ることが夢なんです。', 'Impian saya adalah mendaki Gunung Fuji setidaknya sekali seumur hidup.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', 'vocabulary', '登山', '登山', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Naiki gunung. Itulah pendakian gunung.', 'Naiki gunung. Itulah pendakian gunung.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', 'Mendaki Gunung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', 'とざん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', 'ふじ山に登山してみたいです。', 'Saya ingin mencoba mendaki Gunung Fuji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', 'もう登山はこりごりです。', 'Saya tidak pernah ingin mendaki gunung lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4dc35f6c-886f-4af7-8545-6f826e09ea51', '「登山に行くってのはどう？」「さあ、どうしようかなあ。」', '"Bagaimana kalau kita mendaki gunung?" "Yah, aku tidak tahu tentang itu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'vocabulary', '合う', '合う', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya sesuai jadi versi kata kerjanya adalah sesuai. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'Sesuai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'To Come Together', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'To Meet', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'To Match', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'あう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', '肉りょうりには赤ワインが合います。', 'Anggur merah cocok dipadukan dengan hidangan daging.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', '合うかどうか、しちゃくしてかくにんした方がいいよ。', 'Anda harus mencobanya untuk melihat apakah itu cocok untuk Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a345be97-db35-4265-9fc3-b31a1a683acf', 'アメリカのインド料理は、アメリカ人の口に合うよう、実際のインドでの調理方法とはかなり違った方法で作られている。', 'Masakan India di Amerika sedikit diubah dari cara penyajiannya di India agar sesuai dengan selera Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'vocabulary', '間に合う', '間に合う', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ada interval (waktu) yang perlu Anda "sesuaikan" (合う). Untuk menyesuaikan interval tersebut, Anda harus tiba di sana sebelum waktu yang dimaksud. Itu sebabnya kata ini berarti tepat waktu, tepat waktu, atau tepat waktu.', 'Ada interval (waktu) yang perlu Anda "sesuaikan" (合う). Untuk menyesuaikan interval tersebut, Anda harus tiba di sana sebelum waktu yang dimaksud. Itu sebabnya kata ini berarti tepat waktu, tepat waktu, atau tepat waktu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'Tepat Waktu Untuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'To Make It On Time', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'To Be On Time For', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'まにあう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', '今すぐタクシーに乗れば、まだ間に合うかもしれません。', 'Jika kita naik taksi sekarang, kita mungkin masih sampai tepat waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', 'ごめん！じゅうたいにはまっちゃって、待ち合わせに間に合いそうにない。', 'Maaf! Saya terjebak kemacetan, jadi kemungkinan besar saya tidak akan datang tepat waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5abcfab-52ab-4a10-8b31-154a2a4a1d43', '「間に合うと思う？」「もうすぐ7時なんだから、後は自分で考えればわかるだろ。」', '“Apakah menurutmu kita bisa tiba tepat waktu?” "Yah, ini hampir jam tujuh. Hitunglah."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', 'vocabulary', '知り合い', '知り合い', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Anda mungkin pernah melihat kata 知る dan 合う sekarang. Ini adalah seseorang yang Anda "kenal" karena Anda pernah "bertemu" sebelumnya, tapi itu saja. Anda belum begitu mengenal mereka dengan baik, Anda baru bertemu mereka beberapa kali sehingga Anda tahu siapa mereka. Orang ini adalah seorang kenalan.', 'Anda mungkin pernah melihat kata 知る dan 合う sekarang. Ini adalah seseorang yang Anda "kenal" karena Anda pernah "bertemu" sebelumnya, tapi itu saja. Anda belum begitu mengenal mereka dengan baik, Anda baru bertemu mereka beberapa kali sehingga Anda tahu siapa mereka. Orang ini adalah seorang kenalan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', 'Kenalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', 'しりあい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', '知り合いにたのんで、トーフグのコウイチからサインをもらいました。', 'Saya bertanya kepada seorang kenalan apakah mereka bisa memberi saya tanda tangan Koichi dari Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', '今知り合いにれんあい相だんしてるから、カラオケには行けないかも。ごめんね！', 'Aku sedang berkonsultasi dengan kenalanku tentang hubunganku dengan pacarku saat ini, jadi aku mungkin tidak akan bisa ikut pesta karaoke. Maaf!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9877017-5286-4aea-9a4b-5bd7ce87c1a0', 'ここだけの話なんだけど、上司が知り合いの人妻と浮気しているのよね。', 'Jangan bilang siapa-siapa tapi bos saya berselingkuh dengan wanita yang sudah menikah yang merupakan kenalan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', 'vocabulary', '宿題', '宿題', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Pondok tempat Anda menginap memiliki topik seputarnya. Anggap saja sebagai sebuah tema. Tema ini sedang mengerjakan pekerjaan rumah Anda. Jadi ya, Anda baru saja pergi ke penginapan yang bagus untuk berlibur hanya untuk mengerjakan pekerjaan rumah kemana-mana.', 'Pondok tempat Anda menginap memiliki topik seputarnya. Anggap saja sebagai sebuah tema. Tema ini sedang mengerjakan pekerjaan rumah Anda. Jadi ya, Anda baru saja pergi ke penginapan yang bagus untuk berlibur hanya untuk mengerjakan pekerjaan rumah kemana-mana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', 'Pekerjaan rumah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', 'しゅくだい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', 'ななめから見てるから、宿題の答えが見えづらいんだよね。', 'Sulit untuk melihat jawaban pekerjaan rumah Anda karena saya melihatnya dari sudut pandang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', '今日のわたしの宿題、ちょっと見てもらえないかな？', 'Bisakah Anda melihat sekilas pekerjaan rumah saya mulai hari ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e02868b9-b5c8-4685-9320-0947fa54212d', '「でも、ママ！僕…」「つべこべ言わないの。さあ、自分の部屋へ行って、宿題をしなさい。」', '"Tapi, Bu! Aku..." "Tidak ada tapi. Sekarang pergilah ke kamarmu dan kerjakan pekerjaan rumahmu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', 'vocabulary', '新宿', '新宿', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Area penginapan baru adalah Shinjuku, distrik populer di Tokyo. Mungkin ada banyak tempat menginap di Shinjuku. Apa pun itu, Anda harus mengunjunginya, itu menyenangkan! Akan sangat membantu jika Anda juga pernah mendengar tentang Shinjuku sebelumnya. Lakukan riset tentang Shinjuku jika Anda belum pernah mendengarnya.', 'Area penginapan baru adalah Shinjuku, distrik populer di Tokyo. Mungkin ada banyak tempat menginap di Shinjuku. Apa pun itu, Anda harus mengunjunginya, itu menyenangkan! Akan sangat membantu jika Anda juga pernah mendengar tentang Shinjuku sebelumnya. Lakukan riset tentang Shinjuku jika Anda belum pernah mendengarnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', 'Shinjuku', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', 'しんじゅく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', 'この新宿のホテルのシャワーは、水かぬるま湯しか出ない。', 'Kamar mandi di hotel Shinjuku ini hanya memiliki air dingin atau suam-suam kuku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', '新宿は毎年、わたしの行ってみたい場所ランキングの中で最下位です。', 'Shinjuku selalu berada di urutan terakhir dalam daftar tempat yang ingin saya kunjungi setiap tahunnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('065d11bc-a24a-4573-b855-abdfb529f250', '新宿二丁目は今はゲイタウンとして知られていますが、昔は危険な香りのする赤線地区でした。', 'Shinjuku 2-chome sekarang dikenal sebagai kota gay tetapi dulunya merupakan distrik lampu merah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'vocabulary', '予想', '予想', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Anda sudah punya gambaran konsepnya sebelumnya alias sudah tahu apa yang akan terjadi, atau setidaknya sudah punya ide. Ini adalah ekspektasi terhadap apa yang akan terjadi selanjutnya. Namun jangan biarkan antisipasi Anda menguasai Anda!', 'Anda sudah punya gambaran konsepnya sebelumnya alias sudah tahu apa yang akan terjadi, atau setidaknya sudah punya ide. Ini adalah ekspektasi terhadap apa yang akan terjadi selanjutnya. Namun jangan biarkan antisipasi Anda menguasai Anda!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'Harapan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'Anticipation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'Expect', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'Anticipate', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'Prediction', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'よそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', 'わたしは未来を予想できるんです。', 'Saya bisa memprediksi masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', '今日もコウイチはちこくするであろうというわたしの予想は見事に外れてしまった。', 'Prediksiku kalau Koichi akan terlambat lagi hari ini ternyata salah total.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70a39d5a-2329-4b39-b8b0-488b297a46e1', '予想外の出来事が生じているため、今日は氷の舟で溶岩のプールを渡ることはできません。', 'Karena keadaan yang tidak terduga, perahu es tidak akan melintasi kolam lava hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'vocabulary', '回想', '回想', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Anda memikirkan konsep tersebut beberapa kali, setiap kali memikirkan setiap kali Anda memikirkan konsep ini sebelumnya. Setiap kali Anda melihat ke belakang, itulah retrospeksi terhadap konsep tersebut. Anda melihat ke belakang berkali-kali sampai tidak ada lagi waktu untuk melihat ke belakang.', 'Anda memikirkan konsep tersebut beberapa kali, setiap kali memikirkan setiap kali Anda memikirkan konsep ini sebelumnya. Setiap kali Anda melihat ke belakang, itulah retrospeksi terhadap konsep tersebut. Anda melihat ke belakang berkali-kali sampai tidak ada lagi waktu untuk melihat ke belakang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'Retrospeksi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'Reminiscence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'かいそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'この映画のこの回想のシーンがすごくすきなんだよね。', 'Saya sangat menyukai adegan retrospektif dalam film ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'コウイチはえんがわでネコと一しょにとりとめのない回想にふけっていた。', 'Koichi mengenang kucingnya di beranda dengan tidak jelas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b682a5d-40d9-41cd-95c7-da5d6f9d8988', 'ビエトが時々、仕事中にヤクザ時代のことを回想しているのをわたしは知っている。', 'Saya tahu Viet terkadang mengenang hari-hari yakuza-nya selama jam kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'vocabulary', '思想', '思想', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Konsep yang Anda pikirkan adalah pemikiran Anda. Itu adalah ide Anda. Sebagai sebuah kelompok, mereka membentuk ideologi Anda.', 'Konsep yang Anda pikirkan adalah pemikiran Anda. Itu adalah ide Anda. Sebagai sebuah kelompok, mereka membentuk ideologi Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'Pikir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'Idea', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'Ideology', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'しそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'コウイチの思想にはついていけません。', 'Saya tidak bisa mengikuti pikiran Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'きのう、ニュースを見ていたら、ビエトが思想犯としてたいほされたニュースが出て本当にびっくりしたよ。', 'Saat saya menonton berita kemarin, saya sangat terkejut hingga dikatakan bahwa Viet ditangkap karena kejahatan pemikiran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee58de5a-bcae-4d27-94bf-6161011df3ee', 'コウイチはトーフグの創始者であり、近代日本を代表する啓蒙思想家である。', 'Koichi adalah pendiri Tofugu dan salah satu pemikir besar modern Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', 'vocabulary', '五感', '五感', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Lima perasaan yang kamu miliki itu apa? Penglihatan, pendengaran, pengecapan, sentuhan dan penciuman (jangan hitung yang keenam dimana anda melihat orang mati). Inilah panca indera yang mungkin Anda miliki.', 'Lima perasaan yang kamu miliki itu apa? Penglihatan, pendengaran, pengecapan, sentuhan dan penciuman (jangan hitung yang keenam dimana anda melihat orang mati). Inilah panca indera yang mungkin Anda miliki.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', 'Panca Indera', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', 'Five Senses', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', 'ごかん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', '五感のうちどれか一つを失ってしまうとしたら、どれを選びますか？また、その理由も教えてください。', 'Jika Anda harus kehilangan salah satu dari kelima indera Anda, manakah yang akan Anda tinggalkan dan mengapa?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', 'さく夜のゆめで、今までにかいだことのないにおいを感じました。五感ってねている間も働いているんでしょうか。', 'Dalam mimpiku tadi malam, ada bau yang tidak kusadari sebelumnya... apakah kelima indera bekerja dalam mimpi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6bc4a1e7-83a3-4da8-8896-791feba1c373', '五感に関する日本語の単語と動詞の他に、第六感に関する語彙も学習してください。', 'Silakan pelajari kata-kata dan kata kerja bahasa Jepang yang berhubungan dengan panca indera, serta beberapa kosakata bahasa Jepang yang berhubungan dengan indra keenam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1964548c-4e15-4ffc-908c-b94f5f2d981a', 'vocabulary', '同感', '同感', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ketika Anda memiliki perasaan yang sama dengan orang lain, Anda bersimpati padanya, karena Anda tahu bagaimana perasaannya. Anda baik sekali!', 'Ketika Anda memiliki perasaan yang sama dengan orang lain, Anda bersimpati padanya, karena Anda tahu bagaimana perasaannya. Anda baik sekali!') ON CONFLICT (id) DO NOTHING;
