INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1964548c-4e15-4ffc-908c-b94f5f2d981a', 'わたしはコウイチの意見に同感ですね。', 'Saya berempati dengan pandangan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1964548c-4e15-4ffc-908c-b94f5f2d981a', '今までにこんなに同感したことがないぐらい、思いっきり同感しています。', 'Saya tidak pernah begitu setuju dengan seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1964548c-4e15-4ffc-908c-b94f5f2d981a', '「私、フグのこと嫌い。」「同感だわ。」', '"Aku benci Fugu." “Saya merasakan hal yang sama.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('22e91dc6-b06e-4981-b5b9-35945455a003', 'vocabulary', '待合室', '待合室', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sebuah ruangan tempat Anda bergabung dengan orang lain untuk menunggu. Ini adalah ruang tunggu.', 'Sebuah ruangan tempat Anda bergabung dengan orang lain untuk menunggu. Ini adalah ruang tunggu.') ON CONFLICT (id) DO NOTHING;
