INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('826ddab5-4b9f-41b3-b619-4034b1fd6f5d', 'かんどうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('826ddab5-4b9f-41b3-b619-4034b1fd6f5d', '感動してなみだが止まりません。', 'Itu sangat mengharukan, saya tidak bisa berhenti menangis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('826ddab5-4b9f-41b3-b619-4034b1fd6f5d', 'トーフグのせつ立ひ話を聞いて、とても感動しました。', 'Saya mendengar cerita rahasia bagaimana Tofugu didirikan dan sangat tersentuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('826ddab5-4b9f-41b3-b619-4034b1fd6f5d', 'なんてこった！今までの人類の歴史上で最高の日本語学習教材を作っちまったぜ！みんなマジで感動するだろうな！', 'Astaga! Saya baru saja membuat materi pembelajaran bahasa Jepang terbaik dalam sejarah umat manusia! Semua orang akan sangat bersemangat!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', 'vocabulary', '感心', '感心', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Perasaanmu ada di hatimu. Ketika perasaan Anda ada di dalam hati Anda, itu adalah perasaan yang murni. Anda bisa berbahagia untuk orang lain dan merasakan kekaguman atas kesuksesan mereka. Ini adalah perasaan yang luar biasa untuk ada di hati Anda.', 'Perasaanmu ada di hatimu. Ketika perasaan Anda ada di dalam hati Anda, itu adalah perasaan yang murni. Anda bisa berbahagia untuk orang lain dan merasakan kekaguman atas kesuksesan mereka. Ini adalah perasaan yang luar biasa untuk ada di hati Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', 'Kekaguman', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', 'かんしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', '感心なお子さんですね。', 'Anda memiliki anak yang mengagumkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', '毎日休まずに部屋をそうじするなんて、感心、感心。', 'Anda mendapatkan kekaguman saya dengan membersihkan kamar Anda setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b9f8b02-d7c3-4c70-bcb6-cc67c85b30b0', 'ケイティは、真面目で熱心な働きと細かい気配りで、同僚たちを感心させた。', 'Katie mendapatkan kekaguman dari rekan kerjanya atas kerja keras dan perhatiannya terhadap detail.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', 'vocabulary', '感想', '感想', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Saat Anda mengambil perasaan Anda dan mengonsepnya, Anda memunculkan kesan dan pemikiran Anda tentang subjek tersebut. Itu sebabnya kata ini adalah pikiran atau kesan.', 'Saat Anda mengambil perasaan Anda dan mengonsepnya, Anda memunculkan kesan dan pemikiran Anda tentang subjek tersebut. Itu sebabnya kata ini adalah pikiran atau kesan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', 'Tayangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', 'One''s Impressions', false) ON CONFLICT DO NOTHING;
