INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', 'かんそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', 'マイケルの日かは、毎朝同りょう全員に前日に見たアニメの感想を話すことです。', 'Rutinitas Michael sehari-hari adalah menceritakan pemikirannya kepada semua rekannya mengenai anime yang ditontonnya sehari sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', '文学がきらいなわたしの弱点の一つは、読んだ小せつの感想を聞かれても「よかった」としか言えないことである。', 'Salah satu kekurangan saya sebagai orang yang tidak menyukai sastra adalah saya hanya bisa berkata “bagus” ketika ditanya kesan saya terhadap novel yang saya baca.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad4e1a56-dafa-4dd7-bfae-1d6eb51322c8', '私達のサイトについて、感想をお聞かせください。どんなご意見でも結構です。', 'Silakan lihat situs kami dan beritahu kami kesan Anda. Setiap komentar akan dihargai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('422cf55a-d14a-4cd0-9c53-6d33fe5a56c9', 'vocabulary', '暗い', '暗い', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat gelap? Gelap.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat gelap? Gelap.') ON CONFLICT (id) DO NOTHING;
