INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('422cf55a-d14a-4cd0-9c53-6d33fe5a56c9', 'くらい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('422cf55a-d14a-4cd0-9c53-6d33fe5a56c9', 'もうちょっとiPhoneの画面を暗くしてくれませんか。', 'Bisakah Anda membuat layar iPhone Anda sedikit lebih gelap?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('422cf55a-d14a-4cd0-9c53-6d33fe5a56c9', '田中さんは暗やみきょうふしょうなので、部屋が暗いとねむれないんですって。', 'Kudengar Pak Tanaka mengidap nyctophobia, jadi dia tidak bisa tidur di kamar yang gelap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('422cf55a-d14a-4cd0-9c53-6d33fe5a56c9', '最近、暗いニュースばっかりだけど、こんな暗い世の中でも滅茶苦茶良いことだってあるんだよ。えっと、それで…うーん。何を言いかけたのか忘れちゃったんだけど、とにかく、僕と結婚してくれませんか？', 'Segala sesuatu dalam berita akhir-akhir ini menyedihkan, tetapi ada hikmah besar dari awan gelap ini, Anda tahu. Dan... yah... Aku agak kehilangan akal, tapi maukah kau menikah denganku?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac8320c9-e5a2-432d-bdcf-d3bfbe324654', 'vocabulary', '暗殺', '暗殺', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Pembunuhan gelap adalah pembunuhan. Itu dilakukan oleh seseorang yang mengenakan pakaian ninja dan berkulit gelap, bersembunyi di balik bayang-bayang untuk momen menyerang.', 'Pembunuhan gelap adalah pembunuhan. Itu dilakukan oleh seseorang yang mengenakan pakaian ninja dan berkulit gelap, bersembunyi di balik bayang-bayang untuk momen menyerang.') ON CONFLICT (id) DO NOTHING;
