INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ac8320c9-e5a2-432d-bdcf-d3bfbe324654', 'あんさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac8320c9-e5a2-432d-bdcf-d3bfbe324654', 'そのヤクザの組長は暗殺されてしまいました。', 'Bos yakuza itu akhirnya dibunuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac8320c9-e5a2-432d-bdcf-d3bfbe324654', 'もう暗殺教室の映画は見ましたか？とってもおも白いですよね〜。', 'Apakah kamu sudah menonton film Assassination Classroom? Menyenangkan sekali, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac8320c9-e5a2-432d-bdcf-d3bfbe324654', 'ねぇ、ビエト！どうやってこんなに面白い暗殺計画を思いついたの？', 'Hei, Vietnam! Bagaimana Anda bisa membuat rencana pembunuhan yang unik?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd9b316a-8b87-4bac-b2a6-7e7f364258e4', 'vocabulary', '暗記', '暗記', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Dalam kegelapan jika Anda mencoba menuliskan sesuatu, itu tidak akan berhasil dengan baik. Anda tidak dapat melihat. Jadi, bagaimana Anda bisa "menulis sesuatu" dalam kegelapan? Anda menuliskannya dalam pikiran Anda. Ini adalah menghafal! Kenali kata ini? Aplikasi SRS "Anki" berasal dari kata ini, menurutku!', 'Dalam kegelapan jika Anda mencoba menuliskan sesuatu, itu tidak akan berhasil dengan baik. Anda tidak dapat melihat. Jadi, bagaimana Anda bisa "menulis sesuatu" dalam kegelapan? Anda menuliskannya dalam pikiran Anda. Ini adalah menghafal! Kenali kata ini? Aplikasi SRS "Anki" berasal dari kata ini, menurutku!') ON CONFLICT (id) DO NOTHING;
