INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd9b316a-8b87-4bac-b2a6-7e7f364258e4', '短期間で丸暗記しても、すぐわすれてしまうだろう？', 'Sekalipun Anda menggunakan hafalan untuk menghafalnya dalam jangka pendek, Anda akan segera melupakannya lagi, bukan?') ON CONFLICT DO NOTHING;
