INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37fb8566-ad4b-4dc2-8aea-ef291b278c7d', 'ハリケーンとの天気予ほうがあったのに、全然雨がふらなかった。', 'Meskipun prakiraan cuaca menyebutkan akan terjadi badai, namun kami tidak mendapatkan hujan sama sekali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37fb8566-ad4b-4dc2-8aea-ef291b278c7d', '「すみませんが、ちょっとたのみ事をしてもいいですか。」「はい、全然いいですよ！」', '"Maaf, tapi bolehkah saya meminta sedikit bantuan?" Tentu saja!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37fb8566-ad4b-4dc2-8aea-ef291b278c7d', '「分かりましたか？」 「申し訳ないのですが、チンプンカンプンで全然分かりません。今言ったことをもう少しゆっくり言っていただけませんか？」', '"Apakah kamu mengerti?" "Maafkan aku. Aku benar-benar bingung. Bisakah kamu mengatakannya lagi dengan lebih pelan?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fed04640-eb25-49b5-8053-98a8ce8f13bf', 'vocabulary', '当然', '当然', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sesuatu yang secara alami benar adalah sesuatu yang sangat jelas dan alami. Anda tahu itu, kan? 当然!', 'Sesuatu yang secara alami benar adalah sesuatu yang sangat jelas dan alami. Anda tahu itu, kan? 当然!') ON CONFLICT (id) DO NOTHING;
