INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73b84d6d-f160-46ef-ac86-4a231973ac93', 'コウイチとコウイチ子がこいに落ちるのはとても自然なことでした。', 'Wajar jika Koichi dan Koichiko saling jatuh cinta.') ON CONFLICT DO NOTHING;
