INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4779ae3d-c1c2-4799-b7b4-f4be3aaf2254', '山登りがしゅ味なんですか？', 'Apakah mendaki gunung merupakan hobi Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4779ae3d-c1c2-4799-b7b4-f4be3aaf2254', 'ものしずかな友人と、山登りに行ってきました。', 'Aku pergi mendaki gunung bersama temanku yang pendiam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4779ae3d-c1c2-4799-b7b4-f4be3aaf2254', 'お互い色々あったんだけど、山登りをしながらじっくり話し合ってさ。なんと復縁することになったよ。', 'Kami berdua telah melalui banyak hal, namun kami berbicara panjang lebar saat mendaki gunung dan memutuskan untuk kembali bersama.') ON CONFLICT DO NOTHING;
