INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff875bad-eb3b-42cf-ab47-0f1bf0a86fdb', 'ビエトのさぎにひっかかったひがい者の合計は、百人になった。', 'Jumlah total korban yang ditangkap oleh penipuan Viet mencapai seratus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff875bad-eb3b-42cf-ab47-0f1bf0a86fdb', '合計金がくを出してもらっていいですか？', 'Bisakah Anda memberikan totalnya untuk saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff875bad-eb3b-42cf-ab47-0f1bf0a86fdb', '何度も足し算をしたんですが、その度に合計が違ったんですよね。私、馬鹿なんでしょうか？', 'Saya menambahkan angkanya berulang kali dan mendapatkan jumlah yang berbeda setiap kali. Apakah saya bodoh?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('508ff0c4-bcdb-433b-b25e-bdaa2f07b473', 'vocabulary', '商品', '商品', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Barang dagangan tetaplah barang dagangan.', 'Barang dagangan tetaplah barang dagangan.') ON CONFLICT (id) DO NOTHING;
