INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('70eb6a2c-0c9a-4850-9e44-347f9751acf5', 'ひとごろし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70eb6a2c-0c9a-4850-9e44-347f9751acf5', '人殺しをしたら、刑務所に行かなければなりません。', 'Jika Anda melakukan pembunuhan, Anda harus masuk penjara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70eb6a2c-0c9a-4850-9e44-347f9751acf5', '昨日、この近所で人殺しがあったそうです。', 'Saya mendengar ada pembunuhan di lingkungan ini kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70eb6a2c-0c9a-4850-9e44-347f9751acf5', '計算ずくの人生なんてつまらないと思って好き勝手していたら、いつの間にか人殺しになってたんだ。', 'Kupikir menjalani hidup yang penuh perhitungan tidak akan menyenangkan, jadi aku akan melakukan apa saja sesukaku, tapi aku akhirnya menjadi seorang pembunuh sebelum aku menyadarinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', 'vocabulary', '殺人者', '殺人者', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Mudah-mudahan Anda pernah melihat 殺人 (pembunuhan) dari level 13. Jadi, seseorang yang melakukan pembunuhan itu apa? Seorang pembunuh.', 'Mudah-mudahan Anda pernah melihat 殺人 (pembunuhan) dari level 13. Jadi, seseorang yang melakukan pembunuhan itu apa? Seorang pembunuh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', 'Pembunuh', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', 'Killer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', 'さつじんしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', 'その殺人者は、とう走中に大変な失ぱいをおかしてしまった。', 'Pembunuh itu membuat kesalahan besar saat melarikan diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', '殺人者とうたがわれていましたが、ついにようぎが晴れました。', 'Saya dicurigai sebagai pembunuhnya, namun akhirnya saya dibebaskan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7ee5a86-2db5-4e92-9848-0cd1d01060ec', '今の今まで、俺の友達の人生は信じられない苦難の連続でした。彼の人生は殺人者の子どもとして始まりました。', 'Hingga saat ini, kehidupan teman saya merupakan perjuangan yang luar biasa. Dia memulai hidupnya sebagai bayi seorang pembunuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', 'vocabulary', '暗記する', '暗記する', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Semoga Anda pernah melihat 暗記 sebelumnya. Artinya "menghafal". Jadi, ubah itu menjadi kata kerja dan Anda harus menghafalnya.', 'Semoga Anda pernah melihat 暗記 sebelumnya. Artinya "menghafal". Jadi, ubah itu menjadi kata kerja dan Anda harus menghafalnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', 'Untuk Menghafal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', 'あんきする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', 'クリステンはセーラームーンのテーマ曲の歌しを暗記している。', 'Kristen hafal lirik lagu tema Sailor Moon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', '明日までに、台本に書いてあるセリフを一つ残らず暗記しなければいけません。', 'Saya harus menghafal setiap baris dalam naskah besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1a5e1f8e-fc81-4299-b4b9-fdb5c90cadca', '文を丸ごと暗記する方が、単語だけを暗記するより効率がいい。', 'Menghafal kalimat lebih efisien daripada menghafal kata-kata saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', 'vocabulary', '消化', '消化', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sesuatu apa yang pertama-tama akan memadamkan sesuatu dan kemudian mengubahnya? Satu hal yang terpikir olehku adalah tubuhmu. Dibutuhkan dalam makanan, memadamkannya di perut Anda, lalu mengubahnya menjadi sesuatu yang dapat digunakan tubuh Anda (dan kemudian dikeluarkan). Itu sebabnya proses “pemadaman-perubahan” ini terjadi pada pencernaan Anda.', 'Sesuatu apa yang pertama-tama akan memadamkan sesuatu dan kemudian mengubahnya? Satu hal yang terpikir olehku adalah tubuhmu. Dibutuhkan dalam makanan, memadamkannya di perut Anda, lalu mengubahnya menjadi sesuatu yang dapat digunakan tubuh Anda (dan kemudian dikeluarkan). Itu sebabnya proses “pemadaman-perubahan” ini terjadi pada pencernaan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', 'Pencernaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', 'しょうか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', 'このくすりは、消化をそく進してくれます。', 'Obat ini akan merangsang pencernaan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', 'コウイチは下り気味だから、消化の良いものを食べさせてあげてね。', 'Koichi sedang mengalami diare, jadi tolong suruh dia makan sesuatu yang mudah dicerna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcc281f1-58b4-45d8-b0b0-3a5bfdb50df5', '昼に食べたラーメンをまだ消化しきっていない。', 'Saya belum selesai mencerna ramen yang saya makan untuk makan siang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', 'vocabulary', '消化不良', '消化不良', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Mudah-mudahan Anda sudah melihat 消化 sekarang dan tahu bahwa artinya "pencernaan". Jika Anda mengetahuinya, maka Anda dapat melihat bahwa “pencernaannya” kurang baik. Ketika pencernaan Anda tidak baik, apa yang Anda miliki? Gangguan pencernaan. Permisi, saya harus lari ke kamar kecil...', 'Mudah-mudahan Anda sudah melihat 消化 sekarang dan tahu bahwa artinya "pencernaan". Jika Anda mengetahuinya, maka Anda dapat melihat bahwa “pencernaannya” kurang baik. Ketika pencernaan Anda tidak baik, apa yang Anda miliki? Gangguan pencernaan. Permisi, saya harus lari ke kamar kecil...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', 'Gangguan pencernaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', 'しょうかふりょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', '消化不良のくすりをさがしています。', 'Saya sedang mencari obat gangguan pencernaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', 'コウイチくんにこく白したんだけど、返事が全然はっきりしなかったから、消化不良ですごくモヤモヤしてるんだよね。', 'Aku mengajak Koichi berkencan, tapi jawabannya sangat tidak jelas dan itu membuatku frustasi dan membuatku mengalami gangguan pencernaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efd9a9d7-3fe8-487c-a39a-f7027f4ee1e8', '今、消化不良で苦しんでるの。胸焼けもするし、膨満感もあるし、すごく気持ち悪い。しばらく放っておいてくれない。', 'Saya menderita gangguan pencernaan. Saya mengalami sakit maag, kembung, dan perut saya terasa mual. Tolong tinggalkan aku sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'vocabulary', '同期中', '同期中', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Sesuatu membuat satu hal sama dengan hal lain dalam jangka waktu tertentu. Anda akan sering melihat kata ini pada hal-hal yang berkaitan dengan komputer. Ini sedang menyinkronkan.', 'Sesuatu membuat satu hal sama dengan hal lain dalam jangka waktu tertentu. Anda akan sering melihat kata ini pada hal-hal yang berkaitan dengan komputer. Ini sedang menyinkronkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'Menyinkronkan', true) ON CONFLICT DO NOTHING;
