INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'どうきちゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'iPhone同期中に電源が切れて軽くあせった。', 'Saat saya menyinkronkan iPhone, iPhone mati dan saya sedikit ketakutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'Dropbox、いつも写しん同期中にフリーズしてしまうのはなぜ。', 'Saya bertanya-tanya mengapa Dropbox selalu macet saat menyinkronkan foto.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30a2287-6eaf-402c-956f-41cb7d0c939b', 'たぶんもうすぐ反映されると思う。私のエバーノート今同期中だし。', 'Ini mungkin akan segera muncul. Evernote saya sedang disinkronkan sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14dd0c19-3a3b-433d-8cd8-2329b1afee40', 'vocabulary', '期待する', '期待する', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Semoga Anda sekarang sudah mengetahui kata 期待 (harapan). Ini adalah versi kata kerjanya, yang membuatnya diharapkan.', 'Semoga Anda sekarang sudah mengetahui kata 期待 (harapan). Ini adalah versi kata kerjanya, yang membuatnya diharapkan.') ON CONFLICT (id) DO NOTHING;
