INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('14dd0c19-3a3b-433d-8cd8-2329b1afee40', 'きたいする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14dd0c19-3a3b-433d-8cd8-2329b1afee40', '病気がちな体しつなので、あまり期待しないでください。', 'Saya cukup rentan terhadap penyakit, jadi jangan berharap terlalu banyak dari saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14dd0c19-3a3b-433d-8cd8-2329b1afee40', 'つまは、けっこん記念日にはおっとがみかんを買ってかえってくるものだと期待していた。', 'Sang istri mengantisipasi suaminya akan kembali dengan membawa jeruk clementine pada hari jadi mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14dd0c19-3a3b-433d-8cd8-2329b1afee40', '今年は母親以外の女子からのバレンタインのチョコレートを期待しています。', 'Saya menantikan coklat Valentine dari gadis-gadis selain ibu saya tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8805a84-ce33-4ead-b26a-d526096adf89', 'vocabulary', '試合', '試合', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Upaya untuk bersatu bukan sekedar berkumpul. Bayangkan dua orang bertinju. Mereka berusaha untuk menjatuhkan satu sama lain ketika mereka bergabung bersama. Itu sebabnya kata ini adalah permainan atau pertandingan. Apakah kamu menonton 試合 hari ini? TIDAK! Jangan ceritakan apa yang terjadi, saya rekam di VHS.', 'Upaya untuk bersatu bukan sekedar berkumpul. Bayangkan dua orang bertinju. Mereka berusaha untuk menjatuhkan satu sama lain ketika mereka bergabung bersama. Itu sebabnya kata ini adalah permainan atau pertandingan. Apakah kamu menonton 試合 hari ini? TIDAK! Jangan ceritakan apa yang terjadi, saya rekam di VHS.') ON CONFLICT (id) DO NOTHING;
