INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8805a84-ce33-4ead-b26a-d526096adf89', '良かったらもう一試合しませんか？', 'Jika Anda tidak keberatan, mengapa kita tidak bermain game lain bersama-sama?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8805a84-ce33-4ead-b26a-d526096adf89', 'けん道の試合の結果はどうでしたか？', 'Apa hasil pertandingan kendo?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8805a84-ce33-4ead-b26a-d526096adf89', '「あの野球の試合は本当にひどかったね。」「本当にそうだね。」', '"Pertandingan bisbol itu sungguh buruk." "Ya, ceritakan padaku tentang hal itu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e2d4e89-4ada-42e8-9d2b-ff527eb47304', 'vocabulary', '良質', '良質', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kualitas yang baik selalu berkualitas baik. Jangan berhemat!', 'Kualitas yang baik selalu berkualitas baik. Jangan berhemat!') ON CONFLICT (id) DO NOTHING;
