INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e2d4e89-4ada-42e8-9d2b-ff527eb47304', '良質のワインを飲む事が私の唯一の楽しみだ。', 'Minum anggur berkualitas baik adalah satu-satunya kesenangan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9f729361-0f15-480e-8cb6-b14d82a884b8', 'vocabulary', '宿', '宿', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Pondok adalah salah satu bentuk penginapan. Itu juga dianggap sebagai penginapan atau hotel.', 'Pondok adalah salah satu bentuk penginapan. Itu juga dianggap sebagai penginapan atau hotel.') ON CONFLICT (id) DO NOTHING;
