INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9f729361-0f15-480e-8cb6-b14d82a884b8', 'やど', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f729361-0f15-480e-8cb6-b14d82a884b8', '十年前にそこをおとずれた時には、こんな宿は全くありませんでした。', 'Ketika saya pergi ke sana sepuluh tahun yang lalu, tidak ada penginapan seperti ini sama sekali.') ON CONFLICT DO NOTHING;
