INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e889e8d-8b4b-4968-88d3-21f99b0032b0', '男が女のペースに合わせてゆっくり歩くのは、その女のことが好きな時だけさ。', 'Seorang pria hanya akan melambat untuk menyamai kecepatan wanita jika dia menyukainya.') ON CONFLICT DO NOTHING;
