INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('890e14cb-6c73-420b-91bb-8ced9814df2b', '母の具合があまりよくないんです。', 'Kondisi ibu saya tidak terlalu baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('890e14cb-6c73-420b-91bb-8ced9814df2b', 'なんかめっちゃ具合わるそうだけど、大じょうぶ?', 'Kamu tidak tampak hebat sama sekali. Apakah kamu baik-baik saja?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('890e14cb-6c73-420b-91bb-8ced9814df2b', 'ちょっと昨日から具合が良くなくて。', 'Cuacaku sedikit buruk kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('16ef178e-db45-4f61-9512-284a4ba26ff4', 'vocabulary', '王様', '王様', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Raja (nama resmi ender) adalah raja, dan Anda berbicara kepadanya dengan sopan. Bagaimanapun juga, dialah rajanya! Jika tidak, dia mungkin akan memenggal kepalamu!', 'Raja (nama resmi ender) adalah raja, dan Anda berbicara kepadanya dengan sopan. Bagaimanapun juga, dialah rajanya! Jika tidak, dia mungkin akan memenggal kepalamu!') ON CONFLICT (id) DO NOTHING;
