INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16ef178e-db45-4f61-9512-284a4ba26ff4', '王様は料理が大好きです。', 'Raja suka memasak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16ef178e-db45-4f61-9512-284a4ba26ff4', 'あの王様は、とんでもなくケチなんだ。', 'Raja itu sangat pelit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16ef178e-db45-4f61-9512-284a4ba26ff4', '王様は、力士と尻相撲をしたがっています。', 'Raja ingin bertanding gulat dengan pegulat sumo.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b502753c-4b88-45d8-b720-8c9155c4ae00', 'vocabulary', '合図', '合図', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Diagram yang dilihat semua orang bersama-sama adalah sebuah sinyal atau tanda.', 'Diagram yang dilihat semua orang bersama-sama adalah sebuah sinyal atau tanda.') ON CONFLICT (id) DO NOTHING;
