INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b502753c-4b88-45d8-b720-8c9155c4ae00', 'わたしが合図をしたら、大声で「エイドリアーン！」とさけんでください。', 'Saat saya memberi isyarat, teriaklah, "Adrian!" dengan keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b502753c-4b88-45d8-b720-8c9155c4ae00', 'わたしに、売りか買いかの合図の出し方をおしえてくれませんか？', 'Bisakah Anda mengajari saya cara memberi sinyal beli atau jual?') ON CONFLICT DO NOTHING;
