INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('770abd2d-6c20-42fc-b08a-5eaa0788a7fd', 'vocabulary', '港', '港', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
