INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('770abd2d-6c20-42fc-b08a-5eaa0788a7fd', 'ベラクルスという港町に行ってみたいです。', 'Saya ingin mengunjungi kota pelabuhan Veracruz.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('770abd2d-6c20-42fc-b08a-5eaa0788a7fd', 'ごう雨のため、港への道は通行止めになっています。', 'Karena hujan lebat, jalan menuju pelabuhan ditutup.') ON CONFLICT DO NOTHING;
