INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('86cfcac4-82db-449b-99b7-24e9ff646039', 'vocabulary', '神様', '神様', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Tuhan (nama resmi ender) adalah Tuhan! Atau para dewa, jika Anda berbicara dengan lebih dari satu. Anda harus bersikap sopan kepada mereka, jadi tambahkan akhiran itu di sana.', 'Tuhan (nama resmi ender) adalah Tuhan! Atau para dewa, jika Anda berbicara dengan lebih dari satu. Anda harus bersikap sopan kepada mereka, jadi tambahkan akhiran itu di sana.') ON CONFLICT (id) DO NOTHING;
