INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86cfcac4-82db-449b-99b7-24e9ff646039', 'あの神様、まだおむかえを待ってるの？', 'Apakah dewa itu masih menunggu seseorang datang dan menjemputnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86cfcac4-82db-449b-99b7-24e9ff646039', 'ギターの神様と言えば、だれを思いうかべますか？', 'Siapa yang terlintas di benak Anda ketika mendengar nama “dewa gitar”.') ON CONFLICT DO NOTHING;
