INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b5cbecb-3986-44b1-a753-779da5d17179', 'vocabulary', '特選', '特選', 3, '7e6f2a9b-0c1d-8e3f-4a5b-6c7d8e9f0a1b', 'Jika ada sesuatu yang istimewa, Anda memilihnya. Itu menjadikannya pilihan spesial milik Anda dan mendapat hadiah spesial yang hanya bisa Anda berikan!', 'Jika ada sesuatu yang istimewa, Anda memilihnya. Itu menjadikannya pilihan spesial milik Anda dan mendapat hadiah spesial yang hanya bisa Anda berikan!') ON CONFLICT (id) DO NOTHING;
