INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b5cbecb-3986-44b1-a753-779da5d17179', '親分の絵が、コンクールで特選に入賞したぞ！', 'Lukisan bos kami memenangkan hadiah spesial di kontes!') ON CONFLICT DO NOTHING;
