INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('0b5cbecb-3986-44b1-a753-779da5d17179', 'fa067747-2ba4-4f1c-a03b-2b676dcf2d6c') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6fcbe7a9-7105-47b4-b3f3-74294eff8967', 'radical', '原', 'original', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ada sesuatu yang putih dan kecil tersangkut di tebing ini. Ini... itu... sangat orisinal, Anda tidak dapat menyebutkan namanya. Anda belum pernah melihat yang seperti ini. Itu satu-satunya yang sejenis. Kamu memutuskan untuk menamainya "asli" saja karena kamu bukan orang yang sangat orisinal...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6fcbe7a9-7105-47b4-b3f3-74294eff8967', 'Asli', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('76e5f4e9-d25f-4d0b-9de5-fe2bb0faad50', 'radical', '忄', 'soul', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ada sirip yang mengambang di sisa ikan. Inilah jiwa ikan yang tersisa setelah kamu memakan tubuhnya. Pastikan Anda mengucapkan selamat tinggal pada jiwa ikan yang Anda makan. Itu penuh hormat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('76e5f4e9-d25f-4d0b-9de5-fe2bb0faad50', 'Jiwa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('03f78bb5-bdbd-4545-a83a-3dce8ffa23d4', 'radical', '疋', 'coat-rack', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Lihat semua lengan yang mencuat dari kelompok radikal ini? Itu untuk menggantung banyak topi, syal, dan mantel karena itu rak mantel.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('03f78bb5-bdbd-4545-a83a-3dce8ffa23d4', 'Rak Mantel', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f307f2e4-edeb-4d84-8f00-8163e75f3719', 'radical', '比', 'compare', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Radikal ini terdiri dari dua versi radikal sendok yang sedikit berbeda (yang harus Anda ketahui). Perhatikan baik-baik kedua sendok ini. Bandingkan perbedaan mereka. Seperti salah satu majalah tempat Anda membandingkan dua gambar serupa. Tapi kali ini dengan sendok.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f307f2e4-edeb-4d84-8f00-8163e75f3719', 'Bandingkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b59dbd74-f88f-4395-b2f0-6ae8fccf2114', 'radical', '[bar]', 'bar', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ada dua pemabuk di sini. Hal ini menjadikan radikalisme sebagai sebuah bar. Di mana lagi kamu akan minum?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b59dbd74-f88f-4395-b2f0-6ae8fccf2114', 'Batang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5047be8a-3e75-4bf4-8c4a-cb41781c7c27', 'radical', '行', 'go', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda memiliki kata radikal untuk loiter, two, dan barb. Seseorang yang menggunakan dua duri pada Anda saat Anda berkeliaran benar-benar ingin Anda PERGI!! Ayo, berhenti berkeliaran di luar toko serba adaku, ya, anak-anak!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5047be8a-3e75-4bf4-8c4a-cb41781c7c27', 'Pergi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7b82b2ae-b4b4-4218-a17e-aae4da3f114f', 'radical', '去', 'past', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Radikal ini sama dengan kanji. Artinya masa lalu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7b82b2ae-b4b4-4218-a17e-aae4da3f114f', 'Masa lalu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('47f32617-5c50-451b-8428-77b8a2707a9f', 'radical', '犭', 'animal', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ini terlihat seperti ekor dengan beberapa helai rambut yang terlepas darinya. Namun jangan bingung dengan jari, karena bentuknya melengkung, dan benda yang menonjol lebih tidak menentu, seperti rambut atau bulu. Itu sebabnya radikal ini adalah radikal hewan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('47f32617-5c50-451b-8428-77b8a2707a9f', 'Hewan', true) ON CONFLICT DO NOTHING;
