INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('628bbb0f-451e-4264-baaf-21bbc6f6f6e4', 'vocabulary', '疑問', '疑問', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Masalah keraguan disebabkan oleh terlalu banyak keraguan. Pikirkan saja. Jangan meragukan diri sendiri, itu sebabnya Anda salah mengartikan kata-kata itu! :P', 'Masalah keraguan disebabkan oleh terlalu banyak keraguan. Pikirkan saja. Jangan meragukan diri sendiri, itu sebabnya Anda salah mengartikan kata-kata itu! :P') ON CONFLICT (id) DO NOTHING;
