INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37cf6300-0739-463b-9527-14888ff0cd19', '大人には大人の事情があるんですよ。', 'Orang dewasa mempunyai keadaan yang dewasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37cf6300-0739-463b-9527-14888ff0cd19', '警察はすべての事情を考慮しなければならない。', 'Polisi harus mempertimbangkan semua keadaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37cf6300-0739-463b-9527-14888ff0cd19', 'サマンサはワニカニのサービス利用代金がはらえない事情を説明しました。', 'Samantha menjelaskan alasan di balik ketidakmampuannya membayar penggunaan Wanikani.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', 'vocabulary', '人情', '人情', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Perasaan orang (people) adalah perasaan manusiawi yang dimiliki setiap orang. Itulah arti kemanusiaan, dan sering kali mengacu pada perasaan kebaikan dan empati terhadap orang lain.', 'Perasaan orang (people) adalah perasaan manusiawi yang dimiliki setiap orang. Itulah arti kemanusiaan, dan sering kali mengacu pada perasaan kebaikan dan empati terhadap orang lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', 'Perasaan Manusia', true) ON CONFLICT DO NOTHING;
