INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', 'にんじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', '人情のあたたかさに生かされています。', 'Saya bertahan hidup dengan kehangatan kemanusiaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', 'コウイチ様は人情味にあふれているすばらしいお方ですが、ビエト様はひとかけらの人情もないごく悪ヤクザです。', 'Koichi-sama adalah orang yang luar biasa dengan empati yang dalam, tetapi Viet adalah yakuza yang jahat dan tidak memiliki satu pun kemanusiaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('318aebf6-916e-4f89-9130-43c6d27013df', '私達はトーフグの毎日のブログ記事を通して、日本人の生き方や人情を描き出すことを目指しています。', 'Tujuan kami dengan artikel Tofugu harian adalah untuk menggambarkan sifat manusia, emosi, dan kehidupan sehari-hari orang Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'vocabulary', '情け', '情け', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda memiliki perasaan Anda... inilah perasaan yang dimiliki manusia. Ketika kamu meminta seseorang untuk mempunyai perasaan (Punya perasaan, KAY?? (け di akhir)), kamu meminta mereka untuk mengasihani atau mengasihani kamu. Silakan! Miliki perasaan manusiawi yang dimiliki orang lain, seperti simpati atau kasihan. Jangan bunuh aku, kawan!', 'Anda memiliki perasaan Anda... inilah perasaan yang dimiliki manusia. Ketika kamu meminta seseorang untuk mempunyai perasaan (Punya perasaan, KAY?? (け di akhir)), kamu meminta mereka untuk mengasihani atau mengasihani kamu. Silakan! Miliki perasaan manusiawi yang dimiliki orang lain, seperti simpati atau kasihan. Jangan bunuh aku, kawan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'Kasihan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'Sympathy', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'Mercy', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'Compassion', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'なさけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'コウイチ子は、コウイチが情けのかけらもない男だと知って、別れました。', 'Koichiko putus dengan Koichi setelah dia mengetahui Koichi adalah seorang pria tanpa sedikit pun simpati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', '日本語には、「旅は道づれ世は情け」ということわざがあります。', 'Dalam bahasa Jepang ada pepatah, "Penting bagi kita untuk berbelas kasih terhadap satu sama lain saat kita melakukan perjalanan di dunia ini."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a14ffe2-a8b5-4a2e-ab2d-eef22bf7f722', 'テストは70点が合格点だったが、私は69点だったのにも関わらずお情けで合格させてもらえた。', 'Saya membutuhkan nilai 70 untuk lulus tes, dan meskipun saya mendapat nilai 69, saya diberi nilai yang sangat disayangkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'vocabulary', '感情', '感情', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Perasaan + perasaan = perasaan! Itu juga bisa berarti emosi.', 'Perasaan + perasaan = perasaan! Itu juga bisa berarti emosi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'Perasaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'Emotion', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'かんじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'おこると感情のコントロールがうまく出来ません。', 'Saya tidak bisa mengendalikan emosi saya dengan baik ketika saya marah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', 'これは大事なことですから、感情に左右されずにれいせいにはんだんしてくださいね。', 'Ini penting, jadi harap menilainya dengan semangat yang baik daripada mengandalkan perasaan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e65885af-5c01-4f07-9804-ecc1189ca32d', '感情に流されすぎてはいけないよ。自分の感情に負けることには何の価値もないよ。', 'Jangan terlalu menyerah pada perasaan Anda. Tidak ada gunanya membiarkan emosi menguasai Anda, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', 'vocabulary', '皆様', '皆様', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Semua orang (gelar nama formal). Ini hanyalah cara sopan untuk mengatakan kepada semua orang (dan Anda ingin bersikap sopan kepada semua orang, karena semua orang> Anda).', 'Semua orang (gelar nama formal). Ini hanyalah cara sopan untuk mengatakan kepada semua orang (dan Anda ingin bersikap sopan kepada semua orang, karena semua orang> Anda).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', 'Semuanya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', 'All', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', 'Everybody', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', 'みなさま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', '皆様、間もなく当ひ行きはロサンゼルス空港に着りくします。', 'Baiklah semuanya, pesawat akan segera mendarat di Bandara Los Angeles.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', '皆様のごけんこうとご多こうをおいのり申し上げます。', 'Saya mendoakan yang terbaik untuk semua orang dan selalu diberikan kesehatan yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f34fc51-c02b-4208-aa79-8bc4b258bfd6', '「皆様、ご着席いただけますか？」「お言葉ですが、それは良い考えではないと思います。何故だか分かりませんが、我々の椅子に接着剤が付いているのです。」', '"Bisakah semua orang mengambil tempat duduknya masing-masing?" "Dengan segala hormat, menurutku itu bukan ide yang bagus. Ada lem super di kursi kita karena suatu alasan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'vocabulary', '情熱', '情熱', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Jika Anda merasakan demam, berarti Anda sedang mengalami sesuatu yang membuat tubuh Anda memanas. Anda memiliki banyak gairah.', 'Jika Anda merasakan demam, berarti Anda sedang mengalami sesuatu yang membuat tubuh Anda memanas. Anda memiliki banyak gairah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'Gairah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'Enthusiasm', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'じょうねつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('951267ab-be9f-448c-b361-330790e8295a', '情熱さえあれば何だってできるよ！', 'Anda dapat melakukan apapun yang Anda inginkan selama Anda memiliki passion.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'ビエトがこんなに情熱てきだったなんて、信じられません。', 'Saya tidak percaya betapa antusiasnya Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('951267ab-be9f-448c-b361-330790e8295a', 'コウイチは、日本とアメリカの伝統を融合させることに、生涯情熱を捧げることを決意しました。', 'Koichi memutuskan untuk menjadikan hasrat hidupnya mencapai perpaduan antara tradisi Jepang dan Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'vocabulary', '皆さん', '皆さん', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Semua orang + さん (nama akhir biasa). Ini adalah cara normal untuk mengatakan semuanya', 'Semua orang + さん (nama akhir biasa). Ini adalah cara normal untuk mengatakan semuanya') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'Semuanya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'Everybody', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'All', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'みなさん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'それは皆さんが決めてください。', 'Itu terserah kalian semua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', 'わたしは皆さんと仲良くなりたいだけなんです。決して下心なんてありません。', 'Saya hanya ingin bergaul dengan semua orang. Saya sama sekali tidak punya motif tersembunyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0e615353-31c8-491b-894a-9d9f2b3c3f69', '皆さん、こんにちは。今週中には、トーフグセミナーの日程を確定させたいと思っています。数日中にビエトと話しをして、その後で皆さんに日程をお伝えさせて頂きます。', 'Halo semuanya. Saya berharap kita dapat menentukan tanggal seminar Tofugu minggu ini. Saya akan berbicara dengan Viet dalam beberapa hari ke depan dan kemudian saya akan mengumumkan jadwal semua orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'vocabulary', 'お願いします', 'お願いします', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ini adalah kata rumit yang tidak memiliki terjemahan yang bagus. Cara terbaik yang pernah saya lihat dalam hal menyampaikan makna adalah mohon dan tolong bantu saya. Saat Anda mengucapkan kata ini, Anda seperti mengatakan "tolong bantu saya dan saya mengandalkan Anda dan Anda juga luar biasa." Bagaimanapun, tolong adalah cara yang cukup bagus untuk melakukannya. Jadi, ketika Anda melihat kata ini, Anda akan melihat ada kanji permintaan di dalamnya. Anda bisa menebak Anda meminta sesuatu. Benda apa itu? Ini membantu (tolong bantu saya) dan Anda juga meminta dengan sangat baik (tolong).', 'Ini adalah kata rumit yang tidak memiliki terjemahan yang bagus. Cara terbaik yang pernah saya lihat dalam hal menyampaikan makna adalah mohon dan tolong bantu saya. Saat Anda mengucapkan kata ini, Anda seperti mengatakan "tolong bantu saya dan saya mengandalkan Anda dan Anda juga luar biasa." Bagaimanapun, tolong adalah cara yang cukup bagus untuk melakukannya. Jadi, ketika Anda melihat kata ini, Anda akan melihat ada kanji permintaan di dalamnya. Anda bisa menebak Anda meminta sesuatu. Benda apa itu? Ini membantu (tolong bantu saya) dan Anda juga meminta dengan sangat baik (tolong).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'Tolong Bantu Saya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'Please', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'If You Would Be So Kind', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'おねがいします', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', '神様、お願いします！日本語が上手くなりたいんです。', 'Tolong Tuhan! Saya ingin fasih berbahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', 'ゆうれい会員でもかまわないので、お願いします。', 'Jika Anda bukan anggota aktif, silakan bergabung!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('673f8a6e-f9a2-4eef-b518-3aa61eae5de9', '通路側の席をお願いします。窓から外の景色を眺めるのが嫌いなんです。', 'Bisakah saya mendapatkan tempat duduk di lorong? Aku benci melihat ke luar jendela.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'vocabulary', '心願', '心願', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Apa yang diminta hatimu, itulah yang diinginkan hatimu. Ini adalah keinginan tulus Anda.', 'Apa yang diminta hatimu, itulah yang diinginkan hatimu. Ini adalah keinginan tulus Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'Keinginan Sepenuh Hati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'Heartfelt Wish', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'Prayer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'Heart''s Desire', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'しんがん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', 'サーモンの心願には心が打たれますね。', 'Kami terharu dengan doa Salmon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', '今回のハリケーンのひがいが少なくてすむようにというのがわたしの心願です。', 'Harapan saya yang tulus adalah agar kerusakan yang disebabkan oleh badai kali ini berkurang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26ede190-7dd3-4981-aea7-2aec136e499d', '私はその神社で心願成就の御札を買いました。', 'Saya membeli jimat di kuil untuk membantu memenuhi keinginan hati saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'vocabulary', '例外', '例外', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Sesuatu yang di luar keteladanan tidak mengikuti aturan. Bukan itu yang seharusnya (contoh), ini pengecualian.', 'Sesuatu yang di luar keteladanan tidak mengikuti aturan. Bukan itu yang seharusnya (contoh), ini pengecualian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'Pengecualian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'れいがい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'このレストランの料理は例外なくどれも美味しいです。', 'Semua hidangan di restoran ini lezat tanpa terkecuali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'きわめて例外のケースをのぞいて、この病院がその手術に成功したのをほとんど見たことがありません。', 'Kecuali beberapa kasus luar biasa, saya belum pernah melihat rumah sakit ini berhasil menyelesaikan prosedurnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fdb66041-ccd9-4ff6-b333-d72aac0ebfe2', 'コウイチはいつも朝遅くまで寝ていますが、金曜日はスーツを着なくてはいけないので例外です。', 'Koichi biasanya tidur, tapi hari Jumat adalah pengecualian karena dia harus mengenakan jas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', 'vocabulary', '一例', '一例', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Salah satu contoh hanyalah contoh dari apa yang Anda gambarkan. Hanya satu contoh.', 'Salah satu contoh hanyalah contoh dari apa yang Anda gambarkan. Hanya satu contoh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', 'Contoh', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', 'Example', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', 'いちれい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', 'これはほんの一例にすぎません。', 'Ini hanyalah salah satu contoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', '一例としては、ごはんやじゃがいもを食べるりょうをへらしたからといって、やせられるわけではないということがあげられます。', 'Sebagai contoh, Anda tidak bisa menjadi lebih kurus hanya dengan mengurangi makan nasi dan kentang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a844dca6-0ac8-4828-963c-15b4040964d2', '秘書としてサーモンを迎え入れた後で、彼女が職場で突然感情を爆発させる性格であることが判明したのです。例えば、自分のデスクの電話を引き抜いて、粉々にブチ壊しちゃったりとか、まあ、ほんの一例を挙げればそんな感じです。', 'Setelah saya mempekerjakan Salmon sebagai sekretaris, saya mengetahui bahwa dia adalah tipe orang yang tiba-tiba mengalami ledakan emosi di kantor. Misalnya, dia merobek telepon dari mejanya dan menghancurkannya hingga berkeping-keping, hanya untuk menyebutkan satu kejadian kecil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'vocabulary', '例えば', '例えば', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ini memiliki arti yang hampir sama dengan kanji asalnya. Namun, alih-alih sekadar menjadi "contoh", ini adalah contoh. Kadang-kadang bisa juga berarti berasumsi ketika berbicara tentang skenario hipotetis. Jadi, misalkan saya memulai sebuah kalimat dengan ini, saya bisa menjadi seperti "例えば, saya menggunakan 例えば dalam sebuah kalimat."', 'Ini memiliki arti yang hampir sama dengan kanji asalnya. Namun, alih-alih sekadar menjadi "contoh", ini adalah contoh. Kadang-kadang bisa juga berarti berasumsi ketika berbicara tentang skenario hipotetis. Jadi, misalkan saya memulai sebuah kalimat dengan ini, saya bisa menjadi seperti "例えば, saya menggunakan 例えば dalam sebuah kalimat."') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'Misalnya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'For Instance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'Supposing That', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'たとえば', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', '例えば、昔はすごく人気があったけど、今は落ちぶれてしまった人がいたとしましょう。', 'Sebagai contoh, katakanlah ada seseorang yang dulunya sangat populer namun sekarang sudah tidak populer lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', '例えば、舌をかみそうになった時、コウイチなら何て言うと思う？', 'Misalnya, menurut Anda apa yang akan dikatakan Koichi ketika dia hampir menggigit lidahnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08e575e9-b7c4-49b0-8544-9fb65f2b0eb8', 'なぁ、さくらちゃん、例えば、週に一度や二度ぐらい、うちに来ないか？', 'Hei, Sakura, kenapa kamu tidak datang ke rumahku, sekali atau dua kali seminggu atau apalah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'vocabulary', '例文', '例文', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Contoh tulisan adalah sebuah tulisan yang menjadi contoh mungkin sebuah kata atau kanji atau semacamnya. Ini adalah contoh kalimat.', 'Contoh tulisan adalah sebuah tulisan yang menjadi contoh mungkin sebuah kata atau kanji atau semacamnya. Ini adalah contoh kalimat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'Contoh Kalimat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'Model Sentence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'Sample Sentence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'れいぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', '例文という語いを使ったいい例文が思いつきません。', 'Saya tidak dapat menemukan contoh kalimat bagus yang menggunakan kata "contoh kalimat".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', 'ワニカニの例文の中で一番好きな文章を教えてください。', 'Beri tahu kami contoh kalimat WaniKani mana yang menjadi favorit Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34b5337c-1455-407d-a9d4-5947d5c0f9f6', '何故だか分からないんだけど、僕の先生は例文を作る時にいつも僕の名前を使うんだよね。', 'Entah kenapa guruku selalu menggunakan namaku saat membuat contoh kalimat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', 'vocabulary', '悪例', '悪例', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Contoh yang buruk adalah contoh yang buruk dan merupakan sesuatu yang tidak Anda inginkan.', 'Contoh yang buruk adalah contoh yang buruk dan merupakan sesuatu yang tidak Anda inginkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', 'Contoh Buruk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', 'Bad Precedent', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', 'あくれい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', '日本語を学ぶ時には、いい例だけでなく、悪例を学ぶことも必要です。', 'Saat belajar bahasa Jepang, penting untuk belajar dari contoh yang baik dan juga contoh yang buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', 'コウイチは悪例のかたまりだ。', 'Koichi adalah sekelompok contoh buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42d150a9-ab27-4164-9eff-6894b027be25', '僕の両親は、今後の寝る時間に悪例を残すことになるからって、絶対に夜更かしさせてくれないんだ。', 'Orang tua saya tidak pernah membiarkan saya begadang karena mereka percaya hal itu akan menjadi preseden buruk bagi waktu tidur saya di masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'vocabulary', '参る', '参る', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji itu sendiri berarti berpartisipasi, jadi Anda mungkin mengira kata ini berarti "berpartisipasi" tetapi kata ini sedikit lebih rumit dari itu. Anggap saja sebagai "berpartisipasi" tetapi Anda harus datang atau pergi untuk melakukannya. Ini adalah cara yang sederhana untuk mengatakan hal-hal tersebut, jadi Anda pergi ke tempat-tempat ini dengan perasaan senang hati, senang sekali Anda dapat berpartisipasi lebih dari apa pun. Selain itu, ini juga merupakan cara sederhana untuk mengatakan berkunjung, sering kali digunakan jika Anda mengunjungi sesuatu yang sakral seperti kuil atau makam. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'Akan Datang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'To Go', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'To Visit', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'To Be Defeated', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'To Be At A Loss', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'まいる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', 'いざ、参らん！', 'Ayo pergi!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', '今週末は、母のおはかに参るつもりです。', 'Akhir pekan ini aku berencana mengunjungi makam ibuku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86492ccb-ff8e-42a9-87fc-e6bd8d6d4f3f', '私は毎日神社に参ります。', 'Saya mengunjungi kuil Shinto setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'vocabulary', '完全', '完全', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ketika segala sesuatunya sempurna, itu berarti lengkap. Tidak hanya itu, tapi sempurna (karena SEMUAnya sempurna, tidak hanya sebagian saja).', 'Ketika segala sesuatunya sempurna, itu berarti lengkap. Tidak hanya itu, tapi sempurna (karena SEMUAnya sempurna, tidak hanya sebagian saja).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'Lengkap', true) ON CONFLICT DO NOTHING;
