INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'Completeness', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'かんぜん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'トーフグは日々少しずつ完全のいきに近づいている。', 'Tofugu mendekati kesempurnaan sedikit demi sedikit setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', '残念ながら、コウイチには完全なアリバイがあります。', 'Sayangnya, Koichi punya alibi yang sempurna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b557f7-156e-4857-a883-d403faa79dab', 'ああ、もう！お前のせいで完全に気が散っちゃったじゃないか！話したいことって何なんだよ。オフィスで飼う犬だっけか？', 'Ya ampun! Sekarang kamu benar-benar mengalihkan perhatianku. Apa yang ingin kamu bicarakan... anjing kantor, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a3f76d96-e6f1-43b2-8714-6d9a7064cdb3', 'vocabulary', '完成', '完成', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ketika sesuatu telah menjadi sempurna maka telah mencapai penyelesaian.', 'Ketika sesuatu telah menjadi sempurna maka telah mencapai penyelesaian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a3f76d96-e6f1-43b2-8714-6d9a7064cdb3', 'Penyelesaian', true) ON CONFLICT DO NOTHING;
