INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3f76d96-e6f1-43b2-8714-6d9a7064cdb3', '完成前に起こしてもらえますか？', 'Bisakah Anda membangunkan saya sebelum selesai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3f76d96-e6f1-43b2-8714-6d9a7064cdb3', 'トーフグはこの数日間で、かなりのりょうを完成させた。', 'Tofugu telah mencapai banyak hal dalam beberapa hari terakhir.') ON CONFLICT DO NOTHING;
