INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e804487b-8b06-4f4c-ae12-29633a08d0c6', 'vocabulary', '念願', '念願', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Apa yang diminta oleh pikiranmu di dalam kepalamu, tanpa henti seperti orang gila, adalah keinginan hatimu.', 'Apa yang diminta oleh pikiranmu di dalam kepalamu, tanpa henti seperti orang gila, adalah keinginan hatimu.') ON CONFLICT (id) DO NOTHING;
