INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e804487b-8b06-4f4c-ae12-29633a08d0c6', 'コウイチは、世界の平和を念願して、出家しました。', 'Koichi dengan sungguh-sungguh mengharapkan perdamaian dunia dan menjadi seorang pendeta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e804487b-8b06-4f4c-ae12-29633a08d0c6', 'ついに長年の念願だったアフリカ旅行を実げんしました。', 'Saya akhirnya mewujudkan impian saya yang telah lama ditunggu-tunggu untuk bepergian ke Afrika.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e804487b-8b06-4f4c-ae12-29633a08d0c6', 'やったー！ついに念願の彼氏ができたよー！やっぱ一生懸命願えば叶うもんだね！超幸せー！', 'Hore! Setelah sekian lama menunggu, akhirnya aku punya pacar. Saya kira jika Anda berharap cukup keras, Anda benar-benar bisa mendapatkan apa yang Anda inginkan. Saya sangat senang!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4249d080-6ce2-4ed2-a09c-c12cb1e565d7', 'vocabulary', '残念', '残念', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Sisa pemikiran Anda sangatlah kecil. Anda telah memikirkan segala kemungkinan untuk mengatasi masalah ini. Pada akhirnya, sisa pikiran Anda hanya tersisa satu kalimat: "sayang sekali." Tidak ada lagi yang perlu dipikirkan selain sisanya.', 'Sisa pemikiran Anda sangatlah kecil. Anda telah memikirkan segala kemungkinan untuk mengatasi masalah ini. Pada akhirnya, sisa pikiran Anda hanya tersisa satu kalimat: "sayang sekali." Tidak ada lagi yang perlu dipikirkan selain sisanya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4249d080-6ce2-4ed2-a09c-c12cb1e565d7', 'Sayang sekali', true) ON CONFLICT DO NOTHING;
