INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4249d080-6ce2-4ed2-a09c-c12cb1e565d7', 'それは残念すぎる。', 'Sangat disayangkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4249d080-6ce2-4ed2-a09c-c12cb1e565d7', '折角のチャンスだったのに、残念です。', 'Itu adalah kesempatan yang langka, jadi sayang sekali saya melewatkannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4249d080-6ce2-4ed2-a09c-c12cb1e565d7', '「このテレビ番組のために私が蜘蛛を食べなくちゃいけないって、本当？」「残念ながらそのようです。」', '"Benarkah aku harus makan laba-laba di acara TV ini?" "Sayangnya memang demikian."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', 'vocabulary', '人性', '人性-3677', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Sifat seseorang hanyalah sifat manusia! Setiap orang mempunyai naluri kemanusiaannya masing-masing.', 'Sifat seseorang hanyalah sifat manusia! Setiap orang mempunyai naluri kemanusiaannya masing-masing.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', 'Sifat Manusia', true) ON CONFLICT DO NOTHING;
