INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', 'じんせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', '私は、大学で人性学を勉強しています。', 'Saya sedang belajar etologi di universitas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', '私は、キリストは神性と人性という二つの本性を持つという両性せつを支持します。', 'Saya mendukung pendapat diofisit bahwa Yesus mempunyai dua kodrat: kodrat ilahi dan kodrat manusia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b87abea-bd51-4b6c-8d35-0befa6259a9f', '人性論における人間の本性において、私は結局人の性質は善悪を共に備えていると思います。', 'Mengenai pembahasan sifat asli manusia dalam Konfusianisme, saya percaya bahwa sifat manusia dilengkapi dengan sisi baik dan sisi jahat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('508284b4-7705-4de7-acf5-be3facc3c2c9', 'vocabulary', '女性', '女性', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Seseorang yang berjenis kelamin perempuan kemungkinan besar adalah perempuan.', 'Seseorang yang berjenis kelamin perempuan kemungkinan besar adalah perempuan.') ON CONFLICT (id) DO NOTHING;
