INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18558e55-8595-4fac-87f2-d83c2a540120', 'こまってるんだったら、性病ちりょうのお金、少しだったら都合してあげられるよ。', 'Saya bisa meminjami Anda sejumlah uang untuk pengobatan PMS, jika Anda kesulitan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18558e55-8595-4fac-87f2-d83c2a540120', '全く都合の悪い時に性病にかかったもんだよ。', 'Saya terkena penyakit menular seksual pada saat yang paling tidak nyaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('18558e55-8595-4fac-87f2-d83c2a540120', '性病を移してくれてどうも有難う。とても嬉しいです。', 'Terima kasih banyak telah memberi saya PMS. Itu sangat berarti bagi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('56ab9251-48ac-48c9-b45a-f88df57e4048', 'vocabulary', '男性', '男性', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Jenis kelamin laki-laki dikenal sebagai "laki-laki".', 'Jenis kelamin laki-laki dikenal sebagai "laki-laki".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('56ab9251-48ac-48c9-b45a-f88df57e4048', 'Laki-laki', true) ON CONFLICT DO NOTHING;
