INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('96731a05-7000-4acd-ab80-506f3f43a050', 'ぎょうざの皮を半分に折って折り目を作って下さい。', 'Silakan lipat kulit gyoza dan buat lipatannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('96731a05-7000-4acd-ab80-506f3f43a050', 'きっ茶店で折り紙を折っていたら、一人の女の子が近よってきた。', 'Saat aku sedang melipat origami di kafe, seorang gadis mendekatiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('96731a05-7000-4acd-ab80-506f3f43a050', 'その紙を折った時に、指を切ってしまったんだ。', 'Ketika saya sedang melipat kertas, saya mendapat potongan kertas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f34af4ac-59e2-4938-8c48-b0512e2a0c6c', 'vocabulary', '失望', '失望', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ada kesalahan dalam harapanmu. Itu rusak, dan semuanya berantakan. Anda merasakan kekecewaan dan keputusasaan yang sangat besar.', 'Ada kesalahan dalam harapanmu. Itu rusak, dan semuanya berantakan. Anda merasakan kekecewaan dan keputusasaan yang sangat besar.') ON CONFLICT (id) DO NOTHING;
