INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f34af4ac-59e2-4938-8c48-b0512e2a0c6c', 'しつぼう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f34af4ac-59e2-4938-8c48-b0512e2a0c6c', 'ホイップクリームたっぷりでって言ったのに、全然たっぷりじゃなくて失望しています。', 'Saya kecewa karena krim kocoknya tidak banyak padahal saya minta tambahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f34af4ac-59e2-4938-8c48-b0512e2a0c6c', 'あの先生は、期待していたよりも英語が上手じゃなくて失望しました。', 'Guru itu tidak pandai berbicara bahasa Inggris seperti yang saya kira, jadi saya kecewa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f34af4ac-59e2-4938-8c48-b0512e2a0c6c', 'マジ、自分に超失望中だよ〜。ノースリーブのシャツが着たいんだけど、ポッチャリ二の腕が気になってさ。しかも、腰まわりもたるんできたし。彼氏は私のポッチャリした指が好きだとか言うんだけど、そんなの全然嬉しくないってのさ。', 'Saya sangat kecewa. Aku ingin memakai baju tanpa lengan, tapi lenganku yang gemuk sangat menggangguku. Pinggangku juga menjadi lembek. Pacarku bilang dia menyukai jariku yang gemuk, tapi itu sama sekali tidak membuatku bahagia, tahu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('66380d36-1f29-432a-a05c-f357529854ea', 'vocabulary', '望み', '望み', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Sebuah harapan sebenarnya adalah sebuah keinginan yang ada di dalam diri Anda (walaupun bisa juga menjadi sebuah harapan).', 'Sebuah harapan sebenarnya adalah sebuah keinginan yang ada di dalam diri Anda (walaupun bisa juga menjadi sebuah harapan).') ON CONFLICT (id) DO NOTHING;
