INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75121aaa-0326-4211-8a99-73200862d439', 'ビエトの人格を疑います！', 'Saya mempertanyakan karakter Viet!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75121aaa-0326-4211-8a99-73200862d439', 'フグってとっても温こうな人格の持ち主だね。', 'Fugu memiliki kepribadian yang sangat lembut, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75121aaa-0326-4211-8a99-73200862d439', 'コウイチは人格者です。毎週日曜日に孤児院に出向いて、ベーコンを寄付しているのです。', 'Koichi adalah orang yang berintegritas. Setiap hari Minggu dia pergi ke panti asuhan dan menyumbangkan bacon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', 'vocabulary', '合格する', '合格する', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Statusnya bergabung bersama. Anggap saja ini seperti sekumpulan pesan status di Facebook, semuanya muncul bersamaan. Ujian besar pemerintah baru saja selesai. Status semua orang bergabung di Facebook bersama-sama untuk mengatakan mereka lulus, menunjukkan lulus ujian.', 'Statusnya bergabung bersama. Anggap saja ini seperti sekumpulan pesan status di Facebook, semuanya muncul bersamaan. Ujian besar pemerintah baru saja selesai. Status semua orang bergabung di Facebook bersama-sama untuk mengatakan mereka lulus, menunjukkan lulus ujian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', 'Untuk Lulus Ujian', true) ON CONFLICT DO NOTHING;
