INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', 'ごうかくする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', '折角苦労して合格したのに、何でそんなすぐに大学やめちゃったの？', 'Anda bekerja sangat keras untuk lulus ujian, jadi mengapa Anda tiba-tiba berhenti kuliah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', '今朝の時点では、まだ合格したのかどうか分からなかったんです。', 'Sampai pagi ini, saya belum tahu apakah saya lulus ujian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bf06a20-3028-4d07-9dce-f9c89fb95a20', '表向きは入学試験に合格するために学習塾に通ってたんだけど、私は実は友達と一緒にいたかっただけなんです。', 'Aku bersekolah di sekolah khusus untuk lulus ujian masuk, tapi sebenarnya aku hanya ingin berkumpul dengan teman-temanku di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10e1f60a-a8d4-48e7-8c7b-c11db90e2006', 'vocabulary', '性格', '性格', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Jenis kelamin dan status Anda adalah bagian dari kepribadian Anda. Pikirkan tentang gender apa yang Anda identifikasi, dan apa status Anda saat ini (dalam hubungan, tempat tinggal, pekerjaan...). Sekarang pikirkan bagaimana semua itu mempengaruhi kepribadian Anda!', 'Jenis kelamin dan status Anda adalah bagian dari kepribadian Anda. Pikirkan tentang gender apa yang Anda identifikasi, dan apa status Anda saat ini (dalam hubungan, tempat tinggal, pekerjaan...). Sekarang pikirkan bagaimana semua itu mempengaruhi kepribadian Anda!') ON CONFLICT (id) DO NOTHING;
