INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ca0c216-e919-41a4-a9db-ba3382964fb3', '「何でミカサがエレンのことを好きなのか私には分からないわ。だって、エレンって傲慢だし、思いやりがないし、それに格好良くもないのに。」「恋は盲目っていうじゃない。」', '"Aku tidak mengerti kenapa Mikasa menyukai Eren. Dia sombong, tidak pengertian, dan bahkan tidak tampan." "Cinta itu buta."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dafc1fd1-b1ac-4b09-ad4b-26a0947e2256', 'vocabulary', '残り', '残り', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ini memiliki arti yang sama dengan kanji.り kecil yang dilempar ke sana hanyalah sedikit sisa yang menempel di ujung kanji. Tidak perlu memperhatikan hal itu.', 'Ini memiliki arti yang sama dengan kanji.り kecil yang dilempar ke sana hanyalah sedikit sisa yang menempel di ujung kanji. Tidak perlu memperhatikan hal itu.') ON CONFLICT (id) DO NOTHING;
