INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('322769b4-9b71-47fb-bf7e-fd6d187d5dea', 'この映画に出えんしているはいゆうたちは、みんな才能があります。', 'Para aktor dalam film ini semuanya berbakat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('322769b4-9b71-47fb-bf7e-fd6d187d5dea', '外国語を勉強するのに才能がいると思いますか。', 'Apakah menurut Anda Anda perlu berbakat untuk belajar bahasa asing?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('322769b4-9b71-47fb-bf7e-fd6d187d5dea', '君はゴミをゴミ箱に投げ入れる才能があるね。', 'Anda memiliki bakat membuang sampah ke tempat sampah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69c132ab-558a-4658-bbe5-0487892ed6d5', 'vocabulary', '能力', '能力', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kekuatan kemampuan Anda adalah apa yang dapat Anda lakukan. Ini adalah kemampuan Anda. Itu juga merupakan kemampuan Anda.', 'Kekuatan kemampuan Anda adalah apa yang dapat Anda lakukan. Ini adalah kemampuan Anda. Itu juga merupakan kemampuan Anda.') ON CONFLICT (id) DO NOTHING;
