INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4b7b6fd7-31cf-4e00-9ba6-cc9ddfcf51be', 'びじゅつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b7b6fd7-31cf-4e00-9ba6-cc9ddfcf51be', '大学で美術のクラスをとっています。', 'Saya mengambil kelas seni rupa di perguruan tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b7b6fd7-31cf-4e00-9ba6-cc9ddfcf51be', 'き業のリーダーには美術のセンスも必要とされるが、コウイチにはそんなセンスは全くない。', 'Para pemimpin perusahaan harus memiliki selera terhadap seni rupa, namun Koichi tidak memiliki hal seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b7b6fd7-31cf-4e00-9ba6-cc9ddfcf51be', 'アヤは、人間の剥製という美しい美術作品が並べられたアジトを「トーフグの恐ろしい美術館」と名付けた。そして、コウイチとビエトもその剥製の一つにされようとしていた。', 'Aya menamai tempat persembunyiannya "Galeri Seni Mengerikan Tofugu" karena tempat itu dipenuhi dengan mayat-mayat yang dipenuhi karya seni yang indah. Koichi dan Viet akan bergabung dengan koleksinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', 'vocabulary', '信じる', '信じる', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya percaya jadi versi vocab verbanya adalah percaya.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya percaya jadi versi vocab verbanya adalah percaya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', 'Percaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', 'To Trust In', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', 'しんじる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', '信じられないかもしれないが、実はビエトはスパイだったんだよ。', 'Percaya atau tidak, Viet ternyata adalah mata-mata.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', '自分が目にしたもの以外は信じない主ぎなんです。', 'Saya tipe orang yang hanya mempercayai apa yang sebenarnya mereka lihat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('342599f2-2adb-46f8-b165-be0215fcb8cd', '自分がもはやサンタクロースを信じていないということに、最近イライラしている...と思うんだよね。', 'Sepertinya akhir-akhir ini aku merasa kesal karena aku tidak lagi percaya pada Sinterklas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'vocabulary', '自信', '自信', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ketika Anda percaya pada diri sendiri, Anda memiliki banyak kepercayaan diri (atau kepercayaan diri). Ini adalah hal yang baik untuk dimiliki!', 'Ketika Anda percaya pada diri sendiri, Anda memiliki banyak kepercayaan diri (atau kepercayaan diri). Ini adalah hal yang baik untuk dimiliki!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'Percaya diri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'Self Confidence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'じしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'コウイチは大変な自信家です。', 'Koichi adalah orang yang cukup percaya diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'もっと自信を持った方がいいよ！', 'Anda harus lebih percaya diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12b5e41d-d59e-46a2-b573-fe9b852fb62a', 'ビエトは、誰よりもコウイチのことをよく知っているので、誰よりもうまくコウイチの顔を描ける自信があると言っていた。', 'Viet mengatakan dia yakin dia bisa menggambar wajah Koichi lebih baik dari siapapun karena dia mengenalnya lebih baik dari siapapun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'vocabulary', '信号', '信号', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Jika percaya dengan angka tersebut, maka tidak akan terjadi kemacetan karena lampu lalu lintas akan berfungsi dengan baik. Lampu lalu lintas didasarkan pada data dan nomor lalu lintas. Anda hanya harus percaya dan berharap semuanya berhasil dalam hal lampu lalu lintas ini.', 'Jika percaya dengan angka tersebut, maka tidak akan terjadi kemacetan karena lampu lalu lintas akan berfungsi dengan baik. Lampu lalu lintas didasarkan pada data dan nomor lalu lintas. Anda hanya harus percaya dan berharap semuanya berhasil dalam hal lampu lalu lintas ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'Lampu Lalu Lintas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'Signal', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'Traffic Signal', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'Stoplight', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'Semaphore', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'しんごう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', '赤信号で止まって、青信号でわたるのよ。', 'Anda berhenti di lampu merah dan menyeberang jalan di lampu hijau, oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'あぶないから、信号をむししてはいけませんよ。', 'Mengabaikan lampu lalu lintas itu berbahaya, jadi jangan lakukan itu, oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5c67ddc-dda0-43bd-9545-77ebc09765e0', 'いいか、よく聞けよ。六つ目の信号で左折した後、八つ目の角まで歩いて右折したら、そこで会った人に向かってお尻を振るんだ。それが秘密のサインだからな。そしたら、奴はお前を俺たちのアジトまで連れて行ってくれるさ。', 'Dengarkan baik-baik. Belok kiri di lampu lalu lintas keenam, berjalanlah delapan blok lagi, belok kanan dan goyangkan pantat Anda ke arah seseorang yang akan Anda temui di sana. Itu tanda rahasianya, oke? Lalu, dia akan membawamu ke tempat persembunyian kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', 'vocabulary', '信心', '信心', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Apa yang Anda yakini dalam hati Anda, dan bukan dalam kepala Anda, itulah iman Anda. Ini adalah sesuatu yang tidak mengikuti logika, itu semua keyakinan hati, itu semua iman.', 'Apa yang Anda yakini dalam hati Anda, dan bukan dalam kepala Anda, itulah iman Anda. Ini adalah sesuatu yang tidak mengikuti logika, itu semua keyakinan hati, itu semua iman.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', 'Iman', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', 'Belief', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', 'しんじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', '私の母は仏教を信心しています。', 'Ibu saya percaya pada agama Buddha.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', '信心ぶって他人をひはんしてくるから、あの子のことあんまり好きじゃないんだよね。', 'Saya tidak terlalu menyukainya karena dia dengan sok suci mengkritik orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c3cf103-9337-48d0-acf0-dca11e2be1d7', '彼の家族はとても信心深くてスピリチュアルなので、他のお酒を飲まずにスピリッツだけ飲みます。', 'Keluarganya sangat religius dan spiritual, sehingga mereka tidak meminum minuman beralkohol apa pun selain minuman beralkohol.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'vocabulary', '信用', '信用', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Tugas Anda adalah percaya. Untuk melakukan itu, Anda harus memiliki kepercayaan yang besar terhadap apa yang Anda yakini... belum lagi keyakinan.', 'Tugas Anda adalah percaya. Untuk melakukan itu, Anda harus memiliki kepercayaan yang besar terhadap apa yang Anda yakini... belum lagi keyakinan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'Percaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'Confidence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'しんよう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'トーフグチームは、コウイチの言うことを全めん的に信用しています。', 'Tim Tofugu sepenuhnya mempercayai apa yang dikatakan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', 'コウイチの不しょう事が、トーフグの信用をきずつけてしまった。', 'Skandal Koichi telah merusak reputasi Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cf93cfd-475a-4e28-af33-b5962a9740fc', '私は、掃除や料理、マッサージや寝る前の歌なんかで、妻から信用点をつけられていると思っていたが、なんと逆に離婚されてしまったよ。', 'Saya pikir saya akan mendapatkan beberapa poin dari istri saya jika saya membersihkan rumah, menyiapkan makan malam, memijatnya, dan menidurkannya, namun dia malah menceraikan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'vocabulary', '不信', '不信', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ketika Anda tidak bisa (tidak) percaya pada seseorang, itu karena Anda tidak mempercayainya. Mungkin seseorang mendiskreditkan mereka dan sekarang Anda tidak mempercayai semua yang mereka katakan.', 'Ketika Anda tidak bisa (tidak) percaya pada seseorang, itu karena Anda tidak mempercayainya. Mungkin seseorang mendiskreditkan mereka dan sekarang Anda tidak mempercayai semua yang mereka katakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'Ketidakpercayaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'Mistrust', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'Discredit', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'Unfaithfulness', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'ふしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'あの変人が不信の目でおれのことを見てくるんだよ。', 'Keanehan itu membuatku menatap tidak percaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', 'ワニカニユーザーのトーフグへの不信はつのるばかりだった。', 'Ketidakpercayaan pengguna WaniKani terhadap Tofugu semakin kuat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0dbd4cc3-4e6f-4edf-8b5e-6e472fa3ebd2', '新しい日本語学習教材を部分的に公開することは、我々の会社が何か事実を隠蔽しようとしているとの不信を招くかもしれないじゃないですか？', 'Tidakkah menurut Anda rilis sebagian materi pembelajaran bahasa Jepang baru dapat menimbulkan kecurigaan bahwa perusahaan kita menutupi beberapa fakta?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'vocabulary', '返信', '返信', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda harus percaya itu akan kembali. Apa yang Anda yakini untuk kembali? Jawabannya. Anda membuat permintaan untuk sesuatu (munculkan sesuatu yang sangat Anda inginkan tetapi harus diminta). Sekarang Anda menunggu jawabannya.', 'Anda harus percaya itu akan kembali. Apa yang Anda yakini untuk kembali? Jawabannya. Anda membuat permintaan untuk sesuatu (munculkan sesuatu yang sangat Anda inginkan tetapi harus diminta). Sekarang Anda menunggu jawabannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'Balas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'Answer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'へんしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'やばい、返信するのわすれてた。ちょっと大変なことになってしまうかも。', 'Oh tidak, aku lupa membalasnya. Apa yang telah saya lakukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'き読になったのに、いつまでたっても返信が来ないんだよね。', 'Bunyinya "baca," tapi saya tidak pernah mendapat balasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8551a9c-996e-43c6-af7d-6045ce88c210', 'お疲れ〜。返信したつもりだったんだけど、どうやら力尽きて、送信ボタンを押す前に寝てたみたい。ごめんね、許して〜。', 'Bagaimana kabarnya? Kupikir aku sudah mengirimkan balasan padamu, tapi sepertinya aku terlalu lelah dan tertidur sebelum menekan tombol ''kirim''. Maaf. Maafkan aku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'vocabulary', '単に', '単に', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Jika Anda beralih ke (に) sederhana, Anda mengatakan sederhana, sekadar, atau hanya saja.', 'Jika Anda beralih ke (に) sederhana, Anda mengatakan sederhana, sekadar, atau hanya saja.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'Cukup', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'Merely', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'Only', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'たんに', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', 'コウイチは単に大変な努力家なだけですよ。', 'Itu hanya karena Koichi adalah pekerja keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', '「トーフグは、私にとっては単にお金をかせぐためのものではないんです。トーフグこそが私の人生なんです。」と、コウイチは言った。', 'Koichi berkata, "Bagiku, Tofugu bukan sekadar untuk menghasilkan uang. Ini adalah hidupku."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c926084-7d10-4122-8db2-2054133e63e2', '剣道では、単に相手を倒すことだけではなく、自らの心を鍛えることも重要です。', 'Dalam kendo, penting bukan hanya untuk mengalahkan lawan tapi juga melatih pikiranmu sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', 'vocabulary', '単語', '単語', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Bagian bahasa yang sederhana adalah kata-kata individual. Jika dipikir-pikir, ini benar. Pertama-tama, jumlahnya banyak sekali. Kedua, mereka kecil. Itu hanyalah sebagian kecil dari bahasa dan "kata" untuk bagian-bagian kecil ini adalah kata.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', 'Kata', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', 'Vocabulary', false) ON CONFLICT DO NOTHING;
