INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', '日本語の単語の単語ちょうを作りました。', 'Saya membuat buku catatan untuk kosakata bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', '単語の意味が分からない時は、じしょを引きます。', 'Ketika saya tidak tahu arti sebuah kata, saya mencarinya di kamus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84c28c78-e17a-4aaa-9f1d-4b5f1d2f1fd7', '日本語の単語ゲーム作ったんだけど、やってみない？', 'Saya membuat permainan kata Jepang. Apakah Anda ingin mencoba?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', 'vocabulary', '変', '変', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini lebih merupakan arti "aneh", bukan arti "perubahan". Seperti halnya, kamu 変な猫！', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini lebih merupakan arti "aneh", bukan arti "perubahan". Seperti halnya, kamu 変な猫！') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', 'Aneh', true) ON CONFLICT DO NOTHING;
