INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', 'へん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', 'はしらのかげに変な人がいると思ったらただのコウイチだった。', 'Kupikir ada pria aneh di balik tiang, tapi ternyata hanya Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', '同じ仕事をしているのに男性の方が女性よりきゅう料が高いなんてぜっ対に変だよ！', 'Benar-benar tidak masuk akal jika laki-laki mendapat gaji lebih tinggi dibandingkan perempuan meski melakukan pekerjaan yang sama!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('408fe6f5-c41f-4a6d-b9bc-358da94c7899', '変だなぁ。僕のメールボックスには、君が送ったと言っているメールがどこにも見当たらないよ。', 'Itu aneh. Saya tidak dapat menemukan email yang Anda kirimkan kepada saya di mana pun di kotak surat saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('78bc39ec-e283-4fd6-9d99-9f220833a022', 'vocabulary', '変人', '変人', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Orang aneh adalah orang yang eksentrik. Mereka juga eksentrik.', 'Orang aneh adalah orang yang eksentrik. Mereka juga eksentrik.') ON CONFLICT (id) DO NOTHING;
