INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78bc39ec-e283-4fd6-9d99-9f220833a022', 'あの変人のクローゼット、見た？', 'Apakah kamu melihat apa yang ada di lemari orang aneh itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78bc39ec-e283-4fd6-9d99-9f220833a022', '変人的なふるまいをしつづける世界記ろくにちょう戦したが、おしくも世界記ろくにはあと十分足りなかった。', 'Saya menantang diri saya sendiri untuk mencetak rekor dunia baru dalam bertindak seperti orang aneh, namun saya terlambat sepuluh menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78bc39ec-e283-4fd6-9d99-9f220833a022', 'あなたの上司はちょっと変人ですが、すぐに馴染めると思いますよ。', 'Bosmu sedikit eksentrik tapi menurutku kamu akan cocok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a23e12b-b145-45f9-9241-ff5abe56f967', 'vocabulary', '変化', '変化', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Perubahan dan perubahan sama dengan perubahan yang lebih besar lagi.', 'Perubahan dan perubahan sama dengan perubahan yang lebih besar lagi.') ON CONFLICT (id) DO NOTHING;
