INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a23e12b-b145-45f9-9241-ff5abe56f967', 'へんか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a23e12b-b145-45f9-9241-ff5abe56f967', 'コウイチは、天こうの変化にとてもびん感で、雨の日はよくへん頭痛をわずらっています。', 'Koichi sangat sensitif terhadap perubahan cuaca dan dia sering mengalami migrain saat hari hujan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a23e12b-b145-45f9-9241-ff5abe56f967', '十年前におとずれた時とくらべて、東京はずいぶんと変化しましたね。', 'Tokyo telah banyak berubah sejak saya berkunjung sepuluh tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a23e12b-b145-45f9-9241-ff5abe56f967', 'うわ！すごいね。既に変化が現れているのが分かるよ。', 'Wow! Ini luar biasa! Saya sudah bisa melihat perubahannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'vocabulary', '変死', '変死', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kematian yang aneh adalah kematian yang tampaknya tidak benar. Ini adalah kematian yang tidak wajar, dan mungkin merupakan kematian yang tidak disengaja (yaitu bukan disebabkan oleh sebab alamiah).', 'Kematian yang aneh adalah kematian yang tampaknya tidak benar. Ini adalah kematian yang tidak wajar, dan mungkin merupakan kematian yang tidak disengaja (yaitu bukan disebabkan oleh sebab alamiah).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'Kematian Tidak Wajar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'Accidental Death', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'へんし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'けいさつは、コウイチの変死についてちょうさしています。', 'Polisi sedang menyelidiki kematian Koichi yang tidak wajar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', '「なんかパニクってるけど、どうしたの？」「コウイチは変死して、トーフグがとうさんするって聞いたんだよ。最悪だよ。」', '“Kamu terlihat kesal. Apakah semuanya baik-baik saja?” "Saya baru saja mendengar bahwa Koichi meninggal karena kecelakaan dan Tofugu bangkrut. Ini mimpi buruk."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee19be95-86c4-430c-8ca8-21cea517eceb', 'コウイチが謎の変死を遂げたというニュースは、全国民を震撼させた。', 'Berita bahwa Koichi menemui kematian yang misterius dan tidak wajar mengejutkan negara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61b7f0c9-c5ce-4954-96fd-48d0a45f8283', 'vocabulary', '大変', '大変', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Perubahan besar adalah hal yang sangat serius. Dan orang-orang juga tidak menyukai perubahan, sehingga menjadikannya peristiwa yang buruk. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('61b7f0c9-c5ce-4954-96fd-48d0a45f8283', 'Serius', true) ON CONFLICT DO NOTHING;
