INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61b7f0c9-c5ce-4954-96fd-48d0a45f8283', '日本語を習とくするのは大変ですが、がんばってくださいね。', 'Menguasai bahasa Jepang itu sulit, tapi lakukan yang terbaik!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61b7f0c9-c5ce-4954-96fd-48d0a45f8283', '大変丈夫な子供が生まれました。', 'Mereka memiliki anak yang sangat sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61b7f0c9-c5ce-4954-96fd-48d0a45f8283', '災害時は、電話回線もネット回線も混み合って、繋がりづらくなるので、ブログの更新が大変です。', 'Saat terjadi bencana, telepon dan sirkuit Internet kelebihan beban dan sulit tersambung, sehingga sulit untuk mengunggah postingan blog baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', 'vocabulary', '事変', '事変', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Suatu tindakan yang dapat mengubah suatu tempat atau bahkan dunia pastilah sebuah peristiwa besar. Terkadang Anda akan melihat ini di akhir nama "insiden", seperti "Manshuu Jihen" (満州事変), alias "Insiden Manshuu". Anda tahu bahwa ini bukanlah kejadian yang tidak biasa atau aneh (seperti 変事) karena kanji "aneh" (変) tidak muncul pertama kali pada kata ini. Sebaliknya, kata ini muncul setelah dan berarti "perubahan" dalam kasus ini.', 'Suatu tindakan yang dapat mengubah suatu tempat atau bahkan dunia pastilah sebuah peristiwa besar. Terkadang Anda akan melihat ini di akhir nama "insiden", seperti "Manshuu Jihen" (満州事変), alias "Insiden Manshuu". Anda tahu bahwa ini bukanlah kejadian yang tidak biasa atau aneh (seperti 変事) karena kanji "aneh" (変) tidak muncul pertama kali pada kata ini. Sebaliknya, kata ini muncul setelah dan berarti "perubahan" dalam kasus ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', 'Insiden', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', 'じへん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', '上海事変は何年に起こりましたか。', 'Tahun berapa Insiden Shanghai terjadi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', '事変という言葉を使った例文をさがしていたら、東京事変というバンドがあることを知りました。', 'Ketika saya sedang mencari contoh kalimat dengan kata insiden, saya menemukan sebuah band bernama Tokyo Incident.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cbf9b20-a528-415c-8e2c-6dfaf50b4d8a', '満州事変について説明をしてもらえますか？', 'Bisakah Anda menjelaskan apa yang dimaksud dengan Insiden Manchuria?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('afa2e337-f9cc-4449-82af-2d6912524038', 'vocabulary', '夫', '夫', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
