INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afa2e337-f9cc-4449-82af-2d6912524038', '私の夫の歯は、とても丈夫です。', 'Suami saya memiliki gigi yang sangat sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afa2e337-f9cc-4449-82af-2d6912524038', '私の夫は、大変すばらしい男性です。', 'Suamiku adalah pria yang luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afa2e337-f9cc-4449-82af-2d6912524038', 'ほら、また始まった。あんたって本当にいつも自分の夫の不満ばかり言っているよね。', 'Ini dia lagi, selalu mengeluh tentang suamimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6647b4b2-1846-45d3-be34-173d777709a3', 'vocabulary', '式', '式', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
