INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6647b4b2-1846-45d3-be34-173d777709a3', 'いったい式場はどこなんだ？', 'Dimana sih upacaranya diadakan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6647b4b2-1846-45d3-be34-173d777709a3', '開会式は九時にスタートする予定です。', 'Upacara pembukaan dijadwalkan pada jam 9 pagi') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6647b4b2-1846-45d3-be34-173d777709a3', 'その儀式は退屈だったので、たくさん方程式を解いて時間を潰しました。', 'Ritualnya membosankan, jadi saya menghabiskan waktu dengan menyelesaikan banyak persamaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8091dfc-dad5-4586-a30a-226f21615a5f', 'vocabulary', '昨今', '昨今', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Sebelumnya dari sekarang adalah waktu di sekitar sekarang. Itu terjadi pada saat ini, saat ini, atau baru-baru ini.', 'Sebelumnya dari sekarang adalah waktu di sekitar sekarang. Itu terjadi pada saat ini, saat ini, atau baru-baru ini.') ON CONFLICT (id) DO NOTHING;
