INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a8091dfc-dad5-4586-a30a-226f21615a5f', 'さっこん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8091dfc-dad5-4586-a30a-226f21615a5f', '昨今はあなたの様な大物にお目にかかれることはめったになくなりましたよ、コウイチさん。', 'Saat ini sangat jarang bertemu orang sebesar Anda, Tuan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8091dfc-dad5-4586-a30a-226f21615a5f', '昨今の流行りにあやかって、コウイチはオフィスでしば犬とチンド犬をかうことに決めました。', 'Karena tren terkini, Koichi memutuskan untuk memiliki Shiba-inu dan Jindo di kantor kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8091dfc-dad5-4586-a30a-226f21615a5f', '昨今は就職氷河期だと言われているが、会社を選ばなければどこかには就職できるはずである。', 'Mereka bilang saat ini adalah masa yang sulit bagi pencari kerja, tapi saya yakin Anda harus bisa mendapatkan pekerjaan jika Anda tidak pilih-pilih tentang perusahaan tempat Anda bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', 'vocabulary', '昨日', '昨日', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Hari kemarin adalah kemarin. Sungguh sebuah ledakan dari masa lalu!', 'Hari kemarin adalah kemarin. Sungguh sebuah ledakan dari masa lalu!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', 'Kemarin', true) ON CONFLICT DO NOTHING;
