INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', 'さくじつ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', '昨日の夜は、よくねむれた？', 'Apakah kamu tidur nyenyak tadi malam?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', '昨日はアメリカとカナダで労働者の日でした。', 'Kemarin adalah Hari Buruh di AS dan Kanada.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29d2bcb8-9c40-4cc2-95a5-f56f6b5310ca', '昨日は、大学の課題で、沢山の叙事詩を読まなくてはいけませんでした。', 'Kami harus membaca banyak puisi epik kemarin untuk tugas universitas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', 'vocabulary', '晩', '晩', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', 'Malam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', 'Evening', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', 'ばん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', '昨日の晩はフグの毒にあたって死ぬところでした。', 'Tadi malam, aku hampir mati karena racun ikan buntal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', '三日前の晩から毎晩コウイチがゆめに出てきてわたしにWanikaniを買わないと不こうになると耳打ちするんです。', 'Koichi muncul dalam mimpiku setiap malam selama tiga hari terakhir, dan dia berbisik di telingaku bahwa aku tidak akan bahagia jika aku tidak membeli WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('820deabc-356c-449d-816a-38a6d945b9ee', '「よお！今晩、飲みに行かないか？」「ごめん。今、禁酒中なんだよ。」', '"Hei, kenapa kita tidak pergi minum malam ini?" "Maaf, aku tetap sadar sekarang."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', 'vocabulary', '今晩は', '今晩は', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kata ini terdiri dari sekarang dan malam dengan hiragana は di akhir.は di sini diucapkan sebagai わ (pengucapan lama). Saat Anda mengatakan "sekarang malam!" kamu benar-benar mengucapkan selamat malam.', 'Kata ini terdiri dari sekarang dan malam dengan hiragana は di akhir.は di sini diucapkan sebagai わ (pengucapan lama). Saat Anda mengatakan "sekarang malam!" kamu benar-benar mengucapkan selamat malam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', 'Selamat Malam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', 'こんばんは', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', '今晩は。こんな所で何してるの？', 'Selamat malam. Apa yang kamu lakukan di tempat seperti ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', '「あら、今晩は。」「今晩は。」「昨日の社長とのミーティング、どうだった？」「それが....てっきりしょう進するものだと信じてたんですが、首になりました。」', '"Oh, hei, selamat malam." "Selamat malam." “Bagaimana pertemuan dengan presiden kemarin?” "Yah, saya yakin saya akan dipromosikan, tapi saya malah dipecat."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c3fbf7d-9f6b-4966-a809-50b9a9a984f3', '今晩は、コウイチおじさん。今日は私とフグの赤ちゃんの面倒をみてくれて有難うございます。あ、ところで、電子レンジは使わなかったよね？ 母乳だから、電子レンジ使ったらいけないんだよ。', 'Selamat malam, Paman Koichi. Terima kasih telah merawat bayi kami hari ini. Hei, kamu tidak memasukkannya ke dalam microwave, kan? Karena ini ASI, Anda tidak boleh melakukan itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', 'vocabulary', '毎晩', '毎晩', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Setiap malam hanyalah setiap malam. Apa yang kamu lakukan setiap malam?', 'Setiap malam hanyalah setiap malam. Apa yang kamu lakukan setiap malam?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', 'Setiap Malam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', 'Nightly', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', 'まいばん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', '体を丈夫にするために、毎晩やく用酒を飲んでいます。', 'Untuk meningkatkan kesehatan saya, saya minum alkohol obat setiap malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', '私の夫は、毎晩五時に夕食を食べて、十時には寝ます。', 'Setiap malam suami saya makan malam jam 5 dan tidur jam 10.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc9e9971-fd37-4bb5-bc5f-ae436a697660', '毎晩泣く子を抱きながら、子供の世話をするには大変な忍耐が必要だということを学びました。', 'Sambil menggendong bayi yang menangis setiap malam, saya belajar bahwa Anda memerlukan banyak kesabaran untuk merawat anak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', 'vocabulary', '晴れる', '晴れる', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjernihkan, jadi versi vocab verbanya adalah menjernihkan. Itu juga berarti menjadi cerah juga.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjernihkan, jadi versi vocab verbanya adalah menjernihkan. Itu juga berarti menjadi cerah juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', 'Untuk Menjernihkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', 'To Become Sunny', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', 'はれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', '今は雨がふってますけど、二時までには晴れると思いますよ。', 'Saat ini sedang hujan, tapi menurutku cuaca akan cerah pada pukul dua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', '昨日はよく晴れて良かったですね。', 'Untunglah kemarin cuacanya sangat cerah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca0f47df-14e1-4340-bdb0-37f60ac930b7', 'ようやくフグと結婚することになったので、是非式に来てほしいなと思っています。詳細を同封した招待状を後ほどお送りしますね。パーティーは野外の予定なので、当日晴れるといいんだけどな。', 'Saya akhirnya menikah dengan Fugu dan saya ingin Anda hadir di pernikahan kami. Saya akan mengirimi Anda undangan dengan semua detailnya nanti. Resepsinya diadakan di luar, jadi kuharap hari itu cerah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', 'vocabulary', '方法', '方法', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Cara metode atau cara cara adalah cara atau cara. Ini adalah kata yang bagus untuk berbicara tentang bagaimana melakukan sesuatu. Apa itu 方法? Baiklah, pertama kamu...', 'Cara metode atau cara cara adalah cara atau cara. Ini adalah kata yang bagus untuk berbicara tentang bagaimana melakukan sesuatu. Apa itu 方法? Baiklah, pertama kamu...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', 'Metode', true) ON CONFLICT DO NOTHING;
