INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', 'ほうほう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', 'ビエトには、その方法はきかないっていうか、むしろぎゃくこうかですよ。', 'Metode itu tidak berhasil di Vietnam. Ini sebenarnya bekerja sebaliknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', '赤ちゃんをぐっすりベッドでねむらせる方法が知りたいです。', 'Saya ingin tahu cara membuat bayi tidur nyenyak di tempat tidur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cf97533-0bac-4f90-8d0b-db8a5154ee7e', 'シャーロック・ホームズって、古びた犯罪調査方法を使っているよね？', 'Sherlock Holmes punya metode lama dalam menyelidiki kejahatan, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', 'vocabulary', '文法', '文法', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Metode menulis adalah bagaimana Anda menulis. Anda dapat memiliki kosakata, tetapi Anda harus dapat menggabungkannya menggunakan suatu metode. Metode ini kebetulan tata bahasa.', 'Metode menulis adalah bagaimana Anda menulis. Anda dapat memiliki kosakata, tetapi Anda harus dapat menggabungkannya menggunakan suatu metode. Metode ini kebetulan tata bahasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', 'Tata Bahasa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', 'ぶんぽう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', '日本語の文法の本をさがしています。', 'Saya mencari buku tata bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', '文法を学べば学ぶほど、文章をかくのが上手になりますよ。', 'Semakin banyak tata bahasa yang Anda pelajari, semakin baik tulisan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82b2de8f-036d-4dbc-9903-fa8d66f4ab42', '私の上司、見た目はできる男なのに、いつも間違った文法を使うのが残念すぎるよ。', 'Bos saya terlihat seperti orang yang pintar, jadi sayang sekali dia selalu membuat kesalahan tata bahasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e4e75c7-6e6e-4312-bdbb-56c0939cce14', 'vocabulary', '不法', '不法', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Yang tidak sesuai hukum adalah sesuatu yang melawan hukum. Itu ilegal atau melanggar hukum.', 'Yang tidak sesuai hukum adalah sesuatu yang melawan hukum. Itu ilegal atau melanggar hukum.') ON CONFLICT (id) DO NOTHING;
