INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5e4e75c7-6e6e-4312-bdbb-56c0939cce14', 'ふほう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e4e75c7-6e6e-4312-bdbb-56c0939cce14', 'ビエトが行っている不法のやみとり引のことを、トーフグの社員はだれも知らない。', 'Tidak ada satupun pekerja Tofugu yang mengetahui tentang transaksi pasar gelap ilegal yang dilakukan Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e4e75c7-6e6e-4312-bdbb-56c0939cce14', 'アメリカにはげん時てんで何人の不法たいざい者がいると思いますか？', 'Menurut Anda, berapa banyak orang asing ilegal yang ada di AS saat ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e4e75c7-6e6e-4312-bdbb-56c0939cce14', '不法な捜査で得た証拠は法廷では使えませんよ。', 'Kami tidak dapat menggunakan bukti yang diperoleh melalui penggeledahan yang melanggar hukum di pengadilan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84883751-99fe-4a5f-8251-5cc0ddd5e276', 'vocabulary', '猫', '猫', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Meong!', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Meong!') ON CONFLICT (id) DO NOTHING;
