INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84883751-99fe-4a5f-8251-5cc0ddd5e276', 'うちの猫は、暗算がとく意なんです。', 'Kucing kami pandai mengerjakan matematika di kepalanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84883751-99fe-4a5f-8251-5cc0ddd5e276', 'このクローゼットにあるりょうの四倍の猫の服が家にあります。', 'Saya punya empat kali lebih banyak pakaian kucing di lemari di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84883751-99fe-4a5f-8251-5cc0ddd5e276', '助けてくれ！俺の飼い猫がスクラブルの ’M’のコマを飲み込んじゃったんだ！', 'Anda harus membantu saya! Kucing saya menelan ubin Scrabble "M"!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b425a934-5a27-4193-b14b-f76c06bcbe41', 'vocabulary', '子猫', '子猫', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anak kucing adalah anak kucing yang menggemaskan. Ya ampun!', 'Anak kucing adalah anak kucing yang menggemaskan. Ya ampun!') ON CONFLICT (id) DO NOTHING;
