INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b425a934-5a27-4193-b14b-f76c06bcbe41', 'その子猫は、えだからえだを軽かいにとびうつりました。', 'Anak kucing itu melompat dengan gesit dari dahan ke dahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b425a934-5a27-4193-b14b-f76c06bcbe41', '子猫が時計回りにクルクル歩き回っている動画をYoutubeにアップロードしました。', 'Saya mengunggah video ke Youtube tentang seekor kucing yang berjalan searah jarum jam, berputar-putar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b425a934-5a27-4193-b14b-f76c06bcbe41', '私達、ちょうどこの子猫を見つけて、飼い主をさがしているんです。', 'Kami baru saja menemukan anak kucing ini dan sedang mencari pemiliknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f2eb777d-2ad9-4245-90d3-d04b12e65951', 'vocabulary', '残品', '残品', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Produk selebihnya merupakan barang yang belum terjual. Itu adalah barang dagangan yang tidak terjual. Itu sisa stok.', 'Produk selebihnya merupakan barang yang belum terjual. Itu adalah barang dagangan yang tidak terjual. Itu sisa stok.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f2eb777d-2ad9-4245-90d3-d04b12e65951', 'Barang Dagangan Tidak Terjual', true) ON CONFLICT DO NOTHING;
