INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e2b48a7-8fa7-41c8-8946-fe276ba5d4fc', 'Please', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5e2b48a7-8fa7-41c8-8946-fe276ba5d4fc', 'おねがい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e2b48a7-8fa7-41c8-8946-fe276ba5d4fc', 'お願い！手伝って！', 'Silakan! Bantu aku!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e2b48a7-8fa7-41c8-8946-fe276ba5d4fc', '「ちょっとお願いがあるんだけど……。」「もちろん。言ってみて。」', '"Bisakah kamu membantuku...?" "Tentu saja. Sebutkan saja."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e2b48a7-8fa7-41c8-8946-fe276ba5d4fc', '中小企業は小回りが利くから、こういう仕事をお願いしても平気だろう。', 'Perusahaan yang lebih kecil menghadapi tantangan baru dengan lebih cepat, jadi mereka mungkin tidak akan keberatan jika kita meminta pekerjaan seperti ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'vocabulary', '折り目', '折り目', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Lipatan yang terlihat dengan mata adalah lipatan atau lipatan pada sesuatu.', 'Lipatan yang terlihat dengan mata adalah lipatan atau lipatan pada sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'Lipat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'Crease', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'おりめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'このズボンには、折り目がなかったということを、ここに証明いたします。', 'Dengan ini saya menyatakan bahwa celana ini tidak memiliki satu lipatan pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', '折り紙を半分に折って、折り目をつけてからまた開いてください。', 'Silakan buka kembali origami setelah Anda melipatnya menjadi dua untuk menambah lipatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d76b65c-afae-4d5d-ba0c-f14e81b565f2', 'ズボンには折り目を付けてもらえますか？', 'Bisakah Anda membuat lipatan di celana saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', 'vocabulary', '不完全', '不完全', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda tahu bahwa 完全 berarti "lengkap" atau "sempurna". Jadi, yang tidak “lengkap” atau “sempurna” adalah sesuatu yang tidak lengkap atau tidak sempurna.', 'Anda tahu bahwa 完全 berarti "lengkap" atau "sempurna". Jadi, yang tidak “lengkap” atau “sempurna” adalah sesuatu yang tidak lengkap atau tidak sempurna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', 'Tidak lengkap', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', 'Imperfect', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', 'ふかんぜん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', '不完全な形のあいってどんなものですか。', 'Cinta macam apa yang tidak sempurna?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', '完全なものよりも不完全なものの方が人情味があってよくない？', 'Bukankah hal-hal yang tidak lengkap lebih baik daripada hal-hal yang lengkap, karena ada sisi kemanusiaannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bdfe438-a463-419a-bcac-bfc53f9e7c92', '勝ち試合が雨で中止になり、トーフグソフトボールチームのシーズンが不完全に終わった。', 'Tim softball Tofugu mengalami akhir musim yang tidak lengkap ketika pertandingan yang mereka menangkan dihentikan karena hujan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'vocabulary', '美術館', '美術館', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda tahu 美術 adalah seni rupa. Lalu apa yang dimaksud dengan bangunan publik yang memuat seni rupa tersebut? Itu adalah museum.', 'Anda tahu 美術 adalah seni rupa. Lalu apa yang dimaksud dengan bangunan publik yang memuat seni rupa tersebut? Itu adalah museum.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'Muzium', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'Art Museum', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'Art Gallery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'びじゅつかん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', 'その美術館にかざられていたノアの箱ぶねの絵が好きでした。', 'Saya menyukai gambar bahtera Nuh yang dipajang di galeri seni.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', '母が残してくれた指輪を、美術館にき付しました。', 'Saya menyumbangkan cincin yang diturunkan dari ibu saya ke museum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8fad7238-a64c-41a1-863a-d92a33a598c3', '「どうやって美術館のツアーガイドになれるの？芸術の専門家か何かじゃなくちゃいけないんじゃないの？」「いいや、そうでもないよ。 美術館が情報を全部くれるから、まぁ、台詞を覚えるようなもんだよ。」', '“Bagaimana kamu bisa menjadi pemandu wisata di museum? Bukankah kamu harus menjadi ahli seni atau semacamnya?” "Tidak, tidak juga. Mereka memberimu semua informasi, itu seperti menghafal naskah."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', 'vocabulary', '折り紙', '折り紙', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda tahu bahwa 折る berarti "melipat", lalu bagaimana dengan "melipat kertas"? Pernah mendengar sesuatu yang melibatkan banyak pelipatan kertas dalam bahasa Jepang? Kemungkinan besar Anda pernah mengalaminya. Inilah origami alias seni melipat kertas.', 'Anda tahu bahwa 折る berarti "melipat", lalu bagaimana dengan "melipat kertas"? Pernah mendengar sesuatu yang melibatkan banyak pelipatan kertas dalam bahasa Jepang? Kemungkinan besar Anda pernah mengalaminya. Inilah origami alias seni melipat kertas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', 'Origami', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', 'Art Of Paper Folding', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', 'おりがみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', '今日のコウイチの弁当箱の中には、なぜか食べ物の代わりに折り紙が入っていました。', 'Hari ini, di kotak bento Koichi, ada beberapa origami sebagai pengganti makanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', '私はプロの折り紙アーティストです。', 'Saya seorang seniman origami profesional.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd41c523-4b2d-4ff9-b078-7cecd40a8846', '私のことをこの数年間支えてくれたみなさん、本当に有難うございます。お陰様で、ついに折り紙で河豚が折れるようになりました。', 'Saya ingin berterima kasih kepada semua orang yang telah memberikan dukungan kepada saya selama bertahun-tahun. Syukurlah, saya akhirnya menguasai cara membuat origami Fugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('498eff15-f239-4b8a-b0a6-3afee72bf98e', 'vocabulary', '不合格', '不合格', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda tahu bahwa 合格する berarti "lulus ujian", lalu apa kebalikannya? Gagal dalam ujian atau kegagalan.', 'Anda tahu bahwa 合格する berarti "lulus ujian", lalu apa kebalikannya? Gagal dalam ujian atau kegagalan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('498eff15-f239-4b8a-b0a6-3afee72bf98e', 'Gagal dalam Tes', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('498eff15-f239-4b8a-b0a6-3afee72bf98e', 'Failure', false) ON CONFLICT DO NOTHING;
