INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28877fca-8fd0-4ab3-8d20-68b14b544e10', 'あのポーカーのトーナメントで、悪い予感はしてたんだけど、捨てるのは不可能な手札を持っていたんだよ。', 'Di turnamen poker, saya punya firasat buruk, tetapi saya tidak bisa melipat tangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d0e6755-ab6c-491d-95b1-5bfc0608c943', 'vocabulary', '可能', '可能', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kemampuannya ada, jadi mungkin... tunggu, ada cukup kemampuan untuk membuat ini mungkin? Ayo lakukan!', 'Kemampuannya ada, jadi mungkin... tunggu, ada cukup kemampuan untuk membuat ini mungkin? Ayo lakukan!') ON CONFLICT (id) DO NOTHING;
