INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d0e6755-ab6c-491d-95b1-5bfc0608c943', '今年の春から、むすめを保育園にあずけることが可能だと聞いて、胸のつかえが下りました。', 'Mendengar bahwa saya bisa memasukkan putri saya ke tempat penitipan anak pada musim semi ini, membuat saya merasa sangat terbebani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d0e6755-ab6c-491d-95b1-5bfc0608c943', 'もう少し実げん可能なかい決さくをていあんしてください。', 'Harap sampaikan beberapa kemungkinan solusi lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d0e6755-ab6c-491d-95b1-5bfc0608c943', '私は年間一億ドルを稼ぐことは実現可能だと思います。', 'Menurut saya, menghasilkan seratus juta dolar setahun adalah hal yang mungkin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9382825f-66de-4b15-bf4a-3dfeec7d426c', 'vocabulary', '変える', '変える', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kanjinya adalah perubahan, dan kata kerjanya adalah mengubah sesuatu. Jika Anda mengubah satu hal dengan hal lain, Anda akan mengubahnya. Kata ini mengacu pada mengubah satu hal untuk hal serupa.', 'Kanjinya adalah perubahan, dan kata kerjanya adalah mengubah sesuatu. Jika Anda mengubah satu hal dengan hal lain, Anda akan mengubahnya. Kata ini mengacu pada mengubah satu hal untuk hal serupa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9382825f-66de-4b15-bf4a-3dfeec7d426c', 'Untuk Mengubah Sesuatu', true) ON CONFLICT DO NOTHING;
