INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8a8433b2-e33d-4385-8aef-1f0d2610adc3', 'ひょうじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a8433b2-e33d-4385-8aef-1f0d2610adc3', 'そんなこわい表情をしないでください。', 'Tolong jangan membuat ekspresi wajah yang menakutkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a8433b2-e33d-4385-8aef-1f0d2610adc3', 'ワニカニの売り上げレポートを見たコウイチの表情はとてもうれしそうだった。', 'Setelah melihat laporan pendapatan WaniKani, wajah Koichi terlihat sangat bahagia.') ON CONFLICT DO NOTHING;
