INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39220528-4940-4048-aee4-468871e2c8c1', '「列の最後びはここですか？」「いいえ、私は列の先頭です。」', '“Apakah ini akhir dari antrean?” “Tidak. Saya berada di barisan paling depan.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39220528-4940-4048-aee4-468871e2c8c1', '私のせきは、前から二列目でした。', 'Tempat dudukku ada di baris kedua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39220528-4940-4048-aee4-468871e2c8c1', 'ベーコンショップの前には長い列ができていた。', 'Ada antrean panjang di depan toko bacon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a3c0b0f-e28c-4d88-9d49-3638826bbb42', 'vocabulary', '記念日', '記念日', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Beberapa hari begitu istimewa sehingga Anda harus menuliskan semua pemikiran Anda setelah selesai. Ini adalah hari-hari istimewa seperti hari libur dan hari jadi Anda.', 'Beberapa hari begitu istimewa sehingga Anda harus menuliskan semua pemikiran Anda setelah selesai. Ini adalah hari-hari istimewa seperti hari libur dan hari jadi Anda.') ON CONFLICT (id) DO NOTHING;
