INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('144f3b09-5f4a-4adf-abcc-acb0cc9316ec', 'お酒を飲みすぎて、完全に理性を失ってしまっていました。', 'Saya terlalu banyak minum dan kehilangan akal sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('144f3b09-5f4a-4adf-abcc-acb0cc9316ec', 'ビエトは、今時は、ヤクザもぼう力にたよるんじゃなく、理性にうったえなくっちゃダメだって言ってたよ。', 'Viet mengatakan bahwa saat ini bahkan yakuza harus menggunakan kecerdasan daripada menggunakan kekerasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('144f3b09-5f4a-4adf-abcc-acb0cc9316ec', 'ダメだと分かっていたが、理性を保てなかったんだ。', 'Aku mengerti bahwa itu tidak ada harapan, tapi aku tidak bisa berpegang pada alasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a22b056e-d749-4b6c-9b32-02009c629c34', 'vocabulary', '情けない', '情けない', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda telah melihat bagaimana kata 情け berarti kasihan, jadi menambahkan ない pada kata itu akan mengubahnya menjadi kata sifat yang berarti menyedihkan dan menyedihkan.', 'Anda telah melihat bagaimana kata 情け berarti kasihan, jadi menambahkan ない pada kata itu akan mengubahnya menjadi kata sifat yang berarti menyedihkan dan menyedihkan.') ON CONFLICT (id) DO NOTHING;
