INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a22b056e-d749-4b6c-9b32-02009c629c34', '情けないですが、すぐに人を信じる性格なので、よくだまされるんです。', 'Sedih memang, tapi saya mempunyai sifat yang sangat percaya, sehingga saya sering ditipu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a22b056e-d749-4b6c-9b32-02009c629c34', 'ツテでしゅうしょくするなんて、情けない。実力で勝負しろよ。', 'Memalukan sekali mendapatkan pekerjaan menggunakan koneksi. Anda harus bersaing menggunakan kemampuan Anda sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a22b056e-d749-4b6c-9b32-02009c629c34', '日本の政治家には、本当に情けない奴が多い。', 'Memang ada banyak politisi Jepang yang menyedihkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a26a90f-0f74-47b1-b142-4f27b4d85111', 'vocabulary', '相変わらず', '相変わらず', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Perubahan timbal balik yang Anda lakukan dengan orang lain akan berjalan begitu lancar sehingga semuanya tampak berjalan seperti biasa. Semuanya akan sama seperti sebelumnya karena perubahan itu saling menguntungkan.', 'Perubahan timbal balik yang Anda lakukan dengan orang lain akan berjalan begitu lancar sehingga semuanya tampak berjalan seperti biasa. Semuanya akan sama seperti sebelumnya karena perubahan itu saling menguntungkan.') ON CONFLICT (id) DO NOTHING;
