INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4a26a90f-0f74-47b1-b142-4f27b4d85111', 'あいかわらず', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a26a90f-0f74-47b1-b142-4f27b4d85111', '相変わらずかっこいい鼻輪をつけてるね。でも、今日は鼻毛が出てるよ。', 'Seperti biasa, kamu punya cincin hidung yang keren, tapi aku bisa melihat bulu hidungmu hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a26a90f-0f74-47b1-b142-4f27b4d85111', '相変わらず面白いことをしてるね。', 'Ini menarik, seperti biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a26a90f-0f74-47b1-b142-4f27b4d85111', 'ビエトは相変わらず、つぶやくような小声で、ヒドイことを言いまくってるね。', 'Viet menggumamkan sumpah seperti biasa, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1ccaabdd-7791-4625-a9af-acd1a741931e', 'vocabulary', '折れる', '折れる', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Anda sudah mempelajari bagaimana 折る berarti "melipat sesuatu" atau "mematahkan sesuatu". Ini adalah versi intransitif, yang berarti tidak memiliki objek. Anda baru saja melipat sesuatu terlalu jauh, dan sekarang mulai rusak.', 'Anda sudah mempelajari bagaimana 折る berarti "melipat sesuatu" atau "mematahkan sesuatu". Ini adalah versi intransitif, yang berarti tidak memiliki objek. Anda baru saja melipat sesuatu terlalu jauh, dan sekarang mulai rusak.') ON CONFLICT (id) DO NOTHING;
