INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f29c2584-d708-4f30-b640-01726b7e5ba0', 'はれ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f29c2584-d708-4f30-b640-01726b7e5ba0', '天気予ほうでは、明日も明後日も明々後日も晴れでしょうって言ってたよ。', 'Ramalan cuaca mengatakan besok, lusa, dan dua hari dari sekarang akan cerah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f29c2584-d708-4f30-b640-01726b7e5ba0', '予ほうは「晴れ後くもり」だし、かさはいらないんじゃない？', 'Ramalan cuaca mengatakan "cuaca cerah, nanti akan berawan", jadi menurut saya Anda tidak memerlukan payung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f29c2584-d708-4f30-b640-01726b7e5ba0', '折角の誕生日だし、晴れて良かったですね。', 'Untung saja hal itu jelas pada hari ulang tahunmu, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('46196956-588a-47db-94a3-7f7c31db0f2a', 'vocabulary', '一昨日', '一昨日', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Ingat bagaimana Anda mengetahui bahwa 昨日 berarti "kemarin?" Nah, satu hari sebelum hari itu adalah hari sebelum hari terakhir.', 'Ingat bagaimana Anda mengetahui bahwa 昨日 berarti "kemarin?" Nah, satu hari sebelum hari itu adalah hari sebelum hari terakhir.') ON CONFLICT (id) DO NOTHING;
