INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46196956-588a-47db-94a3-7f7c31db0f2a', '今さらですが一昨日の5月5日はルフィのたん生日でした。', 'Memang agak terlambat, tapi kemarin lusa, tanggal 5 Mei, adalah hari ulang tahun Luffy.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46196956-588a-47db-94a3-7f7c31db0f2a', '一昨日だったら空いてたんだけど、今月は他の日は全てうまってしまってるんだよね。', 'Saya tersedia sehari sebelumnya, tetapi bulan ini semua hari saya yang lain sudah penuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46196956-588a-47db-94a3-7f7c31db0f2a', '一昨日、夫の不倫現場を見てしまったんです。', 'Sehari sebelumnya saya memergoki suami saya selingkuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', 'vocabulary', '本能', '本能', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Kemampuan yang awalnya Anda gunakan adalah naluri. Hewan mempunyai banyak hal karena mereka tidak pandai belajar. Mereka harus mulai mengenal mereka sejak awal.', 'Kemampuan yang awalnya Anda gunakan adalah naluri. Hewan mempunyai banyak hal karena mereka tidak pandai belajar. Mereka harus mulai mengenal mereka sejak awal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', 'Naluri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', 'ほんのう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', '動物は本能的に火をおそれるが、コウイチは例外だった。', 'Hewan secara naluriah takut terhadap api, tetapi Koichi adalah pengecualian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', 'いつも、生まれもった本能のおももくままにできるだけしたがうようにしています。', 'Saya selalu berusaha mengandalkan naluri bawaan saya sebanyak mungkin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ee376b6-25fc-489a-b5b5-ca4c929541f7', '熊は、動物の本能で危険を察知した。', 'Beruang itu merasakan bahaya dengan naluri binatangnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f0170faf-2caf-4b68-8001-4761b9edd3fd', 'vocabulary', '昨年', '昨年', 3, '8f7a3b0c-1d2e-9f4a-5b6c-7d8e9f0a1b2c', 'Tahun kemarin sebenarnya adalah tahun lalu. Kalau begitu, hari ini pasti Tahun Baru!', 'Tahun kemarin sebenarnya adalah tahun lalu. Kalau begitu, hari ini pasti Tahun Baru!') ON CONFLICT (id) DO NOTHING;
