INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0170faf-2caf-4b68-8001-4761b9edd3fd', 'この二十四時間スーパーは、昨年オープンしました。', 'Supermarket 24 jam ini dibuka tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0170faf-2caf-4b68-8001-4761b9edd3fd', '昨年は旅行でグアムに行きました。', 'Saya melakukan perjalanan ke Guam tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0170faf-2caf-4b68-8001-4761b9edd3fd', '昨年、医者から中性しぼうのあたいが高いと言われちゃったんですよ。', 'Tahun lalu, dokter saya memberi tahu saya bahwa saya mempunyai kadar trigliserida yang tinggi.') ON CONFLICT DO NOTHING;
