INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5210c7b5-e8ec-4105-ac60-856fc5c4b441', 'この人参スープには失望しました。', 'Saya kecewa dengan sup wortel ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5210c7b5-e8ec-4105-ac60-856fc5c4b441', '酒好きの王様に、人参リキュールをプレゼントしたが、よろこばれなかった。', 'Saya menghadiahkan minuman keras wortel kepada Raja, yang menyukai alkohol, tetapi dia tidak menyukainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5210c7b5-e8ec-4105-ac60-856fc5c4b441', 'お願いします。何でも食べるので、人参だけは勘弁してください。', 'Silakan. Saya akan makan yang lainnya, hanya saja bukan wortelnya. Silakan.') ON CONFLICT DO NOTHING;
