INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('5210c7b5-e8ec-4105-ac60-856fc5c4b441', 'e0b951a4-99c8-4891-a753-481faba9c6bb') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('db10b830-13e6-4da7-b439-992b2c164f92', 'radical', '[zombie]', 'zombie', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Radikal ini memiliki sosok yang mengulurkan kedua tangannya ke arah Anda dengan sedikit kotoran di kepalanya. Ini adalah zombie, dan dia pasti baru saja keluar dari kubur jika dilihat dari penampilannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('db10b830-13e6-4da7-b439-992b2c164f92', 'Zombi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('85fe042b-ea3d-4040-9b0d-36ec27a6432a', 'radical', '辛', 'spicy', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda berdiri di atas salib. Mengapa? Karena Anda makan sesuatu yang sangat pedas sehingga membuat Anda memohon belas kasihan Yesus. Anda perlu menyelamatkan mulut Anda dari api pedas. Untuk memastikan dia mendengar Anda, Anda berdiri di salib terdekat. Pastikan untuk merasakan betapa pedasnya ini di mulut Anda untuk mengingatnya dengan lebih baik!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('85fe042b-ea3d-4040-9b0d-36ec27a6432a', 'Pedas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3f6d9dbc-c380-4fb0-8d73-987990c40a37', 'radical', '面', 'face', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda memiliki daun, mulut, dan mata. Itu semua adalah hal yang akan Anda temukan di wajah! Tunggu, tidak ada sehelai daun pun yang tumbuh di wajahmu? Huh... nah bayangkan saja kamu punya wajah manusia normal dengan daun di suatu tempat ya spinners.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3f6d9dbc-c380-4fb0-8d73-987990c40a37', 'Wajah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8883b43c-f918-4963-a5bc-34a98f0af43f', 'radical', '巳', 'snake', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ada dua cara untuk mengingat yang satu ini. Pertama, Anda dapat melihat ini dan melihat bahwa itu adalah ular yang melingkar. Atau kalau mau, bisa dibayangkan sebagai kepala ular dengan wajah menghadap ke kanan (lihat mulutnya yang terbuka?). Kami mungkin menggunakan keduanya saat mempelajari kanji, namun untuk saat ini Anda dapat memilih salah satu yang paling sesuai dengan gaya hafalan Anda. Pastikan Anda menjadi ular ketika Anda melihat radikal ini.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8883b43c-f918-4963-a5bc-34a98f0af43f', 'Ular', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9ecf2ab4-7aa0-4fdb-83ac-0d4562841e54', 'radical', '非', 'criminal', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda pikir Anda melihat beberapa kaki di balik jeruji itu. Siapa yang dipenjara? Hanya penjahat. Penjahat ini cukup tinggi, karena Anda hanya melihat kakinya di belakang sana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9ecf2ab4-7aa0-4fdb-83ac-0d4562841e54', 'Kriminal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('31e60333-d359-41eb-b164-5bac3a7df4ae', 'radical', '壴', 'drum', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Radikal ini terdiri dari samurai dan kacang. Samurai biasa memasukkan kacang ke dalam drum sehingga mereka bisa mengetuk dan mengocoknya untuk menimbulkan suara. Dapatkah Anda membayangkan menggoyangkan dan mengetuk drum radikal ini?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('31e60333-d359-41eb-b164-5bac3a7df4ae', 'gendang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0359d990-2b31-44c9-8ae6-57fe545f9f67', 'radical', '楽', 'comfort', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Radikal ini sama dengan kanji. Artinya kenyamanan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0359d990-2b31-44c9-8ae6-57fe545f9f67', 'Kenyamanan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ca8526c2-092b-4e51-8071-9457b437e22e', 'radical', '果', 'fruit', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Semuanya tentang beras di Jepang dan Tiongkok kuno. Jadi padi yang ada di pohon itu bukanlah nasi, tentu saja itu adalah makanan yang lain. Itu buah!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ca8526c2-092b-4e51-8071-9457b437e22e', 'Buah', true) ON CONFLICT DO NOTHING;
