INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', 'vocabulary', '悲しい', '悲しい', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ini adalah kanji tunggal dengan しい di akhir, jadi kamu tahu itu kata sifat. Apa bentuk kata sifat dari sedih? Ini menyedihkan, menyedihkan.', 'Ini adalah kanji tunggal dengan しい di akhir, jadi kamu tahu itu kata sifat. Apa bentuk kata sifat dari sedih? Ini menyedihkan, menyedihkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', 'Sedih', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', 'かなしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', 'それは悲しすぎるね。', 'Itu terlalu menyedihkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', '悲しいけど、今ので運を使い切ってしまった気がする。', 'Sedihnya, aku merasa seperti aku baru saja menggunakan seluruh keberuntunganku untuk itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a6feaf1-8fde-4e8f-92a3-ba4c999502b3', '桃ちゃんが悲しい気持ちの時は、お父さんもお母さんも辛い気持ちになってしまうのよ。', 'Saat kamu merasa sedih, Momo, baik ayahmu maupun aku sendiri tidak bahagia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'vocabulary', '悲しむ', '悲しむ', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya sedih dan kata kerja ini bersifat transitif, jadi artinya sedih terhadap suatu hal. Huu huu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya sedih dan kata kerja ini bersifat transitif, jadi artinya sedih terhadap suatu hal. Huu huu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'Menjadi Sedih Tentang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'To Be Saddened By', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'かなしむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'かの女は失れんしてとても悲しんでいます。', 'Dia dicampakkan dan dia sangat sedih karenanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', '人間だけではなく、動物も仲間の死を悲しみます。', 'Hewan, seperti halnya manusia, berduka atas kematian teman-temannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb364af8-5296-4911-a8db-a0ac4836dcbb', 'そう悲しむなって。お前の日本語は今はそれで十分だよ。ただ、勉強することを投げ出さずに、少しずつ上手くなればいいさ。', 'Jangan sedih. Bahasa Jepang Anda sudah cukup baik untuk saat ini. Jangan berhenti belajar dan Anda akan meningkat sedikit demi sedikit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'vocabulary', '係わる', '係わる', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda tahu bahwa kanji berarti koneksi. Ini adalah kata kerja, jadi salah satu maknanya adalah dihubungkan dengan. Ada banyak cara lain untuk mengatakan hal ini juga. Kata ini memiliki fitur yang sedikit lengkap. Bisa dibilang terlibat atau bahkan terpengaruh. Pada dasarnya hal-hal yang ada hubungannya dengan keterhubungan dengan sesuatu yang lain.', 'Anda tahu bahwa kanji berarti koneksi. Ini adalah kata kerja, jadi salah satu maknanya adalah dihubungkan dengan. Ada banyak cara lain untuk mengatakan hal ini juga. Kata ini memiliki fitur yang sedikit lengkap. Bisa dibilang terlibat atau bahkan terpengaruh. Pada dasarnya hal-hal yang ada hubungannya dengan keterhubungan dengan sesuatu yang lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'Untuk Terlibat Dengan', true) ON CONFLICT DO NOTHING;
