INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'かかわる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'ビエトがやばいそしきと係わっているのは知っているけど、そのはんざいに係わっていたとはやっぱり思えないんだよな。', 'Saya tahu Viet terlibat dengan organisasi berbahaya, tapi menurut saya dia masih tidak ada hubungannya dengan kejahatan tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'あのれん中には係わらない方がいいよ。', 'Jangan terlibat dengan orang-orang seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bcac39d8-9d70-4a17-b287-227fab769844', 'もし毒抜きをせずに河豚を食べたら、命に係わりますよ。', 'Jika Anda makan ikan buntal tanpa mengeluarkan racunnya, itu adalah masalah hidup dan mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', 'vocabulary', '危険', '危険', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sesuatu yang berbahaya dan berisiko mungkin cukup berisiko, berbahaya, dan tidak aman.', 'Sesuatu yang berbahaya dan berisiko mungkin cukup berisiko, berbahaya, dan tidak aman.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', 'Berisiko', true) ON CONFLICT DO NOTHING;
