INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', 'きけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', 'まだ危険なじょうきょうだが、回ふくの希望はある。', 'Situasinya masih berisiko, namun masih ada harapan untuk kesembuhannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', '駅ではよく、「危険ですから黄色い線の内がわまでお下がりください」というアナウンスが流れています。', 'Di stasiun-stasiun, sering kali ada pengumuman yang berbunyi, "Ini tidak aman, jadi harap tetap berada di belakang garis kuning."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f4c210c-cb6d-4f76-b0df-b4cbf2ae2ce3', '我が社が現在債務不履行の危険性に瀕しているのは真実だが、リスクを覚悟のうえで、信頼に基づいて行動し続けるしかないと思うんだ。', 'Memang benar bahwa perusahaan kita berisiko gagal bayar atas pinjamannya, namun saya yakin kita harus tetap mengambil risiko dan bertindak berdasarkan keyakinan kita.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', 'vocabulary', '危ない', '危ない', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat berbahaya? Itu berbahaya.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat berbahaya? Itu berbahaya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', 'Berbahaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', 'Risky', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', 'あぶない', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', '危ないから、車に荷物をつむのは力の強いビエトにやってもらおう。', 'Itu berbahaya, jadi serahkan saja memuat bagasi ke dalam mobil kepada Viet, siapa yang kuat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', '四つ葉のクローバーを見つけたら幸運がおとずれるって言うけど、ぎゃくに危ない目にあっちゃったよ。', 'Katanya kalau kamu menemukan semanggi berdaun empat, kamu akan mendapat keberuntungan, tapi aku malah berada dalam situasi berbahaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86f6859a-55ac-45a3-9792-c82a0d47d0e1', '危ない会社のこんなに危ない計画に巻き込まれることに、誰も反対しなかったなんて信じられないよ！', 'Saya tidak percaya tidak ada seorang pun yang menentang untuk terlibat dalam rencana berisiko dari perusahaan berisiko seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', 'vocabulary', '取る', '取る', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengambil, jadi versi verbanya adalah mengambil sesuatu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengambil, jadi versi verbanya adalah mengambil sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', 'Untuk Mengambil', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', 'To Take Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', 'とる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', '運転めんきょ証がやっと取れました！', 'Saya akhirnya mendapatkan SIM saya!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', 'たなからマグカップを取ってくれない？', 'Bisakah kamu mengambilkan mug dari rak untukku?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1c1eea9-f47d-4ed7-8875-cde10f6eb98a', '私がこの行動の責任はすべて取ります。本当にごめんなさい。', 'Saya bertanggung jawab penuh atas tindakan saya. Saya benar-benar minta maaf.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'vocabulary', '喜ぶ', '喜ぶ', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bersukacita, jadi versi vocab verbanya adalah bersukacita. Meskipun menjadi bahagia mungkin terdengar sedikit lebih alami.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bersukacita, jadi versi vocab verbanya adalah bersukacita. Meskipun menjadi bahagia mungkin terdengar sedikit lebih alami.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'Untuk Bersukacita', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'To Become Happy', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'To Be Glad', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'よろこぶ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'やっとラケットの真ん中にボールを当てることができて、息子はとても喜んでいました。', 'Anak saya sangat senang ketika akhirnya dia memukul bola dengan bagian tengah raket.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', 'うちの母、初めて白がぞめをしたんだけど、十才はわか返って見えるって言って、本人はすごく喜んでるよ。', 'Ibuku mengecat ubannya untuk pertama kalinya, dan sekarang menurutnya dia terlihat setidaknya sepuluh tahun lebih muda, jadi dia sangat gembira.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1cf089ba-ec2d-4fd4-bb2c-1cff22de531c', '日本語を勉強することがあなたの人生で唯一の喜びだと聞いて、私達はとても嬉しく思っています。喜んでアドバイスするので、質問があればいつでも聞いてくださいね。', 'Kami sangat senang mendengar bahwa belajar bahasa Jepang adalah satu-satunya kebahagiaan dalam hidup Anda. Kami akan dengan senang hati menawarkan beberapa tips kepada Anda, jadi jangan ragu untuk mengajukan pertanyaan apa pun kepada kami kapan saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f7c176da-933e-4fc3-91dc-ca3e6a98fb8d', 'vocabulary', '公園', '公園', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Taman umum adalah taman yang bersifat umum. Itu adalah taman umum.', 'Taman umum adalah taman yang bersifat umum. Itu adalah taman umum.') ON CONFLICT (id) DO NOTHING;
