INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7c176da-933e-4fc3-91dc-ca3e6a98fb8d', 'この通りを真っ直ぐ行くと、公園があります。', 'Jika Anda lurus ke jalan ini, ada sebuah taman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7c176da-933e-4fc3-91dc-ca3e6a98fb8d', '公園ですなあそびをしていたら、手が真っ黒になってしまった。', 'Saya sedang bermain pasir di taman umum dan tangan saya berubah menjadi hitam seperti batu bara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7c176da-933e-4fc3-91dc-ca3e6a98fb8d', '「フグと一緒にいった公園、どうだった？」「正直今までに行った公園の中で一番楽しかったよ。」', '"Jadi, bagaimana taman yang kamu dan Fugu kunjungi?" "Itu sebenarnya taman paling menyenangkan yang pernah kami kunjungi."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf1968b5-63aa-4413-86b7-559b4f48b48b', 'vocabulary', '園', '園', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
