INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('34767b0f-f19c-4422-873b-0c1c0a763878', 'るす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34767b0f-f19c-4422-873b-0c1c0a763878', '母は買い物に出かけているので、私と妹が留守番をしています。', 'Ibuku sedang berbelanja, jadi aku dan adikku sedang menjaga rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34767b0f-f19c-4422-873b-0c1c0a763878', 'コウイチの家にいってみたが、留守でした。', 'Saya mengunjungi rumah Koichi, tapi dia tidak ada di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34767b0f-f19c-4422-873b-0c1c0a763878', '私の夫は出張で留守がちです。夫が留守にしてる間、とても寂しいので、一日少なくとも五回は電話をします。', 'Suamiku selalu jauh dari rumah karena perjalanan bisnisnya. Saya menjadi sangat kesepian jadi saya meneleponnya setidaknya lima kali sehari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'vocabulary', '不幸', '不幸', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ketika Anda tidak mempunyai kebahagiaan, Anda mempunyai ketidakbahagiaan, kemalangan dan kesengsaraan. Ini juga bisa berarti kematian, biasanya pada anggota keluarga.', 'Ketika Anda tidak mempunyai kebahagiaan, Anda mempunyai ketidakbahagiaan, kemalangan dan kesengsaraan. Ini juga bisa berarti kematian, biasanya pada anggota keluarga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'Ketidakbahagiaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'Misfortune', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'Misery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'Death', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'ふこう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', 'まるで不幸のどん底のようにいるような顔をしてるけど、大丈夫？', 'Anda tampak seperti sedang berada dalam kemalangan. Apakah kamu baik-baik saja?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', '家族に不幸があったので、明日、明後日会社を休ませてください。', 'Ada kematian di keluarga saya. Bisakah saya mengambil libur besok dan lusa?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68dc6225-067a-4164-ac84-60b8c61865aa', '不幸は仲間を好むってよく言うけど、それって私があなたと付き合っている理由をうまく説明しているよね。', 'Mereka bilang kesengsaraan suka ditemani, itulah sebabnya aku berkencan denganmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', 'vocabulary', '幸せ', '幸せ', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ini adalah versi kata benda dari kanji 幸. Kanji berarti kebahagiaan dan kosakatanya berarti kebahagiaan.', 'Ini adalah versi kata benda dari kanji 幸. Kanji berarti kebahagiaan dan kosakatanya berarti kebahagiaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', 'Kebahagiaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', 'しあわせ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', '末ながくお幸せにね。', 'Saya berharap Anda bahagia selama bertahun-tahun yang akan datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', 'ビエトは、うらないしから今年中に幸せがおとずれると言われました。', 'Seorang peramal memberi tahu Viet bahwa kebahagiaan akan datang kepadanya dalam tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0de14a3-8580-44dd-a596-31e536674d7c', '「私はお金で幸せは買えると思います。何故なら、私は花火を見ていると幸せな気持ちになるからです。もし私が大金持ちだったら、毎日花火を楽しんでずっと幸せな気持ちでいられることができます。」彼女は幸せそうな口調でそう言った。', '“Menurutku uang bisa membeli kebahagiaan karena menonton kembang api membuatku bahagia. Kalau aku punya banyak uang, aku bisa menikmati kembang api setiap hari dan merasa bahagia sepanjang waktu,” ujarnya bahagia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'vocabulary', '政治', '政治', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Jika Anda ingin menyembuhkan pemerintah, Anda harus terjun ke dunia politik. Harus bergabung dengan mereka untuk memperbaikinya... tapi bisakah Anda bertahan selama itu tanpa merusak diri Anda sendiri?', 'Jika Anda ingin menyembuhkan pemerintah, Anda harus terjun ke dunia politik. Harus bergabung dengan mereka untuk memperbaikinya... tapi bisakah Anda bertahan selama itu tanpa merusak diri Anda sendiri?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'Politik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'Government', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'せいじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'ついに、大学で政治を学ぶという私の長年の希望がかないました。', 'Harapan saya sejak lama, yaitu kuliah politik di perguruan tinggi, akhirnya terwujud.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'サーモンの政治に対する考えはとても保守的です。', 'Sikap Salmon terhadap pemerintah sangat konservatif.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d4a2ba7-fd86-4032-9e9f-0be15f397b11', 'ワシントンDCで起きている政治騒動なんてお構いなしに、トーフグは共和党と民主党の両地域で雇用を生み出している。', 'Menyadari gejolak politik yang terjadi di Washington D.C., Tofugu telah menciptakan lapangan kerja bagi wilayah yang didominasi Partai Republik dan Demokrat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e95066b3-8831-45e7-a460-4b7119d44f79', 'vocabulary', '治す', '治す', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. 
