INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95066b3-8831-45e7-a460-4b7119d44f79', '生理つうを治すにはアスピリンを飲むのがいいよ。', 'Anda harus minum aspirin untuk meredakan nyeri haid Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95066b3-8831-45e7-a460-4b7119d44f79', 'ハーブりょう法でがんを治すことについて、どう思われますか？', 'Apa pendapat Anda tentang menyembuhkan kanker dengan menggunakan obat herbal?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95066b3-8831-45e7-a460-4b7119d44f79', 'ビエトだけが、コウイチが怪我や病気を治すことができる不思議な力を持っていることを知っている。', 'Hanya Viet yang tahu kalau Koichi mempunyai kekuatan aneh yang bisa menyembuhkan luka dan penyakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c7e2c0a-8881-41bc-946d-eb21b6c3ddad', 'vocabulary', '全治', '全治', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Semua sembuh! Itu berarti Anda telah sembuh total! Anda sudah sembuh!', 'Semua sembuh! Itu berarti Anda telah sembuh total! Anda sudah sembuh!') ON CONFLICT (id) DO NOTHING;
