INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8c7e2c0a-8881-41bc-946d-eb21b6c3ddad', 'ぜんじ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c7e2c0a-8881-41bc-946d-eb21b6c3ddad', '医者には、全治するのは難しいと思う、多分後いしょうが残るだろうって言われました。', 'Dokter memberitahuku bahwa sulit untuk pulih sepenuhnya dan mungkin masih ada beberapa kerusakan permanen yang tersisa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c7e2c0a-8881-41bc-946d-eb21b6c3ddad', '交通きそくをきちんと守っていたのに、トラックにはねられて全治一年の大ケガをしました。', 'Meskipun saya mematuhi peraturan lalu lintas dengan ketat, saya ditabrak truk dan mengalami cedera parah yang membutuhkan waktu satu tahun untuk pulih sepenuhnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c7e2c0a-8881-41bc-946d-eb21b6c3ddad', 'ビエトが暴力団抗争で全治六カ月の重傷を負った時、コウイチは特殊治癒能力を使ってその傷を治した。', 'Ketika Viet menderita luka parah akibat perang geng yang biasanya membutuhkan waktu enam bulan untuk sembuh total, Koichi menyembuhkannya dengan kekuatan penyembuhan spesialnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'vocabulary', '不治', '不治', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ketika Anda tidak dapat menyembuhkan sesuatu, ini adalah masalah yang tidak dapat disembuhkan.', 'Ketika Anda tidak dapat menyembuhkan sesuatu, ini adalah masalah yang tidak dapat disembuhkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'Tidak dapat disembuhkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'Incurable', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'ふじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'ふち', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', '不治のがんで、よ命三ヶ月だとせん告されました。', 'Saya didiagnosis mengidap kanker yang tidak dapat disembuhkan dan saya diberi waktu tiga bulan untuk hidup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', '私の息子は、不治ののうしっかんと戦っています。', 'Anak saya sedang berjuang melawan kelainan otak yang tidak dapat disembuhkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941636a6-cf6d-4e45-adf7-5f4358cedb08', 'コウイチは一度不治の病に倒れ、「俺たちは必ず、また会えるよ」とビエトに言い残し亡くなったのですが、言葉通り次の日にはオフィスに出勤し、以前と全く同じように業務をこなしました。', 'Ketika Koichi jatuh sakit parah dan meninggal, kata-kata terakhirnya kepada Viet adalah, "Kita akan bertemu lagi." Sesuai dengan kata-katanya, dia kembali ke kantor keesokan harinya dan melakukan segala sesuatunya sama seperti sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', 'vocabulary', '明治', '明治', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ini adalah era Bright Rule! Jika ini tidak masuk akal, jangan khawatir. Lebih fokus pada bacaannya yaitu めいじ. Kedengarannya familier? Ini adalah Era Meiji atau Kaisar Meiji yang terkenal. Jika Anda belum mengetahuinya, pertimbangkan untuk membaca, ini sejarah yang menarik!', 'Ini adalah era Bright Rule! Jika ini tidak masuk akal, jangan khawatir. Lebih fokus pada bacaannya yaitu めいじ. Kedengarannya familier? Ini adalah Era Meiji atau Kaisar Meiji yang terkenal. Jika Anda belum mengetahuinya, pertimbangkan untuk membaca, ini sejarah yang menarik!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', 'Era Meiji', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', 'Meiji Emperor', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', 'Meiji', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', 'めいじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', '明治生まれのそ母は、生前は仏教の教えをちゅう実に守っていました。', 'Nenek saya lahir di era Meiji, dan dia dengan setia mempraktikkan ajaran Buddha ketika dia masih hidup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', '明治い新についてのろん文を書いています。', 'Saya sedang menulis makalah tentang Restorasi Meiji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('50ccbd46-37bb-4784-9338-f4741be9aa09', '明治時代の生活を描いたドラマを見ているんですが、当時は一万円が大金だったということに驚きました。', 'Saya sedang menonton serial drama tentang kehidupan di zaman Meiji dan saya terkejut karena sepuluh ribu yen adalah jumlah uang yang besar pada saat itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', 'vocabulary', '留学', '留学', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda menahan studi Anda dan membawanya ke tempat asing. Tempat asing itu membuatmu belajar di luar negeri.', 'Anda menahan studi Anda dan membawanya ke tempat asing. Tempat asing itu membuatmu belajar di luar negeri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', 'Belajar di Luar Negeri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', 'Studying Abroad', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', 'りゅうがく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', '「兄は親の言いつけを守らず、留学してしまいました。」「留学先はどこなんですか？」「アメリカです。」', '“Kakak laki-lakiku tidak menuruti perintah orang tua kami dan pergi belajar ke luar negeri.” “Di mana tujuan studinya di luar negeri?” "Itu di AS."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', '留学先で、日本語を自然にしゃべる練習をたくさんしました。', 'Ketika saya belajar di luar negeri, saya banyak berlatih berbicara bahasa Jepang secara alami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ad424b8-97f1-4f30-872e-95a7cc606724', '約束を来週の日曜日に変更していただけませんか？土曜日に、留学の書類を取りに日本総領事館に行かなければならなくなってしまって。', 'Bisakah Anda menjadwal ulang janji temu saya untuk hari Minggu depan? Pada hari Sabtu saya harus pergi ke Konsulat Jenderal Jepang untuk mengambil beberapa dokumen studi di luar negeri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81a7e437-89d3-433a-8c06-859465938494', 'vocabulary', '幸福', '幸福', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Dengan sedikit keberuntungan dan kebahagiaan, Anda bisa mencapai kebahagiaan, meskipun hal itu tidak perlu dikatakan lagi.', 'Dengan sedikit keberuntungan dan kebahagiaan, Anda bisa mencapai kebahagiaan, meskipun hal itu tidak perlu dikatakan lagi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81a7e437-89d3-433a-8c06-859465938494', 'Kebahagiaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('81a7e437-89d3-433a-8c06-859465938494', 'こうふく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a7e437-89d3-433a-8c06-859465938494', '幸福の科学というしゅう教団体について調べてみました。', 'Saya mencari beberapa informasi tentang kelompok agama bernama Happy Science.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a7e437-89d3-433a-8c06-859465938494', 'トーフグに幸福をもたらすために、コウイチはじゅう業員全員に幸福のフグのおまもりを一万ドルで買わせようとしました。', 'Untuk membawa kebahagiaan bagi Tofugu, Koichi mencoba membuat seluruh karyawannya membeli jimat fugu kebahagiaan seharga $10.000 masing-masing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a7e437-89d3-433a-8c06-859465938494', '彼女は幸運の星のもとに生まれたため、幸福すぎて毎日涙が止まらないんだよ。', 'Dia dilahirkan di bawah bintang keberuntungan dan dia memiliki begitu banyak kebahagiaan dalam hidupnya sehingga dia tidak bisa menahan tangis setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83131b22-c136-4928-af73-a5afd173811a', 'vocabulary', '笑う', '笑う', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya tertawa jadi versi vocab verbanya adalah tertawa.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya tertawa jadi versi vocab verbanya adalah tertawa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('83131b22-c136-4928-af73-a5afd173811a', 'Tertawa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('83131b22-c136-4928-af73-a5afd173811a', 'わらう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83131b22-c136-4928-af73-a5afd173811a', 'その冒険家は、後世に名を残したいんだと笑って言った。', 'Petualang itu tertawa dan berkata dia ingin mewariskan namanya kepada anak cucu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83131b22-c136-4928-af73-a5afd173811a', 'クリステンは、笑いながらコウイチに謝ざいを要求しました。', 'Kristen menuntut permintaan maaf dari Koichi sambil tertawa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83131b22-c136-4928-af73-a5afd173811a', '「昨夜、フグとデートをしたの。」「どうだった？」「楽しかった。めちゃくちゃ笑ったわ。」', '"Aku berkencan dengan Fugu tadi malam." "Bagaimana hasilnya?" "Menyenangkan. Saya banyak tertawa."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'vocabulary', '笑顔', '笑顔', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Wajah yang tertawa adalah wajah yang tersenyum (atau sekadar senyuman!). 笑顔 ada di mana-mana!', 'Wajah yang tertawa adalah wajah yang tersenyum (atau sekadar senyuman!). 笑顔 ada di mana-mana!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'Tersenyumlah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'Smiling Face', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'えがお', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'あの笑顔がコウイチのせい実さを証明しているよね。', 'Wajah tersenyum itu membuktikan integritas Koichi, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'この国の王子は笑顔で国民を殺すとてもひどい男です。', 'Pangeran negeri ini adalah orang yang sangat mengerikan yang membunuh warganya sambil tersenyum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d43941a-bd20-4908-9aab-aac09afffa03', 'この笑顔の素敵な男は俺の連れで、コウイチっていうの。', 'Pria cantik dan tersenyum yang bersamaku ini adalah Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae9c178a-d2fd-499d-9485-d77b0b0149fe', 'vocabulary', 'ゴミ箱', 'ゴミ箱', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'ゴミ berarti "sampah." Tambahkan kotak ke dalamnya dan Anda memiliki kotak sampah alias tempat sampah atau tempat sampah.', 'ゴミ berarti "sampah." Tambahkan kotak ke dalamnya dan Anda memiliki kotak sampah alias tempat sampah atau tempat sampah.') ON CONFLICT (id) DO NOTHING;
