INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae9c178a-d2fd-499d-9485-d77b0b0149fe', 'ゴミ箱に、新せんな箱づめの魚がすてられていました。', 'Ada kotak ikan segar di tempat sampah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae9c178a-d2fd-499d-9485-d77b0b0149fe', 'そのゴミ箱の中にけっこん指輪があるかもしれないというかすかな希望がありました。', 'Saya sangat berharap untuk menemukan cincin kawin di tempat sampah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae9c178a-d2fd-499d-9485-d77b0b0149fe', 'ゴミ箱のゴミを捨てる時のあなたってとってもセクシーだと思うのよね。だから、ちょっと私のためにゴミ箱のゴミを捨ててくれないかな？', 'Menurutku kamu sangat seksi saat mengosongkan tong sampah— bisakah kamu mengosongkan tong sampah untukku?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5281e418-ae38-4f30-8672-676addb25618', 'vocabulary', '箱', '箱', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
