INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5397b2dc-11c9-4e46-b5f3-0316ced4eab1', 'ぜんめん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5397b2dc-11c9-4e46-b5f3-0316ced4eab1', '前面も後面も両方とも緑色の箱をさがしてください。', 'Silakan temukan kotak yang memiliki warna hijau di sisi depan dan belakang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5397b2dc-11c9-4e46-b5f3-0316ced4eab1', '手紙や小包を送る時には、いつも前面にトーフグのステッカーを貼ります。', 'Setiap kali kami mengirim surat atau paket, kami menempelkan stiker Tofugu di depannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5397b2dc-11c9-4e46-b5f3-0316ced4eab1', 'この時、ビエトは「タコスの日」を祭日にしようという運動の前面に立つようになった。', 'Saat ini, Viet menjadi garda depan dalam gerakan menjadikan Hari Taco sebagai hari libur nasional.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', 'vocabulary', '地面', '地面', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Permukaan tanah/bumi adalah permukaan yang membentuk tanah atau permukaan bumi.', 'Permukaan tanah/bumi adalah permukaan yang membentuk tanah atau permukaan bumi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', 'Tanah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', 'Earth''s Surface', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', 'じめん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', '海の中じゃなくて地面の中に住めたらいいのに、とフグは言いました。', 'Fugu mengatakan bahwa dia lebih suka tinggal di bawah tanah daripada di bawah air.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', '家の前の庭は草が生えていないので、夏の間は地面がとても熱くなります。', 'Halaman depan kami tidak ditumbuhi rumput, sehingga permukaan bumi menjadi sangat panas saat musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bb10833-be45-42dc-af8e-78fc5d01aad6', 'コウイチはフグを優しく撫でてから、地面に降ろしてあげました。', 'Koichi dengan lembut membelai Fugu dan membaringkannya di tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'vocabulary', '外面', '外面', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Wajah luar dari sesuatu adalah bagian luar dari benda itu.', 'Wajah luar dari sesuatu adalah bagian luar dari benda itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'Eksterior', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'Surface', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'Outside', false) ON CONFLICT DO NOTHING;
