INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'そとづら', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', 'ビエトは外面はいい人そうですが、実はとてもおそろしい一面を持っています。', 'Di permukaan, Viet terlihat seperti pria baik, namun sebenarnya dia memiliki sisi yang menakutkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', '外面だけがいい男性とけっこんし、外面は立ぱだけど内面はボロボロの中古住たくを買ってしまい、今とても苦労しているんです。', 'Saya menikah dengan seorang pria yang bagaikan bidadari di luar dan bagaikan iblis di rumahnya, dan kami membeli sebuah rumah tua yang eksteriornya bagus, namun interiornya sudah usang, jadi saya mengalami masa-masa sulit saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('412b98a9-422d-4adf-8817-186cda75cedc', '彼の外面に騙されない方がいいですよ。私がインストラクターのことが嫌いだったのは、上司にはいい顔をして陰で後輩のことを小突き回していたからです。', 'Anda tidak boleh tertipu dengan penampilan luarnya. Saya benci instruktur saya karena dia menunjukkan wajah manis kepada atasannya sementara dia menindas bawahan, termasuk saya, di belakang mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3fc4a581-889b-4af2-bc98-809c690c81b7', 'vocabulary', '画面', '画面', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Permukaan suatu gambar adalah layar. Bayangkan saja layar komputer Anda. Di permukaannya ada gambar, kan? Ia kebetulan bergerak sepanjang waktu, namun tetap saja berupa layar!', 'Permukaan suatu gambar adalah layar. Bayangkan saja layar komputer Anda. Di permukaannya ada gambar, kan? Ia kebetulan bergerak sepanjang waktu, namun tetap saja berupa layar!') ON CONFLICT (id) DO NOTHING;
