INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70f88feb-79eb-425d-87af-adda283bf8d0', 'あなたに、面と向かってお話したいことがあります。ご予定は、いつが空いていますか？', 'Ada yang ingin kubicarakan denganmu secara tatap muka. Kapan Anda tersedia?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0622ec25-3024-4aa7-948b-8468268c3460', 'vocabulary', '面白い', '面白い', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Wajah benda ini putih sekali! Mengapa warnanya sangat putih dibandingkan yang lainnya? Ini menarik sekali...', 'Wajah benda ini putih sekali! Mengapa warnanya sangat putih dibandingkan yang lainnya? Ini menarik sekali...') ON CONFLICT (id) DO NOTHING;
