INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ece3b741-56a0-40bd-86c6-cd4368a1c393', '日本の自動車のハンドルは通常右側にあります。', 'Setir mobil Jepang biasanya berada di sisi kanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ece3b741-56a0-40bd-86c6-cd4368a1c393', 'コウイチのつくえの右側の引き出しには、塩がたくさん入っています。', 'Ada banyak garam di laci sebelah kanan meja Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ece3b741-56a0-40bd-86c6-cd4368a1c393', '心霊写真を撮っちゃったの。ほら。この写真の右側に、その場にはいなかった幼い女の子が写ってるのよ。分かる？', 'Kami memotret hantu. Lihat. Ada seorang gadis kecil yang tidak ada di sebelah kanan gambar. Bisakah kamu melihatnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb196846-c61d-4d59-bf05-5fa12b872525', 'vocabulary', '左側', '左側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sisi kiri adalah sisi kiri. Sesederhana itu.', 'Sisi kiri adalah sisi kiri. Sesederhana itu.') ON CONFLICT (id) DO NOTHING;
