INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb196846-c61d-4d59-bf05-5fa12b872525', 'このエスカレーターでは、みんな左側に立っていますね。', 'Kurasa semua orang berdiri di sisi kiri eskalator ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb196846-c61d-4d59-bf05-5fa12b872525', '日本は、イギリスと同じで、車は左側通行ですよ。', 'Mereka mengemudi di sebelah kiri di Jepang sama seperti di Inggris.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb196846-c61d-4d59-bf05-5fa12b872525', '寝る時は、左側を下にして横になる方が好きです。', 'Saat tidur, saya lebih suka berbaring miring ke kiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bd81d21e-c358-42bf-a029-a3448eb561c0', 'vocabulary', '内側', '内側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sisi dalam adalah bagian dalam. Sedikit berlebihan tetapi sangat masuk akal.', 'Sisi dalam adalah bagian dalam. Sedikit berlebihan tetapi sangat masuk akal.') ON CONFLICT (id) DO NOTHING;
