INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd81d21e-c358-42bf-a029-a3448eb561c0', 'りそな銀行の内側で待っています。', 'Aku akan menunggumu di dalam Resona Bank.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd81d21e-c358-42bf-a029-a3448eb561c0', '右の内側のかかとにトゲがささったみたいです。', 'Sepertinya ada serpihan di tumit kanan bagian dalamku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd81d21e-c358-42bf-a029-a3448eb561c0', 'ゾンビを中に入れないために、金属製のシャッターを下ろして、内側から鍵を掛ける必要があります。', 'Kita perlu menurunkan penutup logam dan menguncinya dari dalam untuk menghalangi masuknya zombie.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e30ef5c9-45b1-498d-85c1-336fb391092a', 'vocabulary', '外側', '外側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sisi luar adalah bagian luar.', 'Sisi luar adalah bagian luar.') ON CONFLICT (id) DO NOTHING;
