INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30ef5c9-45b1-498d-85c1-336fb391092a', '外側に開くと思ったら、内側に開くドアだったんだね。', 'Saya pikir pintu ini terbuka ke luar, tapi sebenarnya terbuka ke dalam, saya kira.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30ef5c9-45b1-498d-85c1-336fb391092a', 'いつもは外側のポケットにかぎを入れておくんですけど...おかしいなぁ。', 'Biasanya saya menaruh kunci di saku luar....aneh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e30ef5c9-45b1-498d-85c1-336fb391092a', 'サーモンのフライを作ろうとしたんだけど、外側だけ焦げちゃって内側は血生臭いオレンジ色のままになっちゃった。油がちょっと熱すぎたのかも。', 'Saya mencoba menggoreng salmon, tetapi bagian luarnya gosong dan bagian dalamnya tetap berdarah dan berwarna oranye. Saya kira minyaknya mungkin terlalu panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b163b91-f1f7-47bc-93f4-9a84056b707d', 'vocabulary', '両側', '両側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kedua belah pihak adalah kedua belah pihak. Sisi mana? Kedua belah pihak.', 'Kedua belah pihak adalah kedua belah pihak. Sisi mana? Kedua belah pihak.') ON CONFLICT (id) DO NOTHING;
