INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b853bf4e-fa40-4063-9028-454a0f9efd14', 'vocabulary', '東側', '東側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sisi Timur adalah sisi Timur.', 'Sisi Timur adalah sisi Timur.') ON CONFLICT (id) DO NOTHING;
