INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f6b2750-151b-4920-b6d1-ab9e4af830d1', 'vocabulary', '西側', '西側', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sisi Barat dari sesuatu dikenal sebagai Sisi Barat atau Sisi Barat. Maaf, saya tidak punya cerita yang bisa sejalan dengan sisi Barat Anda.', 'Sisi Barat dari sesuatu dikenal sebagai Sisi Barat atau Sisi Barat. Maaf, saya tidak punya cerita yang bisa sejalan dengan sisi Barat Anda.') ON CONFLICT (id) DO NOTHING;
