INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6d5f4c4-d593-4af5-891f-fcb7dc22298b', 'しょう来は、原子エネルギーの勉強をしたいと思っています。', 'Di masa depan, saya rasa saya ingin mempelajari energi atom.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6d5f4c4-d593-4af5-891f-fcb7dc22298b', 'この原子の原子番号と原子記号は何だったっけ？', 'Berapakah nomor atom dan lambang atom atom tersebut?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6d5f4c4-d593-4af5-891f-fcb7dc22298b', '老朽化した原子力発電所は、多くの国々にとって悩みの種です。', 'Pembangkit listrik tenaga nuklir yang menua merupakan masalah bagi banyak negara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d3fa4b2f-23d9-474c-b905-6bbfbcebd91f', 'vocabulary', '原作', '原作', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Barang asli yang Anda buat adalah karya asli. Menurut saya, lebih baik memiliki yang asli daripada salinan.', 'Barang asli yang Anda buat adalah karya asli. Menurut saya, lebih baik memiliki yang asli daripada salinan.') ON CONFLICT (id) DO NOTHING;
