INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d3fa4b2f-23d9-474c-b905-6bbfbcebd91f', 'マンガが原作の映画は、原作の良さを失ってしまうことが多いです。', 'Film buku komik sering kali kehilangan cita rasa karya aslinya.') ON CONFLICT DO NOTHING;
