INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('93f28d06-f8d6-4b63-aca4-921b797d1fc8', 'vocabulary', '内因', '内因', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Penyebab dalam adalah penyebab internal. Penyebab internal biasanya merupakan penyebab yang paling buruk, jika Anda bertanya kepada saya.', 'Penyebab dalam adalah penyebab internal. Penyebab internal biasanya merupakan penyebab yang paling buruk, jika Anda bertanya kepada saya.') ON CONFLICT (id) DO NOTHING;
