INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb75764e-01a7-4fb9-9b59-7da264c1f44e', '下りの主因はおそらくさっき食べたソフトクリームです。', 'Penyebab utama diare saya mungkin adalah soft serve yang saya makan tadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb75764e-01a7-4fb9-9b59-7da264c1f44e', 'ニアミスの主因は、この電車がスピードを上げるべきではないタイミングで上げたことです。', 'Penyebab utama terjadinya nyaris celaka adalah kereta melaju padahal tidak seharusnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb75764e-01a7-4fb9-9b59-7da264c1f44e', '癌や自閉症など、多くの病気の主因は未だに分かっていません。', 'Penyebab utama dibalik berbagai kondisi seperti kanker dan autisme masih belum diketahui.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', 'vocabulary', '悪因悪果', '悪因悪果', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Hal-hal yang menyebabkan kejahatan adalah buah dari kejahatan. Ini adalah pepatah kecil yang bagus. Dalam bahasa Inggris, Anda mungkin mengatakannya sebagai kejahatan melahirkan kejahatan. Ingat itu.', 'Hal-hal yang menyebabkan kejahatan adalah buah dari kejahatan. Ini adalah pepatah kecil yang bagus. Dalam bahasa Inggris, Anda mungkin mengatakannya sebagai kejahatan melahirkan kejahatan. Ingat itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', 'Kejahatan Menghasilkan Kejahatan', true) ON CONFLICT DO NOTHING;
