INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', 'あくいんあっか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', '悪因悪果って言うだろ？当然のむくいだよ。', 'Mereka mengatakan “kejahatan menghasilkan kejahatan” bukan? Jadi mereka mendapat hukuman yang pantas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', '悪いことをしたら、悪因悪果で後々ひどい目にあうよ。', 'Jika Anda melakukan sesuatu yang buruk, Anda akan mendapat masalah di kemudian hari karena kejahatan menghasilkan kejahatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('732e0a06-4799-404a-be39-0dc478f9d66b', '聖書には、業について何て書いてあるんだっけ？悪因悪果とかだっけか？', 'Apa yang Alkitab katakan tentang karma? Apakah itu seperti “kejahatan menghasilkan kejahatan” atau semacamnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54e56deb-e8e0-4cf9-94f0-4bc66cb62540', 'vocabulary', '席', '席', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
