INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c647c5ac-f8ce-4ed1-be1e-f49084a316d5', 'にちじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c647c5ac-f8ce-4ed1-be1e-f49084a316d5', 'コウイチの日常の仕事がどんなものなのか知りたいです。', 'Saya ingin tahu seperti apa kehidupan kerja Koichi sehari-hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c647c5ac-f8ce-4ed1-be1e-f49084a316d5', '私の日常はとても平ぼんです。', 'Kehidupan sehari-hari saya sangat biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c647c5ac-f8ce-4ed1-be1e-f49084a316d5', '新しい言語を学ぶ際、まず始めに日常で一般的に使われる実用的な言葉から覚える方が効率的だ。', 'Saat Anda mempelajari bahasa baru, akan lebih efisien jika memulai dengan kata-kata praktis sehari-hari terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', 'vocabulary', '常識', '常識', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kecermatan yang normal adalah kearifan yang Anda lakukan setiap hari, tanpa berpikir. Semua hal yang Anda lakukan adalah hal yang masuk akal.', 'Kecermatan yang normal adalah kearifan yang Anda lakukan setiap hari, tanpa berpikir. Semua hal yang Anda lakukan adalah hal yang masuk akal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', 'Akal Sehat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', 'Common Knowledge', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', 'じょうしき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', '常識のある人たちばかりで、安心しました。', 'Saya lega bahwa kalian memiliki akal sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', '常識テストを受けてみたが、結果はさんざんだった。', 'Saya mengikuti tes pengetahuan umum, tetapi hasilnya buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c4de1d64-96f4-4ff1-9c67-3a5364e8067b', '常識は脇に置いて、少しだけ既存の考えに囚われずに考えてみませんか？', 'Bagaimana kalau mengesampingkan akal sehat dan berpikir di luar kebiasaan sejenak?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'vocabulary', '敗れる', '敗れる', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti kegagalan, tapi "gagal" tidak masuk akal. Namun, apa jadinya jika Anda mengalami kegagalan? Ya, Anda dikalahkan, dan Anda juga tidak berhasil. Jadi, kata kerjanya adalah dikalahkan dan tidak berhasil.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti kegagalan, tapi "gagal" tidak masuk akal. Namun, apa jadinya jika Anda mengalami kegagalan? Ya, Anda dikalahkan, dan Anda juga tidak berhasil. Jadi, kata kerjanya adalah dikalahkan dan tidak berhasil.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'Untuk Dikalahkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'To Be Unsuccessful', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'やぶれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'ブルージェイズは、レッドソックスに三対一で敗れました。', 'The Blue Jays kalah dalam pertandingan tersebut dari Red Socks dengan skor 1-3.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'みんなが予想していた通り、コウイチは今回ものど自まんコンテストで敗れてしまいました。', 'Seperti yang kita semua duga, Koichi kembali dikalahkan dalam kontes menyanyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8130dc2-e569-4aec-8575-b3b6c5993945', 'オリンピックの予選第一回戦で敗れた日本代表のアイスホッケーチームに、怒ってカレーを投げつけた男の話聞いた？', 'Pernahkah Anda mendengar bahwa seorang pria kesal dengan tim hoki es nasional Jepang ketika mereka dikalahkan di babak pertama pertandingan penyisihan Olimpiade dan melemparkan kari ke arah mereka?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', 'vocabulary', '失敗', '失敗', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kesalahan dan kegagalan, semuanya menjadi satu. Ini pasti merupakan salah satu kegagalan dan kesalahan besar yang Anda buat.', 'Kesalahan dan kegagalan, semuanya menjadi satu. Ini pasti merupakan salah satu kegagalan dan kesalahan besar yang Anda buat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', 'Kegagalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', 'Mistake', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', 'しっぱい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', 'こっちの選手はバントを失敗したと思ったら、今度はこっちの選手がとうるいに失敗したんだよ。', 'Ketika pemain ini gagal melakukan bunt, pemain lain tersebut ketahuan mencuri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', '失敗して後かいする方が、何もせずに後かいするよりマシだと思うんだ。', 'Saya pikir kegagalan masih lebih baik daripada tidak melakukan apa pun dan kemudian menyesali bahwa Anda bahkan tidak mencobanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae1577fd-42bc-4da2-b14e-68ef10f96a72', '正直言って、君が作ったこの映画は失敗作だね。でも、一度失敗したからといって、くよくよしてちゃ駄目だよ。誰かも、「成功とは、失敗から失敗へと熱意を失うことなく進んでいける能力である」って言ってただろ？', 'Sejujurnya, film yang Anda buat ini gagal. Namun, Anda tidak bisa membiarkan hal itu membuat Anda putus asa hanya karena Anda gagal sekali. Ada yang bilang kesuksesan adalah kemampuan untuk berpindah dari satu kegagalan ke kegagalan lainnya tanpa kehilangan semangat, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'vocabulary', '勝敗', '勝敗', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda telah menang dan Anda mengalami kegagalan. Ketika Anda membicarakan keduanya dalam satu kata, Anda menang atau kalah.', 'Anda telah menang dan Anda mengalami kegagalan. Ketika Anda membicarakan keduanya dalam satu kata, Anda menang atau kalah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'Kemenangan Atau Kekalahan', true) ON CONFLICT DO NOTHING;
