INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'Outcome', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'しょうはい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'その戦いの勝敗なら、一昨日の朝決まりましたよ。', 'Hasil pertandingan ditentukan pada pagi hari sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', 'コウイチのその一言が、勝敗の分かれ目になったんです。', 'Satu kata yang diucapkan Koichi membuat perbedaan antara kemenangan dan kekalahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af6805cd-900d-4c25-864e-baf58d5e061b', '私の両親はいつも、全力を尽くしさえすれば、勝敗は問題ではないと言っていたけれど、私はそれが好きじゃありませんでした。もちろん、私は勝敗をとても気にします。だって、ベストを尽くした後に負けるなんて、意味が無いじゃないですか。', 'Orang tuaku selalu mengatakan kepadaku bahwa tidak masalah aku menang atau kalah, selama aku berusaha sebaik mungkin, tapi aku tidak menyukainya. Tentu saja, saya sangat peduli dengan kemenangan dan kekalahan. Jika aku kalah setelah melakukan yang terbaik, maka tidak ada gunanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'vocabulary', '敗者', '敗者', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kegagalan seseorang (orang) adalah pihak yang kalah atau kalah.', 'Kegagalan seseorang (orang) adalah pihak yang kalah atau kalah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'Pecundang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'The Defeated', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'はいしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'まだ敗者ふっ活戦が残っていますよ。', 'Kami masih memiliki pertandingan hiburan tersisa bagi mereka yang kalah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'その歯医者は、生まれながらの敗者であった。', 'Dokter gigi itu dilahirkan untuk menjadi pecundang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a935c1de-a7a8-4317-8cf1-30a83a1e35a7', 'スポーツを見るとき、全力を尽くした負け犬と自分を重ね合わせてみなよ。それって楽しい？達成感はある？何か意味はあるの？意味無いよね？敗者から勝者に生まれ変わらなきゃ。', 'Setiap kali Anda menonton olahraga, Anda mengidentifikasi diri dengan tim yang tidak diunggulkan yang telah berusaha sebaik mungkin. Apakah itu menyenangkan? Apakah Anda merasa telah mencapai sesuatu? Apa gunanya? Tidak ada gunanya, kan? Anda harus mengubah diri Anda dari pecundang menjadi pemenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', 'vocabulary', '果物', '果物', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sesuatu yang berupa buah hanyalah buah.', 'Sesuatu yang berupa buah hanyalah buah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', 'Buah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', 'くだもの', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', '果物の中では、無花果が一番好きです。', 'Dari semua buah, saya paling suka buah ara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', 'うちの子は野さいはきらいですが、トマトだけは果物だと思っているようで食べてくれるんです。', 'Anak saya tidak suka sayuran, tapi ternyata dia mengira tomat itu buah jadi dia memakannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72a66f08-6e27-4eed-9ce9-6a9dd170dc1f', '「果物屋さんが閉まるまでに、仕事終わりそう？」「大丈夫。もし終わらなかったら明日に回すよ。」', '"Apakah kamu pikir kamu akan menyelesaikan pekerjaanmu sebelum toko buah tutup?" "Jangan khawatir. Jika aku tidak bisa menyelesaikannya, aku akan membiarkannya besok saja."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb333a35-d17d-44fb-b02c-66e2b61d2280', 'vocabulary', '薬', '薬', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Jika Anda sedang mencari obat di Jepang, carilah tanda ini.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Jika Anda sedang mencari obat di Jepang, carilah tanda ini.') ON CONFLICT (id) DO NOTHING;
