INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb333a35-d17d-44fb-b02c-66e2b61d2280', '鼻をきつくつまみながら薬を飲みます。', 'Saat saya minum obat, saya mencubit hidung saya rapat-rapat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb333a35-d17d-44fb-b02c-66e2b61d2280', 'あの男は、薬づけの生活を送っている。', 'Hidupnya penuh dengan narkoba.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb333a35-d17d-44fb-b02c-66e2b61d2280', '私は薬の中で座薬が一番好きです。', 'Jenis obat favorit saya adalah jenis supositoria.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('66792d4a-8a47-4f8e-8056-90e53e43e84a', 'vocabulary', '薬学', '薬学', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Orang yang mempelajari ilmu kedokteran sedang mempelajari ilmu farmasi.', 'Orang yang mempelajari ilmu kedokteran sedang mempelajari ilmu farmasi.') ON CONFLICT (id) DO NOTHING;
