INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('66792d4a-8a47-4f8e-8056-90e53e43e84a', 'やくがく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66792d4a-8a47-4f8e-8056-90e53e43e84a', 'どうしてコウイチは最近薬学の本をデスクにおいているの？', 'Mengapa Koichi menyimpan buku farmakologi itu di mejanya belakangan ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66792d4a-8a47-4f8e-8056-90e53e43e84a', 'かれは、東京大学の薬学部の学生です。', 'Dia adalah mahasiswa departemen farmasi di Universitas Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66792d4a-8a47-4f8e-8056-90e53e43e84a', 'コウイチが、薬学者の募集を検討しているって、本当ですか？', 'Benarkah Koichi sedang mempertimbangkan untuk menyewa seorang ahli farmakologi?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', 'vocabulary', '薬方', '薬方', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ketika obat dikirim ke arah Anda, obat itu akan sampai ke Anda. Itu resep Anda.', 'Ketika obat dikirim ke arah Anda, obat itu akan sampai ke Anda. Itu resep Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', 'Resep', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', 'やくほう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', '医者にもらった薬方を失くしてしまいました。', 'Saya kehilangan resep yang diberikan dokter kepada saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', '字がきたなすぎて、薬方に何が書いてあるのかさっぱり分かりません。', 'Tulisan tangannya sangat berantakan sehingga saya sama sekali tidak mengerti apa yang tertulis di resepnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8700a043-5a2d-4c2c-babb-b230e41a6f57', '古い薬方の中には、危険であるということで現代医療からは除かれているものもある。', 'Beberapa resep lama dianggap berbahaya dan tidak lagi digunakan dalam pengobatan modern.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', 'vocabulary', '薬物', '薬物', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Benda obat adalah obat-obatan dan obat-obatan. Cobalah untuk tidak mengonsumsinya terlalu banyak sekarang!', 'Benda obat adalah obat-obatan dan obat-obatan. Cobalah untuk tidak mengonsumsinya terlalu banyak sekarang!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', 'Obat-obatan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', 'Drugs', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', 'やくぶつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', '「今すぐ薬物をやめろ！」とさけびながら、コウイチはビエトの鼻を人さし指で指した。', 'Koichi berteriak, "Berhenti menggunakan narkoba sekarang juga!" dan menunjuk hidung Viet dengan jari telunjuknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', 'ビエトは、ヤクザの世界からも、薬物からも、完全に足をあらった。', 'Viet benar-benar melepaskan diri dari dunia yakuza dan narkoba.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21251b48-34a1-4a7f-b8b5-1f6978c40eea', '今までに何か薬物によってアレルギー反応が引き起こされたことはありますか？', 'Pernahkah Anda mengalami reaksi alergi terhadap obat apa pun?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'vocabulary', '薬用', '薬用', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Sesuatu yang digunakan untuk pengobatan adalah obat.', 'Sesuatu yang digunakan untuk pengobatan adalah obat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'Obat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'Medicinal Use', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'やくよう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'にきびが気になるので、薬用の石けんで顔をあらうようにしています。', 'Saya khawatir dengan jerawat, jadi saya cenderung menggunakan sabun obat untuk mencuci muka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', 'この薬局に、薬用リップクリームはおいていますか？', 'Apakah apotek ini menyediakan obat pelembab bibir?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4344712-d2f9-4dc6-a4bf-a080d3bbc74c', '咳がひどいんですが、妊娠中に薬用せき止めドロップを服用しても大丈夫でしょうか？', 'Saya menderita batuk parah, jadi bolehkah saya minum obat batuk saat hamil?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'vocabulary', '知識', '知識', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda cerdas tentang apa yang Anda ketahui. Anda memilih apa yang harus disimpan dan apa yang tidak boleh disimpan dalam otak Anda. Ini adalah jumlah pengetahuan Anda.', 'Anda cerdas tentang apa yang Anda ketahui. Anda memilih apa yang harus disimpan dan apa yang tidak boleh disimpan dalam otak Anda. Ini adalah jumlah pengetahuan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'Pengetahuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'Information', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'ちしき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'コウイチって、知識のほうこみたいなやつだよな。', 'Koichi seperti tambang emas informasi, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', 'トーフグの社員は、みんな知識よくがおうせいです。', 'Karyawan Tofugu semuanya sangat haus akan ilmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('815eb90c-720b-4bf0-917e-f88c1fd8d4b4', '日本語の知識を身に付けたいですか？恐がらなくてもいいですよ。簡単です。あなたの知識を別の言語で表現する方法を学べばいいだけなんですから。', 'Apakah Anda ingin memperoleh pengetahuan yang baik tentang bahasa Jepang? Jangan takut. Itu mudah. Anda hanya perlu belajar bagaimana mengungkapkan informasi dalam bahasa lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', 'vocabulary', '意識', '意識', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kecerdasan yang Anda lakukan terhadap ide-ide Anda menunjukkan kesadaran Anda. Ini menunjukkan bahwa Anda berpikir secara sadar, karena Anda tidak hanya tahu bahwa Anda mempunyai ide, namun Anda memikirkannya dan membedakannya.', 'Kecerdasan yang Anda lakukan terhadap ide-ide Anda menunjukkan kesadaran Anda. Ini menunjukkan bahwa Anda berpikir secara sadar, karena Anda tidak hanya tahu bahwa Anda mempunyai ide, namun Anda memikirkannya dan membedakannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', 'Kesadaran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', 'Consciousness', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', 'いしき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', '道をわたる前に、車が来てないことをかくにんするよう意識してください。', 'Harap biasakan untuk memastikan tidak ada mobil yang datang sebelum Anda menyeberang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', '果物や野さいはけんこうに良いので、意識して食べるようにしています。', 'Saya secara sadar makan buah-buahan dan sayur-sayuran karena baik untuk kesehatan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a15515f6-e5d3-4ccd-bb63-e0d56953ec76', 'サーモンは、フグが他の女の子に興味を示そうものなら、意識を失う。', 'Begitu Fugu menunjukkan perhatian pada gadis lain, Salmon kehilangan kesadaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8065566a-e3b5-4691-81d8-97a429b83666', 'vocabulary', '留学生', '留学生', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ingat 留学, yang artinya "belajar di luar negeri"? Apakah Anda juga ingat 学生, yang berarti "siswa"? Kata ini seperti dua kata yang digabung menjadi satu (bersama 学), menjadikannya "siswa yang belajar di luar negeri". Apa cara yang lebih baik untuk mengatakan itu? Bagaimana kalau pertukaran pelajar!', 'Ingat 留学, yang artinya "belajar di luar negeri"? Apakah Anda juga ingat 学生, yang berarti "siswa"? Kata ini seperti dua kata yang digabung menjadi satu (bersama 学), menjadikannya "siswa yang belajar di luar negeri". Apa cara yang lebih baik untuk mengatakan itu? Bagaimana kalau pertukaran pelajar!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8065566a-e3b5-4691-81d8-97a429b83666', 'Pertukaran Pelajar', true) ON CONFLICT DO NOTHING;
