INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ee80dd-6557-4298-a358-57845ac738ad', '天才外科医が、コウイチの脳を取り出して、ビエトにい植しました。', 'Seorang ahli bedah jenius mengambil otak Koichi dan mentransplantasikannya ke Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ee80dd-6557-4298-a358-57845ac738ad', '黒い服を着た男が、マイケルのかばんからさいふを取り出すのを見たよ。', 'Aku melihat seorang pria berpakaian hitam mengambil dompet dari tasmu, Michael.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ee80dd-6557-4298-a358-57845ac738ad', 'オーブンからフグを取り出しておいてくれない？あと五分で着くから。', 'Bisakah Anda mengeluarkan ikan buntal dari oven untuk saya? Saya akan sampai di sana dalam lima menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0579d680-5dff-405a-b73f-fcd5a75cea69', 'vocabulary', '取り分け', '取り分け', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Saat Anda mengambil sesuatu dan membaginya menjadi beberapa bagian, Anda harus sangat berhati-hati untuk tidak memberikan bagian yang tidak setara kepada siapa pun. Hal ini sangat penting karena kita berurusan dengan uang, dan orang-orang akan menyerang dan menembak Anda di bawah meja jika Anda tidak terlalu akurat.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0579d680-5dff-405a-b73f-fcd5a75cea69', 'Terutama', true) ON CONFLICT DO NOTHING;
