INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0579d680-5dff-405a-b73f-fcd5a75cea69', '取り分けコウイチがどなっている時に、ビエトは一人静かに笑っていました。', 'Viet tertawa kecil pada dirinya sendiri, terutama saat Koichi berteriak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0579d680-5dff-405a-b73f-fcd5a75cea69', 'ついにJLPT1に合格したんですが、トーフグには取り分け感謝しています。', 'Saya akhirnya lulus JLPT N1 dan saya sangat mengapresiasi Tofugu untuk itu.') ON CONFLICT DO NOTHING;
