INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a5559c49-b154-47b9-b1bf-e9377beb3e6b', 'るすばん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5559c49-b154-47b9-b1bf-e9377beb3e6b', '一日二万円で留守番の仕事を引き受けた。', 'Saya mengambil pekerjaan menjaga rumah dengan gaji 20.000 yen sehari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5559c49-b154-47b9-b1bf-e9377beb3e6b', 'アメリカでは小さい子どもだけで留守番させるのはい法です。', 'Di Amerika, membiarkan anak kecil mengurus rumah sendirian adalah tindakan ilegal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a5559c49-b154-47b9-b1bf-e9377beb3e6b', '２ヶ月間旅行したければ、留守番を雇う必要があります。', 'Jika Anda ingin bepergian selama dua bulan, Anda perlu menyewa seorang pengasuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e315dd1f-a8d1-4b68-a9d1-ab1239afc9ee', 'vocabulary', '原子力', '原子力', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kekuatan atom (原子) adalah tenaga nuklir.', 'Kekuatan atom (原子) adalah tenaga nuklir.') ON CONFLICT (id) DO NOTHING;
