INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e315dd1f-a8d1-4b68-a9d1-ab1239afc9ee', 'げんしりょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e315dd1f-a8d1-4b68-a9d1-ab1239afc9ee', '今は原子力の是非について話をしているんだ。関係無い話を持ち出して頭を混乱させないでくれ。', 'Kita sedang membicarakan apakah tenaga nuklir itu baik atau tidak saat ini. Jangan mencoba membingungkan kami dengan fakta yang tidak relevan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e315dd1f-a8d1-4b68-a9d1-ab1239afc9ee', '私の父は、以前は原子力発電所で仕事をしていました。', 'Ayah saya dulu bekerja di pembangkit listrik tenaga nuklir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e315dd1f-a8d1-4b68-a9d1-ab1239afc9ee', 'コウイチはゴジラと戦うために、原子力で稼働するトーフグロボットを作った。', 'Koichi membuat robot Tofugu bertenaga nuklir untuk melawan Godzilla.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1aafc342-f1ad-46b1-89f2-4373ae197822', 'vocabulary', '大失敗', '大失敗', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Anda tahu bagaimana 失敗 itu sebuah kesalahan? Nah, kesalahan besar akan menjadi kegagalan total atau kesalahan besar. Sangat buruk!', 'Anda tahu bagaimana 失敗 itu sebuah kesalahan? Nah, kesalahan besar akan menjadi kegagalan total atau kesalahan besar. Sangat buruk!') ON CONFLICT (id) DO NOTHING;
