INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('48142c7f-47ce-42bc-a621-380e0c1a85b4', 'むいしき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48142c7f-47ce-42bc-a621-380e0c1a85b4', '無意識のうちに、舌で虫歯の穴をさわってしまいます。', 'Mau tak mau aku tanpa sadar menelusuri rongga di gigiku dengan ujung lidahku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48142c7f-47ce-42bc-a621-380e0c1a85b4', 'その無意識につめをかむくせは直した方がいいよ。', 'Kebiasaan menggigit kuku yang tidak disengaja harus diperbaiki.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48142c7f-47ce-42bc-a621-380e0c1a85b4', '我々は素晴らしい。何故なら、無意識にクリエイティブになることができるからだ。', 'Kami luar biasa karena secara tidak sadar kami bisa menjadi kreatif.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e933c164-843c-45f5-be75-f1cd5137a3d7', 'vocabulary', '留守番電話', '留守番電話', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Mudah-mudahan Anda tahu bahwa ini ada hubungannya dengan menjaga rumah (留守番). Jadi, telepon (電話) yang berfungsi menjaga rumah bagi Anda itu apa? Itu mesin penjawab Anda.', 'Mudah-mudahan Anda tahu bahwa ini ada hubungannya dengan menjaga rumah (留守番). Jadi, telepon (電話) yang berfungsi menjaga rumah bagi Anda itu apa? Itu mesin penjawab Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e933c164-843c-45f5-be75-f1cd5137a3d7', 'Mesin Penjawab', true) ON CONFLICT DO NOTHING;
