INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a0b2dd1e-3571-4f9e-9440-99103057e7b3', 'この決だんは果たして正しかったのだろうか。', 'Saya ingin tahu apakah ini benar-benar keputusan yang tepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a0b2dd1e-3571-4f9e-9440-99103057e7b3', '外に出ると、果たして見覚えのある風けいが広がっていた。', 'Saat aku keluar, ada pemandangan familiar, seperti yang kuduga.') ON CONFLICT DO NOTHING;
