INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4b3f7cf-5f92-4266-9f61-a123b75570b4', 'vocabulary', '関心', '関心', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Hal-hal yang berhubungan dengan hatimu adalah hal-hal yang paling memprihatinkan dan menarik perhatianmu.', 'Hal-hal yang berhubungan dengan hatimu adalah hal-hal yang paling memprihatinkan dan menarik perhatianmu.') ON CONFLICT (id) DO NOTHING;
