INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4b3f7cf-5f92-4266-9f61-a123b75570b4', '日本のアニメの声ゆうは好きですが、海外のアニメの声ゆうには関心がありません。', 'Saya suka pengisi suara anime Jepang tetapi saya tidak tertarik dengan pengisi suara asing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4b3f7cf-5f92-4266-9f61-a123b75570b4', 'げんざいの最大の関心は何ですか？', 'Apa kekhawatiran terbesar Anda saat ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4b3f7cf-5f92-4266-9f61-a123b75570b4', '当社トーフグ、ならびに当社製品に関心をお寄せいただき、有難うございます。', 'Terima kasih atas minat Anda pada perusahaan kami, Tofugu, dan produk kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4bbf7ea4-4676-4260-bfb4-940bd58b20e7', 'vocabulary', '顔面', '顔面', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Wajah wajah adalah wajah, tetapi lebih khusus lagi wajah seseorang. Mungkin karena hal yang paling mirip dengan wajah yang pernah Anda miliki adalah wajah manusia... setidaknya di mata kita (yang saya maksud dengan "kita" adalah mata umat manusia, karena saya sepenuhnya setuju dengan kalian dalam hal itu).', 'Wajah wajah adalah wajah, tetapi lebih khusus lagi wajah seseorang. Mungkin karena hal yang paling mirip dengan wajah yang pernah Anda miliki adalah wajah manusia... setidaknya di mata kita (yang saya maksud dengan "kita" adalah mata umat manusia, karena saya sepenuhnya setuju dengan kalian dalam hal itu).') ON CONFLICT (id) DO NOTHING;
