INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4bbf7ea4-4676-4260-bfb4-940bd58b20e7', 'トーフグの社員たちは、みんな顔面へんさちが高い。', 'Nilai deviasi wajah pekerja Tofugu semuanya sangat tinggi.') ON CONFLICT DO NOTHING;
