INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b73f1d8d-b671-4d3e-9de6-4dfd7cb627e4', 'もう少しだけ、側にいてもいい？', 'Bolehkah aku berada di sisimu lebih lama lagi?') ON CONFLICT DO NOTHING;
