INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('057ba03c-556d-49eb-868a-526cfe97562f', 'vocabulary', '動物園', '動物園', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ingat bagaimana 動物 berarti binatang? Nah ketika Anda menambahkan taman, itu menjadi kebun binatang. Itu adalah taman untuk binatang. Kecuali hewan-hewan itu tidak bisa pergi. Pernah.', 'Ingat bagaimana 動物 berarti binatang? Nah ketika Anda menambahkan taman, itu menjadi kebun binatang. Itu adalah taman untuk binatang. Kecuali hewan-hewan itu tidak bisa pergi. Pernah.') ON CONFLICT (id) DO NOTHING;
