INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('821e31cb-80f9-459a-b558-62810107a43a', 'vocabulary', '幸運', '幸運', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Ketika Anda membawa kebahagiaan, Anda melihat sisi baik dari segala sesuatu dan akhirnya mendapatkan keberuntungan. Seseorang yang membawa kebahagiaan akan sangat beruntung dalam hidupnya.', 'Ketika Anda membawa kebahagiaan, Anda melihat sisi baik dari segala sesuatu dan akhirnya mendapatkan keberuntungan. Seseorang yang membawa kebahagiaan akan sangat beruntung dalam hidupnya.') ON CONFLICT (id) DO NOTHING;
