INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ad0077b-e2cd-49b3-a714-9dca178eae70', '今はめがねをかけてないので、遠くの物がよく見えません。', 'Saya tidak memakai kacamata sekarang, jadi saya tidak bisa melihat objek jauh dengan baik.') ON CONFLICT DO NOTHING;
