INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa2918ab-cd7c-4ddf-aa23-97450d755355', 'クリステンの子守歌は、プロのいきに達している。', 'Lagu pengantar tidur Kristen telah mencapai tingkat profesional.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa2918ab-cd7c-4ddf-aa23-97450d755355', 'アメリカで一番有名な子守歌は何ですか？', 'Lagu pengantar tidur apa yang paling populer di Amerika?') ON CONFLICT DO NOTHING;
