INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b13c30a-6faa-4710-b19b-5f1a67021dda', '食べたの辞書形は食べるです。', 'Bentuk kamus dari makan adalah makan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b13c30a-6faa-4710-b19b-5f1a67021dda', '辞書形は分かるんですが、活用形がよく分かりません。', 'Saya baik-baik saja dengan bentuk kamus, tapi saya punya masalah dengan bentuk terkonjugasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b13c30a-6faa-4710-b19b-5f1a67021dda', 'この言葉の辞書形を書きなさい。', 'Tuliskan bentuk kamus dari kata ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'vocabulary', '果てる', '果てる', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Jika kamu merobek (てる) buah, hidupnya akan berakhir. Dengan kata lain, orang miskin akan mati. Buah tidak bisa bertahan jika sudah terlalu banyak dipukul.', 'Jika kamu merobek (てる) buah, hidupnya akan berakhir. Dengan kata lain, orang miskin akan mati. Buah tidak bisa bertahan jika sudah terlalu banyak dipukul.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'Untuk Mengakhiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'To Die', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'はてる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'こんなところで果てるわけにはいかないと思ったんです。', 'Saya berpikir, saya tidak boleh mati di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', '三日もねてないから、つかれ果てたよ。', 'Saya belum tidur selama tiga hari dan saya kelelahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b3ad876-e554-4c9d-bd4f-4099b783e1b5', 'いつ果てるともなく続く会議に、社員は全員ウンザリしていた。', 'Rapat berlanjut tanpa ada tanda-tanda akan berakhir dan para karyawan mulai muak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('30c1de13-682f-4dc1-8f7e-c51e48423bc4', 'vocabulary', '幸い', '幸い', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Kebahagiaan adalah kebahagiaan!', 'Kebahagiaan adalah kebahagiaan!') ON CONFLICT (id) DO NOTHING;
