INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('30c1de13-682f-4dc1-8f7e-c51e48423bc4', '幸いなことに、ちょうど空車のタクシーがやって来ました。', 'Untung saja taksi kosong baru saja datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('30c1de13-682f-4dc1-8f7e-c51e48423bc4', 'お役に立てたようで、幸いです。', 'Saya senang bisa membantu Anda.') ON CONFLICT DO NOTHING;
