INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2266adae-5778-43eb-a7be-301025f4e908', 'vocabulary', '治安', '治安', 3, '9a8b4c1d-2e3f-0a5b-6c7d-8e9f0a1b2c3d', 'Jika rakyat Anda bisa santai karena Anda memerintah mereka dengan baik, maka ada ketertiban umum. Anda tidak ingin orang-orang yang Anda pimpin menjadi marah atau stres, Anda menginginkan keamanan publik dan kedamaian publik untuk semua!', 'Jika rakyat Anda bisa santai karena Anda memerintah mereka dengan baik, maka ada ketertiban umum. Anda tidak ingin orang-orang yang Anda pimpin menjadi marah atau stres, Anda menginginkan keamanan publik dan kedamaian publik untuk semua!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2266adae-5778-43eb-a7be-301025f4e908', 'Ketertiban Umum', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2266adae-5778-43eb-a7be-301025f4e908', 'Public Safety', false) ON CONFLICT DO NOTHING;
