INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2395ff6c-6008-465d-b0e5-83a4c640e8b6', '学校の遠足で、動物園に行きました。', 'Kami melakukan piknik sekolah ke kebun binatang.') ON CONFLICT DO NOTHING;
