INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('23500cab-b237-44f7-a9d0-378200ece8b1', 'radical', '祭', 'festival', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Radikal ini sama dengan kanji. Artinya festival.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('23500cab-b237-44f7-a9d0-378200ece8b1', 'Festival', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('19d94249-b962-48d1-b565-78de069abc2a', 'radical', '苟', 'poem', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Paragraf berbunga-bunga bukan sekadar tulisan biasa. Itu berbunga-bunga, yang menjadikannya sebuah puisi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('19d94249-b962-48d1-b565-78de069abc2a', 'Puisi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1a53efaf-3e95-4939-b513-b8b0dda7f904', 'radical', '兑', 'guard', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Radikal ini terdiri dari tanduk dan kakak laki-laki. Tapi itu sebenarnya bukan tanduk, itu bagian dari seragam penjaga baru kakakmu. Dia sekarang adalah penjaga bank atau museum. Anda tidak tahu yang mana, tapi Anda tahu dia sering berdiri di sana-sini dengan seragamnya sekarang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a53efaf-3e95-4939-b513-b8b0dda7f904', 'Penjaga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8e0160aa-38f6-4676-953c-e85fe35e2431', 'radical', '幸', 'happiness', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Radikal ini sama dengan kanji. Artinya kebahagiaan. Jangan bingung dengan 辛 radikal pedas, keduanya sangat mirip!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8e0160aa-38f6-4676-953c-e85fe35e2431', 'Kebahagiaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8924e7f7-5b34-4dde-b2a1-a66118a2e551', 'radical', '先', 'previous', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Radikal ini sama dengan kanji. Artinya sebelumnya.') ON CONFLICT (id) DO NOTHING;
