INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', 'vocabulary', '官金', '官金', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Emas pemerintah (alias uang) adalah dana pemerintah.', 'Emas pemerintah (alias uang) adalah dana pemerintah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', 'Dana Pemerintah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', 'Government Money', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', 'かんきん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', '間違っても官金に手を出すんじゃないぞ！', 'Apa pun yang terjadi, jangan pernah menyalahgunakan uang pemerintah!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', '保育園まで公用車に子どもを乗せて行くことは、ある意味で官金の私消に当たると思いますか？', 'Apakah menurut Anda mengantar anak ke tempat penitipan anak dengan menggunakan mobil umum merupakan penyalahgunaan uang pemerintah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c40d4ea0-70cc-4317-9989-4755a0e60f74', '金曜日に親友が一万ドルの公的資金を濫用したとして官金私消罪で逮捕されたのだが、私には彼女がそんなことをしたとは思えない。', 'Sahabat saya ditangkap pada hari Jumat karena penggelapan dana pemerintah sebesar lebih dari $10.000, namun saya ragu dia benar-benar melakukannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', 'vocabulary', '外交官', '外交官', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Seseorang dari luar yang masuk untuk berbaur dengan pemerintah adalah seorang diplomat. Sungguh, itu yang dilakukan diplomat, bukan? Mereka datang dari luar (negara). Mereka berbaur dengan pemerintah, dan mereka melakukan apa yang harus mereka lakukan!', 'Seseorang dari luar yang masuk untuk berbaur dengan pemerintah adalah seorang diplomat. Sungguh, itu yang dilakukan diplomat, bukan? Mereka datang dari luar (negara). Mereka berbaur dengan pemerintah, dan mereka melakukan apa yang harus mereka lakukan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', 'Diplomat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', 'がいこうかん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', 'あの外交官は、どうしてけっこんして身を固めないんだろう。', 'Saya bertanya-tanya mengapa diplomat itu tidak menikah dan menetap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', '私のおじは外交官で、世界に数台しかないギターを他の国の外交官からプレゼントされました。', 'Paman saya adalah seorang diplomat dan seorang diplomat dari negara lain memberinya sebuah gitar langka, yang merupakan salah satu dari sedikit gitar yang ada di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('048ae90e-ad7a-43e3-8bfa-5fd0f93355f9', '私は外交官で、どうしても今日日本に飛ばなければいけないんです。空席待ちをさせてもらえますか？', 'Saya seorang diplomat dan saya benar-benar harus terbang ke Jepang hari ini, jadi bisakah Anda memasukkan saya ke dalam daftar tunggu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'vocabulary', '察する', '察する', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menebak jadi versi vocab verbanya adalah menebak. Alternatifnya, Anda dapat mempelajarinya sebagai perasaan atau dugaan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menebak jadi versi vocab verbanya adalah menebak. Alternatifnya, Anda dapat mempelajarinya sebagai perasaan atau dugaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'Menebak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'To Sense', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'To Presume', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'さっする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'ふだんの言動から察するに、コウイチは鼻の下が非常に長い。', 'Dari bahasa dan tingkah laku Koichi, menurutku dia sangat lembut terhadap wanita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'うちの夫は、私の気持ちを察するのが下手です。', 'Suamiku tidak pandai menebak perasaanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ab0314-c809-4675-b42e-2da6b198b243', 'いくつかの記事を読んで、私はトーフグチームには何か暗黙の構想があることを察しました。', 'Dari membaca beberapa artikel, saya merasakan bahwa tim Tofugu mempunyai semacam rencana tersirat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'vocabulary', '察知', '察知', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Oke, jadi Anda bisa menebaknya, tetapi Anda juga agak mengetahuinya. Anda bisa mengambil kesimpulan apa jawabannya... Anda tidak 100% yakin, tapi Anda merasa tahu, padahal Anda hanya menebak-nebak.', 'Oke, jadi Anda bisa menebaknya, tetapi Anda juga agak mengetahuinya. Anda bisa mengambil kesimpulan apa jawabannya... Anda tidak 100% yakin, tapi Anda merasa tahu, padahal Anda hanya menebak-nebak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'Inferensi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'Infer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'Sense', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'さっち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', '昨夜、ビエトがコンピューターの不正利用を察知しました。', 'Tadi malam, Viet mendeteksi penggunaan komputer yang tidak sah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', 'ビエトと手下たちは、警察の手入れがあることを事前に察知していたようだ。', 'Viet dan prajuritnya sepertinya sudah merasakan bahwa polisi akan menggerebek mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d92c143e-6e11-4992-a98c-050c9006142a', '僕達の赤ちゃんは、母親であるサーモンの感情や不安をすごく敏感に察知するんです。', 'Bayi kami sangat peka terhadap emosi dan kecemasan ibunya, Salmon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', 'vocabulary', '愛', '愛', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', 'Cinta', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', 'あい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', 'サボテンの花は、母性愛のしょうちょうです。', 'Bunga kaktus merupakan simbol cinta ibu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', '社内恋愛をもう想するのが好きなんですけど、一番最近の私のもう想の中ではコウイチとビエトの間に愛がめ生えちゃったんです！', 'Saya suka berfantasi tentang romansa kantor dan dalam fantasi terbaru saya, cinta tumbuh antara Koichi dan Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bd663c5-ad69-4a76-a82a-83700b036c1f', '私はお金は愛より大切だと思います。よく「愛があれば山でも動かせる」なんて言いますが、実際はお金が無いとそんなことできないでしょ。', 'Saya pikir uang lebih penting daripada cinta. Mereka sering berkata, “cinta bisa memindahkan gunung,” namun kenyataannya Anda tidak bisa melakukan hal itu tanpa uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', 'vocabulary', '愛国心', '愛国心', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda memiliki rasa cinta terhadap negara jauh di lubuk hati Anda, itulah patriotisme.', 'Ketika Anda memiliki rasa cinta terhadap negara jauh di lubuk hati Anda, itulah patriotisme.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', 'Patriotisme', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', 'あいこくしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', '愛国心がやたらに強い男が、トーフグに入社しました。', 'Seorang pria yang sangat patriotik memasuki Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', 'マイケルが、愛国心あふれるチップチューンの曲を作曲しました。', 'Michael menyusun lagu 8-bit yang sangat patriotik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3494ce7-01ca-4dfc-9784-089965a99651', 'あの国が、誤った教育を通じて子どもたちに愛国心を植え付けようとしているのは好ましくないと思います。', 'Saya tidak suka negara ini mencoba menanamkan patriotisme pada anak-anak melalui pendidikan yang salah arah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', 'vocabulary', '自愛', '自愛', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Jika Anda mencintai diri sendiri, itulah cinta diri. Anda biasanya akan melihat kata ini sebagai bagian dari rangkaian frasa ご自愛下さい, yang digunakan dalam email dan sejenisnya untuk mengingatkan penerimanya agar bersikap baik pada diri mereka sendiri. Variasi lainnya termasuk ご自愛くださいませ, ご自愛を, dan ご自愛のほどを.', 'Jika Anda mencintai diri sendiri, itulah cinta diri. Anda biasanya akan melihat kata ini sebagai bagian dari rangkaian frasa ご自愛下さい, yang digunakan dalam email dan sejenisnya untuk mengingatkan penerimanya agar bersikap baik pada diri mereka sendiri. Variasi lainnya termasuk ご自愛くださいませ, ご自愛を, dan ご自愛のほどを.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', 'Cinta Diri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', 'Taking Care Of Oneself', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', 'じあい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', 'お体ご自愛ください。', 'Tolong jaga dirimu baik-baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', '今日は自愛デーにすることに自分で決めたので、一日中自愛しまくっちゃいます。', 'Aku sudah memutuskan sendiri bahwa hari ini adalah hari mencintai diri sendiri, jadi aku akan memanjakan diriku sepanjang hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae890e7c-3db3-40a0-b80f-d873b8324816', '時節柄、お風邪など召しませぬよう、くれぐれも御自愛くださいませ。', 'Saya sangat berharap Anda menjaga diri dengan baik dan tidak masuk angin atau semacamnya di saat seperti ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e0186b5e-e855-4278-9a17-3dd445954578', 'vocabulary', '性愛', '性愛-4003', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Cinta gender adalah cinta yang berkaitan dengan bagian gender. Itu adalah cinta seksual.', 'Cinta gender adalah cinta yang berkaitan dengan bagian gender. Itu adalah cinta seksual.') ON CONFLICT (id) DO NOTHING;
