INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cae3c6d7-d03c-4678-8f05-ce9c17612f4e', 'したの感覚がまひしています。', 'Sensasi di lidahku hilang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cae3c6d7-d03c-4678-8f05-ce9c17612f4e', 'トーフグのユーモアの感覚が好きです。', 'Saya suka selera humor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cae3c6d7-d03c-4678-8f05-ce9c17612f4e', 'もし本当に煙草を止めたいなら、肺を病む人特有の感覚を知ってみることだね。', 'Jika Anda benar-benar ingin berhenti merokok, Anda harus melihat bagaimana rasanya menjadi seseorang yang menderita penyakit paru-paru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', 'vocabulary', '説明', '説明', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda membuat teori Anda cemerlang (dan jelas serta mudah dipahami), Anda pasti sudah memberikan penjelasannya. Sebelumnya gelap dan keruh di benak semua orang. Tapi, saat Anda memberikan penjelasan, penjelasannya menjadi jelas dan mudah dimengerti! Hore!', 'Ketika Anda membuat teori Anda cemerlang (dan jelas serta mudah dipahami), Anda pasti sudah memberikan penjelasannya. Sebelumnya gelap dan keruh di benak semua orang. Tapi, saat Anda memberikan penjelasan, penjelasannya menjadi jelas dan mudah dimengerti! Hore!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', 'Penjelasan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', 'せつめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', '電車のスピードを急に落とした理由を説明してください。', 'Tolong jelaskan mengapa Anda tiba-tiba memperlambat kereta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', 'あんな無茶苦茶な説明で、よく会社の社長がつとまるよな。', 'Bagaimana dia bisa cocok menjadi presiden perusahaan dengan penjelasan buruk seperti itu?!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('acc19077-f728-4550-8111-afa50e2fc2c8', 'ごめん。さっぱり分からないよ。要約すると、説明の趣旨は何なの？', 'Maaf, saya tidak mengerti sama sekali. Apa maksud dari penjelasan anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', 'vocabulary', '小説', '小説', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Teori kecil adalah gagasan yang Anda miliki yang dituangkan di atas kertas. Mungkin itu ide tentang kehidupan yang Anda tulis dalam bentuk novel?', 'Teori kecil adalah gagasan yang Anda miliki yang dituangkan di atas kertas. Mungkin itu ide tentang kehidupan yang Anda tulis dalam bentuk novel?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', 'Baru', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', 'しょうせつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', 'この小説マジで大好きだわ。これはホンモノだよ。', 'Saya sangat menyukai novel ini. Ini sah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', 'お父さん、小説が売れて鼻高々だね。', 'Ayah bersinar bangga karena novelnya laris manis ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49a21a06-9751-457a-ad61-5009e9573239', '「ほら、これでなみだと鼻をふきなよ」と言いながら、コウイチは読んでいた小説のページを一枚やぶって、クリステンにわたした。', '“Ini, bersihkan air mata dan hidungmu,” kata Koichi sambil merobek halaman novel yang sedang dia baca dan menyerahkannya kepada Kristen.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', 'vocabulary', '伝説', '伝説', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Izinkan saya menyampaikan kepada Anda sebuah teori... sebuah teori yang mungkin sebuah legenda besar itu benar.', 'Izinkan saya menyampaikan kepada Anda sebuah teori... sebuah teori yang mungkin sebuah legenda besar itu benar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', 'Legenda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', 'でんせつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', 'アイルランドの伝説の英ゆうと言われれば、だれを思いうかべますか？', 'Ketika Anda mendengar "pahlawan legendaris Irlandia", siapa yang terlintas dalam pikiran Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', 'お前めちゃくちゃモテるな！マジで伝説的だよ。', 'Para gadis mencintaimu, kawan. Anda legendaris, sungguh!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('889314ed-f13f-44cf-84d5-ef70c9999eab', '伝説によると、この海には豆腐を食べるフグが住んでいるそうです。', 'Menurut legenda, ada seekor fugu yang memakan tahu di lautan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'vocabulary', '図説', '図説', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Teori diagram adalah ilustrasi yang digunakan sebagai diagram penjelas. Bayangkan saja sebuah papan kapur dengan segala macam gambar, menunjukkan cara kerjanya, setidaknya secara teori.', 'Teori diagram adalah ilustrasi yang digunakan sebagai diagram penjelas. Bayangkan saja sebuah papan kapur dengan segala macam gambar, menunjukkan cara kerjanya, setidaknya secara teori.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'Ilustrasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'Explanatory Diagram', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'ずせつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', '図説付きの参考書をさがしています。', 'Saya mencari buku teks dengan ilustrasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'アヤが、トーフグ社内の人間関係の図説を作ってくれました。', 'Aya membuat diagram penjelasan tentang hubungan internal Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8deed752-a157-46f3-9b5e-54d3b7911ca2', 'もし解説と共に図説があれば、より分かりやすくなるかと思うんですが、如何でしょうか？', 'Menurut saya akan lebih mudah dipahami jika ada ilustrasi dan penjelasannya, bagaimana menurut anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', 'vocabulary', '警察', '警察', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Mereka memperingatkan Anda dan menebak kapan Anda melakukan kesalahan (tentu saja dengan bukti!). Mereka adalah polisi.', 'Mereka memperingatkan Anda dan menebak kapan Anda melakukan kesalahan (tentu saja dengan bukti!). Mereka adalah polisi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', 'Polisi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', 'けいさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', '警察署に入ると、梅酒のにおいが鼻をついた。', 'Bau umeshu menusuk hidung saya saat memasuki kantor polisi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', 'その警察は、ビエトの警告をあざ笑ったため、後からひどい目にあいました。', 'Petugas polisi itu mencemooh peringatan Viet, jadi dia kemudian mendapati dirinya berada dalam situasi yang menyedihkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e366c979-4c10-4106-92cb-be6ef79cde4f', '警察署での出会いから一時間後、その警察官と泥棒はすっかり意気投合した。', 'Satu jam setelah pertemuan di kantor polisi, petugas polisi dan perampok itu benar-benar cocok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3dd8161-4c7e-438b-9286-cfeb1f42d006', 'vocabulary', '非常', '非常', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketidakadilan yang normal!  Ini adalah hal mengerikan yang terjadi, dan meskipun normal, hal ini tetap merupakan keadaan darurat.', 'Ketidakadilan yang normal!  Ini adalah hal mengerikan yang terjadi, dan meskipun normal, hal ini tetap merupakan keadaan darurat.') ON CONFLICT (id) DO NOTHING;
