INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3dd8161-4c7e-438b-9286-cfeb1f42d006', 'この非常ブレーキ、こわれてるかもしれないよ。', 'Saya pikir rem elektronik ini mungkin rusak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3dd8161-4c7e-438b-9286-cfeb1f42d006', '急に非常ベルが鳴り出して、びっくりしました。何かの非常事たいだったんですか？', 'Alarm darurat tiba-tiba berbunyi dan saya terkejut. Apakah ini semacam situasi darurat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3dd8161-4c7e-438b-9286-cfeb1f42d006', 'いつでも家に非常食を備えて置くことは良いことです。', 'Selalu baik untuk menyimpan jatah darurat di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58a8e93e-8377-4355-a8dd-0d122b1caa74', 'vocabulary', '可愛い', '可愛い', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Mungkin saja untuk menyukai hal ini. Astaga, lucu sekali! Hal apa pun yang sangat lucu mungkin untuk dicintai.', 'Mungkin saja untuk menyukai hal ini. Astaga, lucu sekali! Hal apa pun yang sangat lucu mungkin untuk dicintai.') ON CONFLICT (id) DO NOTHING;
