INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d67dee78-27c5-43e7-badf-919be2154990', '図書館から借りた本に、スーパーの広告が一枚はさまっていました。', 'Dalam sebuah buku yang saya pinjam dari perpustakaan, ada iklan toko kelontong tertempel di antara halaman-halamannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d67dee78-27c5-43e7-badf-919be2154990', 'クーポンが付いた広告を忘れたので、家にもどらなければいけません。', 'Saya harus pulang ke rumah karena lupa iklan dengan kuponnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d67dee78-27c5-43e7-badf-919be2154990', 'ビエトはコウイチに、アヤがトーフグの広告にものすごく変わった絵を描いたことを告げ口しました。', 'Viet memberi tahu Koichi bahwa Aya membuat gambar paling aneh untuk iklan Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', 'vocabulary', '予告', '予告', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Jika Anda mengumumkan sesuatu sebelumnya, Anda akan mendapat pemberitahuan terlebih dahulu. Pemberitahuan terlebih dahulu selalu menyenangkan untuk diberikan.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', 'Pemberitahuan Sebelumnya', true) ON CONFLICT DO NOTHING;
