INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', 'よこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', '大丈夫だよ、コウイチは予告なしにかいこしたりしないよ。', 'Kamu akan baik-baik saja. Koichi tidak akan memecatmu tanpa pemberitahuan sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', '三ヶ月家ちんをたいのうしてしまい、立ちのきを予告されました。', 'Saya membiarkan uang sewa saya belum dibayar selama tiga bulan dan kemudian saya diberi pemberitahuan penggusuran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bb76187-b4bd-4a5c-b82f-a594d5468527', '殺人予告を告げる手紙が、トーフグのオフィスに届けられた。', 'Surat yang memberitahukan terlebih dahulu adanya pembunuhan tiba di kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'vocabulary', '公告', '公告', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Pengumuman publik adalah pemberitahuan publik.', 'Pengumuman publik adalah pemberitahuan publik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'Pemberitahuan Publik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'Public Announcement', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'こうこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'トーフグの決算公告、もう見ましたか。', 'Apakah Anda sudah melihat pengumuman keuangan publik Tofugu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', 'トーフグは、日本政府の官報にコウイチについての重大な公告をのせることにしました。', 'Tofugu memutuskan untuk memasang pemberitahuan publik yang penting tentang Koichi dalam telegram resmi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c9d0d6e-91c7-4971-97c5-2bc1e945f0f3', '日本には、電子公告規則という法律がありますが、あなたの国はどうですか？', 'Ada undang-undang di Jepang yang disebut Peraturan Pemberitahuan Publik Elektronik. Apakah Anda memiliki hal seperti itu di negara Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'vocabulary', '報告', '報告', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Berita yang Anda umumkan menjadi laporan. Ketika seseorang mengumumkan berita tentang suatu topik, mereka memberi Anda laporan tentang informasi tersebut.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'Laporkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'Information', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'ほうこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'コウイチに報告した方がいいんじゃない？', 'Bukankah sebaiknya kita melaporkan hal ini pada Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', 'コウイチは、トーフグの年次報告を、社員たちに口頭で報告しました。', 'Koichi memberikan laporan lisan tentang laporan tahunan Tofugu untuk para pekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8003f762-ba43-46b9-a995-51aa3c57630a', '彼が逃げ出さないように、めちゃくちゃ面白い妊娠の報告方法を考えているの。', 'Aku sedang memikirkan cara terlucu untuk memberi tahu pacarku bahwa aku hamil agar dia tidak lari dariku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'vocabulary', '情報', '情報', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Perasaan dari sebuah berita adalah bahwa berita itu seharusnya memberi Anda informasi dan data, bukan omong kosong.', 'Perasaan dari sebuah berita adalah bahwa berita itu seharusnya memberi Anda informasi dan data, bukan omong kosong.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'Informasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'Data', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'じょうほう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'やつらがベッドの上でざん殺されていたというのはだれからの情報ですか？', 'Dari mana Anda mendapatkan informasi bahwa mereka dibunuh secara brutal di tempat tidur mereka?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'トーフグには、情報の取りあつかいきそくがありますか。', 'Apakah Tofugu memiliki aturan penanganan data?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f5b64f51-c3cd-422f-9751-cf51795479d1', 'えーっと、ワニカニプロジェクトの件で情報を交換したいんですが、後ほどお伺いしてもよろしいですか。', 'Baiklah, nanti saya ingin mampir lagi untuk bertukar informasi mengenai proyek WaniKani, jika Anda berkenan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', 'vocabulary', '予報', '予報', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Laporan berita yang meliput hal-hal sebelumnya (sebelum terjadi) adalah ramalan. Misalnya, ramalan cuaca adalah 天気予報.', 'Laporan berita yang meliput hal-hal sebelumnya (sebelum terjadi) adalah ramalan. Misalnya, ramalan cuaca adalah 天気予報.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', 'Ramalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', 'よほう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', '今日は午後から雨の予報だったことをすっかり忘れていました。', 'Terlintas dalam benak saya bahwa ramalan cuaca mengatakan akan turun hujan pada sore hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', 'お天気お姉さんは、明日から暑くなるって予報してたけどね。', 'Gadis cuaca mengatakan ramalan cuaca menyebutkan cuaca panas, mulai besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d85c0ae-3737-4554-aca7-d67a568d5fa5', '天気予報によると、カナダは今年はずっと雪が降る見通しです。', 'Menurut ramalan cuaca, tahun ini Kanada diperkirakan akan turun salju sepanjang tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'vocabulary', '報じる', '報じる', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti laporan berita jadi Anda bisa mencoba mengatakan "laporan berita" tapi itu tidak masuk akal. Namun yang masuk akal adalah "melaporkan".', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti laporan berita jadi Anda bisa mencoba mengatakan "laporan berita" tapi itu tidak masuk akal. Namun yang masuk akal adalah "melaporkan".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'Untuk Melaporkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'ほうじる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'スーパーマンの死去が報じられ、全米が涙した。', 'Seluruh Amerika menangis ketika mereka menyampaikan kabar bahwa Superman telah meninggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'コウイチの無事が報じられて、胸をなで下ろしました。', 'Saya merasa lega ketika mereka melaporkan bahwa Koichi aman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca8b08f7-a500-441a-b2ef-b6c6a81d631e', 'トーフグは、初音ミクの独占取材を報じた。', 'Tofugu meliput wawancara eksklusif dengan Hatsune Miku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', 'vocabulary', '報道', '報道', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Berita menyebar melalui laporan berita.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', 'Laporan Berita', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', 'ほうどう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', '同りょう達は、みんなその報道のことをすでに知っていました。', 'Semua rekan kerja saya sudah tahu tentang laporan berita tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', '今回のテロのことは、日本ではどのように報道されていますか？', 'Bagaimana serangan teroris ini dilaporkan di Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6f2c1eed-af63-4725-b81a-219eafdbb1f2', '報道によると、本日早朝に起きた玉突き事故で、20匹の魚が地域の病院へ運ばれたそうだよ。', 'Menurut laporan berita, dua puluh ikan diangkut ke rumah sakit setempat setelah tabrakan yang terjadi dini hari tadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', 'vocabulary', '正座', '正座', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Cara duduk yang benar adalah sebagai berikut: duduk tradisional Jepang (yaitu duduk dengan bertumpu pada kedua kaki dan berlutut). Anda juga bisa menyebutnya seiza. Mempelajari bacaan akan membantu memahami maknanya.', 'Cara duduk yang benar adalah sebagai berikut: duduk tradisional Jepang (yaitu duduk dengan bertumpu pada kedua kaki dan berlutut). Anda juga bisa menyebutnya seiza. Mempelajari bacaan akan membantu memahami maknanya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', 'Seiza', true) ON CONFLICT DO NOTHING;
