INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', 'せいざ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', '何でそんなに長い間正座できるの？', 'Kok bisa duduk seiza selama itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', '正座させられると思っていましたが、仏僧のように心が広いコウイチは、私のちこくを許してくれました。', 'Kupikir Koichi akan menyuruhku melakukan seiza, tapi dia bermurah hati seperti pendeta Budha dan memaafkanku karena terlambat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08238840-e46b-44dc-99d7-9136f9c0a965', '法要の間長時間正座をしていたので、足がすごく痺れています。', 'Saya berlutut dalam posisi seiza begitu lama selama upacara peringatan Buddhis hingga kaki saya benar-benar mati rasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', 'vocabulary', '座席', '座席', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kursi duduk mungkin akan menjadi kursi.', 'Kursi duduk mungkin akan menjadi kursi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', 'Kursi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', 'ざせき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', 'この座席のクッション、めっちゃいい感じ。', 'Bantalan kursi ini sangat nyaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', '座席の予約が必要だったとは、知りませんでした。', 'Saya tidak tahu bahwa saya harus membuat reservasi tempat duduk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97d25d76-e577-40c2-8ca3-ef617122f36f', '車内で、サーモンが座席から身を乗り出してフグにキスをした瞬間、信号が青に変わった。', 'Saat Salmon bersandar di kursi untuk mencium Fugu di dalam mobil, lampu lalu lintas berubah menjadi hijau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', 'vocabulary', '銀座', '銀座', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kursi perak bukanlah kerajaan gila di mana rajanya duduk di kursi perak. Itu adalah tempat terkenal di Tokyo. Mungkin kalau kalian baca bacaannya akan lebih jelas apa maksudnya (karena sama). Tempat duduk perak ini adalah Ginza.', 'Kursi perak bukanlah kerajaan gila di mana rajanya duduk di kursi perak. Itu adalah tempat terkenal di Tokyo. Mungkin kalau kalian baca bacaannya akan lebih jelas apa maksudnya (karena sama). Tempat duduk perak ini adalah Ginza.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', 'Ginza', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', 'ぎんざ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', '銀座付近で、じゅうたいをぬけるのにすごく時間がかかった。', 'Butuh waktu lama untuk melewati lalu lintas di sekitar Ginza.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', 'いとこは銀座を歩いていた時に、テレビ局からインタビューを受けました。', 'Saat sepupu saya sedang berjalan-jalan di Ginza, dia diwawancarai oleh kru TV.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13b27a2a-5a3a-4ff1-9fdc-02108b8e3d34', 'もし賢い愛人を見つけたいのなら、東京の銀座に行くのがいいかもね。', 'Jika ingin mencari kekasih yang pintar, mungkin sebaiknya ke Ginza, Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', 'vocabulary', '忘れる', '忘れる', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya lupa, jadi versi vocab verbanya adalah melupakan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya lupa, jadi versi vocab verbanya adalah melupakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', 'Untuk Melupakan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', 'わすれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', 'ごめんね、カナエちゃん。みんなカナエちゃんがどれだけ努力したのかすっかり忘れちゃってたんだ。', 'Maaf, Kanae. Kami semua benar-benar lupa betapa banyak usaha yang Anda lakukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', '危うくコウイチの顔を忘れる所だったよ。', 'Aku hampir lupa wajah Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc1e6391-c805-463b-9463-a22cbb091617', 'もう忘れなって。過ぎてしまったことは今さらどうにもならないんだから。', 'Lupakan saja. Itu air di bawah jembatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', 'vocabulary', '忘年会', '忘年会', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Saatnya berkumpul dan melupakan tahun ini... sungguh tahun yang buruk, untunglah tahun baru akan datang. Pertemuan ini adalah pesta akhir tahun.', 'Saatnya berkumpul dan melupakan tahun ini... sungguh tahun yang buruk, untunglah tahun baru akan datang. Pertemuan ini adalah pesta akhir tahun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', 'Pesta Akhir Tahun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', 'End Of Year Party', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', 'ぼうねんかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', '今日の忘年会であった出来事は、忘れる事にします。', 'Adapun apa yang terjadi di pesta akhir tahun hari ini, biarkan saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', '元々忘れっぽいんで、私には「忘年会」は必要ありません。', 'Aku sudah sangat pelupa, jadi aku tidak memerlukan apa yang disebut "pesta lupakan tahun ini".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc98598a-8228-41a5-8e42-5fae91a6bb82', '多くの日本企業では、新入社員は忘年会で一発芸を披露しなくてはならない。', 'Di banyak perusahaan Jepang, pekerja baru diharuskan melakukan pertunjukan singkat di pesta akhir tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', 'vocabulary', '洗う', '洗う', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencuci jadi versi vocab verbanya adalah mencuci.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencuci jadi versi vocab verbanya adalah mencuci.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', 'Untuk Mencuci', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', 'あらう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', '家に帰ったら手を洗ってうがいをしてください。', 'Sekembalinya ke rumah, harap cuci tangan dan berkumur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', 'ビエトは大切にはいていたビンテージのジーンズをかの女に洗われたショックで今日は休んでいます。', 'Viet mengambil cuti hari ini karena kaget karena jeans spesialnya dicuci oleh pacarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ec70809-dd2b-4b19-be28-b5d729deed93', 'ああ、私達は無洗米を使ってるので、洗う必要は無いですよ。', 'Oh, kami menggunakan beras yang sudah dicuci sebelumnya, jadi tidak perlu dicuci.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55d04b59-f790-4c0d-87a8-a57c867fa376', 'vocabulary', '洗車', '洗車', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Tempat cuci yang mencuci mobil adalah tempat cuci mobil.', 'Tempat cuci yang mencuci mobil adalah tempat cuci mobil.') ON CONFLICT (id) DO NOTHING;
