INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('55d04b59-f790-4c0d-87a8-a57c867fa376', 'せんしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55d04b59-f790-4c0d-87a8-a57c867fa376', 'コウイチの車の洗車をしたいという方がいたら、hello@tofugu.comまでメールしてください。', 'Jika diluar sana ada yang ingin mencuci mobil Koichi, silahkan email kami di hello@tofugu.com.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55d04b59-f790-4c0d-87a8-a57c867fa376', '洗車が終わるのを待っている間、ガソリンスタンドのバイトがずっとダラダラ話しかけてきて、かなりウザかった。', 'Selagi aku menunggu pencucian mobil selesai, pekerja paruh waktu itu terus mengomel dan itu sungguh menjengkelkan.') ON CONFLICT DO NOTHING;
