INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f742abe0-04b9-46e5-b20f-56f22549b125', 'ちょっと！バーベキューグリルから煙が出ているよ！！', 'Hai! Asap keluar dari panggangan!!') ON CONFLICT DO NOTHING;
