INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f6f194f-b821-4b4c-b6c0-395b9725d0dc', '一等車に乗ってるとは、さすがコウイチだね。', 'Anda berada di gerbong kelas satu, ya? Itu sangat mirip denganmu, Koichi!') ON CONFLICT DO NOTHING;
