INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ec07817-5c02-4a34-90d9-2e3018db09c6', 'あなたのお友達リストに私をついかしてください。', 'Silakan tambahkan saya ke daftar teman Anda.') ON CONFLICT DO NOTHING;
