INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ec07817-5c02-4a34-90d9-2e3018db09c6', '「側にいてくれてありがとう。」「何言ってるのよ！友達じゃないの！」', '"Terima kasih telah memihakku." “Apa yang kamu bicarakan? Kita berteman, bukan?”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd3b99e8-b014-4c6f-ae24-b95cc9fabd37', 'vocabulary', '配達する', '配達する', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Anda mendistribusikan barang, mereka mendapatkan barangnya. Anda akan menyampaikannya kepada semua orang.', 'Anda mendistribusikan barang, mereka mendapatkan barangnya. Anda akan menyampaikannya kepada semua orang.') ON CONFLICT (id) DO NOTHING;
