INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea8e07ae-cef1-4a88-82e2-ea3c94c11886', '一つのことに全てをかけないと、真の達人にはなれないぞ。', 'Jika Anda tidak menaruh semua telur Anda dalam satu keranjang, Anda tidak akan menjadi master sejati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea8e07ae-cef1-4a88-82e2-ea3c94c11886', 'ビエトは、カメラの達人です。', 'Viet adalah ahli kamera.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea8e07ae-cef1-4a88-82e2-ea3c94c11886', '父は、ピザ配達の分野で、世界レベルの達人であると評判になっています。', 'Ayah saya terkenal sebagai ahli tingkat dunia dalam bidang pengiriman pizza.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('df1f66cc-9cdb-4bcc-83b5-847f424c67e6', 'vocabulary', '伝達', '伝達', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda mengirimkan sesuatu dan Anda mendapatkannya di ujung yang lain, Anda telah melakukan transmisi.', 'Ketika Anda mengirimkan sesuatu dan Anda mendapatkannya di ujung yang lain, Anda telah melakukan transmisi.') ON CONFLICT (id) DO NOTHING;
