INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('01283ca7-af98-4ec2-9770-e2bcfe88bd26', '静かな通りにある家の方がいいです。', 'Kami lebih memilih rumah di jalan yang tenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('01283ca7-af98-4ec2-9770-e2bcfe88bd26', '下りなのは分かりますが、もう少し静かにしていただけますか？', 'Saya tahu Anda menderita diare, tetapi bisakah Anda menguranginya sedikit lagi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('01283ca7-af98-4ec2-9770-e2bcfe88bd26', 'コウイチとビエトが乗り込むと、そのタクシーは静かに動き出した。', 'Ketika Koichi dan Viet masuk, taksi mulai bergerak dengan tenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00b61cbf-9bb9-436e-b9d5-7243c1766d54', 'vocabulary', '静止', '静止', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Semuanya sunyi dan terhenti. Dunia hening dan semuanya tenang.', 'Semuanya sunyi dan terhenti. Dunia hening dan semuanya tenang.') ON CONFLICT (id) DO NOTHING;
