INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b072324-7f0f-4fca-a0e3-545f4a72ea6a', 'まずは年配の親類に相談してみます。', 'Saya akan mulai dengan berkonsultasi dengan kerabat lanjut usia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b072324-7f0f-4fca-a0e3-545f4a72ea6a', '実は、コウイチとオバマ大とうりょうは遠い親類なんですよ。', 'Sebenarnya Presiden Obama adalah kerabat jauh Koichi.') ON CONFLICT DO NOTHING;
