INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5976ea0-6571-4bcf-b62e-a852ad718633', 'ビエトに殺人の容疑がかかっている。', 'Viet dicurigai melakukan pembunuhan.') ON CONFLICT DO NOTHING;
