INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf88e592-d34c-42bf-b4ff-1069fbef4aaf', 'vocabulary', '生徒', '生徒', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Orang yang lebih muda dalam kehidupan adalah pelajar atau murid. Ini seperti bagaimana 先生 adalah seseorang yang datang sebelum Anda dalam hidup. Keren cara kerjanya, bukan? Oke 生徒, kembali bekerja!', 'Orang yang lebih muda dalam kehidupan adalah pelajar atau murid. Ini seperti bagaimana 先生 adalah seseorang yang datang sebelum Anda dalam hidup. Keren cara kerjanya, bukan? Oke 生徒, kembali bekerja!') ON CONFLICT (id) DO NOTHING;
