INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('147d4149-5c68-4d0e-8d72-0c8fc37ad446', 'トーフグの信徒数は一万人をこえました。', 'Jumlah penganut Tofugu melebihi 10.000.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('147d4149-5c68-4d0e-8d72-0c8fc37ad446', 'かん国ではキリスト教の信徒の方が仏教の信徒よりも多いって知っていましたか。', 'Tahukah Anda bahwa Korea memiliki lebih banyak pengikut Kristen dibandingkan pengikut Buddha?') ON CONFLICT DO NOTHING;
