INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61d06ebc-da91-4b01-bc5f-539ee8dfa6f9', 'コウイチは全てを失ってしまったが、ビエトという親友を得ることができた。', 'Meski Koichi kehilangan segalanya, dia bisa mendapatkan sahabat terbaiknya di Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61d06ebc-da91-4b01-bc5f-539ee8dfa6f9', '人の信らいを得るのは容易なことではない。', 'Tidak mudah untuk mendapatkan kepercayaan seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61d06ebc-da91-4b01-bc5f-539ee8dfa6f9', '日本で英語を教えるという経験から、たくさんのことが得られました。', 'Saya mendapat banyak pengalaman mengajar bahasa Inggris di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('211e009b-628f-4fae-9004-0367af5a23e1', 'vocabulary', '得', '得', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda mampu memperoleh apa pun yang Anda inginkan, Anda mulai melihat manfaat dari segala sesuatu di sekitar Anda dan mulai mengambil keuntungan darinya. Bukankah kamu sangat luar biasa?', 'Ketika Anda mampu memperoleh apa pun yang Anda inginkan, Anda mulai melihat manfaat dari segala sesuatu di sekitar Anda dan mulai mengambil keuntungan darinya. Bukankah kamu sangat luar biasa?') ON CONFLICT (id) DO NOTHING;
