INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('211e009b-628f-4fae-9004-0367af5a23e1', 'お得なクーポン冊子はいかがですか？', 'Apakah Anda ingin buku kupon murah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('211e009b-628f-4fae-9004-0367af5a23e1', 'そんな事して、一体何の得があるっていうの？', 'Apa untungnya melakukan hal seperti itu?') ON CONFLICT DO NOTHING;
