INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f2494e5-c2af-44fe-9929-e9a383783b3c', 'vocabulary', '得意', '得意', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Jika Anda bisa memperoleh ide dengan cepat, Anda harus terbiasa dengan apa pun yang sedang Anda lakukan. Jika Anda memperoleh ide dengan cara ini, kemungkinan besar Anda ahli atau ahli dalam tindakan ini.', 'Jika Anda bisa memperoleh ide dengan cepat, Anda harus terbiasa dengan apa pun yang sedang Anda lakukan. Jika Anda memperoleh ide dengan cara ini, kemungkinan besar Anda ahli atau ahli dalam tindakan ini.') ON CONFLICT (id) DO NOTHING;
