INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f2494e5-c2af-44fe-9929-e9a383783b3c', '一番得意な料理は何ですか。', 'Apa hidangan khasmu?') ON CONFLICT DO NOTHING;
