INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b02c40e6-249f-4e70-afb9-d98e3e8f0a53', 'vocabulary', '説得', '説得', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Anda memperoleh teori demi teori. Dalam melakukan ini, Anda memiliki banyak teori di kepala Anda. Anda menggunakan semua teori ini sebagai alat persuasi. Teori-teori ini akan memungkinkan Anda meyakinkan siapa pun tentang apa pun.', 'Anda memperoleh teori demi teori. Dalam melakukan ini, Anda memiliki banyak teori di kepala Anda. Anda menggunakan semua teori ini sebagai alat persuasi. Teori-teori ini akan memungkinkan Anda meyakinkan siapa pun tentang apa pun.') ON CONFLICT (id) DO NOTHING;
