INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2365ace-8c26-43df-ab3b-61631ea0e32e', '五日も雨が続いています。', 'Hujan telah turun selama lima hari berturut-turut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2365ace-8c26-43df-ab3b-61631ea0e32e', 'コウイチのジョークの後に、気まずいちんもくが続きました。', 'Keheningan yang canggung mengikuti lelucon Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2365ace-8c26-43df-ab3b-61631ea0e32e', '金玉を捻ってしまい、痛みが五時間以上も続いています。', 'Testis saya terpelintir dan rasa sakitnya telah berlangsung selama lebih dari lima jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7eed48d7-49a0-4fb7-9ff1-a3ffbe79f2f3', 'vocabulary', '続々', '続々', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda melanjutkan dan kemudian melanjutkan lagi (itulah kanji pengulangnya), Anda akan mengalami hal-hal yang terjadi satu demi satu. Lanjutkan terus lanjutkan!', 'Ketika Anda melanjutkan dan kemudian melanjutkan lagi (itulah kanji pengulangnya), Anda akan mengalami hal-hal yang terjadi satu demi satu. Lanjutkan terus lanjutkan!') ON CONFLICT (id) DO NOTHING;
