INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4563304-33b8-4110-bbd3-88ca50c5b396', 'ビエトは若い時、あるやみ取引でかなり利えきを上げました。', 'Viet mendapat untung besar dari kesepakatan pasar gelap ketika dia masih muda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4563304-33b8-4110-bbd3-88ca50c5b396', 'コウイチは若いころ、日本に留学していたことがあります。', 'Koichi belajar di Jepang ketika dia masih muda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4563304-33b8-4110-bbd3-88ca50c5b396', 'あの若い女性は、あなたには到底手の届かない高嶺の花だってことに気づいてるわよね。', 'Anda benar-benar menyadari bahwa wanita muda jauh di luar kemampuan Anda, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('225d7538-753b-42d1-9e0e-28dbced92772', 'vocabulary', '若者', '若者', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Seseorang yang muda adalah orang yang masih muda.', 'Seseorang yang muda adalah orang yang masih muda.') ON CONFLICT (id) DO NOTHING;
