INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7dfe1d2f-e20b-4ff7-a7f3-20501e57ab54', 'わかわかしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7dfe1d2f-e20b-4ff7-a7f3-20501e57ab54', 'コウイチっていつまでたっても若々しいよね。', 'Koichi benar-benar memiliki penampilan awet muda selamanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7dfe1d2f-e20b-4ff7-a7f3-20501e57ab54', 'そのファッション、ちょっと若々しすぎない？', 'Tidakkah menurut Anda jenis fesyen seperti itu terlalu muda untuk Anda cari?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7dfe1d2f-e20b-4ff7-a7f3-20501e57ab54', '私の祖母は九十代ですが、六十代の人よりも若く見えます。若さの秘訣は、若々しい気持ちでいることと、よく噛むことだそうです。', 'Nenek saya berusia sembilan puluhan dan dia terlihat lebih muda dibandingkan sebagian orang berusia enam puluhan. Ia mengatakan bahwa merasa awet muda dan sering mengunyah makanan adalah dua rahasia besar masa mudanya.') ON CONFLICT DO NOTHING;
