INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b5c87eb7-e831-433e-ae04-f3f3f480a6df', 'しざい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b5c87eb7-e831-433e-ae04-f3f3f480a6df', 'コウイチの私財がいくらあるか知っていますか。', 'Tahukah Anda berapa banyak dana pribadi yang dimiliki Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b5c87eb7-e831-433e-ae04-f3f3f480a6df', '私は仏僧になるために私財を全部すてて京都へ旅立った。', 'Saya menyerahkan semua harta pribadi saya dan berangkat ke Kyoto untuk menjadi biksu Buddha.') ON CONFLICT DO NOTHING;
