INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3376c0b1-2544-4972-8f4e-6fee036ad934', 'vocabulary', '借財', '借財-4241', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kekayaan yang Anda pinjam adalah hutang Anda.', 'Kekayaan yang Anda pinjam adalah hutang Anda.') ON CONFLICT (id) DO NOTHING;
