INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b46ea44-ee7b-4b09-bce2-93a81c7757b9', '山火事のせいで町中が煙くなっているんです。', 'Seluruh kota sekarang berasap karena kebakaran hutan.') ON CONFLICT DO NOTHING;
