INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c34d2806-655c-4740-a17d-93f6fb818162', 'vocabulary', '人類学', '人類学', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Studi tentang umat manusia (人類) dikenal sebagai antropologi.', 'Studi tentang umat manusia (人類) dikenal sebagai antropologi.') ON CONFLICT (id) DO NOTHING;
