INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6167da3-de5c-4388-a7a3-e6c36aea276c', 'vocabulary', '説明書', '説明書', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Penjelasan (説明) secara tertulis adalah penjelasan tertulis. Saya rasa terkadang Anda tidak ingin memberikan penjelasan secara langsung, ya?', 'Penjelasan (説明) secara tertulis adalah penjelasan tertulis. Saya rasa terkadang Anda tidak ingin memberikan penjelasan secara langsung, ya?') ON CONFLICT (id) DO NOTHING;
