INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97d9a35c-dfb1-4b9a-98ae-e28c21c8b12c', '書類を家のつくえの上においてきてしまったっぽい！', 'Saya pikir dokumen itu ada di meja saya di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97d9a35c-dfb1-4b9a-98ae-e28c21c8b12c', '「いつトーフグの機密書類が欲しい？」「早ければ早いに越したことはないな。」', '"Kapan kamu menginginkan dokumen rahasia Tofugu?" "Lebih cepat lebih baik."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e147e221-f625-4040-95cb-4ab2cbd0204d', 'vocabulary', '人達', '人達', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Kanji 達 terkadang membuat banyak hal menjadi jamak. Jadi, ketika Anda memiliki jumlah jamak dari seseorang, Anda memiliki lebih dari satu orang, Anda memiliki orang.
