INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e147e221-f625-4040-95cb-4ab2cbd0204d', 'この人達、みんな本当によく舌が回るよね。', 'Orang-orang ini banyak bicara, ya?') ON CONFLICT DO NOTHING;
