INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7a2ae5c-72e8-40ad-8f69-dbed2b30e017', '私の母は、いつも静々と機械的に家事をこなしていました。', 'Ibuku selalu mengerjakan pekerjaan rumah dengan tenang dan mekanis.') ON CONFLICT DO NOTHING;
