INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ae8fbeb-e91b-4dd6-8ef6-527feed2925c', '牛にゅうを二カップ加えて、ゆっくりかき回してください。', 'Silakan tambahkan dua cangkir susu dan aduk perlahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ae8fbeb-e91b-4dd6-8ef6-527feed2925c', 'コウイチ君も仲間に加えてあげてよ。', 'Bisakah kamu memasukkan Koichi-kun ke dalam grupmu juga?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ae8fbeb-e91b-4dd6-8ef6-527feed2925c', 'オバマ大統領が作った料理に、塩をひとつまみ加えた。', 'Saya menambahkan sedikit garam ke masakan yang dibuat Presiden Obama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('12dd3868-c43e-47c2-b257-452b9b7b1335', 'vocabulary', '参加', '参加', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ketika Anda berpartisipasi, menambahkan diri Anda sendiri ke dalam aktivitas, itulah partisipasi. Bagus sekali, Anda mendapat bintang emas karena berpartisipasi!', 'Ketika Anda berpartisipasi, menambahkan diri Anda sendiri ke dalam aktivitas, itulah partisipasi. Bagus sekali, Anda mendapat bintang emas karena berpartisipasi!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12dd3868-c43e-47c2-b257-452b9b7b1335', 'Partisipasi', true) ON CONFLICT DO NOTHING;
