INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66f5c3eb-fa33-4d39-ae3d-3e85d3c9c266', '今週の日曜日、摩天楼の見学ツアーに参加します。', 'Saya berpartisipasi dalam tur observasi gedung pencakar langit hari Minggu ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4884f815-8e25-437c-96bd-cd612dd38c52', 'vocabulary', '参加者', '参加者', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Anda tahu bahwa 参加 adalah partisipasi, jadi seseorang yang melakukan partisipasi adalah partisipan.', 'Anda tahu bahwa 参加 adalah partisipasi, jadi seseorang yang melakukan partisipasi adalah partisipan.') ON CONFLICT (id) DO NOTHING;
