INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4884f815-8e25-437c-96bd-cd612dd38c52', '映画好きのパーティーの最年長参加者は、なんと百歳だった。', 'Yang mengejutkan, peserta tertua dalam pesta penonton bioskop tersebut berusia 100 tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0e7cf1a4-872e-473a-a696-8b1bb387dafc', 'vocabulary', '警察官', '警察官', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Pemerintahan polisi (警察) penuh dengan petugas polisi. Ini adalah cara formal untuk mengatakan "petugas polisi". Ini mirip dengan 警官, tetapi memiliki nuansa yang sedikit lebih resmi.', 'Pemerintahan polisi (警察) penuh dengan petugas polisi. Ini adalah cara formal untuk mengatakan "petugas polisi". Ini mirip dengan 警官, tetapi memiliki nuansa yang sedikit lebih resmi.') ON CONFLICT (id) DO NOTHING;
