INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('18b11438-d507-4298-ac94-0cc05ec124f6', 'vocabulary', '手続き', '手続き', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Seseorang memegang tanganmu dan menunjukkan kepadamu cara untuk melanjutkan. "Ini prosedurnya," kata mereka. Gerakkan tanganmu seperti ini. Bagus sekali. Prosedur yang bagus. Bagus!', 'Seseorang memegang tanganmu dan menunjukkan kepadamu cara untuk melanjutkan. "Ini prosedurnya," kata mereka. Gerakkan tanganmu seperti ini. Bagus sekali. Prosedur yang bagus. Bagus!') ON CONFLICT (id) DO NOTHING;
