INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('336279fa-e5c3-44e0-a005-efef0c13e0b5', 'よくそんなに細かい事を覚えていますね。', 'Bagaimana Anda bisa mengingat detail seperti ini?') ON CONFLICT DO NOTHING;
