INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1e7e59ee-f206-4b8f-ac39-c724cc769808', 'vocabulary', '多忙', '多忙', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Jika Anda mempunyai banyak hari sibuk, maka Anda bahkan lebih sibuk dari yang Anda kira!', 'Jika Anda mempunyai banyak hari sibuk, maka Anda bahkan lebih sibuk dari yang Anda kira!') ON CONFLICT (id) DO NOTHING;
