INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f8a77a11-abab-487b-92d5-886e8754f914', '借りた金を早く返すよう警告した。', 'Saya menasihatinya agar dia segera membayar kembali uang yang dipinjamnya.') ON CONFLICT DO NOTHING;
