INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ff8c3871-2e4e-4b9c-b3e3-0594199dba27', 'vocabulary', '達する', '達する', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Anda tahu bahwa 達 berarti mencapai. Jadi, ketika Anda menambahkan する ke dalamnya, Anda menjadikannya kata kerja. Sekarang yang dimaksud adalah mencapai.', 'Anda tahu bahwa 達 berarti mencapai. Jadi, ketika Anda menambahkan する ke dalamnya, Anda menjadikannya kata kerja. Sekarang yang dimaksud adalah mencapai.') ON CONFLICT (id) DO NOTHING;
