INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff8c3871-2e4e-4b9c-b3e3-0594199dba27', '少しおくれたが、無事に目的地に達した。', 'Kami sedikit terlambat, tetapi kami tiba dengan selamat di tujuan.') ON CONFLICT DO NOTHING;
