INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c7be9927-7f89-4a5a-900f-0799b57c59ea', 'vocabulary', '愛人', '愛人', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Orang yang Anda cintai adalah kekasih Anda. Woooh! Jangan khawatir, saya tidak akan memberi tahu. Bersenang-senanglah dan jaga keselamatan, anak-anak.', 'Orang yang Anda cintai adalah kekasih Anda. Woooh! Jangan khawatir, saya tidak akan memberi tahu. Bersenang-senanglah dan jaga keselamatan, anak-anak.') ON CONFLICT (id) DO NOTHING;
