INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e75f968-a394-4071-b307-f9fe345b88f0', 'vocabulary', '対等', '対等', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Tidak masalah apa yang Anda katakan versus persamaan hak. Jika Anda benar-benar ingin segala sesuatunya setara, Anda harus mendukung kesetaraan.', 'Tidak masalah apa yang Anda katakan versus persamaan hak. Jika Anda benar-benar ingin segala sesuatunya setara, Anda harus mendukung kesetaraan.') ON CONFLICT (id) DO NOTHING;
