INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('faebdb28-d728-47cd-9d16-a29a5a6c5afa', '天気予報を事前にチェックするのが面倒くさかったんです。', 'Saya hanya merasa repot untuk memeriksa ramalan cuaca sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('faebdb28-d728-47cd-9d16-a29a5a6c5afa', '天気予報では午後から雨になってたよ。', 'Ramalan cuaca menyebutkan akan turun hujan sore ini.') ON CONFLICT DO NOTHING;
