INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb7b7caa-12d2-4ea8-8194-068b32ad8665', 'vocabulary', '心得る', '心得る', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Ingat bagaimana Anda mengetahui bahwa 心得 berarti "pengetahuan"? Versi kata kerjanya adalah mengetahui. (Kamu mengetahuinya jauh di lubuk hatimu.)', 'Ingat bagaimana Anda mengetahui bahwa 心得 berarti "pengetahuan"? Versi kata kerjanya adalah mengetahui. (Kamu mengetahuinya jauh di lubuk hatimu.)') ON CONFLICT (id) DO NOTHING;
