INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('394eb56e-4106-4292-81e3-0156c263d3b1', 'vocabulary', '愛情', '愛情', 3, '0b9c5d2e-3f4a-1b6c-7d8e-9f0a1b2c3d4e', 'Perasaan cinta yang Anda alami berarti Anda sedang jatuh cinta!', 'Perasaan cinta yang Anda alami berarti Anda sedang jatuh cinta!') ON CONFLICT (id) DO NOTHING;
