INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('394eb56e-4106-4292-81e3-0156c263d3b1', '私の両親は、愛情の深い人たちでした。', 'Orang tua saya adalah orang yang sangat penyayang.') ON CONFLICT DO NOTHING;
