INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('8dfc32e6-6718-46f8-beb6-a79567860a7b', 'c305efc4-4382-4737-bf9c-ef7c4f5b2eec') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5496286c-ba4b-48ba-9e2b-3897fe1b07d0', 'radical', '飛', 'fly', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Radikal ini cukup rumit, namun tidak banyak yang terlihat radikal, jadi Anda beruntung. Ini terlihat seperti semacam benteng terbang raksasa. Lihat baling-baling di belakang saat bergerak ke kiri? Bayangkan saja sesuatu seperti ini terbang di udara. Itu sebabnya radikal ini disebut terbang, karena ia terbang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5496286c-ba4b-48ba-9e2b-3897fe1b07d0', 'Terbang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3c9463db-1f07-4d44-b7fe-57c7aaf5ca58', 'radical', '示', 'jackhammer', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Apakah Anda melihat pegangan di atas dan duri di bawah? Itu benar-benar hebat. Bagaimana Anda bisa mengetahuinya? Dua garis diagonal di samping menunjukkan gerakan jackhammer naik dan turun dengan sangat cepat, melakukan apa yang dilakukan jackhammers. BBBHHRZHHHHRHHRZHZHHZH JUJUJUJUJU.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3c9463db-1f07-4d44-b7fe-57c7aaf5ca58', 'palu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('beee0d98-07eb-4fe6-8e22-f3cfdc34afa2', 'radical', '至', 'mole', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ada sampah di tanah yang sepertinya... bergerak? Jika Anda mengangkat sampah itu, Anda akan menemukan tahi lalat di tanah! Tikus tanah suka menggali di bawah tanah dan mencari barang untuk diambil (seperti sampah). Mereka adalah rakun di tanah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('beee0d98-07eb-4fe6-8e22-f3cfdc34afa2', 'Tahi lalat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0e24fdac-a291-4370-809d-c2554e5080c8', 'radical', '義', 'righteousness', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Tanduk raja. Mereka begitu besar dan menyebabkan raja mempunyai ego. Ego ini memberi raja rasa kebenaran yang tidak seharusnya dia miliki. Yah, menurutku itulah yang dilakukan raja, tapi tanduk itu konyol.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0e24fdac-a291-4370-809d-c2554e5080c8', 'Kebenaran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9c94b223-7a98-4707-b66b-1882bb08c31b', 'radical', '冊', 'bookshelf', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ini terlihat seperti sekumpulan buku di rak. Itu rak buku!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c94b223-7a98-4707-b66b-1882bb08c31b', 'Rak Buku', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a0df31c4-cf13-412c-84fb-aac3a1142b80', 'radical', '圣', 'tombstone', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ada bangku yang mencuat dari tanah. Anda berjalan dan menyadari ada tulisan di atasnya. Sebenarnya itu adalah batu nisan. Anda bisa duduk di atasnya dan mengingat orang-orang yang berada di bawah tanah sekarang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a0df31c4-cf13-412c-84fb-aac3a1142b80', 'Batu Nisan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ea3e3a7f-ec28-45a7-b3f8-a33ab2f9156a', 'radical', '斉', 'simultaneous', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda menulis sambil melihat ke bulan, bisa dipastikan orang lain juga melakukannya. Orang mempunyai kebiasaan memandang bulan secara bersamaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ea3e3a7f-ec28-45a7-b3f8-a33ab2f9156a', 'Serentak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('37502168-b12d-4345-b4f3-b3680e416f72', 'radical', '矛', 'spear', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ibumu membawa semacam senjata rumit. Anda melihat lebih dekat dan melihat bahwa itu adalah tombak. Ujungnya yang lancip ada di sebelah kanan, dan ada beberapa hiasan yang menggantung di sana. Itu tombak yang sangat mewah, dan kamu bertanya-tanya dari mana ibumu mendapatkannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('37502168-b12d-4345-b4f3-b3680e416f72', 'Tombak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('52c63df1-0776-48fa-aefe-74722c9f38cf', 'radical', '次', 'next', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Radikal ini sama dengan kanji. Artinya selanjutnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('52c63df1-0776-48fa-aefe-74722c9f38cf', 'Selanjutnya', true) ON CONFLICT DO NOTHING;
