INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', 'vocabulary', '困る', '困る', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya tertekan dan susah. Versi kata kerjanya adalah menjadi tertekan dan bermasalah.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya tertekan dan susah. Versi kata kerjanya adalah menjadi tertekan dan bermasalah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', 'Menjadi Tertekan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', 'To Be Troubled', false) ON CONFLICT DO NOTHING;
