INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', 'こまる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', 'タンがのどに絡んで困っています。', 'Dahak tersangkut di tenggorokan dan itu mengganggu saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', '日本語を勉強していますが、名詞や助詞などの意味が分からなくて困っています。', 'Saya sedang belajar bahasa Jepang, tetapi saya mendapat masalah karena saya tidak mengerti arti kata benda, partikel, dan sebagainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('72ace959-3185-46f7-afd1-e492b68b6de4', '「どうして遅くまでお店を開けておけないの？」「すみませんが、私に言われても困ります。私はただここで働いているだけなので。」', '"Kenapa kamu tidak tetap buka nanti?" "Maaf, sebenarnya bukan itu panggilanku. Aku hanya bekerja di sini."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('78cc70c5-f658-4159-8771-f9c797749a9c', 'vocabulary', '連続', '連続', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda membawa dan melanjutkan sesuatu, Anda membuat versi serialnya. Ayo ikut sekarang. Oke, lanjutkan! Ayo ikut sekarang. Oke, lanjutkan! Mungkin seperti inilah Lord of the Rings dibuat. Ayo ikut sekarang.', 'Jika Anda membawa dan melanjutkan sesuatu, Anda membuat versi serialnya. Ayo ikut sekarang. Oke, lanjutkan! Ayo ikut sekarang. Oke, lanjutkan! Mungkin seperti inilah Lord of the Rings dibuat. Ayo ikut sekarang.') ON CONFLICT (id) DO NOTHING;
