INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('78cc70c5-f658-4159-8771-f9c797749a9c', 'れんぞく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78cc70c5-f658-4159-8771-f9c797749a9c', 'この乗り放題切ぷは、連続する三日間のみ有こうです。', 'Tiket all-you-can-ride ini dibatasi untuk penggunaan tiga hari berturut-turut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78cc70c5-f658-4159-8771-f9c797749a9c', '朝のニュースは、連続殺人事けんの話で持ち切りでした。', 'Kasus pembunuhan berantai menjadi satu-satunya topik berita pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78cc70c5-f658-4159-8771-f9c797749a9c', '君との人生は本当に驚きの連続だよ。まさか三百六十五日連続で遅刻するなんて思ってもみなかったよ。', 'Hidup bersamamu sungguh penuh kejutan. Saya tidak percaya Anda terlambat bekerja selama 365 hari berturut-turut!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7555b508-a36e-42ef-a4da-0fd637313207', 'vocabulary', '連れる', '連れる', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membawa serta jadi versi vocab verbanya adalah membawa serta.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membawa serta jadi versi vocab verbanya adalah membawa serta.') ON CONFLICT (id) DO NOTHING;
