INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9407a23f-d846-4e32-aac7-48bf93caa9df', 'くらしぶりからして、あの夫妻、相当お金が余ってそうだと思いませんか。', 'Dari cara hidup mereka, sepertinya mereka mempunyai uang yang cukup banyak, bukan?') ON CONFLICT DO NOTHING;
