INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb7b141-d9a8-44be-a26f-1ce304c2961d', '穴じゃく子、倒したのだれ？', 'Siapa yang menjatuhkan sendok berlubang itu?') ON CONFLICT DO NOTHING;
