INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1e26fcc-78fe-434d-9e7a-cfed84b7f62f', '面倒な仕事をおし付けられたと思ったことは、一度もありません。', 'Aku tidak pernah berpikir mereka akan memberiku tugas-tugas yang menyusahkan.') ON CONFLICT DO NOTHING;
