INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1e26fcc-78fe-434d-9e7a-cfed84b7f62f', '今に見てなさい。あのフグ少年はきっと面倒を引き起こすわよ。', 'Tandai kata-kataku. Bocah Fugu itu akan menimbulkan masalah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4e8a3674-e221-4552-acc9-7d2c72da6e27', 'vocabulary', '倒産', '倒産', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika seseorang merobohkan properti Anda, itu akan berakhir dengan kebangkrutan. Sayangnya, tanpa properti Anda pasti akan bangkrut.', 'Jika seseorang merobohkan properti Anda, itu akan berakhir dengan kebangkrutan. Sayangnya, tanpa properti Anda pasti akan bangkrut.') ON CONFLICT (id) DO NOTHING;
