INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1bde5763-9ff8-49cd-b96f-8fc3894b24aa', 'そんざい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bde5763-9ff8-49cd-b96f-8fc3894b24aa', 'そもそも、この町には水害防止対さくが存在していなかったんだよ。', 'Sejak awal, tidak ada tindakan pengendalian banjir di kota ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bde5763-9ff8-49cd-b96f-8fc3894b24aa', 'じゃあ、最初はオゾンそうに穴は存在していなかったんですか？', 'Jadi apakah itu berarti lapisan ozon pada awalnya tidak berlubang?') ON CONFLICT DO NOTHING;
