INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('714ccee2-3a19-40fc-adb8-2b0e33e8bd07', '穴ぐまって、実在するんですね。', 'Luak benar-benar ada, ya?') ON CONFLICT DO NOTHING;
