INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('75db785c-7817-453f-92bf-52b9fb6bbec6', 'vocabulary', '在外', '在外', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ketika Anda berada di luar (di luar apa? Jepang tentunya), Anda berada di luar negeri atau di luar negeri.', 'Ketika Anda berada di luar (di luar apa? Jepang tentunya), Anda berada di luar negeri atau di luar negeri.') ON CONFLICT (id) DO NOTHING;
