INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75db785c-7817-453f-92bf-52b9fb6bbec6', '在外し産はどのようにかん理していますか？', 'Bagaimana Anda mengelola aset Anda di luar negeri?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75db785c-7817-453f-92bf-52b9fb6bbec6', '在外ほう人の安ぴはげん在確にん中です。', 'Kami sedang memeriksa keselamatan warga Jepang di luar negeri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75db785c-7817-453f-92bf-52b9fb6bbec6', '在外投票をする前に、申し込み用紙を日本大使館か日本領事館に提出する必要があります。', 'Sebelum memberikan suara di luar negeri, Anda harus mengajukan permohonan ke kedutaan Jepang atau konsulat Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2c83c94a-9753-4f58-ac75-c4723c6b4fce', 'vocabulary', '夢中', '夢中', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Bahkan di tengah mimpimu, kamu memikirkan bantal tubuhmu. Anda tergila-gila pada mereka, terbungkus dalam daya serap.', 'Bahkan di tengah mimpimu, kamu memikirkan bantal tubuhmu. Anda tergila-gila pada mereka, terbungkus dalam daya serap.') ON CONFLICT (id) DO NOTHING;
