INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c83c94a-9753-4f58-ac75-c4723c6b4fce', '穴をつくろうのに夢中な母のすがたを見て、うれしくなりました。', 'Aku senang melihat ibuku begitu asyik menambal lubang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c83c94a-9753-4f58-ac75-c4723c6b4fce', '皿洗いの男に夢中のウェイトレスのことを好きになってしまったんだ。', 'Saya jatuh cinta dengan seorang pelayan yang tergila-gila dengan mesin pencuci piring.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c83c94a-9753-4f58-ac75-c4723c6b4fce', '「サーモン。あのさ、多分知らなかっただろうけど、高校生の頃、き、きみに夢中だったんだ。」「知ってたわよ。フグ。」', '"Salmon, ya, kamu mungkin tidak mengetahui hal ini, tapi saat SMA, aku, um, tergila-gila padamu." "Aku tahu, Fugu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29dd06c9-50ec-4873-8977-c4ca7a36a0b5', 'vocabulary', '悪夢', '悪夢', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Mimpi buruk juga dikenal sebagai mimpi buruk. Ah! Tidaaaak!', 'Mimpi buruk juga dikenal sebagai mimpi buruk. Ah! Tidaaaak!') ON CONFLICT (id) DO NOTHING;
