INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29dd06c9-50ec-4873-8977-c4ca7a36a0b5', '主役が急病になったんだけど、代役が見つからなくてね。まさに悪夢だったよ。', 'Aktor utama tiba-tiba sakit dan kami tidak dapat menemukan aktor lain untuk menggantikannya. Sungguh mimpi buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29dd06c9-50ec-4873-8977-c4ca7a36a0b5', '太った猫になって歩けないという悪夢を見た。', 'Saya bermimpi buruk bahwa saya berubah menjadi kucing gemuk yang tidak bisa berjalan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29dd06c9-50ec-4873-8977-c4ca7a36a0b5', '腕を胸の前で組んで寝ると悪夢が見れるって聞いたから試したら、朝から晩までひたすらトイレ掃除をずっとしているという夢を見たよ。', 'Saya dengar Anda bisa membuat diri Anda mengalami mimpi buruk jika Anda tidur dengan tangan terlipat di depan dada, jadi saya mencobanya dan saya bermimpi sedang membersihkan toilet tanpa henti dari pagi hingga malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08da321b-1fa6-48d3-8911-fa61e0ddf108', 'vocabulary', '夢', '夢', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
