INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08da321b-1fa6-48d3-8911-fa61e0ddf108', 'あなたは夢を売っているそうですが、一個いくらですか？', 'Saya mendengar bahwa Anda menjual mimpi. Berapa harga satu mimpi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08da321b-1fa6-48d3-8911-fa61e0ddf108', '昨日、コウイチに指圧をしてもらっている夢を見たんだ。', 'Kemarin, saya bermimpi Koichi sedang memijat saya shiatsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08da321b-1fa6-48d3-8911-fa61e0ddf108', '私の夢は漫画家になることです。叶うといいな。', 'Impian saya adalah menjadi seniman manga. Saya harap itu akan menjadi kenyataan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3fb9948f-d5c5-4911-aea2-079618f199e6', 'vocabulary', '妻', '妻', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Namun, sebagian besar ini digunakan untuk merujuk pada istri Anda sendiri.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Namun, sebagian besar ini digunakan untuk merujuk pada istri Anda sendiri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3fb9948f-d5c5-4911-aea2-079618f199e6', 'Istri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3fb9948f-d5c5-4911-aea2-079618f199e6', 'My Wife', false) ON CONFLICT DO NOTHING;
