INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5ddfeca-dbe1-4a82-a53d-605a9712dc0e', 'ビエトとダリンが、水害で飛んだデータをふく元しています。', 'Viet dan Darin sedang memulihkan data yang hilang akibat kerusakan air.') ON CONFLICT DO NOTHING;
