INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29586722-2586-4293-8801-fe7a3f78dc23', '飛行機のチケット、もう取っちゃったんだよね。', 'Saya sudah memesan tiket pesawat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29586722-2586-4293-8801-fe7a3f78dc23', '飛行機でコウイチのとなりの席になった時、めちゃくちゃこうふんしました。', 'Saya sangat bersemangat ketika Koichi duduk di sebelah saya di pesawat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29586722-2586-4293-8801-fe7a3f78dc23', '私は飛行機が苦手なので、一生日本に行けることはないでしょう。', 'Saya tidak suka pesawat terbang, jadi saya tidak akan pernah bisa pergi ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29800ee6-0d32-4f86-b819-9fd7197fa0f0', 'vocabulary', '危機', '危機', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Mesin berbahaya sedang berjalan melalui kota Anda, menghancurkan segalanya. Ini adalah krisis yang sangat besar!', 'Mesin berbahaya sedang berjalan melalui kota Anda, menghancurkan segalanya. Ini adalah krisis yang sangat besar!') ON CONFLICT (id) DO NOTHING;
