INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4484fdc9-8ea3-484b-84fe-f4d9ea5b8d25', 'これから戦時中に犯した罪を告白します。', 'Saya akan mengakui dosa yang saya lakukan selama perang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4484fdc9-8ea3-484b-84fe-f4d9ea5b8d25', '法律を犯してまでするような事じゃないよね。', 'Saya rasa tidak ada gunanya jika kita harus melanggar hukum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4484fdc9-8ea3-484b-84fe-f4d9ea5b8d25', 'ビエトがミスを犯すことなどない。ビエトに不可能は無い。', 'Viet tidak bisa membuat kesalahan. Bagi Vietnam, tidak ada yang mustahil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d4fb9420-3b71-4919-b1ed-15f5ad39ee90', 'vocabulary', '犯人', '犯人', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Orang yang melakukan kejahatan adalah penjahat.', 'Orang yang melakukan kejahatan adalah penjahat.') ON CONFLICT (id) DO NOTHING;
