INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eecbbb3-e162-430c-aba6-67cc5fbd3af2', 'コウイチはワニカニの正確なユーザー数を知りません。', 'Koichi tidak mengetahui jumlah pasti pengguna WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eecbbb3-e162-430c-aba6-67cc5fbd3af2', 'マイケルはコウイチのランチリクエストを正確に記おくし、注文するというにんむを終えました。', 'Michael menyelesaikan misinya untuk menghafal permintaan makan siang Koichi dengan sempurna dan memesannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eecbbb3-e162-430c-aba6-67cc5fbd3af2', '君って、ああ言えばこう言うし、しかも言うことがどれもいちいち正確なのが結構頭にくるんだけど。', 'Sebenarnya, saya cukup kesal melihat Anda membalas segala hal dan betapa akuratnya ucapan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', 'vocabulary', '経つ', '経つ', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda tahu bagaimana 経 berarti berlalunya waktu, bukan? Nah, ini adalah bentuk kata kerjanya. Apa yang dilakukan waktu ketika berlalu? Itu berlalu. Jadi, kata kerja ini berarti lulus atau berlalu.', 'Anda tahu bagaimana 経 berarti berlalunya waktu, bukan? Nah, ini adalah bentuk kata kerjanya. Apa yang dilakukan waktu ketika berlalu? Itu berlalu. Jadi, kata kerja ini berarti lulus atau berlalu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', 'Untuk Lulus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', 'To Elapse', false) ON CONFLICT DO NOTHING;
