INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', '時間が経つのを忘れて、ゲームに夢中になっていました。', 'Saya begitu asyik dengan permainan itu sehingga saya tidak menyadari waktu berlalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', 'トーフグができてから、もう何年経ちましたか？', 'Berapa tahun telah berlalu sejak Tofugu dimulai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4de3724e-a6a4-459e-b5ef-b77950126c6b', '「あいつら、幸せな結婚生活を送れると思う？」「時間が経てばわかるよ。」', '"Apakah menurutmu mereka akan memiliki pernikahan yang bahagia?" "Waktu akan menjawabnya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed84c95b-0857-47e2-a56c-3f80ecfcf3c0', 'vocabulary', '経験', '経験', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Melalui berbagai ujian seiring berjalannya waktu, Anda telah memperoleh banyak pengalaman. Hanya waktu dan pengujian yang diperlukan.', 'Melalui berbagai ujian seiring berjalannya waktu, Anda telah memperoleh banyak pengalaman. Hanya waktu dan pengujian yang diperlukan.') ON CONFLICT (id) DO NOTHING;
