INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ed84c95b-0857-47e2-a56c-3f80ecfcf3c0', 'けいけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed84c95b-0857-47e2-a56c-3f80ecfcf3c0', '私は、飛行機で旅行をした経験がありません。', 'Saya belum pernah punya pengalaman bepergian dengan pesawat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed84c95b-0857-47e2-a56c-3f80ecfcf3c0', '友達を助けようとしたら、今度は非難のほこ先が自分に向いてしまうという経験をしたことがある人はいますか？', 'Adakah orang lain yang pernah mengalami saat Anda mencoba membantu teman dan kemudian Anda malah disalahkan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed84c95b-0857-47e2-a56c-3f80ecfcf3c0', '「そうだ、結婚カウンセリングは試してみたの？」 「もちろん、とっくに経験済みだわよ。でも、上手くいかなかったわ。」', '"Oh! Apakah kamu sudah mencoba konseling pernikahan?" "Tentu saja. Kami sudah mengalaminya sejak lama, tapi hasilnya buruk."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c364c0c-a630-4fd5-ad84-2cf3fa549e61', 'vocabulary', '経験者', '経験者', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Seseorang yang mempunyai pengalaman (経験) adalah orang yang berpengalaman.', 'Seseorang yang mempunyai pengalaman (経験) adalah orang yang berpengalaman.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8c364c0c-a630-4fd5-ad84-2cf3fa549e61', 'Orang Berpengalaman', true) ON CONFLICT DO NOTHING;
