INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c364c0c-a630-4fd5-ad84-2cf3fa549e61', '経験者から、価値あるアドバイスをいただくことができました。', 'Kami bisa mendapatkan nasihat berharga dari orang yang berpengalaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c364c0c-a630-4fd5-ad84-2cf3fa549e61', 'やっぱり経験者はちがうね。', 'Seperti yang Anda harapkan, orang yang berpengalaman itu luar biasa, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c364c0c-a630-4fd5-ad84-2cf3fa549e61', 'コウイチはトーフグに犯罪経験者を雇うと思いますか？', 'Apakah menurut Anda Koichi akan mempekerjakan penjahat berpengalaman di Tofugu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ccdb06c3-c8d6-422d-8f7c-a6e6c1255eca', 'vocabulary', '罪', '罪', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda memiliki rasa bersalah maka Anda telah melakukan dosa atau kejahatan. Kemarilah dan mengaku pada Pastor Koichi.', 'Jika Anda memiliki rasa bersalah maka Anda telah melakukan dosa atau kejahatan. Kemarilah dan mengaku pada Pastor Koichi.') ON CONFLICT (id) DO NOTHING;
