INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ccdb06c3-c8d6-422d-8f7c-a6e6c1255eca', 'マミがコウイチのベーコンを食べた罪は思っている以上に重い。', 'Kejahatan Mami karena memakan bacon Koichi lebih serius dari yang dia kira.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ccdb06c3-c8d6-422d-8f7c-a6e6c1255eca', '私の会社の社長は会計さぎの罪で有罪になった。', 'Presiden perusahaan saya dinyatakan bersalah atas kejahatan penipuan akuntansi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ccdb06c3-c8d6-422d-8f7c-a6e6c1255eca', 'コウイチは罪なき一般市民を殺害した人は雇わないと思うよ。', 'Saya rasa Koichi tidak akan mempekerjakan siapa pun yang melakukan kejahatan pembunuhan warga sipil tak berdosa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a0c9962-8ec2-4990-bc09-776ae63e994d', 'vocabulary', '有罪', '有罪', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Memiliki rasa bersalah berarti bersalah. Ini juga bisa berarti rasa bersalah.', 'Memiliki rasa bersalah berarti bersalah. Ini juga bisa berarti rasa bersalah.') ON CONFLICT (id) DO NOTHING;
