INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a0c9962-8ec2-4990-bc09-776ae63e994d', '犯人には、有罪かつ死けいのはん決が下りました。', 'Penjahat dinyatakan bersalah dan dijatuhi hukuman mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a0c9962-8ec2-4990-bc09-776ae63e994d', '有罪の五名のうち二名は大しん院に上告した。', 'Dua dari lima orang yang bersalah mengajukan banding ke Mahkamah Agung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a0c9962-8ec2-4990-bc09-776ae63e994d', '飲酒運転で有罪になるのはご免なので、運転はできません。', 'Saya tidak bisa mengemudi karena saya akan bersalah karena mengemudi dalam keadaan mabuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c86166cd-17aa-4880-966e-e223899dae9b', 'vocabulary', '犯罪', '犯罪', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda memiliki kejahatan dan Anda memiliki rasa bersalah. Sepertinya Anda melakukan kejahatan itu.', 'Anda memiliki kejahatan dan Anda memiliki rasa bersalah. Sepertinya Anda melakukan kejahatan itu.') ON CONFLICT (id) DO NOTHING;
