INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2af926f6-9e3c-4e45-bf2a-b10defe55250', 'ぎろん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2af926f6-9e3c-4e45-bf2a-b10defe55250', 'コウイチ達は、日本まで飛行機で行くか船で行くかで議論してるんだ。', 'Koichi dan yang lainnya sedang berdiskusi apakah kami harus naik pesawat atau perahu ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2af926f6-9e3c-4e45-bf2a-b10defe55250', 'マイケルが書いた記事は、大いに議論を呼んでいます。', 'Artikel yang ditulis Michael menuai kontroversi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2af926f6-9e3c-4e45-bf2a-b10defe55250', 'コウイチとビエトは、夕飯に何を食べるかについて数時間に渡って議論に議論を重ねたが、結論には至らなかった。', 'Koichi dan Viet berdebat tentang apa yang harus dimakan untuk makan malam selama berjam-jam tanpa mengambil keputusan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'vocabulary', '不思議', '不思議', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ini bukanlah apa yang Anda pikir akan terjadi selama pertimbangan Anda. Anda pikir itu akan sangat normal. Sebaliknya, justru sebaliknya. Penuh keajaiban dan misteri. Luar biasa', 'Ini bukanlah apa yang Anda pikir akan terjadi selama pertimbangan Anda. Anda pikir itu akan sangat normal. Sebaliknya, justru sebaliknya. Penuh keajaiban dan misteri. Luar biasa') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'Bertanya-tanya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'Mystery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'Marvelous', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'ふしぎ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', '休みの日の時間って、不思議と飛ぶようにすぎるよね。', 'Sungguh misteri bagaimana waktu berlalu di hari libur Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', 'ビエトの周りにいると不思議なことがよく起こるよね！この前も列の最後尾にならんでいたのになぜか前の人が次々とゆずってくれるし。', 'Hal-hal menakjubkan sering terjadi ketika saya berada di dekat Viet! Suatu hari, misalnya, kami bergabung di ujung barisan, namun semua orang di depan kami membiarkan kami memotong, satu demi satu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8beb793-e49b-4b03-8b94-af7553ab3f8e', '私達はコウイチをすごく頼りにしていますが、どうしていつもそんなに陽気にしてるのか不思議にも思っています。', 'Kita semua bergantung pada Koichi, tapi kita juga bertanya-tanya mengapa dia tampak begitu ceria sepanjang waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c21c70af-8e31-4374-9b71-d87d277d49e6', 'vocabulary', '困難', '困難', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda tertekan dan itu sulit. Ini cukup berat dan kesulitan yang Anda rasakan.', 'Anda tertekan dan itu sulit. Ini cukup berat dan kesulitan yang Anda rasakan.') ON CONFLICT (id) DO NOTHING;
