INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e80afba8-9dd6-4caa-b383-8031ea6ca2b0', '公園につくと、たくさんのシャボン玉が空を飛んでいました。', 'Saat kami sampai di sebuah taman, banyak sekali gelembung-gelembung yang melayang di udara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e80afba8-9dd6-4caa-b383-8031ea6ca2b0', 'ああ見えて、コウイチはすごく高く飛ぶことができるんだ。', 'Koichi mungkin terlihat tidak mampu melakukan hal seperti itu, tapi dia sebenarnya bisa melompat sangat tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e80afba8-9dd6-4caa-b383-8031ea6ca2b0', 'トーフグの最新のEブックは、飛ぶように売れています。', 'E-book terbaru Tofugu segera beredar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd13b7b6-e883-49f5-9052-97d161556d96', 'vocabulary', '経済', '経済', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Ketika perjalanan waktu berakhir, Anda melihatnya kembali dan melihat seberapa baik Anda melakukannya. Apakah kita menghasilkan lebih banyak uang? Apakah penghasilan kita lebih sedikit? Itu semua ekonomi, sayang (itu uang, sayang!).', 'Ketika perjalanan waktu berakhir, Anda melihatnya kembali dan melihat seberapa baik Anda melakukannya. Apakah kita menghasilkan lebih banyak uang? Apakah penghasilan kita lebih sedikit? Itu semua ekonomi, sayang (itu uang, sayang!).') ON CONFLICT (id) DO NOTHING;
