INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab493a4-b9f8-420c-9b91-83040305cc3a', '判子屋さんで、判子を注文しました。', 'Saya memesan segel pribadi saya di toko segel.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab493a4-b9f8-420c-9b91-83040305cc3a', 'ここにはサイン、そこには判子をおしてください。', 'Silakan tanda tangan di sini dan tempelkan stempel Anda di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab493a4-b9f8-420c-9b91-83040305cc3a', 'この書類には、コウイチによって公的な判子が押されています。', 'Dokumen ini secara resmi disegel oleh Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3af42ca-7e0a-4510-9240-fe709239548d', 'vocabulary', '制服', '制服', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda mengontrol orang, Anda membuat mereka memakai pakaian yang sama. Itu seragam.', 'Jika Anda mengontrol orang, Anda membuat mereka memakai pakaian yang sama. Itu seragam.') ON CONFLICT (id) DO NOTHING;
