INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d23ffe3-7d6f-46b3-a7ae-dd96ef7aff10', 'これは、新制度についての初心者向け案内書です。', 'Buku panduan untuk sistem baru ini ditujukan bagi pemula.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('985edefb-e844-4ff4-9146-d37b86234bba', 'vocabulary', '強制', '強制', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Mereka mempunyai kendali yang kuat atas kita. Itu sebabnya mereka bisa memaksa kita melakukan semua hal wajib ini. Kita harus melakukannya. Mereka terlalu kuat!', 'Mereka mempunyai kendali yang kuat atas kita. Itu sebabnya mereka bisa memaksa kita melakukan semua hal wajib ini. Kita harus melakukannya. Mereka terlalu kuat!') ON CONFLICT (id) DO NOTHING;
