INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('985edefb-e844-4ff4-9146-d37b86234bba', '母は、フグと私がこのアール・デコ様式の建物に引っ越すよう強制しました。', 'Ibu saya memaksa Fugu dan saya pindah ke properti art-deco bersejarah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f353ccb-e403-46c9-ad9e-0336638ad0e5', 'vocabulary', '自制', '自制', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Pengendalian diri adalah pengendalian diri dan pengendalian diri. Miliki beberapa!', 'Pengendalian diri adalah pengendalian diri dan pengendalian diri. Miliki beberapa!') ON CONFLICT (id) DO NOTHING;
