INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('74ec1df2-fd99-4734-844e-a75b747dd649', 'この事務所では、喫煙は認められていません。', 'Merokok tidak diperbolehkan di kantor ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('74ec1df2-fd99-4734-844e-a75b747dd649', 'この事務所には、余計な金はビタ一文も無いんだよ。', 'Tidak ada uang tambahan sepeser pun di kantor ini.') ON CONFLICT DO NOTHING;
