INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c2eb71e4-fbe2-4b08-af0f-3a1201a0cfbf', 'vocabulary', '任務', '任務', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda memiliki tugas. Anda punya tugas. Anda memiliki tugas dan tugas yang harus dilakukan.', 'Anda memiliki tugas. Anda punya tugas. Anda memiliki tugas dan tugas yang harus dilakukan.') ON CONFLICT (id) DO NOTHING;
