INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('085e7d49-6eb5-4910-80e1-698122c1e10a', 'ベンチャー・キャピタル、いわゆる冒険資本が不足するには、わけがあります。', 'Ada alasan mengapa kekurangan modal ventura.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('515b4f6a-eb94-4683-aa65-9947e207d7db', 'vocabulary', '資金', '資金', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Sumber daya emas yang kami miliki adalah dana kami saat ini. Jika sumber dayanya termasuk banyak emas, maka dana kita banyak. Kalau tidak, berarti kita tidak punya banyak dana.', 'Sumber daya emas yang kami miliki adalah dana kami saat ini. Jika sumber dayanya termasuk banyak emas, maka dana kita banyak. Kalau tidak, berarti kita tidak punya banyak dana.') ON CONFLICT (id) DO NOTHING;
