INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('515b4f6a-eb94-4683-aa65-9947e207d7db', '資金が底をつき始めたときに、パリでホテル代を払ってくれるというあの素晴らしいお方にお会いしたのです。', 'Saat kami mulai kehabisan dana, kami bertemu dengan seseorang yang luar biasa di Paris yang menawarkan untuk membayar tagihan hotel kami.') ON CONFLICT DO NOTHING;
