INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('192544c1-0585-444d-b95c-1bbf0077e6ee', '色んな資料が、箱の中で混ぜこぜになっていました。', 'Berbagai bahan tercampur di dalam kotak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('192544c1-0585-444d-b95c-1bbf0077e6ee', 'その警察官は、資料の情報だけで事件を解決してしまった。', 'Petugas polisi telah menyelesaikan kasus ini hanya dengan menggunakan informasi dalam dokumen.') ON CONFLICT DO NOTHING;
