INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c87ede62-9111-4476-b4e0-3fe0b5f9ede9', 'vocabulary', '投資', '投資', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Silakan dan gunakan sumber daya Anda untuk proyek tersebut. Itu bisa menggunakan investasi.', 'Silakan dan gunakan sumber daya Anda untuk proyek tersebut. Itu bisa menggunakan investasi.') ON CONFLICT (id) DO NOTHING;
