INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7089a80e-a4a4-46da-b791-f53522de0ec8', '私たちには反対する権利があります。', 'Kami mempunyai hak untuk menolak.') ON CONFLICT DO NOTHING;
