INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a12f535-3048-4c57-b4e0-99b26fbf8734', '私は経済的に苦しい立場にあるため、週五日フルタイムの仕事をしているうえに、週六日パートタイムでも働いています。', 'Saya bekerja penuh waktu lima hari seminggu dan paruh waktu enam hari seminggu karena saya berada dalam situasi keuangan yang sulit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49a07127-17ce-4bba-b29b-e601dda407db', 'vocabulary', '判断する', '判断する', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', '判断 adalah penilaian. Jadikan itu menjadi kata kerja dan Anda harus menilai, atau menyimpulkan.', '判断 adalah penilaian. Jadikan itu menjadi kata kerja dan Anda harus menilai, atau menyimpulkan.') ON CONFLICT (id) DO NOTHING;
