INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d67c41b-b3a5-458c-a452-2e9a8d2b759c', '子どもたちは両親が不祥事を隠したことを非難した。', 'Anak-anak mengkritik orang tua mereka karena menyembunyikan skandal tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1473bba-09b1-45fa-ab00-d75144ae8dda', 'vocabulary', '倒れる', '倒れる', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda telah melihat bagaimana 倒す berarti "menjatuhkan". Tapi inilah saatnya sesuatu terjatuh dengan sendirinya. Kamu tahu bahwa kamu tidak melakukan apa pun di sini, karena ketika kamu tidak menyentuh semua benda kaca halus ini, sangat jarang (れる) ada sesuatu yang terjatuh (karena kamu tidak menyentuh apa pun, dasar bodoh). Itu juga saat Anda atau orang lain pingsan. Kamu tidak memaksakan diri, kamu malah terjatuh sendiri.', 'Anda telah melihat bagaimana 倒す berarti "menjatuhkan". Tapi inilah saatnya sesuatu terjatuh dengan sendirinya. Kamu tahu bahwa kamu tidak melakukan apa pun di sini, karena ketika kamu tidak menyentuh semua benda kaca halus ini, sangat jarang (れる) ada sesuatu yang terjatuh (karena kamu tidak menyentuh apa pun, dasar bodoh). Itu juga saat Anda atau orang lain pingsan. Kamu tidak memaksakan diri, kamu malah terjatuh sendiri.') ON CONFLICT (id) DO NOTHING;
