INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06b6a1db-c13f-4ff5-829e-cc060c75b2b0', 'フグは、センターオーバーの三塁打をかっ飛ばした。', 'Fugu mengirim tiga kali terbang di atas lapangan tengah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06b6a1db-c13f-4ff5-829e-cc060c75b2b0', '僕の順を飛ばさないでよ！', 'Jangan lewati giliranku!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('602dd1cf-31ec-4ce7-8224-6bb086e530a3', 'vocabulary', '確かめる', '確かめる', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Seperti halnya 確か yang artinya pasti, ini adalah versi kata kerjanya. Jadi ketika Anda "melakukan hal tertentu" Anda akan memastikan sesuatu atau Anda akan memverifikasi sesuatu.', 'Seperti halnya 確か yang artinya pasti, ini adalah versi kata kerjanya. Jadi ketika Anda "melakukan hal tertentu" Anda akan memastikan sesuatu atau Anda akan memverifikasi sesuatu.') ON CONFLICT (id) DO NOTHING;
