INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('17d4f71e-7389-4a2a-9ed5-fdda5d9e7a45', 'けいざいがく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17d4f71e-7389-4a2a-9ed5-fdda5d9e7a45', '経済学のけの字も知らないので、学校に行くことにしたんです。', 'Saya tidak tahu apa-apa tentang ekonomi, jadi saya memutuskan untuk bersekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('971ab652-060b-454f-9194-82f301db6995', 'vocabulary', '断つ', '断つ', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya terpotong jadi versi vocab verbanya adalah terpotong. Jangan bingung dengan 断る yang berarti "menolak". Anda tahu ini harus dihentikan karena つ, yang mengisyaratkan bahwa Anda sudah makan dua (つ) terlalu banyak coklat, dan inilah waktunya untuk menghentikan Anda.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya terpotong jadi versi vocab verbanya adalah terpotong. Jangan bingung dengan 断る yang berarti "menolak". Anda tahu ini harus dihentikan karena つ, yang mengisyaratkan bahwa Anda sudah makan dua (つ) terlalu banyak coklat, dan inilah waktunya untuk menghentikan Anda.') ON CONFLICT (id) DO NOTHING;
