INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('971ab652-060b-454f-9194-82f301db6995', '酔っぱらった時に何をしでかしたかを考慮すると、あなたは絶対にお酒を断つべきですよ。', 'Ingatlah bahwa Anda tidak tahu apa yang dapat Anda lakukan saat mabuk, jadi Anda harus benar-benar berhenti minum alkohol.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a6aef9aa-ac16-4697-b709-d569ba5d4714', 'vocabulary', '経路', '経路', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda melewati jalan tersebut, Anda memikirkan jalan mana yang harus digunakan, kapan menggunakannya, dan pada dasarnya menentukan rute dan jalur yang harus diambil untuk mencapai tujuan Anda.', 'Jika Anda melewati jalan tersebut, Anda memikirkan jalan mana yang harus digunakan, kapan menggunakannya, dan pada dasarnya menentukan rute dan jalur yang harus diambil untuk mencapai tujuan Anda.') ON CONFLICT (id) DO NOTHING;
