INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6aef9aa-ac16-4697-b709-d569ba5d4714', 'このアパートから東大までの一番速くて安い通学経路を教えてください。', 'Apa rute tercepat dan termurah untuk pulang pergi dari apartemen ini ke Universitas Tokyo?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('affc39a1-d718-4e8c-a75d-0ce7e3863601', 'vocabulary', '在留する', '在留する', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika 在留 adalah tempat tinggal, maka versi kata kerjanya adalah tinggal.', 'Jika 在留 adalah tempat tinggal, maka versi kata kerjanya adalah tinggal.') ON CONFLICT (id) DO NOTHING;
