INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('affc39a1-d718-4e8c-a75d-0ce7e3863601', 'ざいりゅうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('affc39a1-d718-4e8c-a75d-0ce7e3863601', '外国人が日本に在留する時に必要になるものは何ですか？', 'Apa saja yang dibutuhkan orang asing saat tinggal di Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a538ad38-03b0-4fcb-8b69-b746033bd793', 'vocabulary', '在留', '在留', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Tempat Anda ditahan adalah tempat Anda berada. Selama Anda berada di tempat ini, ini akan menjadi tempat tinggal Anda. Catatan: pada dasarnya berarti "tempat tinggal" dalam arti yang lebih luas dan merupakan bagian dari kata seperti "kartu tempat tinggal" atau "penduduk asing".', 'Tempat Anda ditahan adalah tempat Anda berada. Selama Anda berada di tempat ini, ini akan menjadi tempat tinggal Anda. Catatan: pada dasarnya berarti "tempat tinggal" dalam arti yang lebih luas dan merupakan bagian dari kata seperti "kartu tempat tinggal" atau "penduduk asing".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a538ad38-03b0-4fcb-8b69-b746033bd793', 'Tempat Tinggal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a538ad38-03b0-4fcb-8b69-b746033bd793', 'ざいりゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a538ad38-03b0-4fcb-8b69-b746033bd793', '日本在留のアメリカ人と友達になりました。', 'Saya berteman dengan seorang Amerika yang tinggal di Jepang.') ON CONFLICT DO NOTHING;
