INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('196043c9-7f12-4897-b51c-e2b44eeb99ef', 'vocabulary', '待機', '待機', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda ingin mesin menunggu sehingga Anda membuatnya waspada. Jika mesin itu adalah komputer Anda, Anda menempatkannya dalam keadaan siaga. Anda hanya ingin itu tetap di sana dan tidak melakukan apa pun sampai Anda siap, itu saja.', 'Anda ingin mesin menunggu sehingga Anda membuatnya waspada. Jika mesin itu adalah komputer Anda, Anda menempatkannya dalam keadaan siaga. Anda hanya ingin itu tetap di sana dan tidak melakukan apa pun sampai Anda siap, itu saja.') ON CONFLICT (id) DO NOTHING;
