INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43f52c7f-4567-4b2a-9b20-e847991b0072', '赤ちゃんが産まれたよ。', 'Bayi kami lahir.') ON CONFLICT DO NOTHING;
