INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43f52c7f-4567-4b2a-9b20-e847991b0072', 'コウイチは、産まれて数時間ですでに話すことができた。', 'Koichi sudah bisa berbicara beberapa jam setelah dilahirkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae000cda-1e7b-40ff-8844-d9f35e4a6103', 'vocabulary', '任す', '任す', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Arti kata ini sama dengan 任せる. Kedua kata tersebut cukup umum, namun 任す sedikit kurang umum dibandingkan 任せる.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae000cda-1e7b-40ff-8844-d9f35e4a6103', 'Untuk Menitipkan Sesuatu', true) ON CONFLICT DO NOTHING;
