INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae000cda-1e7b-40ff-8844-d9f35e4a6103', 'この店のことは全て君の判断に任すよ。', 'Saya akan menyerahkan segalanya tentang toko ini pada penilaian Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae000cda-1e7b-40ff-8844-d9f35e4a6103', '大きな仕事を任されて、うれしいけど少し不安でもある。', 'Aku senang dipercayakan pekerjaan besar, tapi aku juga sedikit gugup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae000cda-1e7b-40ff-8844-d9f35e4a6103', '今回、プロジェクトマネージャーを任されることになった田中です。よろしくお願いします。', 'Saya Tanaka dan saya ditugaskan sebagai manajer proyek. Saya berharap dapat bekerja sama dengan Anda semua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('80e0c4b8-b7a3-40ce-86ac-49c08605af22', 'vocabulary', '経由', '経由', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Anda melewati suatu tempat karena suatu alasan, jadi Anda melewati tempat itu.', 'Anda melewati suatu tempat karena suatu alasan, jadi Anda melewati tempat itu.') ON CONFLICT (id) DO NOTHING;
