INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('80e0c4b8-b7a3-40ce-86ac-49c08605af22', 'けいゆ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e0c4b8-b7a3-40ce-86ac-49c08605af22', '京都に東京経由で行った時です。', 'Saat itulah saya pergi ke Kyoto melalui Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e0c4b8-b7a3-40ce-86ac-49c08605af22', '大阪を経由しても行けますよ。', 'Anda juga bisa pergi melalui Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80e0c4b8-b7a3-40ce-86ac-49c08605af22', '旅館の予約は、インターネット経由で行うのが一番いいと思う。', 'Saya pikir yang terbaik adalah memesan penginapan Anda melalui internet.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'vocabulary', '任せる', '任せる', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Jika Anda menyerahkan suatu tugas kepada seseorang, itu berarti Anda akan mempercayakan sesuatu kepada orang tersebut, atau Anda akan mendelegasikan sesuatu. Dengan kata lain, Anda akan menyerahkan sesuatu kepada mereka, agar mereka melakukannya untuk Anda.', 'Jika Anda menyerahkan suatu tugas kepada seseorang, itu berarti Anda akan mempercayakan sesuatu kepada orang tersebut, atau Anda akan mendelegasikan sesuatu. Dengan kata lain, Anda akan menyerahkan sesuatu kepada mereka, agar mereka melakukannya untuk Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'Untuk Menitipkan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'To Delegate Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'To Leave Something To', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'まかせる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', 'この会社では、若い会社員にも重要な仕事を任せています。', 'Di perusahaan ini, karyawan muda pun diserahi tugas-tugas penting.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', '本当に大事なことなので、他の人には任せられません。', 'Ini sangat penting, jadi tidak bisa diserahkan kepada orang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f13d63d-ecc6-4286-b5aa-4e5d3a819927', '任せることを学ばなければ、自分が大変になりますよ。', 'Jika Anda tidak belajar mendelegasikan, Anda akan mempersulit diri Anda sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', 'vocabulary', 'お任せ', 'お任せ', 3, '1c0d6e3f-4a5b-2c7d-8e9f-0a1b2c3d4e5f', 'Kata ini berasal dari 任せる, tetapi tanpa る di akhir, kata tersebut merupakan kata benda. Anda juga memiliki sebutan kehormatan お di awal, yang merupakan petunjuk bahwa Anda sedang memanggil orang lain. Jadi Anda mempercayakan sesuatu kepada lawan bicara Anda, dan ini berarti menyerahkan keputusan kepada orang lain. Ini banyak digunakan di restoran, yang berarti pilihan koki atau sekadar omakase. Dengan kata lain, Anda menyerahkan pilihan makanan kepada koki.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', 'Menyerahkan Keputusan Pada Orang Lain', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', 'Chef''s Choice', false) ON CONFLICT DO NOTHING;
