INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', 'おまかせ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', 'ヘアスタイルは、お任せでお願いできますか？', 'Bisakah saya menyerahkan keputusan gaya rambut saya kepada Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', '五千円のお任せコースで予約したよ。', 'Saya membuat reservasi untuk omakase spesial 5.000 yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b7ae7d3-baec-4c92-b32b-7b01af5fa36f', '法律の相談は、私共にお任せください！', 'Jika Anda memerlukan nasihat hukum, Anda dapat mengandalkan saya!') ON CONFLICT DO NOTHING;
