INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('96681f7a-f9a7-40f3-b63b-89fd0152fe39', 'radical', '曽', 'mask', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ini terlihat seperti topeng, bukan? Ia bertanduk, matanya gila, dan mulutnya besar. Tak seorang pun akan terlihat seperti ini, itulah sebabnya ini hanyalah topeng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('96681f7a-f9a7-40f3-b63b-89fd0152fe39', 'Masker', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d55245cc-785f-430a-9fb8-78e7b06c939a', 'radical', '角', 'angle', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Radikal ini sama dengan kanji. Artinya sudut.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d55245cc-785f-430a-9fb8-78e7b06c939a', 'Sudut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d945f3df-2474-409a-8c75-331bd28e7c87', 'radical', '刃', 'blade', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Anda memiliki pedang yang ada setetes sesuatu di atasnya. Tetesan itu adalah setetes darah. Tentu saja, pedang akan memotong seseorang hingga menumpahkan darah, tetapi yang Anda perlukan hanyalah pisau apa pun untuk memotong seseorang. Pedang, pisau, apa saja, asalkan bilahnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d945f3df-2474-409a-8c75-331bd28e7c87', 'Pedang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('834f2cf0-a8c7-4e08-9d42-436c2b1594f9', 'radical', '丬', 'icicle', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Es ini berbentuk tongkat. Itu es!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('834f2cf0-a8c7-4e08-9d42-436c2b1594f9', 'Es', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1a6e049c-1a62-421c-b90b-6f1ded853986', 'radical', '直', 'fix', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Radikal ini sama dengan kanji. Artinya memperbaiki.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1a6e049c-1a62-421c-b90b-6f1ded853986', 'Perbaiki', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('25326c26-9554-4494-8578-7e8d18347567', 'radical', '弗', 'dollar', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ini adalah coretan dengan dua garis melewatinya. Hmmm sepertinya familiar bukan? Seharusnya, karena itu simbol dolar: $. Yah, cukup dekat. Lihat saja ini dan pikirkan, ah ya, dolar Amerika yang normal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25326c26-9554-4494-8578-7e8d18347567', 'Dolar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f5949bb5-71aa-4609-b2bc-e6e09c316a04', 'radical', '及', 'escalator', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Apakah Anda ingat tangga (乃)? Radikal ini hampir sama, tetapi ada bagian-bagiannya yang ekstra. Itu masih tangga... tapi lebih rumit. Dan lebih cepat! Itu sebabnya ini adalah eskalator!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f5949bb5-71aa-4609-b2bc-e6e09c316a04', 'Eskalator', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('965b6f4e-d341-4c93-ab37-0c629454d8b6', 'radical', '丩', 'vines', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Radikal ini terdiri dari dua tanaman merambat yang menjuntai ke bawah dan sebuah cabang yang menghubungkan keduanya. Bayangkan berayun dengan gaya Tarzan ini. AaaaAA aAA AAAaaaa!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('965b6f4e-d341-4c93-ab37-0c629454d8b6', 'Tanaman merambat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('c2b8693a-f444-4acc-87b4-f90351db5111', 'radical', '平', 'peace', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Radikal ini sama dengan kanji. Artinya perdamaian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c2b8693a-f444-4acc-87b4-f90351db5111', 'Perdamaian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b92ec8ea-1623-4bfa-97d0-671e4f379ae5', 'radical', '韋', 'korea', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ada lima mulut yang memakan sapi di Korean BBQ. Korea terkenal dengan BBQnya yang lezat, dan Anda membutuhkan banyak orang untuk memakan semua daging sapi tersebut. Setidaknya lima orang. (Paham? Lima orang!) Itu sebabnya yang radikal ini adalah Korea.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b92ec8ea-1623-4bfa-97d0-671e4f379ae5', 'Korea', true) ON CONFLICT DO NOTHING;
