INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0aad0467-670f-4c94-8894-c5a73aef848e', 'ここ5年間、ビエトの一日当たりの飲酒量が増えてきています。', 'Selama lima tahun terakhir, jumlah alkohol harian di Vietnam meningkat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('469b5069-6e37-4e95-8a98-f4ead441be69', 'vocabulary', '増加', '増加', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Peningkatan akan menambah apa yang Anda miliki sebelumnya. Ini adalah peningkatan, penambahan, atau pertumbuhan.', 'Peningkatan akan menambah apa yang Anda miliki sebelumnya. Ini adalah peningkatan, penambahan, atau pertumbuhan.') ON CONFLICT (id) DO NOTHING;
