INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f00cfad-9d3b-42eb-b4ef-2d8da681f46d', 'vocabulary', '急増', '急増', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Peningkatan yang tiba-tiba hanyalah peningkatan atau lonjakan yang tiba-tiba!', 'Peningkatan yang tiba-tiba hanyalah peningkatan atau lonjakan yang tiba-tiba!') ON CONFLICT (id) DO NOTHING;
