INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c73bf935-1ed2-434d-8c02-2fecef9d03ab', 'くつひもが解けているよ。危ないから、早く結んだ方がいいよ。', 'Tali sepatumu terlepas. Itu berbahaya, kamu harus cepat mengikatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0cbda9a4-c9eb-44cf-955a-6a383738ec25', 'vocabulary', '解決', '解決', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Untuk mengatasi masalah tersebut kami memutuskan untuk mencari solusi, cara memecahkan masalah tersebut.', 'Untuk mengatasi masalah tersebut kami memutuskan untuk mencari solusi, cara memecahkan masalah tersebut.') ON CONFLICT (id) DO NOTHING;
