INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cbda9a4-c9eb-44cf-955a-6a383738ec25', 'コウイチはお金で何でも解決できると思っている。', 'Koichi berpikir dia bisa menyelesaikan masalah apa pun dengan uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cbda9a4-c9eb-44cf-955a-6a383738ec25', 'いい解決策が思いつかないんだよね。', 'Saya tidak dapat memberikan solusi yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cbda9a4-c9eb-44cf-955a-6a383738ec25', 'トーフグの株式を上場させる前に、解決しなければならない難題がまだ山積みになっている。', 'Sebelum Tofugu dipublikasikan, banyak masalah sulit yang menumpuk harus diselesaikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4da3274-74a5-4df0-a559-165dba0a0a45', 'vocabulary', '理解', '理解', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Saya telah melepaskan semua alasannya dan membuatnya lebih sederhana, sehingga lebih mudah untuk dipahami. Ini sedikit meningkatkan pemahaman dan pemahaman saya!', 'Saya telah melepaskan semua alasannya dan membuatnya lebih sederhana, sehingga lebih mudah untuk dipahami. Ini sedikit meningkatkan pemahaman dan pemahaman saya!') ON CONFLICT (id) DO NOTHING;
