INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4da3274-74a5-4df0-a559-165dba0a0a45', 'コウイチのアイデアは、いつもみんなの理解をこえています。', 'Ide-ide Koichi selalu di luar pemahaman semua orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4da3274-74a5-4df0-a559-165dba0a0a45', '油と水が混じらないということは理解しています。', 'Saya mengerti bahwa minyak dan air tidak dapat bercampur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4da3274-74a5-4df0-a559-165dba0a0a45', '愛してるよ、ソファー。お前だけは俺のことを理解してくれる。', 'Aku mencintaimu, sofa. Hanya kamu yang mengerti aku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f45a482f-a545-4f1f-af99-b27b243a8366', 'vocabulary', '正解', '正解', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Memang benar Anda telah memecahkan jawabannya, mendapatkan jawaban yang benar. Anda akan sering melihat ini di acara permainan Jepang. 正解!!!!', 'Memang benar Anda telah memecahkan jawabannya, mendapatkan jawaban yang benar. Anda akan sering melihat ini di acara permainan Jepang. 正解!!!!') ON CONFLICT (id) DO NOTHING;
