INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f45a482f-a545-4f1f-af99-b27b243a8366', '正解です！', 'Itu benar!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f45a482f-a545-4f1f-af99-b27b243a8366', 'クイズ大会で難しい問題に正解したので、とてもはなが高いです。', 'Saya berhasil memberikan jawaban yang benar untuk pertanyaan sulit selama kompetisi kuis, jadi saya sangat bangga pada diri saya sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f45a482f-a545-4f1f-af99-b27b243a8366', 'コウイチには内緒にしておいて、正解だったね。', 'Kami benar dalam merahasiakannya dari Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('66205364-0fa0-47fd-9506-66006ca33b54', 'vocabulary', '分解', '分解', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ambil semua bagian yang terpisah. Sekarang lepaskan ikatannya, uraikan hubungan antara kedua bagian tersebut. Dengan cara ini kita bisa melakukan perincian. Kami sedang membongkar atau membongkar sesuatu.', 'Ambil semua bagian yang terpisah. Sekarang lepaskan ikatannya, uraikan hubungan antara kedua bagian tersebut. Dengan cara ini kita bisa melakukan perincian. Kami sedang membongkar atau membongkar sesuatu.') ON CONFLICT (id) DO NOTHING;
