INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66205364-0fa0-47fd-9506-66006ca33b54', 'アルコールの分解を進めてくれます。', 'Ini mendorong pemecahan alkohol.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66205364-0fa0-47fd-9506-66006ca33b54', '小さいころ、よく時計を分解してあそんでいました。', 'Ketika saya masih kecil, saya akan bermain-main dengan jam tangan dengan cara membongkarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66205364-0fa0-47fd-9506-66006ca33b54', '電気分解の分解効率を向上させることはできる、お父さん？', 'Bisakah ayah meningkatkan efisiensi penguraian elektrolisis?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27cfff1e-eb38-4bbf-ac30-b3ea513c0818', 'vocabulary', '実際', '実際', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Peristiwa kebenaran adalah kenyataan. Kata ini juga banyak digunakan sebagai kata keterangan (dengan atau tanpa partikel に) yang berarti sebenarnya atau sungguh.', 'Peristiwa kebenaran adalah kenyataan. Kata ini juga banyak digunakan sebagai kata keterangan (dengan atau tanpa partikel に) yang berarti sebenarnya atau sungguh.') ON CONFLICT (id) DO NOTHING;
