INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27cfff1e-eb38-4bbf-ac30-b3ea513c0818', '今現在、実際にトーフグは何名の顧客を抱えているのですか？', 'Berapa banyak klien yang sebenarnya dimiliki Tofugu saat ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0670e54-184f-4bba-be2e-5eb7f8fc3ce9', 'vocabulary', '国際', '国際', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Anda memiliki kesempatan untuk mengunjungi negara lain. Wow, internasional sekali!', 'Anda memiliki kesempatan untuk mengunjungi negara lain. Wow, internasional sekali!') ON CONFLICT (id) DO NOTHING;
