INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('476e1f65-686a-49c5-af73-a324ca56fd32', 'vocabulary', '認める', '認める', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengenali, jadi versi vocab verbanya adalah mengenali.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengenali, jadi versi vocab verbanya adalah mengenali.') ON CONFLICT (id) DO NOTHING;
