INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('476e1f65-686a-49c5-af73-a324ca56fd32', '認めるのは悔しいけど、今回はフグはいい仕事をしていると思うよ。', 'Saya benci mengakuinya, tapi menurut saya Fugu melakukan pekerjaannya dengan baik kali ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7520a12e-0ff2-46ab-9460-866563b75984', 'vocabulary', '確認', '確認', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Pastikan untuk memastikan bahwa Anda mengenalinya. Perlu konfirmasi dan verifikasi, jadi pastikan kembali ya.', 'Pastikan untuk memastikan bahwa Anda mengenalinya. Perlu konfirmasi dan verifikasi, jadi pastikan kembali ya.') ON CONFLICT (id) DO NOTHING;
