INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f56096fd-b3bc-4923-9c8a-9151d9176bef', 'vocabulary', '寝る', '寝る', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbaring jadi versi vocab verbanya adalah berbaring, namun sebenarnya yang kamu lakukan adalah mencoba untuk tidur.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbaring jadi versi vocab verbanya adalah berbaring, namun sebenarnya yang kamu lakukan adalah mencoba untuk tidur.') ON CONFLICT (id) DO NOTHING;
