INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f56096fd-b3bc-4923-9c8a-9151d9176bef', 'よし、そろそろ寝るね〜。おやすみ〜。また明日〜。', 'Baiklah, aku akan pergi tidur. Tidur nyenyak. Sampai jumpa di pagi hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c5837366-3919-4ddc-9287-92466be1c7f3', 'vocabulary', '昼寝', '昼寝', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Tidur siang adalah tidur yang Anda lakukan di siang hari, disebut juga tidur siang.', 'Tidur siang adalah tidur yang Anda lakukan di siang hari, disebut juga tidur siang.') ON CONFLICT (id) DO NOTHING;
