INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5837366-3919-4ddc-9287-92466be1c7f3', 'コウイチはただ今昼寝中です。おかけになって少々お待ちください。', 'Koichi sedang tidur siang saat ini. Silakan duduk dan tunggu sebentar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00e57a8d-663b-439c-870a-043337bdc8c3', 'vocabulary', '寝不足', '寝不足', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ingat bagaimana 不足 merupakan kekurangan fisik? Nah, sekarang Anda kurang tidur secara fisik. Itu adalah kurang tidur.', 'Ingat bagaimana 不足 merupakan kekurangan fisik? Nah, sekarang Anda kurang tidur secara fisik. Itu adalah kurang tidur.') ON CONFLICT (id) DO NOTHING;
