INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d67146c-5e8d-4c92-87db-87a4df4814ec', '夏が過ぎ、木の葉が色づき初めていた。', 'Musim panas telah berakhir dan dedaunan di pepohonan mulai berubah warna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d67146c-5e8d-4c92-87db-87a4df4814ec', 'トーフグの社員達はみんな、台風が過ぎるのをオフィスで待った。', 'Seluruh karyawan Tofugu menunggu di kantor hingga topan berlalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d67146c-5e8d-4c92-87db-87a4df4814ec', '昨晩は、晩ご飯を食べ過ぎて、どうしても寝られませんでした。', 'Saya tidak bisa tidur tadi malam karena saya makan terlalu banyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('53c7237f-5c98-4dec-b0fc-aad9d76b8118', 'vocabulary', '過去', '過去', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Jika Anda melampaui masa lalu maka Anda akan mundur ke masa lalu (setidaknya jika Anda berasal dari "masa kini".) Jika ini masalahnya, maka Anda pasti berada di masa lalu.', 'Jika Anda melampaui masa lalu maka Anda akan mundur ke masa lalu (setidaknya jika Anda berasal dari "masa kini".) Jika ini masalahnya, maka Anda pasti berada di masa lalu.') ON CONFLICT (id) DO NOTHING;
