INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a01ee165-e15f-46b7-a2b7-c70c3c90210f', 'vocabulary', '置く', '置く', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ketika Anda meletakkan sesuatu yang tidak Anda letakkan begitu saja, Anda harus meletakkan barang tersebut atau bahkan (untuk) meletakkan barang tersebut. Pada dasarnya, Anda harus meletakkan sesuatu pada kata kerja ini. Ini sedikit berbeda dari arti kanji yang Anda pelajari tetapi tidak terlalu berbeda.', 'Ketika Anda meletakkan sesuatu yang tidak Anda letakkan begitu saja, Anda harus meletakkan barang tersebut atau bahkan (untuk) meletakkan barang tersebut. Pada dasarnya, Anda harus meletakkan sesuatu pada kata kerja ini. Ini sedikit berbeda dari arti kanji yang Anda pelajari tetapi tidak terlalu berbeda.') ON CONFLICT (id) DO NOTHING;
