INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a01ee165-e15f-46b7-a2b7-c70c3c90210f', 'フグと私は今距離を置いてるの。', 'Fugu dan aku membuat jarak di antara kami saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0b86d11-0210-459a-8544-d16cff1da3a4', 'vocabulary', '位置', '位置', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Silakan dan beri peringkat pada sesuatu. Yang ini peringkat #1, jadi posisinya naik lebih tinggi. Kemudian Anda memberi peringkat #67 pada sesuatu. Posisinya lebih rendah.', 'Silakan dan beri peringkat pada sesuatu. Yang ini peringkat #1, jadi posisinya naik lebih tinggi. Kemudian Anda memberi peringkat #67 pada sesuatu. Posisinya lebih rendah.') ON CONFLICT (id) DO NOTHING;
