INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8088f1dc-ad53-483d-8fb2-2eae68698768', 'vocabulary', '費用', '費用', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Biaya penggunaan adalah biaya dan biaya yang harus kita bayar, saya khawatir. Jika Anda menggunakan sesuatu, akan ada biaya.', 'Biaya penggunaan adalah biaya dan biaya yang harus kita bayar, saya khawatir. Jika Anda menggunakan sesuatu, akan ada biaya.') ON CONFLICT (id) DO NOTHING;
