INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace7165d-f536-4656-830b-697f7bb5ae68', '私は社費で日本語を勉強させてもらっています。', 'Saya belajar bahasa Jepang dengan biaya perusahaan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd7ebe3f-7040-423f-a261-694612ac4dd3', 'vocabulary', '示す', '示す', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menunjukkan, jadi versi vocab verbanya adalah menunjukkan atau menunjukkan. Ini digunakan dalam konteks seperti "sebuah penelitian menunjukkan bahwa belajar bahasa Jepang itu menyenangkan" dan "Saya menunjukkan kesediaan saya untuk belajar kanji".', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menunjukkan, jadi versi vocab verbanya adalah menunjukkan atau menunjukkan. Ini digunakan dalam konteks seperti "sebuah penelitian menunjukkan bahwa belajar bahasa Jepang itu menyenangkan" dan "Saya menunjukkan kesediaan saya untuk belajar kanji".') ON CONFLICT (id) DO NOTHING;
