INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd7ebe3f-7040-423f-a261-694612ac4dd3', 'このマークは何を示しているんですか？', 'Apa yang ditunjukkan oleh tanda ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd7ebe3f-7040-423f-a261-694612ac4dd3', 'ビエトにメールすると、ワニカニのやみ値を示してくれるらしい。', 'Saya dengar jika Anda mengirim email ke Viet, dia akan menunjukkan nilai pasar gelap WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd7ebe3f-7040-423f-a261-694612ac4dd3', '約束なんてしないで。言葉ではなく行いで示してよ。', 'Jangan berjanji padaku apa pun. Tindakan berbicara lebih keras daripada kata-kata.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4e6efd34-0305-4b48-860d-5b42e76882fc', 'vocabulary', '指示', '指示', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Gunakan jari Anda untuk menunjukkan beberapa hal. Ini adalah instruksi Anda. Oke, lakukan ini (tunjuk), lakukan itu (tunjuk), dan terakhir lakukan ini (tunjuk).', 'Gunakan jari Anda untuk menunjukkan beberapa hal. Ini adalah instruksi Anda. Oke, lakukan ini (tunjuk), lakukan itu (tunjuk), dan terakhir lakukan ini (tunjuk).') ON CONFLICT (id) DO NOTHING;
