INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54c4346d-1434-4b49-975b-ca02648be9a3', 'vocabulary', '観る', '観る', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya pemandangan, jadi apa versi vocab verbanya? Itu untuk melihat atau menonton.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya pemandangan, jadi apa versi vocab verbanya? Itu untuk melihat atau menonton.') ON CONFLICT (id) DO NOTHING;
