INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('94ebf9d7-b903-4f07-bcc3-2f36fee3eac0', 'vocabulary', '観光', '観光', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Mari kita melihat sinar matahari! Oh tunggu, kita tidak bisa melakukan itu di sini. Kita harus pergi jalan-jalan untuk melihat sinar matahari yang menakjubkan ini.', 'Mari kita melihat sinar matahari! Oh tunggu, kita tidak bisa melakukan itu di sini. Kita harus pergi jalan-jalan untuk melihat sinar matahari yang menakjubkan ini.') ON CONFLICT (id) DO NOTHING;
