INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94ebf9d7-b903-4f07-bcc3-2f36fee3eac0', '観光案内のパンフレットありますか？', 'Bolehkah saya minta brosur tamasya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94ebf9d7-b903-4f07-bcc3-2f36fee3eac0', '観光シーズンに京都のホテルを取るのは難しい。', 'Sulit mendapatkan hotel di Kyoto selama musim turis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94ebf9d7-b903-4f07-bcc3-2f36fee3eac0', '歩いて観光する方が好きなんですが、今年は小さい子供がいるので、レンタカーを借りて観光しました。', 'Saya lebih suka jalan-jalan jalan kaki, tapi kami menyewa mobil tahun ini karena kami punya anak kecil.') ON CONFLICT DO NOTHING;
