INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cba768b6-2ef7-4695-9a8b-bfad3dc2be5d', 'vocabulary', '確認する', '確認する', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', '確認 adalah konfirmasi. Jika itu adalah kata kerja, Anda harus mengonfirmasi atau memverifikasi.', '確認 adalah konfirmasi. Jika itu adalah kata kerja, Anda harus mengonfirmasi atau memverifikasi.') ON CONFLICT (id) DO NOTHING;
