INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9df3fe2b-0d1f-461f-a911-d9d6b3f6c96d', 'vocabulary', '吸収', '吸収', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Anda menyedot sesuatu dan mendapatkannya. Sshhhwwwwww! Ketika Anda menyedot sesuatu dan memasukkannya ke dalam tubuh Anda, Anda telah melakukan penyerapan karena benda itu telah tersedot ke dalam diri Anda.', 'Anda menyedot sesuatu dan mendapatkannya. Sshhhwwwwww! Ketika Anda menyedot sesuatu dan memasukkannya ke dalam tubuh Anda, Anda telah melakukan penyerapan karena benda itu telah tersedot ke dalam diri Anda.') ON CONFLICT (id) DO NOTHING;
