INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68b679cc-0517-4aec-88a6-54facb71b77c', 'vocabulary', '収入', '収入', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Silakan masukkan apa yang Anda peroleh di sini. Kami akan membagi semuanya nanti. Tapi kita harus memasukkan semuanya di sini agar kita tahu penghasilan kita.', 'Silakan masukkan apa yang Anda peroleh di sini. Kami akan membagi semuanya nanti. Tapi kita harus memasukkan semuanya di sini agar kita tahu penghasilan kita.') ON CONFLICT (id) DO NOTHING;
