INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81522565-8811-4136-89a2-44b949bea9e8', 'vocabulary', '無職', '無職', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Bila status pekerjaan Anda “tidak ada” maka kemungkinan besar Anda menganggur. Anda mengalami pengangguran.', 'Bila status pekerjaan Anda “tidak ada” maka kemungkinan besar Anda menganggur. Anda mengalami pengangguran.') ON CONFLICT (id) DO NOTHING;
