INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3684d2a5-d6f6-430f-9b05-db5dfe4d35b3', '私の職場には、最新のコンピュータが備えられています。', 'Tempat kerja saya dilengkapi dengan komputer terkini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3684d2a5-d6f6-430f-9b05-db5dfe4d35b3', 'どうやら、職場に私のかくれファンがいるみたいなんです。', 'Rupanya aku punya pengagum rahasia di tempat kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3684d2a5-d6f6-430f-9b05-db5dfe4d35b3', 'もしこの職場に残りたいのなら、物事をたいそうに考える癖を無くしてください。', 'Jika Anda ingin tetap berada di tempat kerja ini, Anda harus menghentikan kebiasaan Anda yang menganggap segala hal sebagai masalah besar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('94099628-6886-4fd8-b414-cb5cad397adf', 'vocabulary', '職業', '職業', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Bisnis pekerjaan Anda adalah pekerjaan Anda. Apa bisnis pekerjaan Anda?', 'Bisnis pekerjaan Anda adalah pekerjaan Anda. Apa bisnis pekerjaan Anda?') ON CONFLICT (id) DO NOTHING;
