INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94099628-6886-4fd8-b414-cb5cad397adf', '彼女の職業はモデルなの？写真写りがとてもいいんね。', 'Apakah pekerjaannya menjadi model? Dia tampil sangat baik di foto.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f9b8a0e6-381b-4670-8bd7-28f5ab392e74', 'vocabulary', '職員', '職員', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Anggota yang bekerja di bisnis Anda adalah personel atau staf Anda. Anda mempekerjakan mereka, jadi mereka adalah personel Anda!', 'Anggota yang bekerja di bisnis Anda adalah personel atau staf Anda. Anda mempekerjakan mereka, jadi mereka adalah personel Anda!') ON CONFLICT (id) DO NOTHING;
