INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c3cffafe-921c-4ad8-8adb-c6c947970299', 'vocabulary', '有職', '有職', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ketika Anda memiliki pekerjaan, Anda mungkin sudah bekerja.', 'Ketika Anda memiliki pekerjaan, Anda mungkin sudah bekerja.') ON CONFLICT (id) DO NOTHING;
