INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e3f3756-ef54-44b1-865e-35a2ab27f70a', 'その国会議員は辞職しないで議員を続けるそうです。', 'Anggota parlemen tidak akan mengundurkan diri dan akan terus menjadi anggota parlemen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e3f3756-ef54-44b1-865e-35a2ab27f70a', 'マミはコウイチのベーコンを食べた罪で辞職に追いこまれた。', 'Mami terpaksa mengundurkan diri karena kejahatan memakan daging Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e3f3756-ef54-44b1-865e-35a2ab27f70a', '上司にはっきりと「あなたの代わりはいくらでもいる」と言われたので、その会社を辞職しました。', 'Bos saya langsung mengatakan kepada saya bahwa saya dapat dibuang, jadi saya keluar dari perusahaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ed4f67d-0c94-4005-ba8c-bf89d8ed075b', 'vocabulary', '教師', '教師', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Seorang ahli mengajar/guru adalah seorang guru.', 'Seorang ahli mengajar/guru adalah seorang guru.') ON CONFLICT (id) DO NOTHING;
