INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc358d00-7803-4ace-8878-abfda8ebc7cf', 'vocabulary', '医師', '医師', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ahli kedokteran adalah seseorang yang mengetahui banyak hal tentang kedokteran. Orang-orang itu (saya harap) umumnya adalah dokter.', 'Ahli kedokteran adalah seseorang yang mengetahui banyak hal tentang kedokteran. Orang-orang itu (saya harap) umumnya adalah dokter.') ON CONFLICT (id) DO NOTHING;
