INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e041904a-6d83-434c-bedb-6969148c906b', 'vocabulary', '一割', '一割', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Satu divisi adalah sepuluh persen. Anda hanya perlu membayangkan ini dalam puluhan yang berlalu. Pasti ada sistem persentase Jepang kuno yang terbawa atau semacamnya. Ingatlah bahwa satu wari bernilai sepuluh persen, dua wari bernilai dua puluh persen, dan seterusnya.', 'Satu divisi adalah sepuluh persen. Anda hanya perlu membayangkan ini dalam puluhan yang berlalu. Pasti ada sistem persentase Jepang kuno yang terbawa atau semacamnya. Ingatlah bahwa satu wari bernilai sepuluh persen, dua wari bernilai dua puluh persen, dan seterusnya.') ON CONFLICT (id) DO NOTHING;
