INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c511865e-f733-4376-ac38-627e1fd22744', 'vocabulary', '現れる', '現れる', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Kanji berarti waktu sekarang, tetapi ketika sesuatu "melakukan waktu sekarang", maka hal itu membuat dirinya dikenal dalam waktu sekarang. Hal ini menunjukkan dirinya sendiri. Ketika hal itu terjadi pada waktu sekarang, hal itu menyebabkannya muncul atau muncul (seperti pada saat ini, pada waktu sekarang).', 'Kanji berarti waktu sekarang, tetapi ketika sesuatu "melakukan waktu sekarang", maka hal itu membuat dirinya dikenal dalam waktu sekarang. Hal ini menunjukkan dirinya sendiri. Ketika hal itu terjadi pada waktu sekarang, hal itu menyebabkannya muncul atau muncul (seperti pada saat ini, pada waktu sekarang).') ON CONFLICT (id) DO NOTHING;
