INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('064fe2e8-fb05-4b8a-8545-01397b538640', 'vocabulary', '呼ぶ', '呼ぶ', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memanggil, jadi versi vocab verbanya adalah memanggil atau memanggil. Seperti dalam "HEI, KAMU!"', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memanggil, jadi versi vocab verbanya adalah memanggil atau memanggil. Seperti dalam "HEI, KAMU!"') ON CONFLICT (id) DO NOTHING;
