INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f489093e-fa2c-410d-a555-f779d1a0c589', 'vocabulary', '違う', '違う', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbeda jadi versi vocab verbanya adalah menjadi berbeda... dan tentu saja, menjadi berbeda juga berarti salah di Jepang. Jangan berbeda!', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbeda jadi versi vocab verbanya adalah menjadi berbeda... dan tentu saja, menjadi berbeda juga berarti salah di Jepang. Jangan berbeda!') ON CONFLICT (id) DO NOTHING;
