INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('179ccca1-b0ed-4a55-9b5e-23b6f7de7745', '五時過ぎにむかえに行きます。', 'Saya akan menjemput Anda segera setelah jam 5.') ON CONFLICT DO NOTHING;
