INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b849fce9-98c0-4abd-9308-785e949fed3d', 'vocabulary', '差す', '差す', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Kanji adalah pembedaan. Membedakan sesuatu memang menyenangkan, tapi ini digunakan lebih seperti menyinari atau menyinari, seperti saat cahaya menyinari seseorang di atas panggung, membedakannya dari orang lain.', 'Kanji adalah pembedaan. Membedakan sesuatu memang menyenangkan, tapi ini digunakan lebih seperti menyinari atau menyinari, seperti saat cahaya menyinari seseorang di atas panggung, membedakannya dari orang lain.') ON CONFLICT (id) DO NOTHING;
