INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ba489da-49fc-49dd-9489-002ef4ffee23', 'vocabulary', '差別', '差別', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Anda membedakan orang-orang dan berdasarkan itu Anda memisahkan orang-orang. Ini mengerikan! Mengapa begitu banyak diskriminasi?', 'Anda membedakan orang-orang dan berdasarkan itu Anda memisahkan orang-orang. Ini mengerikan! Mengapa begitu banyak diskriminasi?') ON CONFLICT (id) DO NOTHING;
