INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('320c57e1-3ab8-466e-b0fc-6eb2e5f4d0f9', 'vocabulary', '限界', '限界', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Batas dunia adalah batasnya. Itu juga batasnya. Anda tidak bisa melampaui batas dunia.', 'Batas dunia adalah batasnya. Itu juga batasnya. Anda tidak bisa melampaui batas dunia.') ON CONFLICT (id) DO NOTHING;
