INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('39b9d684-6e44-41e9-824b-b356594ae53d', 'vocabulary', '限定', '限定', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Batas Anda ditentukan. Di situlah tempatnya. Bagaimanapun, itu adalah batasmu.', 'Batas Anda ditentukan. Di situlah tempatnya. Bagaimanapun, itu adalah batasmu.') ON CONFLICT (id) DO NOTHING;
