INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69df5473-0dca-46ef-a1df-603537471169', 'このクレジットカードの限度額がいくらだったか忘れちゃったんだよね。', 'Saya lupa berapa batas saya pada kartu kredit ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('382de651-fe97-449e-9e6e-64d65b8b9dbb', 'vocabulary', '限る', '限る', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membatasi jadi versi vocab verbanya adalah membatasi.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membatasi jadi versi vocab verbanya adalah membatasi.') ON CONFLICT (id) DO NOTHING;
