INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('382de651-fe97-449e-9e6e-64d65b8b9dbb', 'やっぱり、日本語の勉強はトーフグに限るよ。', 'Lagi pula, tidak ada yang bisa mengalahkan Tofugu dalam hal belajar bahasa Jepang.') ON CONFLICT DO NOTHING;
