INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d23ebe2-6ddc-4ac9-8273-fd13ba8577be', 'vocabulary', '期限', '期限', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Jangka waktu batas waktu adalah jangka waktu atau batas waktu. Ada batasannya, dan batasan itu ditentukan oleh tanggal jatuh tempo.', 'Jangka waktu batas waktu adalah jangka waktu atau batas waktu. Ada batasannya, dan batasan itu ditentukan oleh tanggal jatuh tempo.') ON CONFLICT (id) DO NOTHING;
