INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d23ebe2-6ddc-4ac9-8273-fd13ba8577be', '期限を設けて仕事をしないと、いつまでたっても終わらないと思うんです。', 'Jika kami tidak menetapkan tenggat waktu untuk pekerjaan kami, saya rasa pekerjaan kami tidak akan pernah selesai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d23ebe2-6ddc-4ac9-8273-fd13ba8577be', 'ビザの期限が切れるので、来月日本を出なくてはいけません。', 'Saya harus meninggalkan Jepang bulan depan karena visa saya akan habis masa berlakunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('053b6dde-cb1b-41f8-98b7-a450acf2ab14', 'vocabulary', '無限', '無限', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Batasannya bukanlah apa-apa. Apa? Tidak ada batasan? Artinya, ini tidak akan pernah berhenti! Itu tidak terbatas!', 'Batasannya bukanlah apa-apa. Apa? Tidak ada batasan? Artinya, ini tidak akan pernah berhenti! Itu tidak terbatas!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('053b6dde-cb1b-41f8-98b7-a450acf2ab14', 'Tak terbatas', true) ON CONFLICT DO NOTHING;
