INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fe0ed82-b6ee-4db7-83e6-d72d9522df62', '明日お墓に供える花を、帰りに買ってきてくれない？', 'Bisakah kamu membeli bunga untuk ditaruh di kuburan besok dalam perjalanan pulang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f282c28b-d513-44b9-90d8-31576f2e7537', 'vocabulary', '子供', '子供', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Seorang pelayan anak adalah seorang anak. Lagipula, anak-anak itu seperti pelayan kecil, apa gunanya lagi?', 'Seorang pelayan anak adalah seorang anak. Lagipula, anak-anak itu seperti pelayan kecil, apa gunanya lagi?') ON CONFLICT (id) DO NOTHING;
