INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a504417-3487-45a8-88ca-ee6cc6d63333', 'vocabulary', '吸収する', '吸収する', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Jika 吸収 adalah "penyerapan", versi kata kerjanya adalah menyerap.', 'Jika 吸収 adalah "penyerapan", versi kata kerjanya adalah menyerap.') ON CONFLICT (id) DO NOTHING;
