INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a504417-3487-45a8-88ca-ee6cc6d63333', '全社員が新システムに関する知識を吸収する良い機会です。', 'Ini adalah peluang besar bagi seluruh pekerja untuk menyerap pengetahuan tentang sistem baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c9bf669d-c1e4-4e57-9224-65b1dda2a221', 'vocabulary', '割れる', '割れる', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ingat bagaimana 割る adalah "membagi"? Sekarang Anda sedang mempelajari versi intransitif serupa. Alih-alih Anda melakukan pembagian, ada sesuatu yang justru terbagi. Ini harus dibagi.', 'Ingat bagaimana 割る adalah "membagi"? Sekarang Anda sedang mempelajari versi intransitif serupa. Alih-alih Anda melakukan pembagian, ada sesuatu yang justru terbagi. Ini harus dibagi.') ON CONFLICT (id) DO NOTHING;
