INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9bf669d-c1e4-4e57-9224-65b1dda2a221', '大便がしたくてたまらなかった彼は、ドアを拳で割れるほど強く叩いた。', 'Dia sangat ingin buang air besar hingga dia hampir mendobrak pintu karena menggedor-gedornya dengan tinjunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82f98062-6419-4d52-8740-d0d4cf27688b', 'vocabulary', '割引', '割引', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Bagilah harga itu dan pisahkan. Anda hanya perlu membayar untuk satu bagian! Diskon yang luar biasa.', 'Bagilah harga itu dan pisahkan. Anda hanya perlu membayar untuk satu bagian! Diskon yang luar biasa.') ON CONFLICT (id) DO NOTHING;
