INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82f98062-6419-4d52-8740-d0d4cf27688b', '二割引きの値札が付いてたはずですよ。', 'Saya yakin ada label harga diskon 20%.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82f98062-6419-4d52-8740-d0d4cf27688b', 'ちょうどホームページへ割引クーポンの追加をしようと思ってたところだよ。', 'Saya akan mulai menambahkan kupon diskon ke situs web.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4060c384-55ea-4674-81de-610646832b8b', 'vocabulary', '理解する', '理解する', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', '理解 adalah pemahaman, jadi versi kata kerjanya adalah...? Bagaimana dengan memahami atau memahami? Ya, benarkah?', '理解 adalah pemahaman, jadi versi kata kerjanya adalah...? Bagaimana dengan memahami atau memahami? Ya, benarkah?') ON CONFLICT (id) DO NOTHING;
