INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('24bf5b8c-7792-49ae-a5df-afab5db41306', 'vocabulary', '呼ばれる', '呼ばれる', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Jika 呼ぶ berarti "memanggil" maka ini serupa. Ini adalah saat Anda dipanggil oleh seseorang (dan Anda tidak melakukan panggilan tersebut). Kata ini harus disebut.', 'Jika 呼ぶ berarti "memanggil" maka ini serupa. Ini adalah saat Anda dipanggil oleh seseorang (dan Anda tidak melakukan panggilan tersebut). Kata ini harus disebut.') ON CONFLICT (id) DO NOTHING;
