INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2282f68e-30f5-455c-a60e-09b4dd5d3120', 'vocabulary', '過ごす', '過ごす', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', '過ぎる berarti melampaui... 過ごす berarti menghabiskan waktu untuk... karena alasan tertentu. Saya kira jika Anda melampaui sesuatu atau seseorang, Anda harus meluangkan waktu untuk melakukannya.', '過ぎる berarti melampaui... 過ごす berarti menghabiskan waktu untuk... karena alasan tertentu. Saya kira jika Anda melampaui sesuatu atau seseorang, Anda harus meluangkan waktu untuk melakukannya.') ON CONFLICT (id) DO NOTHING;
