INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dd0b1e32-1a47-4671-9d2c-1f911c5997b7', '現にさっきそう言ったじゃありませんか。', 'Bukankah kamu sebenarnya mengatakan itu beberapa waktu lalu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64d9f8fc-9202-4f2b-8801-847d70ca4695', 'vocabulary', '増す', '増す', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Itu kata kerja lain dengan kanji 増! Yang ini artinya meningkat juga! Tetapi! Ini adalah peningkatan yang tidak disadari, sedangkan 増やす biasanya merupakan peningkatan yang disadari.', 'Itu kata kerja lain dengan kanji 増! Yang ini artinya meningkat juga! Tetapi! Ini adalah peningkatan yang tidak disadari, sedangkan 増やす biasanya merupakan peningkatan yang disadari.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('64d9f8fc-9202-4f2b-8801-847d70ca4695', 'Untuk Meningkatkan', true) ON CONFLICT DO NOTHING;
