INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64d9f8fc-9202-4f2b-8801-847d70ca4695', '砂糖でさらに甘みが増しますよ。', 'Gula akan membuatnya lebih manis, lho.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', 'vocabulary', '間違える', '間違える', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ingat bagaimana 間違い berarti "kesalahan?" Nah ini adalah versi kata kerjanya. Artinya membuat kesalahan, membingungkan, atau membuat kesalahan.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', 'Membuat Kesalahan', true) ON CONFLICT DO NOTHING;
