INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', 'まちがえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', 'こんな簡単な問題を間違えるなんて、悔しいよ。', 'Membuat kesalahan pada pertanyaan sederhana seperti itu sungguh membuat frustrasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', 'すいません、友人と間違えてしまいました。', 'Maaf, saya salah mengira Anda seorang teman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b4a7671-b5c6-40c3-beed-a6069f94f4c0', '間違えて他人の児童手当が私の銀行に振りこまれていたみたいです。', 'Tampaknya tunjangan anak orang lain tidak sengaja disetorkan ke bank saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0cff764c-19bb-49c6-83b8-2fb0aad061fc', 'vocabulary', '優れる', '優れる', 3, '2d1e7f4a-5b6c-3d8e-9f0a-1b2c3d4e5f6a', 'Ini adalah versi kata kerja dari kanji superior, jadi artinya melampaui. Seseorang yang unggul akan selalu mengungguli dan mengungguli orang lain. Itulah yang membuat mereka begitu unggul!', 'Ini adalah versi kata kerja dari kanji superior, jadi artinya melampaui. Seseorang yang unggul akan selalu mengungguli dan mengungguli orang lain. Itulah yang membuat mereka begitu unggul!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0cff764c-19bb-49c6-83b8-2fb0aad061fc', 'Untuk Melampaui', true) ON CONFLICT DO NOTHING;
