INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33605659-d777-45e3-9c98-73610b60ae45', '一億円、そのスーツケースに収まった？', 'Apakah uang seratus juta yen muat di dalam koper?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33605659-d777-45e3-9c98-73610b60ae45', 'アイスを食べたら、感情が収まってきたんだよね。', 'Setelah makan es krim, emosiku mulai tenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33605659-d777-45e3-9c98-73610b60ae45', '皆で大きいピザを五枚食べきりたかったが、食べ放題の時間内に収まらなかった。', 'Kami ingin memakan kelima pizza besar tersebut, tetapi pizza tersebut tidak dapat habis dalam batas waktu makan sepuasnya.') ON CONFLICT DO NOTHING;
