INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4b267cc9-f2ab-48e3-a44b-3b62b2fb14b4', 'radical', '京', 'capital', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya modal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4b267cc9-f2ab-48e3-a44b-3b62b2fb14b4', 'Modal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('818986bb-f28b-43d4-99b3-c107660964e9', 'radical', '友', 'friend', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya teman.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('818986bb-f28b-43d4-99b3-c107660964e9', 'Teman', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('648608ab-f552-4ec2-8c10-001158b559f5', 'radical', '冓', 'lifeguard', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Anda memiliki tugas untuk menyelamatkan dua jenis nyawa. Siapa yang menyelamatkan dua jenis nyawa? Seorang penjaga pantai. Mereka menyelamatkan nyawa orang-orang yang tenggelam, dan kemudian nyawa orang-orang yang mencoba menolong mereka. Bayangkan seorang penjaga pantai menyelamatkan nyawa dua orang sekaligus. Pahlawan yang luar biasa!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('648608ab-f552-4ec2-8c10-001158b559f5', 'Penjaga pantai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d0ea84a6-e84b-40a7-a332-7c773295668b', 'radical', '甫', 'wedding', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini terlihat seperti seseorang yang mengenakan gaun raksasa yang meneteskan air mata. Ini adalah seseorang di pernikahan mereka. Hal ini menjelaskan gaun besar dan air mata (kebahagiaan!) di mata mereka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d0ea84a6-e84b-40a7-a332-7c773295668b', 'Pernikahan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('202b341b-1b28-4866-b586-2cc61d3e941b', 'radical', '両', 'both', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya keduanya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('202b341b-1b28-4866-b586-2cc61d3e941b', 'Keduanya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9aab1b80-dc7f-4830-bac0-0d74afe721dd', 'radical', '召', 'call', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Jika seseorang menaruh pedang di mulutmu, kamu perlu berteriak minta tolong! Panggillah sekeras yang Anda bisa kepada siapa pun di dekat Anda yang mungkin dapat membantu Anda membuat orang ini mengeluarkan pedang dari mulut Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9aab1b80-dc7f-4830-bac0-0d74afe721dd', 'Telepon', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('137c8963-a4e7-4db5-ae7d-cd34d9689593', 'radical', '[comb]', 'comb', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Lihatlah semua hal kecil yang menonjol. Anda bisa dengan mudah menggunakannya untuk menyisir rambut Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('137c8963-a4e7-4db5-ae7d-cd34d9689593', 'Sisir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3b9db1da-f3ce-4d8d-bd11-b086097cea0f', 'radical', '复', 'black-hole', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Saat Anda menembakkan senjata ke matahari, itu menjadi musim dingin. Tembakan yang Anda tembakkan membuat matahari mengalami reaksi berantai yang gila-gilaan, membuatnya meledak dengan sendirinya dan menjadi lubang hitam. Bayangkan hal ini terjadi dan bayangkan keterkejutan yang Anda rasakan. Anda menembak matahari. Anda menyebabkan musim dingin yang tak terbatas ini (dan segera kematian lubang hitam).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3b9db1da-f3ce-4d8d-bd11-b086097cea0f', 'Lubang Hitam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8b424114-523f-488c-b8b8-f7ca10799605', 'radical', '民', 'peoples', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya masyarakat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8b424114-523f-488c-b8b8-f7ca10799605', 'Masyarakat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e20a3b6d-02c9-41e1-b1cf-a71f6fa82f6e', 'radical', '革', 'leather', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Ketika saya melihat radikal ini, saya melihat tubuh dan (terutama) kepala seekor banteng. Banteng terbuat dari apa? Mereka terbuat dari kulit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e20a3b6d-02c9-41e1-b1cf-a71f6fa82f6e', 'Kulit', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f0bd59bb-bdfa-403d-8001-649191ea8094', 'radical', '余', 'surplus', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya surplus.') ON CONFLICT (id) DO NOTHING;
