INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b5ce6e79-fcfd-4709-bdfa-4e56d91a1959', 'vocabulary', '抜く', '抜く', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengekstrak jadi versi vocab verbanya adalah mengekstrak.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengekstrak jadi versi vocab verbanya adalah mengekstrak.') ON CONFLICT (id) DO NOTHING;
