INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a840f424-ada6-4c78-bece-e82e4291fbbd', '最初スピード違反で止められたんだけど、その後飲酒運転で捕まっちゃったんだよ。', 'Awalnya saya hanya dihentikan karena ngebut, tapi akhirnya saya ketahuan karena mengemudi dalam keadaan mabuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4fc495fe-8f26-404f-93d1-b26de2e64078', 'vocabulary', '与える', '与える', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memberi jadi versi vocab verbanya adalah memberi atau mengabulkan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memberi jadi versi vocab verbanya adalah memberi atau mengabulkan.') ON CONFLICT (id) DO NOTHING;
