INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3877e804-1fee-464f-9ea1-9b3c6112ecd9', '「それじゃあ、いくらお金があれば幸せになれるっていうの？」 「う～ん。痛いところを突かれたな。」', '"Kalau begitu, berapa banyak uang yang kamu perlukan untuk menjadi bahagia?" "Ah. Kamu benar-benar bisa menyodok bagianku yang sakit."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3877e804-1fee-464f-9ea1-9b3c6112ecd9', '妻は、急いでいるのに全然話を終わらせようとしない夫の脇腹を、肘で突きました。', 'Sang istri menusuk tulang rusuk suaminya dengan sikunya karena dia sepertinya tidak akan berhenti berbicara sama sekali, dan mereka sedang terburu-buru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dd30e165-69da-4500-9fcc-45c5ef5c92c6', 'vocabulary', '突然', '突然', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Kamu tiba-tiba menusuk alam...kenapa kamu melakukan itu? Tiba-tiba juga... Sekarang alam pasti akan mati!', 'Kamu tiba-tiba menusuk alam...kenapa kamu melakukan itu? Tiba-tiba juga... Sekarang alam pasti akan mati!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dd30e165-69da-4500-9fcc-45c5ef5c92c6', 'Tiba-tiba', true) ON CONFLICT DO NOTHING;
