INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dd30e165-69da-4500-9fcc-45c5ef5c92c6', '突然、猫のお化けが台所に現れて、「ニャーニャーソング」を歌い始めたんだ。', 'Tiba-tiba hantu kucing muncul di dapur saya dan mulai menyanyikan lagu mew-mew.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('badd9a3e-a644-40d7-81a8-c02b26e1d99b', 'vocabulary', '抜ける', '抜ける', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Ingat bagaimana 抜く berarti "mengambil" atau "memetik"? Yang ini harus diekstraksi. Anda tidak melakukan ekstraksi. Mengapa? Karena kamu benar-benar tidak peduli (ける).', 'Ingat bagaimana 抜く berarti "mengambil" atau "memetik"? Yang ini harus diekstraksi. Anda tidak melakukan ekstraksi. Mengapa? Karena kamu benar-benar tidak peduli (ける).') ON CONFLICT (id) DO NOTHING;
