INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('badd9a3e-a644-40d7-81a8-c02b26e1d99b', 'この文では必要な助詞が抜けていますよ。', 'Partikel yang diperlukan hilang dari kalimat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('badd9a3e-a644-40d7-81a8-c02b26e1d99b', 'ビエトがヤクザグループから抜けたいと言ったのは２０２０年の秋のことだった。', 'Pada musim gugur tahun 2020 lalu, Viet menyatakan ingin keluar dari kelompok Yakuza.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('badd9a3e-a644-40d7-81a8-c02b26e1d99b', '最初の放射線療法から十日目に、髪の毛が抜け始めました。', 'Rambut saya mulai rontok sepuluh hari setelah saya memulai terapi radiasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1c55d68-2532-48fd-a593-d06f11d9accf', 'vocabulary', '捕える', '捕える', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Ingat bagaimana Anda belajar 捕まる adalah "ditangkap". Nah ini versi transitifnya, jadi maksudnya menangkap atau menangkap. Saya kira Anda (atau orang lain) yang melakukan penangkapan, dan itu lebih baik daripada menjadi orang yang tertangkap.', 'Ingat bagaimana Anda belajar 捕まる adalah "ditangkap". Nah ini versi transitifnya, jadi maksudnya menangkap atau menangkap. Saya kira Anda (atau orang lain) yang melakukan penangkapan, dan itu lebih baik daripada menjadi orang yang tertangkap.') ON CONFLICT (id) DO NOTHING;
