INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb2ce81-5848-4655-80ce-c2787cc745f2', 'ルーヴル美術館に行った時、モナリザが曲がって掛かっていた。', 'Saat saya pergi ke Louvre, Mona Lisa digantung miring.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bfdedb71-6a4b-40f8-8d2f-8747ed952aab', 'vocabulary', '値段', '値段', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Nilainya ada dalam berbagai langkah. Setiap langkah adalah jumlah yang berbeda, dan setiap jumlah adalah harga atau biaya.', 'Nilainya ada dalam berbagai langkah. Setiap langkah adalah jumlah yang berbeda, dan setiap jumlah adalah harga atau biaya.') ON CONFLICT (id) DO NOTHING;
