INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bfdedb71-6a4b-40f8-8d2f-8747ed952aab', 'テレビとタイアップした書籍を手がけているのは本当だが、まだ値段は決まっていない。', 'Memang benar kami sedang mengerjakan buku terkait TV kami, tapi harganya belum diputuskan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ede9b592-ada6-485c-930e-5302df2e7cd7', 'vocabulary', '怒る', '怒る', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya marah, versi vocab verbanya adalah marah.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya marah, versi vocab verbanya adalah marah.') ON CONFLICT (id) DO NOTHING;
