INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ede9b592-ada6-485c-930e-5302df2e7cd7', '「フグ、どうしてサーモンがお前のことを怒っているのか分からないんだろ？」「うん。さっぱり分からないよ。」「そうだと思ったよ。」', '"Fugu, kamu tidak mengerti kenapa Salmon marah padamu, kan?" "Tidak, aku tidak tahu." "Itulah yang kupikirkan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d6a8d15-bebc-4229-b6df-8b6bb6a8d317', 'vocabulary', '怒鳴る', '怒鳴る', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Kicauan marah adalah sejenis teriakan. Versi kata kerjanya adalah meneriaki.', 'Kicauan marah adalah sejenis teriakan. Versi kata kerjanya adalah meneriaki.') ON CONFLICT (id) DO NOTHING;
