INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d6a8d15-bebc-4229-b6df-8b6bb6a8d317', '「キンニクマってよく怒鳴るよね。」「そうだね。でも、心配しないで。彼は口は悪いけど根は悪い人ではないから。」', '"Kinnikuma banyak berteriak." “Ya, tapi jangan khawatir. Kulitnya lebih buruk daripada gigitannya.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ccdf2ae-d79d-4758-b274-0d8af370c2be', 'vocabulary', '見抜く', '見抜く', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Setiap kali Anda melihat sesuatu, Anda juga mengekstraknya ke mata Anda. Dengan mengekstraksi begitu banyak hal dengan mata Anda, Anda dapat melihat sifat asli sesuatu. Anda dapat melihat hal-hal seperti situasi, kebohongan, dan orang-orang sebagaimana adanya.', 'Setiap kali Anda melihat sesuatu, Anda juga mengekstraknya ke mata Anda. Dengan mengekstraksi begitu banyak hal dengan mata Anda, Anda dapat melihat sifat asli sesuatu. Anda dapat melihat hal-hal seperti situasi, kebohongan, dan orang-orang sebagaimana adanya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ccdf2ae-d79d-4758-b274-0d8af370c2be', 'Untuk Melihat Sifat Asli Sesuatu', true) ON CONFLICT DO NOTHING;
