INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ccdf2ae-d79d-4758-b274-0d8af370c2be', '首藤さんは人の素質を見抜くのがうまいんですよ。', 'Pak Suto pandai melihat sifat asli seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ccdf2ae-d79d-4758-b274-0d8af370c2be', 'うちの母親は父親のウソを見抜くのがうまい。', 'Ibuku pandai melihat kebohongan ayahku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ccdf2ae-d79d-4758-b274-0d8af370c2be', '近ごろ石油の供給が少なくなってきているのは知っていましたが、その理由は見抜けませんでした。', 'Saya tahu bahwa persediaan minyak telah berkurang dalam beberapa tahun terakhir, namun saya tidak dapat mengetahui alasannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0acbf303-4450-47c0-a89d-807d7a3f7cb7', 'vocabulary', '間抜け', '間抜け', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', '抜く adalah mengekstrak. Jika Anda menjauhkan diri Anda dari dunia untuk jangka waktu tertentu, Anda tidak akan belajar apa pun dan menjadi idiot.', '抜く adalah mengekstrak. Jika Anda menjauhkan diri Anda dari dunia untuk jangka waktu tertentu, Anda tidak akan belajar apa pun dan menjadi idiot.') ON CONFLICT (id) DO NOTHING;
