INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0acbf303-4450-47c0-a89d-807d7a3f7cb7', 'まぬけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0acbf303-4450-47c0-a89d-807d7a3f7cb7', '彼に間抜けな田舎者のお上りさんだと思われたくないの。', 'Aku tidak ingin dia menganggapku sebagai anak desa yang bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7a2275a-c9ba-4970-b2aa-105bf87000c0', 'vocabulary', '抜き出す', '抜き出す', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Anda tahu 抜く dari sebelumnya, itu untuk mengekstrak. Kemudian Anda memiliki 出す yang harus dihapus. Jadi, jika Anda mengekstrak dan menghapus sesuatu, Anda bergerak untuk mengekstrak sesuatu. Dengan mengekstraknya, Anda juga akan memilihnya.', 'Anda tahu 抜く dari sebelumnya, itu untuk mengekstrak. Kemudian Anda memiliki 出す yang harus dihapus. Jadi, jika Anda mengekstrak dan menghapus sesuatu, Anda bergerak untuk mengekstrak sesuatu. Dengan mengekstraknya, Anda juga akan memilihnya.') ON CONFLICT (id) DO NOTHING;
