INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7a2275a-c9ba-4970-b2aa-105bf87000c0', '彼は背広から銃をそっと抜き出した。', 'Dia diam-diam mulai mengeluarkan pistol dari setelan bisnisnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41ed9652-cab5-4fea-acd9-d3c82941136c', 'vocabulary', '招く', '招く', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memberi isyarat sehingga versi vocab verbanya adalah memberi isyarat. Bisa juga berarti mengundang atau memanggil juga.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memberi isyarat sehingga versi vocab verbanya adalah memberi isyarat. Bisa juga berarti mengundang atau memanggil juga.') ON CONFLICT (id) DO NOTHING;
