INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6da9a107-e859-49ee-aa28-bb88ac5ef485', 'vocabulary', '退院する', '退院する', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Saatnya mundur dari institusi. Pada dasarnya Anda meninggalkan suatu institusi, khususnya institusi seperti rumah sakit, rumah sakit jiwa, dll. Jika Anda meninggalkan salah satu tempat tersebut, berarti Anda akan dipulangkan.', 'Saatnya mundur dari institusi. Pada dasarnya Anda meninggalkan suatu institusi, khususnya institusi seperti rumah sakit, rumah sakit jiwa, dll. Jika Anda meninggalkan salah satu tempat tersebut, berarti Anda akan dipulangkan.') ON CONFLICT (id) DO NOTHING;
