INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf7506c7-4fc2-4d34-906e-67327818d800', '彼は実際は35歳だが、3歳児と同程度の知能水準しかない。', 'Ia sebenarnya berusia 35 tahun, namun kecerdasannya tidak melebihi anak berusia tiga tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f359abf-dfe3-4986-9111-80f14ee80358', 'vocabulary', '過程', '過程', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Melampaui batas... oke, apa maksudnya? Anda mengetahui sejauh mana kemampuan Anda, dan kemudian Anda melampauinya untuk menjadi lebih baik. Hal ini harus Anda lakukan berulang kali agar bisa terus menjadi lebih baik. Itu adalah proses yang harus dilalui jika Anda ingin menjadi lebih baik dari sekarang.', 'Melampaui batas... oke, apa maksudnya? Anda mengetahui sejauh mana kemampuan Anda, dan kemudian Anda melampauinya untuk menjadi lebih baik. Hal ini harus Anda lakukan berulang kali agar bisa terus menjadi lebih baik. Itu adalah proses yang harus dilalui jika Anda ingin menjadi lebih baik dari sekarang.') ON CONFLICT (id) DO NOTHING;
