INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('94ea81ac-684a-4eee-abd5-dc34c85d67af', 'vocabulary', '痛み止め', '痛み止め', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', '痛み adalah "sakit." 止める berarti "berhenti". Apa yang menghentikan rasa sakit jika Anda menggunakannya? Bagaimana dengan obat penghilang rasa sakit.', '痛み adalah "sakit." 止める berarti "berhenti". Apa yang menghentikan rasa sakit jika Anda menggunakannya? Bagaimana dengan obat penghilang rasa sakit.') ON CONFLICT (id) DO NOTHING;
