INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83393900-2276-4071-bcdf-89e647f1e9cb', '昨日の夜から歯が酷く痛むんですが、診てもらえますか。', 'Saya mengalami sakit gigi yang parah sejak tadi malam, jadi bisakah Anda memeriksanya untuk saya?') ON CONFLICT DO NOTHING;
