INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71c73fbf-0c70-40d0-975d-ac5cb86cada6', 'おい、お前、今の見てたか？俺、今ドリブルで三人のバックを抜いたんだぜ！俺ってば、ほんと、最高！相手チームにあげた眠り薬入りのオレンジジュースがうまく効いてたみたいだな。', 'Apakah kamu melihatnya? Saya baru saja menggiring bola di sekitar tiga pemain bertahan! Akulah orangnya! Jus jeruk dengan obat tidur yang saya berikan kepada tim lain bekerja dengan sempurna!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('499c9547-a21d-4133-8b39-a21c3caa5b3f', 'vocabulary', '道に迷う', '道に迷う', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Ingat 迷う? Artinya "tersesat". Jika Anda tersesat di suatu jalan, Anda tetap tersesat, berkeliaran mencari belokan yang benar. Kata ini berarti tersesat atau tersesat.', 'Ingat 迷う? Artinya "tersesat". Jika Anda tersesat di suatu jalan, Anda tetap tersesat, berkeliaran mencari belokan yang benar. Kata ini berarti tersesat atau tersesat.') ON CONFLICT (id) DO NOTHING;
