INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53cd4695-3cd3-4713-af1e-f5b414beee60', '精神的に病んでいた時、毎日一人で公園をブラブラしていました。', 'Saat aku mengalami gangguan mental, aku berkeliaran tanpa tujuan di sekitar taman sendirian setiap hari.') ON CONFLICT DO NOTHING;
