INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9a615fb7-2d86-451d-b9eb-cf3386608d4d', 'vocabulary', '迷わす', '迷わす', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Kata 迷う berarti "tersesat" tetapi kata ini berarti menyesatkan. Anda melakukan penyesatan terhadap seseorang atau sesuatu yang lain. Anda mengetahui hal ini karena orang tersebut (わす) baik-baik saja sampai Anda datang untuk menyesatkan mereka.', 'Kata 迷う berarti "tersesat" tetapi kata ini berarti menyesatkan. Anda melakukan penyesatan terhadap seseorang atau sesuatu yang lain. Anda mengetahui hal ini karena orang tersebut (わす) baik-baik saja sampai Anda datang untuk menyesatkan mereka.') ON CONFLICT (id) DO NOTHING;
