INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c82d0fe7-65a0-4d76-924a-ed9483536036', 'vocabulary', '成程', '成程', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Jika Anda menyadari sesuatu sampai batas tertentu, Anda akhirnya akan mengatakan Saya mengerti atau Benar! Namun Anda tidak akan melihat jika Anda tidak cukup sadar. Jadi, sejauh itulah pemahaman yang ingin Anda capai sebelum Anda dapat menjawab "Ahh, memang begitu."', 'Jika Anda menyadari sesuatu sampai batas tertentu, Anda akhirnya akan mengatakan Saya mengerti atau Benar! Namun Anda tidak akan melihat jika Anda tidak cukup sadar. Jadi, sejauh itulah pemahaman yang ingin Anda capai sebelum Anda dapat menjawab "Ahh, memang begitu."') ON CONFLICT (id) DO NOTHING;
