INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b406901-229f-41e5-8bf6-9ce7243869c7', 'vocabulary', '居候', '居候', 3, '3e2f8a5b-6c7d-4e9f-0a1b-2b3c4d5e6f7a', 'Untuk tetap hidup di iklim tertentu, beberapa orang tidak punya pilihan selain menjadi pekerja lepas. Artinya, seorang pemondok yang tidak membayar apa pun. Jika Anda tinggal di suatu tempat dengan iklim yang tidak ramah tetapi tidak mampu membayar sewa, satu-satunya pilihan Anda adalah tinggal bersama seseorang secara gratis.', 'Untuk tetap hidup di iklim tertentu, beberapa orang tidak punya pilihan selain menjadi pekerja lepas. Artinya, seorang pemondok yang tidak membayar apa pun. Jika Anda tinggal di suatu tempat dengan iklim yang tidak ramah tetapi tidak mampu membayar sewa, satu-satunya pilihan Anda adalah tinggal bersama seseorang secara gratis.') ON CONFLICT (id) DO NOTHING;
