INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('dc75501c-8983-40a1-b02f-a6fe9d383759', 'radical', '責', 'blame', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Radikal ini sama dengan kanji. Artinya menyalahkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dc75501c-8983-40a1-b02f-a6fe9d383759', 'Salahkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f7ac28ff-5980-45d3-b3d6-5f0151546f5a', 'radical', '奇', 'odd', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Cincin bibir yang besar adalah hal yang cukup aneh untuk dimiliki. Kalau besar, bibirmu akan melebar, dan itu aneh juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f7ac28ff-5980-45d3-b3d6-5f0151546f5a', 'Aneh', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ccdcd0ef-4ee9-401a-b4bc-ad6dbc595c29', 'radical', '良', 'good', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Radikal ini sama dengan kanji. Artinya bagus.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ccdcd0ef-4ee9-401a-b4bc-ad6dbc595c29', 'Bagus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7d5685c4-47ab-499d-a279-bb4e2ad254c7', 'radical', '巩', 'saw', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anda sedang membuat tabel. Di atas meja ada setetes darah, yaitu darahmu. Ini diperoleh dengan memotong diri Anda sendiri dengan gergaji yang Anda gunakan untuk membuat meja. Bayangkan diri Anda terpotong dengan gergaji secara tidak sengaja. Aduh!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7d5685c4-47ab-499d-a279-bb4e2ad254c7', 'Melihat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2b2f5f07-f201-405d-a6a5-d605444758b0', 'radical', '分', 'part', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Radikal ini sama dengan kanji. Artinya bagian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2b2f5f07-f201-405d-a6a5-d605444758b0', 'Bagian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('12898cc5-a239-417d-8b60-3b07b6e5ff2f', 'radical', '啇', 'mohawk', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ada sesuatu yang lama di kepalamu yang sedang berdiri. Benda apa ini? Mohawk yang mengagumkan. Anda sudah memilikinya begitu lama sehingga terlihat cukup tua... tapi masih mengagumkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12898cc5-a239-417d-8b60-3b07b6e5ff2f', 'Mohawk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('84eda1ba-ad4f-441b-a458-0a097901a300', 'radical', '甲', 'turtle-shell', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Penyu yang malang. Kami tidak menyukai mereka di sini. Ini adalah cangkang kura-kura. Lihat cangkangnya yang hanya tersisa satu ekor? Itu satu-satunya hal yang tidak kami keluarkan dari penyu. Itu hanya cangkang yang berekor, jadi pada dasarnya itu hanyalah cangkang kura-kura.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('84eda1ba-ad4f-441b-a458-0a097901a300', 'Cangkang Penyu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f69c113f-62a3-485d-8ddb-06a9949c3a99', 'radical', '成', 'become', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Radikal ini sama dengan kanji. Artinya menjadi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f69c113f-62a3-485d-8ddb-06a9949c3a99', 'Menjadi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7b7670fd-e8d5-43ff-8614-f6dca836d9dc', 'radical', '皿', 'plate', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ini adalah beberapa piring yang dikeringkan di rak. Mereka ditumpuk dalam satu baris. Bayangkan mengulurkan tangan dan mengambil salah satu piring itu untuk Anda sendiri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7b7670fd-e8d5-43ff-8614-f6dca836d9dc', 'Piring', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('71451f05-8c49-4065-a9bd-b3eb0de29336', 'radical', '卬', 'cat-pirate', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Lihat CP di radikal ini? Itu singkatan dari Bajak Laut Kucing. Meoaarrr.') ON CONFLICT (id) DO NOTHING;
