INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('89062fe4-29ed-4e72-a35c-876b5dab8a7a', 'vocabulary', '絶景', '絶景', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Semua hal baik cepat berlalu. Saat pemandangan di depan Anda padam, maka pemandangan itu pun hilang. Tapi, itu indah, menakjubkan, pemandangan yang luar biasa.', 'Semua hal baik cepat berlalu. Saat pemandangan di depan Anda padam, maka pemandangan itu pun hilang. Tapi, itu indah, menakjubkan, pemandangan yang luar biasa.') ON CONFLICT (id) DO NOTHING;
