INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('189df497-de2a-4ee8-a15b-0c009961d4e7', 'vocabulary', '絶望', '絶望', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ketika harapan telah padam, Anda tidak punya harapan lagi, yang ada hanya keputusasaan.', 'Ketika harapan telah padam, Anda tidak punya harapan lagi, yang ada hanya keputusasaan.') ON CONFLICT (id) DO NOTHING;
