INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ae63b0-3236-42a5-b447-3e3117f1c661', '「私の娘は人魚なんだ。」「ええっ、それってつまり、あんた魚と結婚したってことか？」', '"Putriku adalah putri duyung." "Whoa! Berarti kamu menikah dengan ikan?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('efac5b4d-0436-47c1-bdbf-dab3c81d1309', 'vocabulary', '一人娘', '一人娘', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anak perempuan tunggal (一人) adalah anak perempuan yang tidak mempunyai saudara perempuan lain, sehingga menjadikannya anak perempuan satu-satunya.', 'Anak perempuan tunggal (一人) adalah anak perempuan yang tidak mempunyai saudara perempuan lain, sehingga menjadikannya anak perempuan satu-satunya.') ON CONFLICT (id) DO NOTHING;
