INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cdf2633b-b617-4993-a41f-4aa68fd97168', 'vocabulary', '一杯', '一杯', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Satu cangkir cairan sama dengan satu cangkir (atau satu cangkir cairan).', 'Satu cangkir cairan sama dengan satu cangkir (atau satu cangkir cairan).') ON CONFLICT (id) DO NOTHING;
