INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bc9ed53a-7b56-4bd0-b9f1-1ec1d1c9a165', 'vocabulary', '三杯', '三杯', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Tiga cangkir cairan sama dengan tiga cangkir cairan, atau lebih sederhananya, tiga cangkir.', 'Tiga cangkir cairan sama dengan tiga cangkir cairan, atau lebih sederhananya, tiga cangkir.') ON CONFLICT (id) DO NOTHING;
