INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc9ed53a-7b56-4bd0-b9f1-1ec1d1c9a165', 'その時ちょっとへこみ気味だったもんで、ビールを三杯一気飲みしちゃったんだよね。', 'Saya sedang depresi saat itu, jadi saya menenggak tiga gelas bir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('19589e30-fcbf-4c27-bc75-96de75475055', 'vocabulary', '積もる', '積もる', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengumpulkan dan versi kata kerjanya adalah mengumpulkan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengumpulkan dan versi kata kerjanya adalah mengumpulkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('19589e30-fcbf-4c27-bc75-96de75475055', 'Untuk Mengumpulkan', true) ON CONFLICT DO NOTHING;
