INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19589e30-fcbf-4c27-bc75-96de75475055', '体重を減らすために、日常の食事の量を極端に減らす必要はないよ。それよりも、バランスの良い、健康な食事を取ることの方が重要だ。ちりも積もれば山となるって言うじゃないか。', 'Anda tidak perlu secara drastis mengurangi jumlah makanan yang biasa Anda makan untuk menurunkan berat badan. Lebih penting lagi memiliki pola makan yang seimbang dan sehat. Dikatakan bahwa setiap hal kecil berarti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c0e89644-7e9a-48bf-98f0-b70d1d7cc290', 'vocabulary', '面積', '面積', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Permukaan yang terakumulasi menjadi suatu area merupakan area tertentu. Ini ada hubungannya dengan matematika. Saat Anda menjumlahkan semua permukaan dengan mengumpulkannya ke dalam satu perhitungan, Anda mendapatkan luasnya sendiri!', 'Permukaan yang terakumulasi menjadi suatu area merupakan area tertentu. Ini ada hubungannya dengan matematika. Saat Anda menjumlahkan semua permukaan dengan mengumpulkannya ke dalam satu perhitungan, Anda mendapatkan luasnya sendiri!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c0e89644-7e9a-48bf-98f0-b70d1d7cc290', 'Daerah', true) ON CONFLICT DO NOTHING;
