INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c0e89644-7e9a-48bf-98f0-b70d1d7cc290', '彼のおでこの面積は100平方メートルある。', 'Luas keningnya 100 meter persegi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0e723b4-7b17-4339-9bac-151773cb2a52', 'vocabulary', '体積', '体積', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Di dalam tubuh, cairan menumpuk. Bisa berupa badan cangkir, badan ember, atau badan tubuh Anda. Apapun itu, akumulasi tubuh ini mewakili volume cairan dalam tubuh Anda.', 'Di dalam tubuh, cairan menumpuk. Bisa berupa badan cangkir, badan ember, atau badan tubuh Anda. Apapun itu, akumulasi tubuh ini mewakili volume cairan dalam tubuh Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a0e723b4-7b17-4339-9bac-151773cb2a52', 'Jilid', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a0e723b4-7b17-4339-9bac-151773cb2a52', 'たいせき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a0e723b4-7b17-4339-9bac-151773cb2a52', '父さんにガレージの体積を測るように言われたんだけど、理由は知らないよ。何か変だよね。', 'Ayah saya menyuruh saya mengukur volume garasi kami, tapi saya tidak tahu kenapa. Sepertinya agak aneh bagiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9ff83ffb-c024-4b72-a503-4aa0c55d0609', 'vocabulary', '求婚', '求婚', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ketika Anda meminta pernikahan dengan orang lain, Anda sedang melakukan lamaran pernikahan. Maukah kamu menikah denganku, Brad Pitt?', 'Ketika Anda meminta pernikahan dengan orang lain, Anda sedang melakukan lamaran pernikahan. Maukah kamu menikah denganku, Brad Pitt?') ON CONFLICT (id) DO NOTHING;
