INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c8605206-11e6-46db-bd8e-067aea9add82', 'vocabulary', '新婚旅行', '新婚旅行', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anda tahu bahwa 旅行 adalah sebuah perjalanan. Bagian lainnya adalah pernikahan baru. Apa perjalanan yang Anda lakukan setelah menikah baru? Bulan madu!', 'Anda tahu bahwa 旅行 adalah sebuah perjalanan. Bagian lainnya adalah pernikahan baru. Apa perjalanan yang Anda lakukan setelah menikah baru? Bulan madu!') ON CONFLICT (id) DO NOTHING;
