INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2b092515-6406-4517-a749-e7eb0b2bcd99', 'vocabulary', '未婚', '未婚', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Belum menikah? Anda belum menikah. Anda belum menikah.', 'Belum menikah? Anda belum menikah. Anda belum menikah.') ON CONFLICT (id) DO NOTHING;
