INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ffef8401-370c-4dde-9356-8d6a793b8904', 'vocabulary', '更に', '更に', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Kanji dan kata-katanya hampir sama persis, namun bukan sekedar bermakna lagi, namun juga bermakna lebih jauh dan lebih jauh. Ini adalah salah satu kata esai awal paragraf yang bagus, tapi bukan itu satu-satunya kegunaannya!', 'Kanji dan kata-katanya hampir sama persis, namun bukan sekedar bermakna lagi, namun juga bermakna lebih jauh dan lebih jauh. Ini adalah salah satu kata esai awal paragraf yang bagus, tapi bukan itu satu-satunya kegunaannya!') ON CONFLICT (id) DO NOTHING;
