INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ffef8401-370c-4dde-9356-8d6a793b8904', 'この連続殺人事件で更に被害者が出てしまった。', 'Korban lebih lanjut ditemukan dalam insiden pembunuhan berantai ini.') ON CONFLICT DO NOTHING;
