INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ef441681-5744-4799-b12e-82dcea52c191', 'vocabulary', '更生', '更生', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Sekali lagi Anda memiliki kehidupan! Entah ini semacam kelahiran kembali, atau Anda telah menerima penyadaran dan suntikan lain dalam hidup. Apa pun itu, Anda memiliki kehidupan kembali, jadi itu luar biasa!', 'Sekali lagi Anda memiliki kehidupan! Entah ini semacam kelahiran kembali, atau Anda telah menerima penyadaran dan suntikan lain dalam hidup. Apa pun itu, Anda memiliki kehidupan kembali, jadi itu luar biasa!') ON CONFLICT (id) DO NOTHING;
