INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed321b4e-338c-4f0b-8273-fc50886e1aa0', 'vocabulary', '更新', '更新', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Dan lagi-lagi itu menjadi baru! Dulu, tapi sekarang semuanya baik-baik saja. Ini merupakan pembaharuan yang luar biasa.', 'Dan lagi-lagi itu menjadi baru! Dulu, tapi sekarang semuanya baik-baik saja. Ini merupakan pembaharuan yang luar biasa.') ON CONFLICT (id) DO NOTHING;
