INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ed62145-b49b-476c-a8da-46ad07a2077e', '上司に、もっとお互いのメリットを強調するような企画書に変更するように言われました。', 'Bos saya menyuruh saya mengubah proposal bisnis agar lebih menekankan keuntungan bersama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb92e2ac-f40a-4368-be6d-359521cc8622', 'vocabulary', '浮く', '浮く', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melayang jadi versi vocab verbanya adalah melayang.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melayang jadi versi vocab verbanya adalah melayang.') ON CONFLICT (id) DO NOTHING;
