INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f676dcf9-0df4-43da-9faa-8b93b927b51d', 'その浮世絵についてお話をしませんか？', 'Mengapa kita tidak membicarakan tentang ukiyo-e?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f9b68f21-fb52-4c25-8786-8e6d867cd9b6', 'vocabulary', '浮気', '浮気', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Kamu melayang di atas segalanya, setidaknya begitulah yang dirasakan jiwamu. Anda berselingkuh, dan merasa tidak ada yang menarik perhatian Anda, tetapi... tunggu, apa itu? Apakah itu istrimu? Oh tidak...tidak melayang lagi, kamu tidak.', 'Kamu melayang di atas segalanya, setidaknya begitulah yang dirasakan jiwamu. Anda berselingkuh, dan merasa tidak ada yang menarik perhatian Anda, tetapi... tunggu, apa itu? Apakah itu istrimu? Oh tidak...tidak melayang lagi, kamu tidak.') ON CONFLICT (id) DO NOTHING;
