INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9b68f21-fb52-4c25-8786-8e6d867cd9b6', '「彼は浮気をして、それを携帯電話を持っていないあなたのせいにしたってこと？」「要約するとそんなところね。」', '"Jadi dia selingkuh lalu menyalahkanmu karena tidak punya ponsel?" "Itulah ringkasannya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('17006ed7-c093-401d-b677-eeea492d77e7', 'vocabulary', '盗む', '盗む', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencuri, jadi versi vocab verbanya adalah mencuri.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencuri, jadi versi vocab verbanya adalah mencuri.') ON CONFLICT (id) DO NOTHING;
