INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5df175e-c5c3-49ce-8d39-9675eb69a278', 'vocabulary', '盗作', '盗作', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Mencuri apa yang dibuat orang lain? Wow. Bagus sekali. Itu adalah plagiarisme.', 'Mencuri apa yang dibuat orang lain? Wow. Bagus sekali. Itu adalah plagiarisme.') ON CONFLICT (id) DO NOTHING;
