INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b378c15d-dbe6-4c25-ad80-b5f0798008fd', 'vocabulary', '盗品', '盗品', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ini adalah barang curian (mencuri). Jadi, saya akan memberi Anda kesepakatan, karena, Anda tahu, itu adalah barang curian.', 'Ini adalah barang curian (mencuri). Jadi, saya akan memberi Anda kesepakatan, karena, Anda tahu, itu adalah barang curian.') ON CONFLICT (id) DO NOTHING;
