INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bfdea45c-be3b-4f50-8039-42abf0b98096', 'vocabulary', '遊園地', '遊園地', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Taman bermain adalah tempat Anda bermain. Itu menyenangkan. Itu adalah taman hiburan!', 'Taman bermain adalah tempat Anda bermain. Itu menyenangkan. Itu adalah taman hiburan!') ON CONFLICT (id) DO NOTHING;
