INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('190e5323-0f6d-4b01-b35a-89588f827480', 'この職が私にとって適不適かを考えているんですが、まだ答えは出ていません。', 'Aku sudah memikirkan apakah pekerjaan ini cocok untukku atau tidak, tapi aku belum menemukan jawabannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c803dd6d-3658-4dc9-b865-1a206c2b7cb0', 'vocabulary', '絶やす', '絶やす', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '絶える berarti "mati". 絶やす berarti "membunuh". Anda mengetahui hal ini karena jika ada sesuatu yang mati, Anda akan mengatakan "tidak". Tapi jika kamu yang melakukan pembunuhan, kamu akan menjawab ya (やす).', '絶える berarti "mati". 絶やす berarti "membunuh". Anda mengetahui hal ini karena jika ada sesuatu yang mati, Anda akan mengatakan "tidak". Tapi jika kamu yang melakukan pembunuhan, kamu akan menjawab ya (やす).') ON CONFLICT (id) DO NOTHING;
