INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c803dd6d-3658-4dc9-b865-1a206c2b7cb0', '夜の間、火を絶やさないように気をつけるんだぞ。', 'Pastikan api tidak padam pada malam hari.') ON CONFLICT DO NOTHING;
