INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65102a52-19c5-4519-b049-f7d51524423b', 'vocabulary', '除外', '除外', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Kecualikan yang ini dan letakkan di luar apa yang sedang kita pertimbangkan. Ini adalah pengecualian.', 'Kecualikan yang ini dan letakkan di luar apa yang sedang kita pertimbangkan. Ini adalah pengecualian.') ON CONFLICT (id) DO NOTHING;
