INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65102a52-19c5-4519-b049-f7d51524423b', 'その馬はソエにより競争除外となりました。', 'Kuda itu dikeluarkan dari perlombaan karena nyeri tulang kering.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06d1421f-cf8d-45b6-b606-cee1385531a4', 'vocabulary', '幾ら', '幾ら', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ini memiliki arti yang sama dengan kanji, yaitu seberapa besar artinya. Untuk mengingat hal ini, coba pikirkan bagaimana Ra, Dewa Mesir, selalu bertanya, "Berapa biaya untuk membangun piramida ini?" Ugh, terlalu banyak, ayo kita pekerjakan beberapa budak.', 'Ini memiliki arti yang sama dengan kanji, yaitu seberapa besar artinya. Untuk mengingat hal ini, coba pikirkan bagaimana Ra, Dewa Mesir, selalu bertanya, "Berapa biaya untuk membangun piramida ini?" Ugh, terlalu banyak, ayo kita pekerjakan beberapa budak.') ON CONFLICT (id) DO NOTHING;
