INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06d1421f-cf8d-45b6-b606-cee1385531a4', '送料が幾らになるのか教えて頂けませんでしょうか。', 'Bisakah Anda memberi tahu saya berapa biaya pengirimannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('824d4c99-af7d-4fb2-ab4b-5aebe3b6965a', 'vocabulary', '幾つ', '幾つ', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ini memiliki arti yang sama dengan kanji, yaitu berapa banyak artinya. Anda mengetahui hal ini karena Anda bertanya "berapa banyak" dan mereka menjawab "つ." Ini juga bisa digunakan untuk menanyakan berapa umur seseorang, namun umumnya hanya untuk usia anak-anak.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('824d4c99-af7d-4fb2-ab4b-5aebe3b6965a', 'Berapa Banyak', true) ON CONFLICT DO NOTHING;
