INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('824d4c99-af7d-4fb2-ab4b-5aebe3b6965a', 'その小づつみの中にリンゴが幾つ入っているか数えてもらえる？', 'Bisakah Anda menghitung berapa banyak apel yang ada dalam bungkusan itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('824d4c99-af7d-4fb2-ab4b-5aebe3b6965a', '録音に適したマイクを幾つ知っていますか。', 'Berapa banyak mikrofon yang Anda tahu cukup untuk merekam?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('824d4c99-af7d-4fb2-ab4b-5aebe3b6965a', 'おじょうちゃんは幾つかな？', 'Berapa umurmu, gadis kecil?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10043149-f87f-4dbb-8432-833f6c23719c', 'vocabulary', '幾何学', '幾何学', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Berapa banyak? Apa? Di bidang studi ini, Anda sering menanyakan pertanyaan-pertanyaan ini. Bidang studi ini adalah geometri, karena Anda harus bertanya berapa banyak sisi dan berapa luasnya atau apalah (bisakah Anda mengatakan saya tidak ingat matematika?).', 'Berapa banyak? Apa? Di bidang studi ini, Anda sering menanyakan pertanyaan-pertanyaan ini. Bidang studi ini adalah geometri, karena Anda harus bertanya berapa banyak sisi dan berapa luasnya atau apalah (bisakah Anda mengatakan saya tidak ingat matematika?).') ON CONFLICT (id) DO NOTHING;
