INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('550dc968-2550-4294-8300-a82d57e203fb', '「ねえ、聞いてるの？」「あっ、うん。聞いてるよ。ごめん、ごめん。でも、ちょっと気が散っちゃってた。」', '"Hei, apakah kamu mendengarkan?" "Oh ya. Aku mendengarkan. Maaf, maaf, perhatianku hanya teralihkan sebentar."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8cf83139-3e9f-4093-bd8e-caab9e2b5ed8', 'vocabulary', '散歩', '散歩', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Menyebar di sekitar tanah dan berjalan. Saat Anda berjalan tersebar di mana-mana, Anda akan berjalan-jalan atau berjalan-jalan.', 'Menyebar di sekitar tanah dan berjalan. Saat Anda berjalan tersebar di mana-mana, Anda akan berjalan-jalan atau berjalan-jalan.') ON CONFLICT (id) DO NOTHING;
