INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('97b0f325-c6fa-4322-8c0a-550bde4a2d60', 'vocabulary', '解散', '解散', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Lepaskan dan hamburkan semuanya. Hal ini akan menyebabkan tercerai berainya perpecahan, bahkan putusnya apa saja yang terlepas lalu tercerai-berai.', 'Lepaskan dan hamburkan semuanya. Hal ini akan menyebabkan tercerai berainya perpecahan, bahkan putusnya apa saja yang terlepas lalu tercerai-berai.') ON CONFLICT (id) DO NOTHING;
