INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97b0f325-c6fa-4322-8c0a-550bde4a2d60', '私達にとって、衆議院を解散するメリットとデメリットは何ですか？', 'Apa untung dan ruginya pembubaran DPR?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97b0f325-c6fa-4322-8c0a-550bde4a2d60', 'みんな、応援ありがとう！今日でトーフグバンドは解散するけど、みんなとライブで作った思い出は一生大切にするから！', 'Terima kasih atas dukungannya, semuanya! Band Tofugu bubar hari ini, tapi aku akan selamanya menghargai kenangan yang kubuat bersama kalian di acara itu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97b0f325-c6fa-4322-8c0a-550bde4a2d60', 'トイレにこもっているうちに飲み会は解散しちまったぜ。', 'Pesta minum bubar saat Anda terjebak di kamar mandi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e8d3ef9-4125-41e2-8941-9b47f6aeaee6', 'vocabulary', '似る', '似る', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menyerupai jadi versi vocab verbanya adalah menyerupai atau terlihat seperti.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menyerupai jadi versi vocab verbanya adalah menyerupai atau terlihat seperti.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e8d3ef9-4125-41e2-8941-9b47f6aeaee6', 'Menyerupai', true) ON CONFLICT DO NOTHING;
