INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e8d3ef9-4125-41e2-8941-9b47f6aeaee6', '最初はお母さんに似ていると思っていたけど、だんだんお父さんにも似てきたね！', 'Awalnya kupikir dia mirip ibunya, tapi kemudian dia mulai mirip ayahnya juga!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e8d3ef9-4125-41e2-8941-9b47f6aeaee6', 'このズボン、私がずっと探してたズボンに似てる。', 'Celana ini sepertinya yang sudah lama saya cari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e8d3ef9-4125-41e2-8941-9b47f6aeaee6', 'お前が彼女の兄貴だって？嘘つけ！全然似てないじゃねえか。', 'Apakah kamu memberitahuku bahwa kamu adalah saudara laki-lakinya? Pembohong! Kalian tidak mirip satu sama lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b883150b-341c-42b4-9cf4-3e0895352efa', 'vocabulary', '真似', '真似', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anda mengambil kenyataan dan mencoba menyerupainya. Untuk melakukan ini, Anda harus melakukan peniruan identitas, mimikri, atau peniruan.', 'Anda mengambil kenyataan dan mencoba menyerupainya. Untuk melakukan ini, Anda harus melakukan peniruan identitas, mimikri, atau peniruan.') ON CONFLICT (id) DO NOTHING;
