INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('476e5257-f108-4dcb-b83b-870f4b0f3b64', 'あ、もうこんな時間。子供を迎えに行かなくちゃ。', 'Oh, ini sudah terlambat. Aku harus pergi menjemput anak-anak.') ON CONFLICT DO NOTHING;
