INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('62ca09ff-c0d1-4c85-ac97-c288ab27f989', 'うちの家族には、六世代に渡って先祖代々受け継がれてきた特別なおむつがあります。', 'Keluarga kami memiliki popok khusus yang diturunkan dari ayah ke anak selama enam generasi.') ON CONFLICT DO NOTHING;
