INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('422b5c1a-d984-47f2-84f6-a902714037ce', 'vocabulary', '込む', '込む', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya ramai dan versi vocab verbanya berarti ramai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya ramai dan versi vocab verbanya berarti ramai.') ON CONFLICT (id) DO NOTHING;
