INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c23c31e7-137b-4f8a-a173-64d5a7ad9f5b', 'vocabulary', '欲しい', '欲しい', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari keinginan? Itu juga diinginkan.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari keinginan? Itu juga diinginkan.') ON CONFLICT (id) DO NOTHING;
