INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c23c31e7-137b-4f8a-a173-64d5a7ad9f5b', '「欲しいものを買っていいよ。金額の制限は無しだよ。」「まあ！熱でもあるの？ 何かあったの？」', '“Kamu bisa membeli apapun yang kamu mau. Uang tidak ada batasnya.” "Wow! Apakah kamu demam? Ada apa denganmu?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45103f53-10d7-4943-a148-2c448f181c45', 'vocabulary', '欲求', '欲求', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Apa yang Anda inginkan dan minta adalah keinginan Anda, keinginan Anda, mungkin keinginan Anda. Anda menginginkan hal-hal ini sehingga Anda memintanya. Saya menginginkannya!', 'Apa yang Anda inginkan dan minta adalah keinginan Anda, keinginan Anda, mungkin keinginan Anda. Anda menginginkan hal-hal ini sehingga Anda memintanya. Saya menginginkannya!') ON CONFLICT (id) DO NOTHING;
