INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac73eaaf-585e-4a6a-b0dc-40b1f52c4607', 'どうしてキリスト教徒と仏教徒の中には、肉欲を罪深いものだとして否定する人がいるのですか。', 'Mengapa sebagian umat Kristiani dan Budha menyangkal keinginan daging mereka seolah-olah itu adalah sesuatu yang berdosa?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c7b2ba33-2adf-4de4-8691-0184cd639625', 'vocabulary', '食欲', '食欲', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Saya ingin makanan. Ketika saya ingin makan (atau ketika saya tidak ingin makan), itu ada hubungannya dengan nafsu makan Anda.', 'Saya ingin makanan. Ketika saya ingin makan (atau ketika saya tidak ingin makan), itu ada hubungannya dengan nafsu makan Anda.') ON CONFLICT (id) DO NOTHING;
