INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('47ece077-56ed-487a-90cb-8b76a23b0659', 'vocabulary', '越す', '越す', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melampaui, jadi versi vocab verbanya juga melampaui.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melampaui, jadi versi vocab verbanya juga melampaui.') ON CONFLICT (id) DO NOTHING;
