INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47ece077-56ed-487a-90cb-8b76a23b0659', 'どうすればNBA選手のように身長が6.5フィートを越すのでしょうか。今、6フィートなのですが、6.5を越したいのです。', 'Bagaimana saya bisa lebih tinggi dari 6,5 kaki seperti pemain NBA? Tinggi saya sekarang 6 kaki dan saya ingin melampaui 6,5 kaki.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('789dccc8-a77d-4433-a8bf-28d143e690db', 'vocabulary', '浮かれる', '浮かれる', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '浮く berarti "mengambang", dan 浮かれる mengacu pada metafora "mengambang" yang berarti bahagia, bersemangat, atau gembira. Kita mempunyai metafora yang sama dalam bahasa Inggris - bayangkan berada "di awan sembilan".', '浮く berarti "mengambang", dan 浮かれる mengacu pada metafora "mengambang" yang berarti bahagia, bersemangat, atau gembira. Kita mempunyai metafora yang sama dalam bahasa Inggris - bayangkan berada "di awan sembilan".') ON CONFLICT (id) DO NOTHING;
