INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d5f4703d-d920-4784-bf8c-b683652586ae', 'vocabulary', '散歩する', '散歩する', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '散歩 adalah "berjalan-jalan." Jadikan itu menjadi kata kerja dan Anda harus berjalan-jalan atau berjalan-jalan.', '散歩 adalah "berjalan-jalan." Jadikan itu menjadi kata kerja dan Anda harus berjalan-jalan atau berjalan-jalan.') ON CONFLICT (id) DO NOTHING;
