INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5f4703d-d920-4784-bf8c-b683652586ae', '妻が、今日は早目に仕事を切り上げて犬の散歩をしてほしいと言っているのですが、よろしいでしょうか。', 'Istri saya ingin saya pulang kerja lebih awal dan mengajak anjing jalan-jalan hari ini. Apakah kamu baik-baik saja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a97f1012-6f5a-4548-9da4-f602f09a0e69', 'vocabulary', '除いて', '除いて', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '除く adalah "mengecualikan." Ini adalah bentuk te, dan artinya "kecuali". Jadi, seperti "tolong beli semuanya kecuali brokoli", karena siapa yang mau brokoli?', '除く adalah "mengecualikan." Ini adalah bentuk te, dan artinya "kecuali". Jadi, seperti "tolong beli semuanya kecuali brokoli", karena siapa yang mau brokoli?') ON CONFLICT (id) DO NOTHING;
