INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2e8bad9-aa50-41e6-8228-5fb3d8f2ab21', 'vocabulary', '物真似', '物真似', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '真似 adalah "peniruan identitas." Sebenarnya kata ini juga demikian. Itu juga merupakan peniruan identitas.', '真似 adalah "peniruan identitas." Sebenarnya kata ini juga demikian. Itu juga merupakan peniruan identitas.') ON CONFLICT (id) DO NOTHING;
