INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('18abaa3b-f33c-498d-9d9b-714f97f50762', 'vocabulary', '恐れる', '恐れる', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya takut, jadi versi verbanya adalah takut.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya takut, jadi versi verbanya adalah takut.') ON CONFLICT (id) DO NOTHING;
