INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('939ee63a-7721-45e4-a14f-ade88d67d8e5', 'それじゃあ2人組を作って、トラックに七面鳥を積み始めて下さい。', 'Sekarang silakan ambil rekan dan mulai memuat truk dengan kalkun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('11d6ee12-a1b8-4dcf-8c7b-82c6f7eaf66e', 'vocabulary', '似合う', '似合う', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Itu mirip denganmu! Itu cocok untukmu! Wah, ketampananmu memang membuat syal ini cocok untukmu lho?', 'Itu mirip denganmu! Itu cocok untukmu! Wah, ketampananmu memang membuat syal ini cocok untukmu lho?') ON CONFLICT (id) DO NOTHING;
