INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('11d6ee12-a1b8-4dcf-8c7b-82c6f7eaf66e', 'そのワンピには絶対デニムのジャケットが似合うと思うよ。', 'Menurutku jaket denim akan sangat cocok dengan gaunmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2c04961-cf9b-483c-92c5-4d75fada4806', 'vocabulary', '散らかす', '散らかす', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '散る berarti "tersebar." Ini adalah saat Anda melakukan hamburan. Anda tahu itu karena Anda menyebabkan keributan (らかす) dari semua penghamburan uang yang Anda lakukan, pada orang-orang di bawah.', '散る berarti "tersebar." Ini adalah saat Anda melakukan hamburan. Anda tahu itu karena Anda menyebabkan keributan (らかす) dari semua penghamburan uang yang Anda lakukan, pada orang-orang di bawah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a2c04961-cf9b-483c-92c5-4d75fada4806', 'Untuk Menyebarkan', true) ON CONFLICT DO NOTHING;
