INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2c04961-cf9b-483c-92c5-4d75fada4806', '私の部屋には脱ぎっぱなしの服が床に散らかっています。掃除しても、次の日にはまたすぐ散らかしちゃうんだよね。', 'Ada pakaian kotor berserakan di lantai kamarku. Bahkan jika saya membersihkannya, keesokan harinya akan menjadi berantakan lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c9e34d7-c422-4e5e-85cd-41b29555da94', 'vocabulary', '引っ越す', '引っ越す', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '越す adalah "melampaui." Sekarang Anda keluar dari rumah Anda dan membawa semuanya untuk pergi ke rumah lain. Anda mencoba untuk pindah / pindah rumah.', '越す adalah "melampaui." Sekarang Anda keluar dari rumah Anda dan membawa semuanya untuk pergi ke rumah lain. Anda mencoba untuk pindah / pindah rumah.') ON CONFLICT (id) DO NOTHING;
