INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c9e34d7-c422-4e5e-85cd-41b29555da94', '「パパ、フグと私、結婚して日本に引っ越すつもりよ。」「俺の目の黒いうちはそんなことはさせないぞ。」', '“Ayah, Fugu dan aku akan menikah dan pindah ke Jepang.” "Tidak selama aku masih hidup, kamu tidak akan melakukannya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82300685-c625-4cce-bb22-cb47d7346960', 'vocabulary', '追い越す', '追い越す', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', '越す berarti "melampaui." 追 adalah mengikuti. Jika Anda mengikuti seseorang, dan kemudian Anda melampauinya, Anda telah menyusulnya. Itu sebabnya kata ini berarti menyalip atau melampaui.', '越す berarti "melampaui." 追 adalah mengikuti. Jika Anda mengikuti seseorang, dan kemudian Anda melampauinya, Anda telah menyusulnya. Itu sebabnya kata ini berarti menyalip atau melampaui.') ON CONFLICT (id) DO NOTHING;
