INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa8fcfc1-48ef-461c-b8fe-f7b5af297a53', '私の祖父母はまだ小児科医にかかっています。', 'Kakek-nenek saya masih menemui dokter anak mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9467c0a9-b79b-4c40-a012-0a9af2f638c5', 'vocabulary', '込める', '込める', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anda tahu bahwa 込む berarti "menjadi ramai". Namun, ini adalah saat Anda membuat sesuatu menjadi ramai. Bagaimana cara membuat sesuatu menjadi ramai? Anda harus memasukkan lebih banyak lagi ke dalam benda yang ingin Anda ramaikan hingga menjadi ramai. Untuk melakukan tindakan ini (yang sedang Anda lakukan), Anda mengirimkan (める) sesuatu berulang kali. Ini akan memadati kantor pos jika saya memasukkan semua surat ini ke dalam kotak surat ini! Ha ha! Benar-benar pemberontak!', 'Anda tahu bahwa 込む berarti "menjadi ramai". Namun, ini adalah saat Anda membuat sesuatu menjadi ramai. Bagaimana cara membuat sesuatu menjadi ramai? Anda harus memasukkan lebih banyak lagi ke dalam benda yang ingin Anda ramaikan hingga menjadi ramai. Untuk melakukan tindakan ini (yang sedang Anda lakukan), Anda mengirimkan (める) sesuatu berulang kali. Ini akan memadati kantor pos jika saya memasukkan semua surat ini ke dalam kotak surat ini! Ha ha! Benar-benar pemberontak!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9467c0a9-b79b-4c40-a012-0a9af2f638c5', 'Untuk Memasukkan', true) ON CONFLICT DO NOTHING;
