INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9467c0a9-b79b-4c40-a012-0a9af2f638c5', 'ショットガンに弾を込める時間がなかったんだ。', 'Saya tidak punya cukup waktu untuk memasukkan peluru ke dalam senapan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9467c0a9-b79b-4c40-a012-0a9af2f638c5', 'もっと気持ちを込めて演技しろよ！それでもプロの劇団員か？', 'Berikan lebih banyak emosi dalam penampilan Anda! Apakah Anda benar-benar seorang aktor teater profesional?') ON CONFLICT DO NOTHING;
