INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fefc7c39-d490-4e51-b19d-8bbf558a4729', 'vocabulary', '申し込む', '申し込む', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Saya ingin mengatakan dengan rendah hati di tempat ramai ini bahwa saya akan melamar. Jika ada banyak orang lain yang melamar, Anda merasa tersanjung, sehingga dengan rendah hati Anda mengatakan ingin melamar.', 'Saya ingin mengatakan dengan rendah hati di tempat ramai ini bahwa saya akan melamar. Jika ada banyak orang lain yang melamar, Anda merasa tersanjung, sehingga dengan rendah hati Anda mengatakan ingin melamar.') ON CONFLICT (id) DO NOTHING;
