INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a517581e-f671-4eb6-9313-5443fd59c6ff', '急いで申込書に書き込んだ方がいいよ。あと十分で事務所は閉まっちゃうんだから。', 'Anda sebaiknya bergegas dan mengisi aplikasi. Kantor akan tutup sepuluh menit lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0cdb6347-32f4-411a-b51e-8f99bb0de72a', 'vocabulary', '人込み', '人込み', 3, '4f3a9b6c-7d8e-5f0a-1b2c-3d4e5f6a7b8c', 'Anda tahu bahwa 込む berarti "menjadi ramai" jadi ketika Anda sedang ramai dengan orang-orang... ya... Anda mempunyai banyak orang.', 'Anda tahu bahwa 込む berarti "menjadi ramai" jadi ketika Anda sedang ramai dengan orang-orang... ya... Anda mempunyai banyak orang.') ON CONFLICT (id) DO NOTHING;
