INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0cdb6347-32f4-411a-b51e-8f99bb0de72a', '怖くて人込みの中に行けません。', 'Saya tidak bisa pergi ke tengah kerumunan orang karena saya takut.') ON CONFLICT DO NOTHING;
