INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('3dbf4d3f-6233-4853-95fa-1d3dbbace10f', '7b4d2714-8a23-4139-8f28-ec05176daed8') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9e05ce13-3474-479c-bd51-d4c6e96fd59f', 'radical', '莫', 'greenhouse', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Bunga membutuhkan sinar matahari untuk menjadi besar. Untuk membantu mereka tumbuh sebesar mungkin, kami menaruhnya di rumah kaca.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9e05ce13-3474-479c-bd51-d4c6e96fd59f', 'Rumah Kaca', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e5e55dd7-0067-460a-9a60-8063c87fadaa', 'radical', '呉', 'catapult', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Lihat batu di ketapel? Ia bahkan mempunyai kaki kecil untuk menahannya agar tetap stabil sehingga dapat melontarkan lebih baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5e55dd7-0067-460a-9a60-8063c87fadaa', 'Ketapel', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('22f7b1fb-4125-4a7b-9dad-d2f5cf410f35', 'radical', '堇', 'boot', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Ada sesuatu yang terbuat dari kulit dengan sedikit kotoran di bagian bawahnya. Itu sepatu bot!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('22f7b1fb-4125-4a7b-9dad-d2f5cf410f35', 'booting', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('430cdbc1-9ece-4e20-833f-df40ba90c2d8', 'radical', '亥', 'slice', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Lihat pria itu? Lihat bagaimana dia dipotong setengah??? Itu pasti merupakan tindakan yang sangat kejam untuk melakukan hal itu pada seseorang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('430cdbc1-9ece-4e20-833f-df40ba90c2d8', 'Iris', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ba4a763c-3394-4042-bbe4-f9322dae1ddf', 'radical', '皮', 'skin', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Radikal ini sama dengan kanji. Artinya kulit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ba4a763c-3394-4042-bbe4-f9322dae1ddf', 'Kulit', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5c8ec088-789b-4f98-b187-83efdd24b5db', 'radical', '彑', 'shuriken', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Lihat shurikennya tertancap di tanah? Jika Anda belum mengetahuinya, shuriken hanyalah bintang lempar. Ninja hebat menggunakannya. Itulah yang ada dalam radikal ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c8ec088-789b-4f98-b187-83efdd24b5db', 'senjata rahasia', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d315107f-e022-4a8d-82c2-bd346ca04818', 'radical', '舛', 'dance', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Anda melihat seekor sapi di malam hari. Anda semakin dekat dan menyadari itu sedang menari. Semua sapi menari di malam hari. Bisakah Anda membayangkannya? Sapi itu menari, begitu megah, di bawah sinar matahari terbenam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d315107f-e022-4a8d-82c2-bd346ca04818', 'Menari', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ad763e59-4d3f-4127-ad6f-b7dae78dfc80', 'radical', '包', 'wrap', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Diri Anda (diri sendiri) berada di penjara. Lihatlah penjara yang menyelimuti Anda. Itu membungkusmu dan memelukmu erat-erat. Itu sebabnya ini disebut radikal!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ad763e59-4d3f-4127-ad6f-b7dae78dfc80', 'Bungkus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('01bb3286-ff76-4766-b2de-3ff946e3fe83', 'radical', '兆', 'omen', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Ada ledakan di sekitar kakimu. Seperti yang diperingatkan oleh peramal. Ini adalah pertanda yang dia bicarakan. Pikirkan tentang apa yang terjadi setelah pertanda itu muncul. Keajaiban peramal mengerikan apa yang akan terjadi???') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('01bb3286-ff76-4766-b2de-3ff946e3fe83', 'Pertanda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0a662ca7-ae63-49d3-8c26-b62c8e2bd966', 'radical', '禺', 'splinter', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Meski sedikit dimodifikasi, ada cangkang kura-kura yang berkumis dengan radikal ini. Satu-satunya makhluk berkumis yang menjuntai di sekitar penyu adalah Splinter, tikus raksasa dari Teenage Mutant Ninja Turtles. Jadi radikal ini adalah Splinter (tikus raksasa).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0a662ca7-ae63-49d3-8c26-b62c8e2bd966', 'Serpihan', true) ON CONFLICT DO NOTHING;
