INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('188166ec-925d-4af8-af86-fcddb4bd550f', 'もう一度あの閉店しちゃった洋菓子屋のケーキが食べたいな。', 'Saya ingin makan kue dari toko permen yang tutup itu lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('188166ec-925d-4af8-af86-fcddb4bd550f', '「営業時間は何時から何時までですか？」「午前10時開店で、午後8時閉店となります。」', '"Jam kerjamu berapa?" "Kami buka jam 10 pagi dan tutup jam 8 malam."') ON CONFLICT DO NOTHING;
