INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36817ee7-e09f-479b-a74b-32d5ca45da76', '彼は今は幸せに暮らしているが、ああ見えて苦難を経験してるんだぜ。', 'Dia menjalani kehidupan yang bahagia sekarang, tapi sebenarnya dia mengalami banyak kesulitan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d8d4546-d5c8-496f-afaf-fce88995bbdd', 'vocabulary', '野暮', '野暮', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Bidang penghidupan begitu hidup! Lihatlah segala sesuatu yang melompat-lompat. Ini sangat segar, baru, dan mengagumkan! Meski begitu, karena begitu hidup, segar, dan baru, suasananya sangat tidak murni dan sederhana.', 'Bidang penghidupan begitu hidup! Lihatlah segala sesuatu yang melompat-lompat. Ini sangat segar, baru, dan mengagumkan! Meski begitu, karena begitu hidup, segar, dan baru, suasananya sangat tidak murni dan sederhana.') ON CONFLICT (id) DO NOTHING;
