INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43728903-3fd8-445d-a897-f0128337e759', 'vocabulary', '破産', '破産', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Jika seseorang merampas seluruh properti Anda, hal itu akan menyebabkan kebangkrutan. Dengan semua harta benda Anda terkoyak, Anda akan bangkrut. Orang jahat apa yang melakukan itu?', 'Jika seseorang merampas seluruh properti Anda, hal itu akan menyebabkan kebangkrutan. Dengan semua harta benda Anda terkoyak, Anda akan bangkrut. Orang jahat apa yang melakukan itu?') ON CONFLICT (id) DO NOTHING;
