INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45d400a5-37ad-429d-b281-022398b874cc', 'vocabulary', '交互', '交互', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Anda bercampur, lalu Anda saling bergaul, lalu Anda bercampur, dan kemudian Anda menjadi saling menguntungkan. Sebagai alternatif, Anda dapat mencampurnya lagi?', 'Anda bercampur, lalu Anda saling bergaul, lalu Anda bercampur, dan kemudian Anda menjadi saling menguntungkan. Sebagai alternatif, Anda dapat mencampurnya lagi?') ON CONFLICT (id) DO NOTHING;
