INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45d400a5-37ad-429d-b281-022398b874cc', '彼女は二種類の味のアイスクリームを交互に舐めた。', 'Dia secara bergantian menjilat dua jenis es krim.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('20af1a1f-3d5f-4f42-b3be-381d32dfe5c2', 'vocabulary', '彼', '彼', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
