INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('20af1a1f-3d5f-4f42-b3be-381d32dfe5c2', 'しまった！急須を壊しちゃった。彼が知ったらめちゃくちゃ怒るだろうな。', 'Kotoran! Aku baru saja memecahkan teko bodoh itu. Dia akan sangat marah jika dia tahu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1e36c00c-d9e1-4a50-99f6-91320aeb2a43', 'vocabulary', '彼ら', '彼ら', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Ini dia tapi jamak. Kata "ra" menjadikannya jamak, menjadikannya "mereka" atau "mereka". Meskipun gen ini biasanya merujuk pada sekelompok pria, namun bisa juga mencakup wanita.', 'Ini dia tapi jamak. Kata "ra" menjadikannya jamak, menjadikannya "mereka" atau "mereka". Meskipun gen ini biasanya merujuk pada sekelompok pria, namun bisa juga mencakup wanita.') ON CONFLICT (id) DO NOTHING;
