INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1e36c00c-d9e1-4a50-99f6-91320aeb2a43', '彼らはみんな、電車の切符を買っていなかったため、無賃乗車者として捕まった。', 'Tak satu pun dari mereka membeli tiket kereta api dan mereka ditangkap karena naik kereta tanpa membayar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02b9b2d7-739b-4aab-b1e8-6d2a8d501d1f', 'vocabulary', '恥ずかしい', '恥ずかしい', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari rasa malu? Ini mungkin memalukan atau bahkan memalukan.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari rasa malu? Ini mungkin memalukan atau bahkan memalukan.') ON CONFLICT (id) DO NOTHING;
