INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f04caa2-8051-44a0-9d7e-bde86ef7a44a', 'vocabulary', '払う', '払う', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti membayar sehingga versi vocab verbanya adalah membayar.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti membayar sehingga versi vocab verbanya adalah membayar.') ON CONFLICT (id) DO NOTHING;
