INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('617b3782-6edf-4fce-b937-86e29699d034', 'お勤め先はどちらですか？', 'Untuk siapa Anda bekerja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0615135-5545-436d-8c13-71e79ce18aaa', 'vocabulary', '舞台', '舞台', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Mesin dansa sebenarnya bukanlah sebuah mesin... 台 adalah mesin penghitung benda yang besar, jadi dalam hal ini yang dimaksud adalah panggung. Panggung menari adalah sebuah panggung.', 'Mesin dansa sebenarnya bukanlah sebuah mesin... 台 adalah mesin penghitung benda yang besar, jadi dalam hal ini yang dimaksud adalah panggung. Panggung menari adalah sebuah panggung.') ON CONFLICT (id) DO NOTHING;
