INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a0615135-5545-436d-8c13-71e79ce18aaa', 'すごくいい声持ってるね。舞台で歌を歌ってみようと思った事はないの？', 'Anda memiliki suara yang bagus. Pernahkah Anda berpikir untuk bernyanyi di atas panggung?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0fc1059a-5188-4263-8b1c-3cd2baf73c83', 'vocabulary', '舞う', '舞う', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menari dan versi vocab verbanya berarti menari, sekaligus berdebar-debar.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menari dan versi vocab verbanya berarti menari, sekaligus berdebar-debar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0fc1059a-5188-4263-8b1c-3cd2baf73c83', 'Menari', true) ON CONFLICT DO NOTHING;
