INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('51c8b988-21fd-4ac4-8ec2-f8acb73d912a', 'たのむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('51c8b988-21fd-4ac4-8ec2-f8acb73d912a', '「茹でたワニカニ、いつまでに必要ですか？」「できるだけ早く頼むよ。」', '"Kapan kamu membutuhkan crabigator rebus?" "Saya membutuhkannya sesegera mungkin."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4c296cec-657b-45bb-be0a-7c311a3236ec', 'vocabulary', '信頼', '信頼', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Saya yakin saya bisa mempercayai Anda. Itu sebabnya saya sangat bergantung dan percaya pada Anda untuk melakukannya dengan baik.', 'Saya yakin saya bisa mempercayai Anda. Itu sebabnya saya sangat bergantung dan percaya pada Anda untuk melakukannya dengan baik.') ON CONFLICT (id) DO NOTHING;
