INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c296cec-657b-45bb-be0a-7c311a3236ec', '彼は信頼できるような気がするし、早合点はしたくないね。', 'Saya tidak ingin langsung mengambil kesimpulan karena dia tampaknya cukup bisa dipercaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ac4f151-9e1f-4d38-a49b-5caccd889d3f', 'vocabulary', '降参する', '降参する', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', '降参 adalah "menyerah" jadi versi kata kerjanya adalah menyerah.', '降参 adalah "menyerah" jadi versi kata kerjanya adalah menyerah.') ON CONFLICT (id) DO NOTHING;
