INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ac4f151-9e1f-4d38-a49b-5caccd889d3f', '降参しようと思ったことは今まで一度もないんですか。', 'Pernahkah Anda berpikir untuk menyerah, sekali pun?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e62217db-c306-4645-853e-e9028973428f', 'vocabulary', '一人暮らし', '一人暮らし', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Jika 暮らす berarti "hidup" atau "menjalani hidup", maka menjalani hidup sebagai 一人 berarti Anda hidup sendiri.', 'Jika 暮らす berarti "hidup" atau "menjalani hidup", maka menjalani hidup sebagai 一人 berarti Anda hidup sendiri.') ON CONFLICT (id) DO NOTHING;
