INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f200573c-55f2-437d-8018-0b251dfff560', '母親が病気になったので、私は国に戻ることにしました。', 'Saya memutuskan untuk kembali ke negara saya karena ibu saya sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('262e996b-766a-44b8-8b96-490407368da1', 'vocabulary', '抱く', '抱く', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti pelukan dan versi vocab verbanya adalah memeluk atau merangkul. 抱いて抱いて！', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti pelukan dan versi vocab verbanya adalah memeluk atau merangkul. 抱いて抱いて！') ON CONFLICT (id) DO NOTHING;
