INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed96c902-93c6-4000-973b-187375a2de90', 'vocabulary', '逃げる', '逃げる', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melarikan diri jadi versi vocab verbanya adalah melarikan diri. Bisa juga untuk melarikan diri atau melarikan diri. Pada dasarnya, jika Anda mencoba menjauh dari seseorang atau sesuatu, Anda mungkin melakukan hal ini.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melarikan diri jadi versi vocab verbanya adalah melarikan diri. Bisa juga untuk melarikan diri atau melarikan diri. Pada dasarnya, jika Anda mencoba menjauh dari seseorang atau sesuatu, Anda mungkin melakukan hal ini.') ON CONFLICT (id) DO NOTHING;
