INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('950ffef7-2203-4809-92de-30a9a9484abc', '私の弟は優し過ぎて犯罪者達の逃亡を助けてしまい、そのせいで逮捕されてしまいました。', 'Adik laki-laki saya sangat murah hati sehingga dia membantu pelarian para penjahat dan ditangkap karenanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('284a9cbc-6d14-45e6-a779-74c69452a495', 'vocabulary', '払い戻す', '払い戻す', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', '払い berarti "pembayaran" dan 戻す berarti "mengembalikan". Jika Anda mengembalikan pembayaran, Anda akan membayar kembali, mengembalikan dana, atau mengganti biaya seseorang atas pembayarannya.', '払い berarti "pembayaran" dan 戻す berarti "mengembalikan". Jika Anda mengembalikan pembayaran, Anda akan membayar kembali, mengembalikan dana, atau mengganti biaya seseorang atas pembayarannya.') ON CONFLICT (id) DO NOTHING;
