INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c2073c29-a3a6-4227-97d1-6978bb12c692', 'vocabulary', '取り戻す', '取り戻す', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Mengambil dan mengembalikan sesuatu kepada diri sendiri berarti mengambil kembali sesuatu. Kembalikan!', 'Mengambil dan mengembalikan sesuatu kepada diri sendiri berarti mengambil kembali sesuatu. Kembalikan!') ON CONFLICT (id) DO NOTHING;
