INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d58e8477-a0c0-4d0b-8a19-cf444a17082e', '当人達は内緒話をしているつもりのようだが、声がでかいので全部筒抜けだよ。', 'Mereka mencoba berbisik satu sama lain, tapi suara mereka begitu keras hingga aku bisa mendengar semuanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('190cd502-e732-48a7-bf76-70f42719c9c3', 'vocabulary', '逃す', '逃す', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Anda sudah mengetahui bahwa 逃げる berarti "melarikan diri", dan kata kerja ini adalah saat Anda membiarkan sesuatu lolos, atau lolos dari jari Anda. Jadi ini berarti melewatkan atau kehilangan peluang bagus, atau melepaskan peluang bagus.', 'Anda sudah mengetahui bahwa 逃げる berarti "melarikan diri", dan kata kerja ini adalah saat Anda membiarkan sesuatu lolos, atau lolos dari jari Anda. Jadi ini berarti melewatkan atau kehilangan peluang bagus, atau melepaskan peluang bagus.') ON CONFLICT (id) DO NOTHING;
