INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('190cd502-e732-48a7-bf76-70f42719c9c3', '恋愛のチャンスは逃さないよ！', 'Saya tidak akan pernah melewatkan kesempatan untuk jatuh cinta!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('190cd502-e732-48a7-bf76-70f42719c9c3', '主人がクシャミをしたので、シャッターチャンスを逃してしまいました。', 'Saya melewatkan bidikan sempurna ketika suami saya bersin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('190cd502-e732-48a7-bf76-70f42719c9c3', 'ボーっとしていて、アナウンスを聞き逃してしまった。', 'Saya keluar dari situ dan melewatkan pengumumannya.') ON CONFLICT DO NOTHING;
