INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2b0a58a-6493-4b02-968a-cc9282bd1631', 'vocabulary', '到着', '到着', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Pada waktu kedatangan Anda akan tiba. Ini kedatanganmu.', 'Pada waktu kedatangan Anda akan tiba. Ini kedatanganmu.') ON CONFLICT (id) DO NOTHING;
