INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06732461-3de5-4c0b-b001-39de4dd3da6c', 'vocabulary', '髪', '髪', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Pastikan untuk mengetahui bahwa ini adalah rambut di kepala Anda.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Pastikan untuk mengetahui bahwa ini adalah rambut di kepala Anda.') ON CONFLICT (id) DO NOTHING;
