INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e419af6a-84fd-4e4b-81b4-bc028310ae0d', 'vocabulary', '金髪', '金髪', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Rambut emas adalah rambut pirang. Masuk akal!', 'Rambut emas adalah rambut pirang. Masuk akal!') ON CONFLICT (id) DO NOTHING;
