INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a2e71a-6853-45e5-a96f-eacb75dccf13', 'トイレが詰まって、すっぽんで詰まり抜きをする前に水が溢れちゃって、朝早くから掃除をしなくちゃいけなかったから、とっても疲れました。', 'Toiletnya mampet dan kebanjiran sebelum kami menggunakan penyedotnya, jadi saya harus membersihkannya pagi-pagi dan saya sangat lelah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('681a7193-fca3-4140-8b5e-053f1943416b', 'vocabulary', '疲労', '疲労', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Anda kelelahan karena bekerja. Dari sini, Anda menunjukkan kelelahan dan keletihan.', 'Anda kelelahan karena bekerja. Dari sini, Anda menunjukkan kelelahan dan keletihan.') ON CONFLICT (id) DO NOTHING;
