INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6654a490-1b78-49c5-a16a-56315280e8de', 'vocabulary', '見逃す', '見逃す', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', '逃す adalah "melepaskan" atau "melepaskan". Jika ada sesuatu yang luput dari pandangan Anda, maka Anda akan mengabaikannya.', '逃す adalah "melepaskan" atau "melepaskan". Jika ada sesuatu yang luput dari pandangan Anda, maka Anda akan mengabaikannya.') ON CONFLICT (id) DO NOTHING;
