INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca45c908-0f5a-482b-83df-2a76448c61af', 'vocabulary', '吹き出す', '吹き出す', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Jika 吹く berarti "meniup" dan 出す berarti "menghapus", maka Anda menghilangkan tiupan Anda. Anda harus mulai meniup untuk melakukan itu!', 'Jika 吹く berarti "meniup" dan 出す berarti "menghapus", maka Anda menghilangkan tiupan Anda. Anda harus mulai meniup untuk melakukan itu!') ON CONFLICT (id) DO NOTHING;
