INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca45c908-0f5a-482b-83df-2a76448c61af', '俺の新しい髪型を見て、あいつプッと吹き出したんだぜ。失礼だよな。', 'Dia terkekeh saat melihat gaya rambut baruku. Itu tidak sopan, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ecd249ab-7c5b-42a1-ad0b-f0124143d869', 'vocabulary', '吹き込む', '吹き込む', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Anda tahu bahwa 吹く berarti "meniup" dan 込む berarti "menjadi ramai". Jadi kalau kamu meniup sesuatu sampai ramai, kamu meniup ke dalamnya, dan membuat kata ini "meniup masuk.', 'Anda tahu bahwa 吹く berarti "meniup" dan 込む berarti "menjadi ramai". Jadi kalau kamu meniup sesuatu sampai ramai, kamu meniup ke dalamnya, dan membuat kata ini "meniup masuk.') ON CONFLICT (id) DO NOTHING;
