INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1e63f685-2e75-4b63-86c9-94f3509e2e6f', 'のがれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1e63f685-2e75-4b63-86c9-94f3509e2e6f', '万が一ゾンビが実際に現れた場合を想定して、どうやってゾンビから逃れるのかを考えているんです。', 'I’m thinking about how to escape from zombies if they actually showed up.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34b434ee-043c-4319-b6c7-42e16884b2a8', 'vocabulary', '取り逃がす', '取り逃がす', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'The thing you want to take has escaped. Meaning you failed to catch this thing. This word is to fail to catch.', 'The thing you want to take has escaped. Meaning you failed to catch this thing. This word is to fail to catch.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34b434ee-043c-4319-b6c7-42e16884b2a8', 'To Fail To Catch', true) ON CONFLICT DO NOTHING;
