INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34b434ee-043c-4319-b6c7-42e16884b2a8', '犯罪者を取り逃がすふりをするのは、ちょっとやり過ぎじゃない？', 'Don’t you think pretending that you failed to catch the criminal is a bit overkill?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1e07bc92-5a7c-481f-9f09-44cf514360b0', 'vocabulary', '吹き飛ばす', '吹き飛ばす', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'You know that 吹く is "to blow" and that 飛ばす is "To let fly." So, if you use your blowing to let something fly, you are going to blow away it.', 'You know that 吹く is "to blow" and that 飛ばす is "To let fly." So, if you use your blowing to let something fly, you are going to blow away it.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1e07bc92-5a7c-481f-9f09-44cf514360b0', 'To Blow Away', true) ON CONFLICT DO NOTHING;
