INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1e07bc92-5a7c-481f-9f09-44cf514360b0', 'パーティーに行って、憂鬱なんて吹き飛ばしちゃおうぜ。', 'Let’s go to the party and brush off your depression.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f75a0c9-cfab-4895-a6ed-560927b25295', 'vocabulary', '歳月', '歳月', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Years old in months shows time in years. Just imagine counting time by months and years... You kind of do anyways, right? How old are you? 5 years old. Or, 5 and a half years old (that''s five years six months). So, it makes some sense.', 'Years old in months shows time in years. Just imagine counting time by months and years... You kind of do anyways, right? How old are you? 5 years old. Or, 5 and a half years old (that''s five years six months). So, it makes some sense.') ON CONFLICT (id) DO NOTHING;
