INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('efc1338c-cbcf-452d-bad8-04518f3b5793', 'vocabulary', '二十歳', '二十歳', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Two time ten years old is twenty years old.', 'Two time ten years old is twenty years old.') ON CONFLICT (id) DO NOTHING;
