INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efc1338c-cbcf-452d-bad8-04518f3b5793', '「僕は二十歳になる前に社長になるよ。」「そうだといいけどね。」', '"I’ll be company president before I’m twenty years old." "I hope you’re benar tentang itu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70864f6f-3540-4e54-a451-f9de07b0afb8', 'vocabulary', '万歳', '万歳', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Sepuluh ribu tahun! Itu waktu yang lama. Ini adalah kata untuk frasa bahasa Jepang yang berubah menjadi Inggris, banzai!', 'Sepuluh ribu tahun! Itu waktu yang lama. Ini adalah kata untuk frasa bahasa Jepang yang berubah menjadi Inggris, banzai!') ON CONFLICT (id) DO NOTHING;
