INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9614b9ab-8f36-4fec-ab5c-8386cb379397', 'vocabulary', '歳入', '歳入', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Years old you have entered. These are your yearly (years old) amounts of money you''ve entered into the coffers. These are the annual revenue.', 'Years old you have entered. These are your yearly (years old) amounts of money you''ve entered into the coffers. These are the annual revenue.') ON CONFLICT (id) DO NOTHING;
