INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac1e9efb-e32b-4dad-af2e-4b19ef7574f0', 'vocabulary', '偶然', '偶然', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Secara tidak sengaja tetapi alami (karena tidak ada yang dibuat secara artifisial sebelumnya). Jadi kecelakaan itu benar-benar kecelakaan alami. Kecelakaan seperti ini adalah sesuatu yang terjadi secara kebetulan, atau tidak disangka-sangka. Dengan kata lain, suatu kebetulan.', 'Secara tidak sengaja tetapi alami (karena tidak ada yang dibuat secara artifisial sebelumnya). Jadi kecelakaan itu benar-benar kecelakaan alami. Kecelakaan seperti ini adalah sesuatu yang terjadi secara kebetulan, atau tidak disangka-sangka. Dengan kata lain, suatu kebetulan.') ON CONFLICT (id) DO NOTHING;
