INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f68e4e4e-09a7-419a-8fc8-5c37886e8e5c', 'vocabulary', '配偶者', '配偶者', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Bagikan diri Anda secara tidak sengaja kepada seseorang. Orang itu akhirnya menjadi pasangan Anda. Tampaknya Anda terlalu banyak membagikan diri Anda kepada satu orang.', 'Bagikan diri Anda secara tidak sengaja kepada seseorang. Orang itu akhirnya menjadi pasangan Anda. Tampaknya Anda terlalu banyak membagikan diri Anda kepada satu orang.') ON CONFLICT (id) DO NOTHING;
