INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('de4cad3d-e9d9-4861-86e5-de430ee400c9', 'vocabulary', '暮れる', '暮れる', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Ingat bagaimana Anda mengetahui bahwa 暮らす berarti "hidup?" Nah, ketika Anda terlalu terburu-buru (らす) untuk menjalani hidup sepenuhnya, Anda tidak akan menyadari hari mulai gelap. Anda mencoba untuk hidup siang dan malam sampai semuanya mulai berakhir. Bersinarlah dalam kegelapan itu!', 'Ingat bagaimana Anda mengetahui bahwa 暮らす berarti "hidup?" Nah, ketika Anda terlalu terburu-buru (らす) untuk menjalani hidup sepenuhnya, Anda tidak akan menyadari hari mulai gelap. Anda mencoba untuk hidup siang dan malam sampai semuanya mulai berakhir. Bersinarlah dalam kegelapan itu!') ON CONFLICT (id) DO NOTHING;
