INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a4953d11-ee73-430f-b096-e4f906647903', 'vocabulary', '頂く', '頂く', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Jika Anda dengan rendah hati melakukan sesuatu, Anda akan dengan rendah hati menerima, dengan rendah hati menerima, atau memakan atau meminumnya. Pada dasarnya Anda dengan rendah hati melakukan banyak hal. Dan Anda dapat menggunakan kata ini untuk semuanya!', 'Jika Anda dengan rendah hati melakukan sesuatu, Anda akan dengan rendah hati menerima, dengan rendah hati menerima, atau memakan atau meminumnya. Pada dasarnya Anda dengan rendah hati melakukan banyak hal. Dan Anda dapat menggunakan kata ini untuk semuanya!') ON CONFLICT (id) DO NOTHING;
