INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd586568-4a14-4303-b675-e223f43566fc', '日曜日の早朝、アキラは富士山の頂を目指して、出発した。', 'Minggu dini hari, Akira berangkat menuju puncak Gunung Fuji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd586568-4a14-4303-b675-e223f43566fc', 'ピンク色のネコの一族は、山奥や山の頂に住んでいる。', 'Klan kucing merah muda tinggal jauh di pegunungan dan puncak gunung.') ON CONFLICT DO NOTHING;
