INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('221b8e39-24f9-429b-a47d-dd7ae1b3030d', 'vocabulary', '支払い', '支払い', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Pembayaran yang mendukung Anda dilakukan dalam pembayaran. Apakah Anda melakukan pembayaran untuk mempertahankan rumah atau mobil Anda, atau Anda menerima pembayaran dari atasan Anda, hal itu membuat Anda terus maju.', 'Pembayaran yang mendukung Anda dilakukan dalam pembayaran. Apakah Anda melakukan pembayaran untuk mempertahankan rumah atau mobil Anda, atau Anda menerima pembayaran dari atasan Anda, hal itu membuat Anda terus maju.') ON CONFLICT (id) DO NOTHING;
