INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d797566d-43d8-48ac-beaa-0b5d429a0451', '返事は来週以降になります。', 'Jawabannya adalah minggu depan atau sesudahnya.') ON CONFLICT DO NOTHING;
