INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', 'vocabulary', '由緒', '由緒', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Alasan yang menyatukan orang-orang adalah garis keturunan atau sejarah mereka. Silsilah dan sejarah mengikat orang-orang (terutama keluarga) menjadi satu.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', 'Silsilah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', 'History', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', 'ゆいしょ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', '京都の清水寺は由緒あるお寺だ。', 'Kuil Kiyomizu di Kyoto merupakan kuil dengan sejarah yang panjang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', '由緒ある家の人でも、いい人だとは限らない。', 'Hanya karena dia memiliki garis keturunan yang bergengsi, tidak berarti dia menjadi orang yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716a756-396d-4c53-80a0-d479503b6d40', '日本で最も古い由緒ある神社です。', 'Ini adalah kuil tertua dan paling terhormat di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', 'vocabulary', '由緒正しい', '由緒正しい', 3, '5a4b0c7d-8e9f-6a1b-2c3d-4e5f6a7b8c9d', 'Seseorang atau sesuatu yang 由緒 (silsilahnya) 正しい (benar) adalah silsilah yang terhormat, dan memang patut dimuliakan.', 'Seseorang atau sesuatu yang 由緒 (silsilahnya) 正しい (benar) adalah silsilah yang terhormat, dan memang patut dimuliakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', 'Dari Silsilah Terhormat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', 'Venerable', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', 'ゆいしょただしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', '彼は由緒正しい家系の出身です。', 'Ia berasal dari keluarga dengan garis keturunan terhormat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', 'ここは元々は由緒正しい神社なんですよ。', 'Tempat ini awalnya adalah kuil yang terhormat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae12e26e-d610-48b0-9484-b10aceeecdfc', '由緒正しい生まれの女性に恋をしてしまった。', 'Saya telah jatuh cinta dengan seorang wanita dari garis keturunan terhormat.') ON CONFLICT DO NOTHING;
